[4409] = {name = "[q2]Bauplan: Kleine Zephyriumladung", additional_info = "Benötigt Ingenieurskunst (100)\n[q2]Benutzen: Lehrt Euch die Herstellung einer kleinen Zephyriumladung.\nKleine Zephyriumladung\nBenötigt Ingenieurskunst (100)\n[q2]Benutzen: Sprengt einfache verschlossene Türen auf.\nBenötigt Grobes Sprengpulver (2), Kupfermodulator , Leichtes Leder , Erfrischendes Quellwasser"},
[4410] = {name = "[q2]Bauplan: Schattenschutzbrille", additional_info = "Benötigt Ingenieurskunst (120)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Schattenschutzbrille.\n[q2]Schattenschutzbrille\nWird beim Anlegen gebunden\n{Kopf} {Stoff}\n31 Rüstung\n+5 Intelligenz\n+6 Willenskraft\nHaltbarkeit 40 / 40\nBenötigt Ingenieurskunst (120)\nBenötigt Mittleres Leder (4), Schattenedelstein (2)"},
[4411] = {name = "[q2]Bauplan: Flammendeflektor", additional_info = "Benötigt Ingenieurskunst (125)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Flammendeflektors.\nFlammendeflektor\nBenötigt Stufe 15\n[q2]Benutzen: Absorbiert 500 Punkt(e) Feuerschaden. Hält 1 Min. lang an. (15 Min Abklingzeit)\n5 Aufladungen\nBenötigt Surrendes bronzenes Dingsda , Kleiner Flammenbeutel"},
[4412] = {name = "[q2]Bauplan: Mondsichtgewehr", additional_info = "Benötigt Ingenieurskunst (145)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Mondsichtgewehrs.\n[q2]Mondsichtgewehr\nWird beim Anlegen gebunden\n{Distanz} {Schusswaffe}\n{14 - 26 Schaden} {Tempo 1.70}\n(11.76 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 24\nBenötigt Bronzeröhre (3), Surrendes bronzenes Dingsda (3), Schwerer Griff , Geringer Mondstein (2)"},
[4413] = {name = "[q2]Bauplan: Diskombobulatorstrahl", additional_info = "Benötigt Ingenieurskunst (160)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Diskombobulatorstrahls.\nDiskombobulatorstrahl\n[q2]Benutzen: Verwandelt das Ziel in einen Lepragnom und verringert 12 Sek. lang seinen Nahkampf- und Zauberschaden um 40, sowie sein Bewegungstempo um 20%. (1 Min Abklingzeit)\n5 Aufladungen\nBenötigt Surrendes bronzenes Dingsda (3), Seidenstoff (2), Jade , Bronzeröhre"},
[4414] = {name = "[q2]Bauplan: Tragbarer bronzener Mörser", additional_info = "Benötigt Ingenieurskunst (165)\n[q2]Benutzen: Lehrt Euch die Herstellung eines tragbaren bronzenen Mörsers.\nTragbarer bronzener Mörser\nBenötigt Ingenieurskunst (165)\n[q2]Benutzen: Fügt 85 bis 115 Feuerschaden zu und betäubt Ziele 2 Sek. lang in einem Umkreis von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\n8 Aufladungen\nBenötigt Bronzeröhre (4), Eisenstrebe , Schweres Sprengpulver (4), Mittleres Leder (4)"},
[4415] = {name = "[q3]Bauplan: Handwerkermonokel", additional_info = "Benötigt Ingenieurskunst (185)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Handwerkermonokels.\n[q2]Handwerkermonokel\nWird beim Anlegen gebunden\n{Kopf} {Stoff}\n40 Rüstung\n+15 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Stufe 32\nBenötigt Ingenieurskunst (185)\nBenötigt Schweres Leder (6), Citrin (2)"},
[4416] = {name = "[q2]Bauplan: Goblin-Landmine", additional_info = "Benötigt Ingenieurskunst (195)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Goblin-Landmine.\nGoblin-Landmine\nBenötigt Ingenieurskunst (195)\n[q2]Benutzen: Platziert die Goblin-Landmine auf dem Boden. Sie explodiert, sobald eine feindliche Kreatur an ihr vorbeigeht, und fügt ihr 394 bis 506 Feuerschaden zu. Die Mine ist 1 Min. lang aktiv. (1 Min Abklingzeit)\nBenötigt Schweres Sprengpulver (3), Eisenbarren (2), Gyrochronatom"},
[4417] = {name = "[q2]Bauplan: Große Zephyriumladung", additional_info = "Benötigt Ingenieurskunst (200)\n[q2]Benutzen: Lehrt Euch die Herstellung einer großen Zephyriumladung.\nGroße Zephyriumladung\nBenötigt Ingenieurskunst (200)\n[q2]Benutzen: Sprengt schwere verschlossene Türen auf.\nBenötigt Robustes Sprengpulver (2), Schweres Leder (2), Erfrischendes Quellwasser"},
