[6044] = {name = "[q2]Pläne: Eisenschildstachel", additional_info = "Benötigt Schmiedekunst (150)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Eisenschildstachels.\nEisenschildstachel\nBenötigt Schmiedekunst (150)\n[q2]Benutzen: Bringt einen Eisenstachel an Eurem Schild an, der damit bei jedem Blocken Schaden verursacht.\nBenötigt Eisenbarren (6), Grober Schleifstein (4)"},
[6045] = {name = "[q2]Pläne: Eisengegengewicht", additional_info = "Benötigt Schmiedekunst (165)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Eisengegengewichts zum Ausbalancieren einer Zweihandwaffe.\nEisengegengewicht\nBenötigt Schmiedekunst (165)\n[q2]Benutzen: Bringt ein Gegengewicht an einem Zweihandschwert, einem Zweihandstreitkolben, einer Zweihandaxt oder an einer Zweihand-Stangenwaffe an und macht die Waffe um 3% schneller.\nBenötigt Eisenbarren (4), Grober Schleifstein (2), Geringer Mondstein"},
[6046] = {name = "[q2]Pläne: Stahlwaffenkette", additional_info = "Benötigt Schmiedekunst (190)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Stahlwaffenkette, die Eure Entwaffnung verhindert.\nStahlwaffenkette\nBenötigt Schmiedekunst (190)\n[q2]Benutzen: Bringt eine Kette an Eurer Waffe an, die das Entwaffnen verhindert.\nBenötigt Stahlbarren (8), Schwerer Schleifstein (2), Schweres Leder (4)"},
