[9293] = {name = "[q2]Rezept: Magiewiderstandstrank", additional_info = "Benötigt Alchimie (210)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Magiewiderstandstranks.\nMagiewiderstandstrank\nBenötigt Stufe 32\n[q2]Benutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 3 Min. lang um 50. (2 Min Abklingzeit)\nBenötigt Khadgars Schnurrbart , Lila Lotus , Kristallphiole"},
[9294] = {name = "[q2]Rezept: Wildrankentrank", additional_info = "Benötigt Alchimie (225)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Wildrankentranks.\nWildrankentrank\nBenötigt Stufe 35\n[q2]Benutzen: Stellt 1 bis 1500 Punkt(e) Gesundheit und 1 bis 1500 Punkt(e) Mana wieder her. (2 Min Abklingzeit)\nBenötigt Wildranke , Lila Lotus , Kristallphiole"},
[9295] = {name = "[q2]Rezept: Unsichtbarkeitstrank", additional_info = "Benötigt Alchimie (235)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Unsichtbarkeitstranks.\nUnsichtbarkeitstrank\nBenötigt Stufe 37\n[q2]Benutzen: Gewährt dem Anwender 18 Sek. lang Unsichtbarkeit. (10 Min Abklingzeit)\nBenötigt Geisterpilz , Sonnengras , Kristallphiole"},
[9296] = {name = "[q2]Rezept: Arthas' Gabe", additional_info = "Benötigt Alchimie (240)\n[q2]Benutzen: Lehrt Euch die Herstellung von Arthas' Gabe.\nArthas' Gabe\nBenötigt Stufe 38\n[q2]Benutzen: Erhöht den Schattenwiderstand um 10. Wenn ein Feind den Benutzer trifft, besteht eine Chance von 30%, dass der angreifende Feind mit einer Krankheit infiziert wird, die seinen erlittenen Schaden 3 Min. lang um 8 erhöht. Hält 30 Min. lang an. (Procchance: 30%) (3 Sek. Abklingzeit)\nBenötigt Arthas' Tränen , Blindkraut , Kristallphiole"},
[9297] = {name = "[q2]Rezept: Elixier der Traumvision", additional_info = "Benötigt Alchimie (240)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers der Traumvision.\nElixier der Traumvision\nBenötigt Stufe 38\n[q2]Benutzen: Gewährt Euch eine Traumvision, mit der Ihr Gegenden erforschen könnt, die zu gefährlich sind, sie persönlich zu erforschen. (3 Sek. Abklingzeit)\nBenötigt Lila Lotus (3), Kristallphiole"},
[9298] = {name = "[q2]Rezept: Elixier der Riesen", additional_info = "Benötigt Alchimie (245)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers der Riesen.\nElixier der Riesen\nBenötigt Stufe 38\n[q2]Benutzen: Erhöht Eure Stärke 1 Stunde lang um 25. (3 Sek. Abklingzeit)\nBenötigt Sonnengras , Gromsblut , Kristallphiole"},
