[10713] = {name = "Pläne: Veredelter Mithrilzylinder", additional_info = "Benötigt Schmiedekunst (200)\n[q2]Benutzen: Lehrt Euch die Herstellung eines veredelten Mithrilzylinders. Dieser Gegenstand wird von Gnomen-Ingenieuren verwendet.\nVeredelter Mithrilzylinder\n[q]\"Wird von Gnomen-Ingenieuren verwendet, um ihre Erfindungen zu verstärken.\"\nBenötigt Mithrilbarren (5), Goldbarren , Echtsilberbarren"},
[10714] = {name = "Kristallisierter Azsharit", additional_info = "Questgegenstand\n[q]\"Frisch aus dem Ofen.\""},
[10715] = {name = "Kim'jaels Zielfernrohr", additional_info = "Questgegenstand\nEinzigartig"},
[10716] = {name = "Gnomen-Schrumpfstrahl", additional_info = "Wird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen: Lässt das Ziel schrumpfen und verringert seine Angriffskraft um 250. Zumindest ist das meistens der Fall... (5 Min Abklingzeit)"},
[10717] = {name = "Kim'jaels Kompass", additional_info = "Questgegenstand\nEinzigartig"},
[10718] = {name = "Kim'jaels Wizzlegoober", additional_info = "Questgegenstand\nEinzigartig"},
[10719] = {name = "Mobiler Alarm", additional_info = "Benötigt Ingenieurskunst (205)\n[q2]Benutzen: Beschwört ein explosives Schaf, das den nächstbefindlichen Feind angreift, explodiert und dabei 135 bis 165 Punkt(e) Schaden verursacht. Hält 3 Minuten lang an oder bis zur Explosion. (1 Min Abklingzeit)"},
[10720] = {name = "Gnomen-Net-o-Matik-Projektor", additional_info = "Wird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (210)\n[q2]Benutzen: Hält das Ziel 10 Sek. lang in einem Netz fest. Das Netz ist allerdings mit einer Menge Haken bestückt und verfängt sich manchmal auch in der Kleidung des Benutzers, wenn es abgefeuert wird... (10 Min Abklingzeit)"},
[10721] = {name = "[q2]Gnomen-Unglücksverhinderungsgürtel", additional_info = "Wird beim Anlegen gebunden\n{Taille} {Leder}\n66 Rüstung\n+6 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Ingenieurskunst (215)\n[q2]Benutzen: Ein Kraftfeldschild beschützt Euch vor dem nächsten zugefügten 500-Schaden im Verlauf der nächsten 10 Min.. WARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)"},
[10722] = {name = "Kim'jaels gefülltes Huhn", additional_info = "Questgegenstand\nEinzigartig"},
[10723] = {name = "Gnomen-Amateurradio", additional_info = "Schmuck"},
[10724] = {name = "[q2]Gnomen-Raketenstiefel", additional_info = "Wird beim Anlegen gebunden\n{Füße} {Stoff}\n41 Rüstung\nHaltbarkeit 35 / 35\nBenötigt Ingenieurskunst (225)\n[q2]Benutzen: Diese Stiefel erhöhen Euer Lauftempo 20 Sek. lang erheblich. WARNUNG: Ihre Stromversorgung und Gyros funktionieren nicht immer so, wie sie eigentlich sollten. (30 Min Abklingzeit)"},
[10725] = {name = "Gnomen-Kampfhuhn", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst (230)\n[q2]Benutzen: Erschafft ein Kampfhuhn, dass für 1.50 Min. oder bis es zerstört wird, für euch kämpfen wird. (30 Min Abklingzeit)"},
[10726] = {name = "[q2]Gnomen-Gedankenkontrollkappe", additional_info = "Wird beim Anlegen gebunden\n{Kopf} {Stoff}\n50 Rüstung\n+14 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (215)\n[q2]Benutzen: Beginnt einen mentalen Kampf gegen ein humanoides Ziel und versucht, Kontrolle über dessen Gedanken zu erlangen. Wenn alles gut geht, werdet Ihr die Gedanken des Ziels 20 Sek. lang kontrollieren... (30 Min Abklingzeit)"},
[10727] = {name = "Goblinscher Drachenwerfer", additional_info = "Wird beim Aufheben gebunden\nSchmuck\n[q2]Benutzen: Fügt jedem Feind in einem Kegel vor dem Ingenieur, der die Waffe benutzt, 10 Sek. lang 61 bis 69 Punkt(e) Feuerschaden zu. Es sei denn, sie explodiert... (5 Min Abklingzeit)"},
[10728] = {name = "Muster: Schwarzes Schwadroneurshemd", additional_info = "Benötigt Schneiderei (200)\n[q2]Benutzen: Lehrt Euch, wie man ein schwarzes Schwadroneurshemd näht.\nSchwarzes Schwadroneurshemd\nHemd\nBenötigt Seidenstoffballen (5), Schwarzer Farbstoff , Seidenfaden"},
