[13505] = {name = "[q4]Runenklinge von Baron Rivendare", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{171 - 257 Schaden} {Tempo 3.60}\n(59.44 Schaden pro Sekunde)\nHaltbarkeit 120 / 120\nBenötigt Stufe 58\n[q2]Anlegen: Erhöht Bewegungstempo und Gesundheitsregenerationsrate."},
[13506] = {name = "Fläschchen der Versteinerung", additional_info = "Benötigt Stufe 50\n[q2]Benutzen: Ihr werdet zu Stein und seid 1 Min. lang gegen alle körperlichen Angriffe und Zauber geschützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. (3 Sek. Abklingzeit)"},
[13507] = {name = "Klippenbehüter Longhorns Bericht", additional_info = "Questgegenstand\nEinzigartig\n[q2]<Zum Lesen rechtsklicken>"},
[13508] = {name = "[q2]Auge von Arachnida", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Beschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge bewegt sich schnell, aber auch sehr zerbrechlich. (1 Min Abklingzeit)\n3 Aufladungen"},
[13509] = {name = "[q2]Klammer der Voraussicht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Kontert das Zauberwirken des Feindes und verhindert 10 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung. (1 Min Abklingzeit)"},
[13510] = {name = "Fläschchen der Titanen", additional_info = "Benötigt Stufe 50\n[q2]Benutzen: Erhöht die maximale Gesundheit des Spielers 2 Stunden lang um 1200. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)"},
[13511] = {name = "Fläschchen mit destillierter Weisheit", additional_info = "Benötigt Stufe 50\n[q2]Benutzen: Erhöht das maximale Mana des Spielers 2 Stunden lang um 2000. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)"},
[13512] = {name = "Fläschchen mit oberster Macht", additional_info = "Benötigt Stufe 50\n[q2]Benutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 2 Stunden lang um bis zu 150. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)"},
[13513] = {name = "Fläschchen mit chromatischem Widerstand", additional_info = "Benötigt Stufe 50\n[q2]Benutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 2 Stunden lang um 25. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an und ist mit allen anderen widerstandssteigernden Zaubern und Gegenständen stapelbar. (3 Sek. Abklingzeit)"},
[13514] = {name = "[q2]Wehklage der Banshee", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Verringert die Chance eines Feindes zu treffen 12 Sek. lang um 10%. (1 Min Abklingzeit)\n3 Aufladungen"},
[13515] = {name = "[q3]Ramsteins Blitzschlag", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 55\n[q2]Benutzen: Setzt die Macht des Blitzschlags ein, um allen Feinden um Euch herum 200 Punkt(e) Naturschaden zuzufügen. (5 Min Abklingzeit)"},
[13517] = {name = "Rezept: Alchimistenstein", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Alchimistensteins.\n\n\n[q4]Alchimistenstein\nWird beim Aufheben gebunden\nEinzigartig\nSchmuck\n+8 Willenskraft\nBenötigt Alchimie (300)\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 33%.\nBenötigt Essenz des Feuers (8), Essenz der Erde (8), Essenz der Luft (8), Essenz des Wassers (8), Essenz des Lebens (8), Schwarzes Vitriol (2), Schwarzer Lotus (4)"},
[13518] = {name = "[q2]Rezept: Fläschchen der Versteinerung", additional_info = "Benötigt Alchimie (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fläschchens der Versteinerung.\nFläschchen der Versteinerung\nBenötigt Stufe 50\n[q2]Benutzen: Ihr werdet zu Stein und seid 1 Min. lang gegen alle körperlichen Angriffe und Zauber geschützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. (3 Sek. Abklingzeit)\nBenötigt Steinschuppenöl (30), Bergsilberweisling (10), Schwarzer Lotus , Kristallphiole"},
