[16110] = {name = "Rezept: Monsteromelett", additional_info = "Benötigt Kochkunst (225)\n[q2]Benutzen: Lehrt Euch, wie man ein Monsteromelett zubereitet.\nMonsteromelett\nBenötigt Stufe 40\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. 1392 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 12 Punkt(e) Ausdauer und Willenskraft.\nBenötigt Riesenei , Feine Gewürze (2)"},
[16111] = {name = "Rezept: Gewürzter Chilikrebs", additional_info = "Benötigt Kochkunst (225)\n[q2]Benutzen: Lehrt Euch, wie man gewürzten Chilikrebs zubereitet.\nGewürzter Chilikrebs\nBenötigt Stufe 40\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. 1392 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 12 Punkt(e) Ausdauer und Willenskraft.\nBenötigt Zartes Krebsfleisch , Scharfe Gewürze (2)"},
[16112] = {name = "Handbuch: Schwerer Seidenverband", additional_info = "Benötigt Erste Hilfe (180)\n[q2]Benutzen: Lehrt Euch, wie man einen schweren Seidenverband herstellt.\nSchwerer Seidenverband\nBenötigt Erste Hilfe (125)\n[q2]Benutzen: Heilt 8 Sek. lang 640 Punkt(e) Schaden.\nBenötigt Seidenstoff (2)"},
