[18646] = {name = "[q4]Das Auge der Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\n[q]\"Ihr könnt Bewegungen ausmachen, wenn ihr in das Auge blickt.\"\n[q2]<Zum Lesen rechtsklicken>"},
[18647] = {name = "Bauplan: Rotes Feuerwerk", additional_info = "Benötigt Ingenieurskunst (150)\n[q2]Benutzen: Lehrt Euch die Herstellung von rotem Feuerwerk.\nRotes Feuerwerk\n[q2]Benutzen: Schießt ein Feuerwerk in die Luft, das in tausend rote Sterne explodiert.\nBenötigt Schweres Sprengpulver , Schweres Leder"},
[18648] = {name = "Bauplan: Grünes Feuerwerk", additional_info = "Benötigt Ingenieurskunst (150)\n[q2]Benutzen: Lehrt Euch die Herstellung von grünem Feuerwerk.\nGrünes Feuerwerk\n[q2]Benutzen: Schießt ein Feuerwerk in die Luft, das in tausend grüne Sterne explodiert.\nBenötigt Schweres Sprengpulver , Schweres Leder"},
[18649] = {name = "Bauplan: Blaues Feuerwerk", additional_info = "Benötigt Ingenieurskunst (150)\n[q2]Benutzen: Lehrt Euch die Herstellung von blauem Feuerwerk.\nBlaues Feuerwerk\n[q2]Benutzen: Schießt ein Feuerwerk in die Luft, das in tausend blaue Sterne explodiert.\nBenötigt Schweres Sprengpulver , Schweres Leder"},
[18650] = {name = "Bauplan: EZ-Thro-Dynamit II", additional_info = "Benötigt Ingenieurskunst (200)\n[q2]Benutzen: Lehrt Euch die Herstellung von EZ-Thro-Dynamit II.\nEZ-Thro-Dynamit II\nBenötigt Stufe 30\n[q2]Benutzen: Fügt 213 bis 287 Punkt(e) Feuerschaden in einem Umkreis von 5 Metern zu (sollte es das Ziel treffen; es gelten Beschränkungen). (1 Min Abklingzeit)\n[q]\"Das Dynamit für jedermann, das selten* in der Hand hochgeht, mit mehr als der doppelten Sprengkraft von einfachem EZ-Thro.\"\nBenötigt Robustes Sprengpulver , Magiestoff (2)"},
[18651] = {name = "Bauplan: Echtsilberumwandler", additional_info = "Benötigt Ingenieurskunst (260)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Echtsilber-Umwandlers.\nEchtsilberumwandler\nBenötigt Echtsilberbarren (2), Elementarerde (2), Elementarluft"},
[18652] = {name = "Bauplan: Gyrofrosteisreflektor", additional_info = "Benötigt Ingenieurskunst (260)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Gyrofrosteisreflektors.\n[q3]Gyrofrosteisreflektor\nWird beim Anlegen gebunden\nSchmuck\n+15 Frostwiderstand\nBenötigt Stufe 47\nBenötigt Ingenieurskunst (260)\n[q2]Benutzen: Reflektiert Frostzauber für 5 Sek. zurück auf den Zaubernden. (5 Min Abklingzeit)\nBenötigt Thoriumapparat (6), Echtsilberumwandler (2), Blauer Saphir (2), Essenz des Feuers (4), Frostöl (2), Eiskappe (4)"},
[18653] = {name = "[q2]Bauplan: Goblin-Überbrückungskabel XL", additional_info = "Benötigt Ingenieurskunst (265)\nBenötigtGoblin-Ingenieur\n[q2]Benutzen: Lehrt Euch die Herstellung von Goblin-Überbrückungskabeln XL\nGoblin-Überbrückungskabel XL\nSchmuck\nBenötigt Ingenieurskunst (265)\n[q2]Benutzen: Mit Überbrückungskabeln kann man manchmal einen toten Spieler ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\nBenötigt Thoriumapparat (2), Echtsilberumwandler (2), Verschmorte Verkabelung (2), Eisenweberseide (2), Sternrubin (2)"},
[18654] = {name = "[q2]Bauplan: Gnomischer Alarm-O-Bot", additional_info = "Benötigt Ingenieurskunst (265)\nBenötigtGnomen-Ingenieur\n[q2]Benutzen: Lehrt Euch die Herstellung eines Alarm-O-Bots.\nGnomsicher Alarm-O-Bot\nBenötigt Ingenieurskunst (265)\n[q2]Benutzen: Erschafft für 10 Minuten einen Alarm-O-Bot, der in regelmäßigen Abständen einen Impuls aussendet, welcher getarnte oder unsichtbare Einheiten aufspürt. (10 Min Abklingzeit)\nBenötigt Thoriumbarren (4), Thoriumapparat (2), Unverwüstliches Leder (4), Sternrubin , Verschmorte Verkabelung"},
[18655] = {name = "[q2]Bauplan: Großer Rekombobulator", additional_info = "Benötigt Ingenieurskunst (275)\n[q2]Benutzen: Lehrt Euch die Herstellung eines großen Rekombobulator.\n[q2]Großer Rekombobulator\nSchmuck\nBenötigt Ingenieurskunst (275)\n[q2]Benutzen: Bannt Verwandlungseffekte von einem befreundeten Ziel. Stellt außerdem noch 375 bis 625 Punkt(e) Gesundheit und Mana wieder her. (5 Min Abklingzeit)\n10 Aufladungen\nBenötigt Thoriumröhre (2), Echtsilberumwandler , Runenstoff (2)"},
[18656] = {name = "Bauplan: Mächtige Zephyriumladung", additional_info = "Benötigt Ingenieurskunst (275)\n[q2]Benutzen: Lehrt Euch die Herstellung von mächtigen Zephyriumladungen.\nMächtige Zephyriumladung\nBenötigt Ingenieurskunst (275)\n[q2]Benutzen: Sprengt fast jede verschlossene Tür auf.\nBenötigt Thoriumapparat (2), Dichtes Sprengpulver (3), Unverwüstliches Leder (2), Erfrischendes Quellwasser"},
[18657] = {name = "[q2]Bauplan: Hyperstrahlender Flammenreflektor", additional_info = "Benötigt Ingenieurskunst (290)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Hyperstrahlenden Flammenreflektors.\n[q3]Hyperstrahlender Flammenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+18 Feuerwiderstand\nBenötigt Stufe 53\nBenötigt Ingenieurskunst (290)\n[q2]Benutzen: Reflektiert Feuerzauber für 5 Sek. zurück auf den Zaubernden. (5 Min Abklingzeit)\nBenötigt Dunkeleisenbarren (4), Echtsilberumwandler (3), Essenz des Wassers (6), Sternrubin (4), Azerothianischer Diamant (2)"},
[18658] = {name = "[q2]Bauplan: Ultrablendender Schattenreflektor", additional_info = "Benötigt Ingenieurskunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Ultrablendenden Schattenreflektors.\n[q3]Ultrablendender Schattenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+20 Schattenwiderstand\nBenötigt Stufe 55\nBenötigt Ingenieurskunst (300)\n[q2]Benutzen: Reflektiert Schattenzauber für 5 Sek. zurück auf den Zaubernden. (5 Min Abklingzeit)\nBenötigt Dunkeleisenbarren (8), Echtsilberumwandler (4), Essenz des Lebens (6), Essenz des Untodes (4), Azerothianischer Diamant (2), Großer Opal (2)"},
[18659] = {name = "[q4]Splitter von Nordrassil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\n[q2]Benutzen: Formt eine Segnung wenn mit dem Auge der Schatten und dem Auge der Offenbarung kombiniert.\n[q]\"Ein kleines Fragment des Weltenbaumes\""},
[18660] = {name = "[q2]Weltvergrößerer", additional_info = "Benötigt Ingenieurskunst (250)\nBenötigtGnomen-Ingenieur\n[q2]Benutzen: Vergrößert die gesamte Welt 5 Min. lang oder bis Ihr angreift. (1 Stunde Abklingzeit)\n[q]\"Nur die Technologie der Gnome konnte ein Gerät erfinden, das die ganze Welt revolutionieren würde!\""},
[18661] = {name = "[q2]Bauplan: Weltvergrößerer", additional_info = "Benötigt Ingenieurskunst (260)\nBenötigtGnomen-Ingenieur\n[q2]Benutzen: Lehrt Euch die Herstellung eines Weltvergrößerers.\n[q2]Weltvergrößerer\nBenötigt Ingenieurskunst (250)\nBenötigtGnomen-Ingenieur\n[q2]Benutzen: Vergrößert die gesamte Welt 5 Min. lang oder bis Ihr angreift. (1 Stunde Abklingzeit)\n[q]\"Nur die Technologie der Gnome konnte ein Gerät erfinden, das die ganze Welt revolutionieren würde!\"\nBenötigt Mithrilgehäuse , Thoriumapparat (2), Goldkraftkern , Instabiler Auslöser , Citrin"},
[18662] = {name = "Schwerer Lederball", additional_info = "Einzigartig (10)\n[q2]Benutzen: Werft den Ball einem freundlich gesinnten Spieler zu. Falls er Platz in seinem Rucksack besitzt, wird er ihn fangen!"},
