[19237] = {name = "Sayges Horoskop Nr. 19", additional_info = "Wird beim Aufheben gebunden\n[q]\"Die Verlassenen haben etwas vor.\""},
[19238] = {name = "Sayges Horoskop Nr. 3", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein früherer Gegner wird bald zu einem Verbündeten werden.\""},
[19239] = {name = "Sayges Horoskop Nr. 4", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ihr werdet bei allem ein glückliches Händchen haben.\""},
[19240] = {name = "Sayges Horoskop Nr. 5", additional_info = "Wird beim Aufheben gebunden\n[q]\"Jemand spricht gut von Euch.\""},
[19241] = {name = "Sayges Horoskop Nr. 6", additional_info = "Wird beim Aufheben gebunden\n[q]\"Seid vorsichtig, wenn Ihr in nicht vertrauten Gebieten landet.\""},
[19242] = {name = "Sayges Horoskop Nr. 7", additional_info = "Wird beim Aufheben gebunden\n[q]\"Vermeidet unnötige Risiken.\""},
[19243] = {name = "Sayges Horoskop Nr. 8", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ihr werdet ein Vermögen erhalten.\""},
[19244] = {name = "Sayges Horoskop Nr. 9", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eure erste und letzte Liebe ist Eigenliebe.\""},
[19245] = {name = "Sayges Horoskop Nr. 10", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ruhe ist eine gute Sache, doch Langweile ist dessen Bruder.\""},
[19246] = {name = "Sayges Horoskop Nr. 10", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diejenigen, die einen einfachen Geschmack haben, sind immer mit dem Besten zufrieden.\""},
[19247] = {name = "Sayges Horoskop Nr. 12", additional_info = "Wird beim Aufheben gebunden\n[q]\"Lasst Euch nicht von den Fluten des Krieges hinwegspülen.\""},
[19248] = {name = "Sayges Horoskop Nr. 13", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ihr macht Eure Gegner sprachlos.\""},
[19249] = {name = "Sayges Horoskop Nr. 14", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ihr habt einen guten Riecher für Heuchlerei.\""},
[19250] = {name = "Sayges Horoskop Nr. 15", additional_info = "Wird beim Aufheben gebunden\n[q]\"So manch einer lernt mehr, wenn er andere unterrichtet.\""},
[19251] = {name = "Sayges Horoskop Nr. 16", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ihr werdet bald eine dringliche Entscheidung fällen müssen.\""},
[19252] = {name = "Sayges Horoskop Nr. 18", additional_info = "Wird beim Aufheben gebunden\n[q]\"Nehmt den nächsten Vorschlag an, der Euch zu Ohren kommt.\""},
[19253] = {name = "Sayges Horoskop Nr. 17", additional_info = "Wird beim Aufheben gebunden\n[q]\"Stoßt einen Gnom niemals grundlos an.\""},
[19254] = {name = "Sayges Horoskop Nr. 21", additional_info = "Wird beim Aufheben gebunden\n[q]\"Gottesschilder und Ruhesteine machen einen Helden nicht heldenhaft.\""},
[19255] = {name = "Sayges Horoskop Nr. 22", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eine blaue Antwort ist immer eine schlaue Antwort.\""},
[19256] = {name = "Sayges Horoskop Nr. 2", additional_info = "Wird beim Aufheben gebunden\n[q]\"Morgen werdet Ihr etwas Wunderschönes finden.\""},
