[19318] = {name = "Abgefülltes Alteracquellwasser", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 55\n[q2]Benutzen: Stellt 30 Sek. lang, 4410 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Erhöht zusätzlich Eure Willenskraft für 10 Min. lang um 10.\n[q]\"Aus den Bergquellen von Alterac!\""},
[19319] = {name = "[q3]Köcher aus Harpienhaut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n16 Platz Köcher\nBenötigt Stufe 55\n[q2]Anlegen: Erhöht das Distanzangriffstempo um 15%."},
