[19321] = {name = "[q4]Das unbewegliche Objekt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n2468 Rüstung\n44 Blocken\n+15 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Blockwert Eures Schildes um 27."},
[19322] = {name = "[q2]Ehrenabzeichen der Warsong", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q]\"Beweis für einen siegreichen Kampf in der Warsongschlucht\""},
[19323] = {name = "[q4]Die unaufhaltbare Macht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Streitkolben}\n{175 - 292 Schaden} {Tempo 3.80}\n(61.45 Schaden pro Sekunde)\n+19 Stärke\n+15 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 2%.\n[q2]Trefferchance: Betäubt ein Ziel 1 Sek. lang."},
[19324] = {name = "[q4]Der Geistesbrecher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Einhändig} {Dolch}\n{59 - 111 Schaden} {Tempo 1.80}\n(47.22 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Trefferchance: Verwundet das Ziel für 200 bis 300 Schaden und verringert 30 Sek. lang dessen Intelligenz um 25."},
[19325] = {name = "[q4]Don Julios Band", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+11 Ausdauer\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\n[q2]Anlegen: Verbessert Eure Trefferchance um 1%.\n[q2]Anlegen: +16 Angriffskraft."},
[19326] = {name = "Muster: Macht der Holzschlundfeste", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (290)\nBenötigtHolzschlundfeste\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch die Herstellung der Macht der Holzschlundfeste.\n[q3]Macht der Holzschlundfeste\nWird beim Anlegen gebunden\n{Taille} {Leder}\n93 Rüstung\n+21 Stärke\n+9 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 53\nBenötigt Unverwüstliches Leder (30), Mächtiges Mojo (2), Essenz des Lebens (4), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (2)"},
[19327] = {name = "Muster: Kampfhandschuhe der Holzschlundfeste", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (300)\nBenötigtHolzschlundfeste\n- Respektvoll\n[q2]Benutzen: Lehrt Euch die Herstellung der Kampfhandschuhe der Holzschlundfeste.\n[q3]Kampfhandschuhe der Holzschlundfeste\nWird beim Anlegen gebunden\n{Hände} {Leder}\n112 Rüstung\n+23 Stärke\n+10 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 59\nBenötigt Verzaubertes Leder (8), Mächtiges Mojo (6), Essenz des Lebens (6), Geschmeidiger unverwüstlicher Balg (2), Eisenweberseide (2)"},
[19328] = {name = "Muster: Stiefel der Dämmerung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (290)\nBenötigtArgentumdämmerung\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch die Herstellung der Stiefel der Dämmerung.\n[q3]Stiefel der Dämmerung\nWird beim Anlegen gebunden\n{Füße} {Leder}\n114 Rüstung\n+18 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Stufe 53\n[q2]Anlegen: Erhöht Eure Chance, einem Angriff auszuweichen, um 1%.\nBenötigt Unverwüstliches Leder (30), Wächterstein (2), Essenz des Wassers (4), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (2)"},
[19329] = {name = "Muster: Goldener Mantel der Dämmerung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (300)\nBenötigtArgentumdämmerung\n- Respektvoll\n[q2]Benutzen: Lehrt Euch die Herstellung des Goldenen Mantels der Dämmerung.\n[q3]Goldener Mantel der Dämmerung\nWird beim Anlegen gebunden\n{Schulter} {Leder}\n134 Rüstung\n+22 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 59\n[q2]Anlegen: Erhöht Eure Chance, einem Angriff auszuweichen, um 1%.\nBenötigt Verzaubertes Leder (8), Essenz des Lebens (4), Wächterstein (4), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (2)"},
[19330] = {name = "Muster: Lavagürtel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Lavagürtels.\n[q4]Lavagürtel\nWird beim Anlegen gebunden\n{Taille} {Leder}\n[q2]223 Rüstung\n+15 Ausdauer\n+26 Feuerwiderstand\nHaltbarkeit 40 / 40\nBenötigt Stufe 60\nBenötigt Lavakern (5), Geschmeidiger unverwüstlicher Balg (4), Eisenweberseide (4)"},
[19331] = {name = "Muster: Chromatische Stulpen", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (300)\nBenötigtDrachenlederverarbeitung\n[q2]Benutzen: Lehrt Euch die Herstellung von Chromatischen Stulpen.\n[q4]Chromatische Stulpen\nWird beim Anlegen gebunden\n{Hände} {Kette}\n279 Rüstung\n+5 Feuerwiderstand\n+5 Naturwiderstand\n+5 Frostwiderstand\n+5 Schattenwiderstand\nHaltbarkeit 50 / 50\nBenötigt Stufe 60\n[q2]Anlegen: +44 Angriffskraft.\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 1%.\nBenötigt Feuerkern (5), Lavakern (2), Kernleder (4), Glänzende chromatische Schuppe (4), Geschmeidiger unverwüstlicher Balg (4), Eisenweberseide (4)"},
