[19956] = {name = "[q4]Wushoolays Amulett der Geister", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Schamane\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht den Schaden Eures Zaubers 'Blitzschlagschild' um 100%. Hält 20 Sek. lang an. (3 Min Abklingzeit)\n\n[q]Ornat des Weissagers (0/5)\n[q0]Unversehrte Vision von Voodress\nWushoolays Amulett der Geister\nZandalarianischer Armschienen des Weissagers\nZandalarianischer Gürtel des Weissagers\nZandalarianische Halsberge des Weissagers\n[q0](2) Set : Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\n(3) Set : Verbessert die Gesamtdauer Eures Zaubers 'Frostschock' um 1 Sekunden.\n(5) Set : Erhöht den Radius Eures Zaubers 'Blitzschlag' um 5 Meter."},
[19957] = {name = "[q4]Hazza'rahs Amulett der Zerstörung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Hexenmeister\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht die Chance auf einen kritischen Treffer Eurer Zerstörungszauber um 10%. Hält 20 Sek. lang an. (3 Min Abklingzeit)\n\n[q]Roben des Besessenen (0/5)\n[q0]Kezans unaufhaltsame Schmach\nHazza'rahs Amulett der Zerstörung\nZandalarianische Handlappen des Besessenen\nZandalarianischer Mantel des Besessenen\nZandalarianische Robe des Besessenen\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht den Schaden Eures Zaubers 'Verderbnis' um 2%.\n(5) Set : Verringert die Abklingzeit Eures Zaubers 'Todesmantel' um 15%."},
[19958] = {name = "[q4]Hazza'rahs Amulett der Heilung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\n[q2]Benutzen: Reduziert die Zauberzeit Eurer Zauber 'Große Heilung' um 40% und verringert 15 Sek. lang, die Manakosten Eurer Heilzauber um 5%. (3 Min Abklingzeit)\n\n[q]Gewandung des Glaubenshüters (0/5)\n[q0]Das allsehende Auge von Zuldazar\nHazza'rahs Amulett der Heilung\nZandalarianische Handlappen des Glaubenshüters\nZandalarianische Bindungen des Glaubenshüters\nZandalarianischer Mantel des Glaubenshüters\n[q0](2) Set : Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 22.\n(3) Set : Erhöht die Reichweite Eurer Zauber 'Göttliche Pein' und 'Heiliges Feuer' um 5 Meter.\n(5) Set : Reduziert die Zauberzeit Eures Zaubers 'Gedankenkontrolle' um 0.5 Sekunden."},
[19959] = {name = "[q4]Hazza'rahs Amulett der Magie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Magier\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht die Chance auf einen kritischen Treffer mit Euren Arkanzaubern um 5% Â und erhöht zusätzlich 20 Sek. lang den Schaden eines kritischen Treffers mit Arkanzaubern um 50%. (3 Min Abklingzeit)\n\n[q]Roben des Illusionisten (0/5)\n[q0]Juwel von Kajaro\nHazza'rahs Amulett der Magie\nZandalarianische Handlappen des Illusionisten\nZandalarianischer Mantel des Illusionisten\nZandalarianische Robe des Illusionisten\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Verringert die Manakosten Eurer Zauber 'Arkane Intelligenz' und 'Arkane Brillanz' um 5%.\n(5) Set : Reduziert die Zauberzeit Eures Zaubers 'Flammenstoß' um 0.5 Sekunden."},
