[20033] = {name = "[q0]Zandalarianische Robe des Besessenen", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Stoff}\n100 Rüstung\n+35 Ausdauer\nHaltbarkeit 100 / 100\nKlassen: Hexenmeister\n[q2]Anlegen: Erhöht Eure Chance mit Zaubern zu treffen um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 27.\n\n[q]Roben des Besessenen (0/5)\n[q0]Kezans unaufhaltsame Schmach\nHazza'rahs Amulett der Zerstörung\nZandalarianische Handlappen des Besessenen\nZandalarianischer Mantel des Besessenen\nZandalarianische Robe des Besessenen\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht den Schaden Eures Zaubers 'Verderbnis' um 2%.\n(5) Set : Verringert die Abklingzeit Eures Zaubers 'Todesmantel' um 15%."},
[20034] = {name = "[q0]Zandalarianische Robe des Illusionisten", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Stoff}\n100 Rüstung\n+23 Ausdauer\n+24 Intelligenz\nHaltbarkeit 100 / 100\nKlassen: Magier\n[q2]Anlegen: Erhöht Eure Chance mit Zaubern zu treffen um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 27.\n\n[q]Roben des Illusionisten (0/5)\n[q0]Juwel von Kajaro\nHazza'rahs Amulett der Magie\nZandalarianische Handlappen des Illusionisten\nZandalarianischer Mantel des Illusionisten\nZandalarianische Robe des Illusionisten\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Verringert die Manakosten Eurer Zauber 'Arkane Intelligenz' und 'Arkane Brillanz' um 5%.\n(5) Set : Reduziert die Zauberzeit Eures Zaubers 'Flammenstoß' um 0.5 Sekunden."},
[20035] = {name = "[q3]Gletscherstachel", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Dolch}\n{31 - 59 Schaden} {Tempo 1.30}\n(34.62 Schaden pro Sekunde)\n+4 Intelligenz\nHaltbarkeit 65 / 65\n[q2]Anlegen: Eure Frostblitzzauber haben eine Chance von 6%, dass sie 50 Mana regenerieren.\n[q]\"Teuflische Runen zieren die Klinge.\""},
[20036] = {name = "[q3]Feuerrubin", additional_info = "Wird beim Aufheben gebunden\nSchmuck\n[q2]Benutzen: Erhöht den Schaden Eures nächsten Feuerzaubers um bis zu 100 und stellt 1 bis 500 Mana wieder her. Effekt hält 1 Min. lang an. (3 Min Abklingzeit)\n[q]\"Unberechenbarkeit führt zu beidem, Sieg und Tod.\""},
[20037] = {name = "[q3]Arkankristallanhänger", additional_info = "Wird beim Aufheben gebunden\nHals\n+6 Intelligenz\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 16.\n[q]\"Magier wissen Arkankristalle am Besten für ihre Zwecke zu gebrauchen.\""},
