[20070] = {name = "[q4]Klaue der Weisheit", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Dolch}\n{46 - 95 Schaden} {Tempo 1.70}\n(41.47 Schaden pro Sekunde)\n40 Rüstung\n+8 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nBenötigtDer Bund von Arathor\n- Ehrfürchtig\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 30.\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 1%."},
[20071] = {name = "[q3]Talisman von Arathor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 58\nBenötigtDer Bund von Arathor\n- Freundlich\n[q2]Benutzen: Absorbiert 495 bis 605 Punkt(e) körperlichen Schaden. Hält 15 Sek. lang an. (3 Min Abklingzeit)"},
