[20073] = {name = "[q4]Umhang der Ehrenwache", additional_info = "Wird beim Aufheben gebunden\nRücken\n50 Rüstung\n+5 Beweglichkeit\n+11 Ausdauer\nBenötigt Stufe 60\nBenötigtDer Bund von Arathor\n- Ehrfürchtig\n[q2]Anlegen: +34 Angriffskraft."},
[20074] = {name = "Schwerer Krokiliskeneintopf", additional_info = "Benötigt Stufe 20\n[q2]Benutzen: Stellt im Verlauf von 27 Sek. 874.8 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 8 Punkt(e) Ausdauer und Willenskraft."},
[20075] = {name = "Rezept: Schwerer Krokiliskeneintopf", additional_info = "Benötigt Kochkunst (150)\n[q2]Benutzen: Lehrt Euch, wie man einen schweren Krokiliskeneintopf zubereitet.\nSchwerer Krokiliskeneintopf\nBenötigt Stufe 20\n[q2]Benutzen: Stellt im Verlauf von 27 Sek. 874.8 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 8 Punkt(e) Ausdauer und Willenskraft.\nBenötigt Zartes Krokiliskenfleisch (2), Feine Gewürze"},
[20076] = {name = "[q3]Zandalarianisches Siegel des Mojo", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft eine um bis zu 18 erhöhte Schadens- und Heilwirkung durch Zauber und magische Effekte hinzu."},
[20077] = {name = "[q3]Zandalarianisches Siegel der Macht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft 30 Angriffskraft hinzu."},
[20078] = {name = "[q3]Zandalarianisches Siegel der inneren Ruhe", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft eine um bis zu 33 erhöhte Heilwirkung durch Zauber und magische Effekte hinzu."},
[20079] = {name = "[q2]Zanzas Geist", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht Â 2 Stunden lang die Willenskraft des Spielers um 50 und die Ausdauer um 50. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein. (3 Sek. Abklingzeit)\n[q]\"Gesegnet mit Zanzas Mojo!\""},
[20080] = {name = "[q2]Zanzas Glanz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht die Chance, feindliche Zauber zu reflektieren, um 3%. Hält 2 Stunden lang an. Der erste Angriffszauber gegen den Nutzer wird automatisch reflektiert. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein. (2 Min Abklingzeit)\n[q]\"Gesegnet mit Zanzas Mojo!\""},
[20081] = {name = "[q2]Zanzas Schnelligkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht das Lauftempo des Spielers 2 Stunden lang um 20%. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein. (3 Sek. Abklingzeit)\n[q]\"Gesegnet mit Zanzas Mojo!\""},
