[21215] = {name = "Graccus hausgemachte Früchtepastete", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 40\n[q2]Benutzen: Stellt 20 Sek. lang jede Sekunde 5% Eurer Gesundheit und Eures Manas wieder her. Ihr müsst beim Essen sitzen bleiben. Lasst Euch den leckeren Stollen schmecken.\n[q]\"Mit Graccus Spezialgewürzen haltbar gemacht! Es wird eine ganze Weile dauern, bis das hier schlecht wird...\""},
[21216] = {name = "Kokelwälder Extraspezialgeschenk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Öffnen rechtsklicken>"},
[21217] = {name = "Weisenfisch Supreme", additional_info = "Benötigt Stufe 30\n[q2]Benutzen: Stellt im Verlauf von 21 Sek. 840.0 Gesundheit und 1260 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 6 Mana."},
[21218] = {name = "[q3]Blauer Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Stößt ein Hochfrequenzsignal aus, das eine Qirajipanzerdrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithide gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindseligen Handlungen gegen den Reiter zwingen die Qirajipanzerdrohne, sich wieder einzugraben. (3 Sek. Abklingzeit)"},
[21219] = {name = "Rezept: Weisenfisch Supreme", additional_info = "Benötigt Kochkunst (175)\n[q2]Benutzen: Lehrt Euch, wie man Weisenfisch Surpreme zubereitet.\nWeisenfisch Supreme\nBenötigt Stufe 30\n[q2]Benutzen: Stellt im Verlauf von 21 Sek. 840.0 Gesundheit und 1260 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 6 Mana.\nBenötigt Roher großer Weisenfisch , Scharfe Gewürze"},
