[23722] = {name = "Ewige R.O.I.D.S.", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Erhöht bei Verzehr die Stärke um 25.\n[q]\"Von Kicherfang stammende robuste funktionstüchtige Magiefüllung\""},
[23725] = {name = "QAEnchant Fiery Weapon", additional_info = "[q2]Benutzen: Eine Nahkampfwaffe dauerhaft so verzaubern, dass sie beim Schlag oft zusätzliche 40 Feuerschaden verursacht."},
[23727] = {name = "QAEnchant Gloves +5 Fishing", additional_info = "[q2]Benutzen: Handschuhe dauerhaft so verzaubern, dass sie die Angelfertigkeit um +2 erhöhen."},
[23728] = {name = "QAEnchant Gloves Riding Skill", additional_info = "Benutzen: Handschuhe dauerhaft so verzaubern, dass sie beim Reiten einen geringfügigen Bonus auf das Bewegungstempo gewähren."},
[23743] = {name = "[q0]Monster - Sword 1H - Widow's Remorse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Einhändig} {Schwert}\n{1 - 2 Schaden} {Tempo 2.00}\n(0.75 Schaden pro Sekunde)\nHaltbarkeit 20 / 20"},
[23794] = {name = "[q2]Zanzas ewiger Glanz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht die Chance, feindliche Zauber zu reflektieren, um 3%. Hält 2 Stunden lang an. Der erste Angriffszauber gegen den Nutzer wird automatisch reflektiert. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein.\n[q]\"Gesegnet mit Zanzas Mojo!\""},
[23795] = {name = "[q2]Zanzas ewiger Geist", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht Â 2 Stunden lang die Willenskraft des Spielers um 50 und die Ausdauer um 50. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein.\n[q]\"Gesegnet mit Zanzas Mojo!\""},
[23796] = {name = "[q2]Zanzas ewige Schnelligkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht das Lauftempo des Spielers 2 Stunden lang um 20%. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein.\n[q]\"Gesegnet mit Zanzas Mojo!\""},
[24071] = {name = "[q3]Schmuckloser Dolch", additional_info = "{Einhändig} {Dolch}\n{82 Schaden} {Tempo 1.80}\n(45.56 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\n[q]\"Sieht aus, als wäre er nur für interne Testzwecke.\""},
[24101] = {name = "[q3]Buch des wilden Bisses V", additional_info = "Klassen: Druide\nBenötigt Stufe 60\n[q2]Benutzen: Lehrt 'Wilder Biss' (Rang 5)."},
[24102] = {name = "[q3]Handbuch des Ausweidens IX", additional_info = "Klassen: Schurke\nBenötigt Stufe 60\n[q2]Benutzen: Lehrt 'Ausweiden' (Rang 9)."},
[24222] = {name = "[q3]Dolch des schleichenden Todes", additional_info = "Wird beim Anlegen gebunden\n{Einhändig} {Dolch}\n{47 - 88 Schaden} {Tempo 1.80}\n(37.50 Schaden pro Sekunde)\n+8 Ausdauer\nHaltbarkeit 65 / 65\nBenötigt Stufe 52\n[q2]Anlegen: +18 Angriffskraft."},
[24231] = {name = "[q0]Grober Schnupftabak", additional_info = nil},
[24232] = {name = "[q0]Schäbiger Knoten", additional_info = nil},
[24281] = {name = "[q0]Geschnitzter Elfenbeinknochen", additional_info = "[q]\"Es sieht aus, als wäre die Schnitzerei nicht beendet worden...\""},
[24282] = {name = "[q0]Tagebuch eines Schurken", additional_info = "[q0]Verschlossen"},
[24283] = {name = "[q0]Altmodisches Gewehr", additional_info = "[q]\"Der Name 'Lasitor' ist in den Lauf eingraviert.\""},
[122270] = {name = "[q8]WoW-Marke", additional_info = "Wird beim Aufheben gebunden\n[q]\"Kann gegen Gold im Auktionshaus verkauft werden. Der Gewinner der Auktion kann die Marke für 30 Tage Spielzeit einlösen.\""},
[122284] = {name = "[q8]WoW-Marke", additional_info = "Wird beim Aufheben gebunden\n[q]\"Benutzen: Fügt Ihrem World of Warcraft-Account 30 Tage Spielzeit hinzu.\""},
[172070] = {name = "Kundendienstpaket", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält Ausrüstung für Eure Klasse und Stufe. Benötigt 15 verfügbare Inventarplätze.\""},
[180089] = {name = "Pandahalsband", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Mit Rechtsklick Euer Pandababy beschwören und freigeben."},
[184937] = {name = "Chronostärkungsversetzer", additional_info = "[q2]Benutzen: Verändert das Gefüge der Zeit und bewahrt positive Welteffekte auf, die aus Düsterbruch, Zul'Gurub und dem Teufelswald, sowie vom Drachentöten stammen. (1 Stunde Abklingzeit)"},
[184938] = {name = "[q2]Überladener Chronostärkungsversetzer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die aufgehobenen Weltstärkungseffekte wieder her."},
[189419] = {name = "Fire Resist Plate Gear", additional_info = "[q2]<Zum Öffnen rechtsklicken>"},
[189420] = {name = "Fire Resist Plate Gear", additional_info = "[q2]<Zum Öffnen rechtsklicken>"},
[189421] = {name = "Fire Resist Leather Gear", additional_info = "[q2]<Zum Öffnen rechtsklicken>"},
