[190180] = {name = "Isaacs Herz", additional_info = "Questgegenstand\nEinzigartig"},
[190181] = {name = "Herz der Liebenden", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Ruft mit dem Beschwörungskreis einen Inkubus herbei. (3 Min Abklingzeit)"},
[190186] = {name = "Holzstatuette", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Ruft mit dem Beschwörungskreis einen Inkubus herbei. (3 Min Abklingzeit)\n[q]\"In den Sockel ist etwas graviert: Ich bin wieder zu Hause.\""},
[190187] = {name = "Abgetragener Schal", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Ruft mit dem Beschwörungskreis einen Inkubus herbei. (3 Min Abklingzeit)\n[q]\"Der Stoff ist mit feinen Mustern bestickt, sowie den Buchstaben 'M+K'.\""},
[190232] = {name = "Abgetragener Schal", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Der Stoff ist mit feinen Mustern bestickt, sowie den Buchstaben 'M+K'.\""},
[190307] = {name = "Nicht angezündete Fackel", additional_info = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\n[q]\"Wisst Ihr, was diese Fackel gebrauchen könnte? Eine Flamme.\""},
[190308] = {name = "Brennende Fackel", additional_info = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\nDauer: 5 min\n[q2]Benutzen: Wirft eine Fackel auf die Zielposition und entzündet ein Feuer.\n[q]\"Nützlich, um für feurige Ablenkung zu sorgen!\""},
[190309] = {name = "Holzstatuette", additional_info = "Questgegenstand\nEinzigartig\n[q]\"In den Sockel ist etwas graviert: Ich bin wieder zu Hause.\""},
[190325] = {name = "[q0]Monster - Peitschenstreitkolben des Inkubus, 1H", additional_info = "{Einhändig} {Streitkolben}"},
[191204] = {name = "[q2]Geringer Todesstein", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Macht aus 100 geringen Todessteinen einen großen Todesstein."},
[191249] = {name = "[q2]Großer Todesstein", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein grüner Stein, in dem unbekannte Energie leuchtet.\""},
[191267] = {name = "[q2]Rune der Teleportation: Vorkammer", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Teleportiert Euch in die Vorkammer in Naxxramas."},
[191268] = {name = "[q2]Kugel der Verderbnis", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Zerschmettert die Kugel und erhöht so die von Kel'Thuzads Dienern absorbierte Menge geringer Todessteine 30 Min. lang um 50%."},
[191272] = {name = "[q3]Rute der Totenbeschwörung", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Unterwirft den Willen eines untoten Ziels in Naxxramas, sodass es 5 Min. lang bezaubert wird.\n3 Aufladungen"},
[191280] = {name = "[q3]Pilzsporenansammlung", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Gewährt Euren offensiven Fähigkeiten eine Chance, eine Spore zu beschwören, die Spielercharaktere in der Nähe mit 'Pilzwucher' belegt, wenn sie getötet wird. Dieser Effekt hält 1 Stunde lang an.\n\nPilzwucher \nVerursacht alle 1 Sek. 150 Naturschaden und erhöht die Chance auf einen kritischen Treffer mit Nahkampf-, Distanzangriffen und Zaubern um 15%. (Procchance: 10%, 15s Abklingzeit)"},
[191288] = {name = "[q4]Rune der Teleportation: Hort des Frostwyrms", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Teleportiert Euch zum Hort des Frostwyrms in Naxxramas."},
[191292] = {name = "[q3]Ritualdolch", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Absorbiert die Lebenskraft derer in Eurer Umgebung und erhöht so die Ausdauer pro getroffenem Ziel um 3. Dieser Effekt ist bis zu 40-mal stapelbar und hält 1 Stunde lang an."},
[191312] = {name = "[q4]Vorsorgephylakterium", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagenSchmuck\nBenötigt Stufe 60\n[q2]Anlegen: Verhindert einen Angriff, der Euch ansonsten töten würde. Wenn dieser Effekt ausgelöst wird, werdet Ihr 3 Sek. lang immun gegen Schaden und das Phylakterium wird zerstört."},
[191313] = {name = "Maske des Todes", additional_info = "Dauer: 7 tagen\n[q2]Benutzen: Nehmt das Antlitz eines Bewohners von Naxxramas an."},
[191414] = {name = "[q3]Skelettartefakt", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Fängt die Seele des toten Ziels ein und gewährt Euch so einen vorteilhaften Effekt. Dieser Effekt hält 1 Stunde lang an."},
[191458] = {name = "[q0]Zerschmettertes Phylakterium", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagenSchmuck\nBenötigt Stufe 60\n[q]\"Glanz- und nutzlos.\""},
[191459] = {name = "[q4]Rune des Glücks", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Ermächtigt Kel'Thuzad und seinen Untergebenen mit nekromantischer Energie, was ihnen erhöhte Gesundheit und erhöhten Schaden gewährt. Ermächtigte Gegner bedeuten zusätzliche Belohnungen, wenn sie besiegt werden.\n\n Dieser Effekt ist stapelbar und hält eine ganze Woche lang an."},
[191477] = {name = "[q4]Skelettanbindepfosten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört einen Skelettanbindepfosten.\n\n Gruppenmitglieder können den Pfosten verwenden, um ein Skelettross zu erhalten."},
[191480] = {name = "[q4]Skelettross", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\nReittier\nBenötigt Stufe 40\n[q2]Benutzen: Beschwört ein Skelettross oder gibt es wieder frei. Dieses Ross gehorcht dem Beschwörenden und kann als Reittier in Naxxramas genutzt werden. Feindliche Aktionen gegenüber dem Reiter lassen das Ross furchterfüllt fliehen. (3 Sek. Abklingzeit)"},
[191481] = {name = "[q4]Wappenrock der Meisterschaft", additional_info = "Wird beim Aufheben gebunden\nWappenrock\n[q]\"Ein Beweis für wahre Meisterschaft.\""},
[191550] = {name = "Buch der Todessteine: Maske des Todes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in eine Maske des Todes umzuwandeln.\""},
[191605] = {name = "[q2]Buch der Todessteine: Rune der Teleportation I", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in eine Rune der Teleportation umzuwandeln.\""},
[191606] = {name = "[q2]Buch der Todessteine: Kugel der Verderbnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in eine Kugel der Verderbnis umzuwandeln.\""},
[191607] = {name = "[q3]Buch der Todessteine: Skelettartefakt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in ein Skelettartefakt umzuwandeln.\""},
[191608] = {name = "[q3]Buch der Todessteine: Rute der Totenbeschwörung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in eine Rute der Totenbeschwörung umzuwandeln.\""},
[191609] = {name = "[q3]Buch der Todessteine: Pilzsporenansammlung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in eine Pilzsporenansammlung umzuwandeln.\""},
[191610] = {name = "[q3]Buch der Todessteine: Ritualdolch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in einen Ritualdolch umzuwandeln.\""},
[191611] = {name = "[q4]Buch der Todessteine: Vorsorgephylakterium", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in ein Vorsorgephylakterium umzuwandeln.\""},
[191612] = {name = "[q4]Buch der Todessteine: Rune der Teleportation II", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in eine Rune der Teleportation umzuwandeln.\""},
[191613] = {name = "[q4]Buch der Todessteine: Rune des Glücks", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in eine Rune des Glücks umzuwandeln.\""},
[191614] = {name = "[q4]Buch der Todessteine: Skelettanbindepfosten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in einen Skelettanbindepfosten umzuwandeln.\""},
[191656] = {name = "[q4]Essenz des Todes", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[191660] = {name = "[q3]Thaddius' Blitzbolzen", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Bringt die Bolzen an Eurem Hals an, sodass sie zufällig eine positive oder negative Ladung anwenden, die Schaden und Heilung um 1% erhöht.\n\n Dieser Effekt wird gestapelt, wenn sich Verbündete mit einer ähnlichen Ladung in der Nähe befinden, und fügt Verbündeten mit einer entgegengesetzten Ladung Naturschaden zu."},
[191661] = {name = "[q3]Monströser Spinnenfangzahn", additional_info = "Wird beim Aufheben gebunden\nDauer: 7 tagen\n[q2]Benutzen: Stecht Euch mit dem Fangzahn, was die Bewegungsgeschwindigkeit, das Angriffstempo und das Zaubertempo 1 Stunde lang um 15% erhöht. (Procchance: 5%, 30s Abklingzeit)"},
[191664] = {name = "[q3]Buch der Todessteine: Thaddius' Blitzbolzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in Thaddius' Blitzbolzen umzuwandeln.\""},
[191666] = {name = "[q3]Buch der Todessteine: Monströser Spinnenfangzahn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein Foliant über die Kunst, Todessteine in einen monströsen Spinnenfangzahn umzuwandeln.\""},
[202251] = {name = "Tüte mit Leckerlis", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Öffnet den Leckerlibeutel und steckt ihn in die Tasche Eures Ziels. Dadurch wird der Schaden, den Wildtiere diesem Ziel zufügen, um 20 erhöht. (1 Min Abklingzeit)"},
[202254] = {name = "[q3]Armschienen der Umlenkung", additional_info = "Wird beim Anlegen gebunden\n{Handgelenke} {Leder}\n44 Rüstung\n+11 Ausdauer\n+13 Intelligenz\n+8 Willenskraft\nHaltbarkeit 35 / 35\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 1%."},
[202256] = {name = "[q2]Verzierte Pistole des Freibeuters", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Schusswaffe}\n{6 - 13 Schaden} {Tempo 1.90}\n(5.00 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nKlassen: Schurke\n[q2]Anlegen: Erhaltet die Fähigkeit 'Pistolenheld':\n\n\nZieht Eure Fernkampfwaffe und feuert einen Schnellschuss auf einen Gegner ab, der normalen Distanzwaffenschaden verursacht und die Bewegungsgeschwindigkeit des Ziels 6 Sek. lang um 50% verringert. Gewährt 1 Combopunkt.\n\n 'Pistolenheld' profitiert von allen Talenten und Effekten, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren."},
[202641] = {name = "Schlammbedecktes Notizbuch.", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nKlassen: Schurke\n[q]\"Dieses Buch ist voller Schlamm, aber auf jeder Seite finden sich Runen und eine kurze Notiz in einer Art Geheimsprache.\""},
[203723] = {name = "Schnittis Notiz", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q]\"Eine in Diebesschrift verfasste Nachricht.\"\n[q2]<Zum Lesen rechtsklicken>"},
[203726] = {name = "[q2]Schnittis Rune", additional_info = "Klassen: Schurke"},
[203745] = {name = "[q2]Zaubernotizen: Eislanze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigtRunenschnitzen\n(1)\n[q2]Prägt Eure Handschuhe mit der Rune 'Eislanze':\n\n\nFügt dem gegnerischen Ziel [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 55 / 100 * ( 1 ) ] bis [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 65 / 100 * ( 1 ) ] Frostschaden zu. Fügt eingefrorenen Zielen 400% Schaden zu.\n\n Wenn Eure anderen Frostzauber einem Ziel, das nicht von einem Spielercharakter kontrolliert wird, Schaden zufügen, erhöhen sie den Schaden, den das Ziel durch Euren nächsten Einsatz von 'Eislanze' erleidet, um 20%. Dieser Effekt ist bis zu 5-mal stapelbar und benötigt das Talent 'Winterkälte'.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203746] = {name = "[q2]Zaubernotizen: Lebende Flamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigtRunenschnitzen\n(1)\n[q2]Prägt Eure Hosen mit der Rune 'Lebende Flamme':\n\n\nBeschwört eine Zauberfeuerflamme, die sich auf das Ziel zubewegt und einen Pfad aus Zauberfeuer hinterlässt. Dieser Pfad fügt Gegnern in der Nähe pro Sekunde [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100] Zauberfeuerschaden zu. Hält 10 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203747] = {name = "[q2]Zaubernotizen: Eisige Finger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigtRunenschnitzen\n(1)\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Eisige Finger':\n\n\nVerleiht Euren Kälteeffekten eine Chance von 25%, den Effekt 'Eisige Finger' hervorzurufen. Die eisigen Finger bewirken, dass Eure nächsten 2 gewirkten Zauber einen Effekt haben, den sie auf ein gefrorenes Ziel hätten. Hält 15 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203748] = {name = "[q2]Zaubernotizen: Feuerfontäne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euer Brustteil mit der Rune 'Feuerfontäne':\n\n\nErhöht die kritische Trefferchance aller Eurer Zauber um 15%, aber die kritischen Treffer Eurer Zauber ohne regelmäßige Effekte kosten zusätzlich 1% eures Grundmanas.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203749] = {name = "[q2]Zaubernotizen: Erleuchtung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Erleuchtung':\n\n\nIhr verursacht 10% mehr Schaden, solange Ihr mehr als 70% Mana habt. Während Ihr weniger als 30% Mana habt, beträgt Eure Manaregeneration während des Zauberwirkens 10%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203750] = {name = "Schatzkarte von Elwynn", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q2]Benutzen: Gräbt einen Schatz an dem markierten Ort aus. (1 Min Abklingzeit)\n[q]\"Westlich von Kammwacht. In der Nähe des Stumpfs hinter dem Streunerbau.\""},
[203751] = {name = "[q2]Zaubernotizen: NSZEIELA", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Entziffert die Zaubernotizen mit einer Verständnisfibel, um einen neuen Runenschnitzenzauber zu erlernen."},
[203752] = {name = "[q2]Zaubernotizen: DEELFANE LMEBM", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen."},
[203753] = {name = "[q2]Zaubernotizen: ENEGSG IERIFI", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen."},
[203754] = {name = "Erzmagier Antonidas: Die ungekürzte Autobiografie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Etwas ausschweifend, aber dennoch eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[203755] = {name = "Forschungsaufzeichnungen von Erzmagier Theocritus", additional_info = "Einzigartig\n[q]\"Forschungsnotizen aus dem Turm von Azora. Eine tolle Ergänzung für die Sammlung einer jeden Bibliothek.\""},
[203756] = {name = "[q2]Notizen eines Lehrlings aus Azora: Seite 1", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen."},
[203784] = {name = "Rechtes oberes Kartenteil", additional_info = "[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[203785] = {name = "Linkes oberes Kartenteil", additional_info = "[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[203786] = {name = "Rechtes unteres Kartenteil", additional_info = "[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[203787] = {name = "Linkes unteres Kartenteil", additional_info = "[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[203960] = {name = "[q2]Notizen eines Lehrlings aus Azora: Seite 2", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen."},
[203961] = {name = "[q2]Notizen eines Lehrlings aus Azora: Seite 3", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen."},
[203962] = {name = "[q2]Notizen eines Lehrlings aus Azora: Seite 4", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen."},
[203990] = {name = "[q2]Rune der Verstümmelung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Handschuhe mit der Rune 'Verstümmeln':\n\n\nGreift sofort mit beiden Waffen an, verursacht 95% Waffenschaden sowie mit jeder Waffe zusätzlich [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] Schaden. Der Schaden gegen vergiftete Ziele ist um 20% erhöht. Gewährt 2 Combopunkte.\n\n Sofern nicht anders angegeben, profitiert 'Verstümmeln' von allen Talenten und Effekten, die durch 'Meucheln' ausgelöst werden oder 'Meucheln' modifizieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203991] = {name = "[q2]Rune des Pistolenhelden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Pistolenheld':\n\n\nZieht Eure Fernkampfwaffe und feuert einen Schnellschuss auf einen Gegner ab, der normalen Distanzwaffenschaden verursacht und die Bewegungsgeschwindigkeit des Ziels 6 Sek. lang um 50% verringert. Gewährt 1 Combopunkt.\n\n 'Pistolenheld' profitiert von allen Talenten und Effekten, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203992] = {name = "[q2]Rune der Täuschung", additional_info = "Klassen: Schurke\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203993] = {name = "[q2]Rune des Abschlachtens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Hinterhältiger Mord':\n\n\nVerringert die Energiekosten Eurer Fähigkeiten 'Meucheln' und 'Hinterhalt' um 30 und erhöht den Schaden, den sie Zielen zufügen, die nicht von Spielercharakteren kontrolliert werden, um 70%. [ Handschuhe prägen - Verstümmeln : Gilt nicht für 'Verstümmeln' / Gilt nicht für Fähigkeiten, die durch andere Runen erlernt wurden.]\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[203994] = {name = "[q2]Rune der tödlichen Mischung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Tödliche Mischung':\n\n\nGewährt Euren Giften mehrere Verbesserungen:\n\n Wenn Ihr das Ziel mit irgendeinem anderen Gift vergiftet, belegt Ihr es auch mit tödlichem Gift.\n\n Wenn Eure Waffe mit keinem Gift überzogen ist, besteht eine Chance, dass sie sofort wirkendes Gift anwendet, als wäre sie mit sofort wirkendem Gift überzogen.\n\n Der Schaden des tödlichen Gifts und des sofort wirkenden Gifts wird nun durch Eure Angriffskraft erhöht.\n\n Euer 'Tödliches Gift' kann jetzt gegen Ziele wirken, die bereits vom 'Tödlichen Gift' eines anderen Schurken betroffen sind.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204174] = {name = "[q2]Rune der Präzision", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Hosen mit der Rune 'Zwischen die Augen':\n\n\nFinishing-Move für den Distanzkampf, der durch Angriffskraft erhöhten Schaden pro Combopunkt verursacht und das Ziel betäubt:\n\n 1 Punkt: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] bis [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] Schaden, 1 Sek. Betäubung\n 2 Punkte: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] bis [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] Schaden, 2 Sek. Betäubung\n 3 Punkte: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] bis [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] Schaden, 3 Sek. Betäubung\n 4 Punkte: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] bis [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] Schaden, 4 Sek. Betäubung\n 5 Punkte: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] bis [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] Schaden, 5 Sek. Betäubung\n\n Teilt sich die Abklingzeit mit 'Nierenhieb'.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204270] = {name = "Tiefenkern", additional_info = "Einzigartig"},
[204441] = {name = "[q2]Rune der Blutraserei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euer Brustteil mit der Rune 'Blutraserei':\n\n\n'Verwunden' kann jetzt in der Berserker-Stellung eingesetzt werden. Der Schaden von 'Verwunden' wird um 100% erhöht, und 'Verwunden' verursacht jedes Mal, wenn es Schaden verursacht, zusätzlichen Schaden in Höhe von 4% Eurer Angriffskraft.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204476] = {name = "Abgetrennter Koboldkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[204477] = {name = "Abgetrennter Murlockopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[204478] = {name = "Abgetrennter Gnollkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[204688] = {name = "Erstes Runenbruchstück des Monsterjägers", additional_info = "[q2]Benutzen: Mit 2 anderen Stücken kombinieren, um die vollständige Rune zu erhalten."},
[204689] = {name = "Zweites Runenbruchstück des Monsterjägers", additional_info = "[q2]Benutzen: Mit 2 anderen Stücken kombinieren, um die vollständige Rune zu erhalten."},
[204690] = {name = "Drittes Runenbruchstück des Monsterjägers", additional_info = "[q2]Benutzen: Mit 2 anderen Stücken kombinieren, um die vollständige Rune zu erhalten."},
[204703] = {name = "[q2]Rune der Verwüstung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Handschuhe mit der Rune 'Verwüsten':\n\n\nWährend Ihr Euch in der 'Verteidigungshaltung' befindet und einen Schild tragt, verursacht 'Rüstung zerreißen' zusätzlich pro Sekunde Schaden in Höhe von 150% des Schadens Eurer ausgerüsteten Waffe. Dieser Effekt ist pro Stapel von 'Rüstung zerreißen', der bereits auf dem Ziel ist, um 15% erhöht. Schaden von 'Verwüsten' erzeugt ein hohes Maß an Bedrohung, während Ihr Euch in der 'Verteidigungshaltung' befindet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204716] = {name = "[q2]Rune des rasenden Angriffs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Hosen mit der Rune 'Rasender Angriff':\n\n\nWährend Ihr Zweihandwaffen tragt, ist Euer Angriffstempo um 40% erhöht und Eure erfolgreichen Nahkampfangriffe erzeugen 2 zusätzliche Wut oder 4 zusätzliche Wut, wenn sie kritische Treffer sind.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204795] = {name = "[q2]Rune des Schattenschlags", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Handschuhe mit der Rune 'Schattenschlag':\n\n\nTeleportiert Euch hinter Euer Ziel und schlägt zu, um ihm 150% Waffenschaden zuzufügen. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204804] = {name = "[q3]Hydraxianische Reifen", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Kette}\n95 Rüstung\n+4 Stärke\n+7 Ausdauer\nHaltbarkeit 40 / 40\nBenötigt Stufe 25"},
[204806] = {name = "[q2]Rune des Siegesrauschs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Handschuhe mit der Rune 'Siegesrausch':\n\n\nGreift das Ziel sofort an. Verursacht (1 + Angriffskraft * 45 / 100) Schaden und heilt Euch um 30% Eurer maximalen Gesundheit. Kann nur innerhalb von 20 Sek., nachdem Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, eingesetzt werden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204807] = {name = "[q3]Tiefenklinge", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{71 - 107 Schaden} {Tempo 3.60}\n(24.72 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\n[q2]Trefferchance: Trifft alle Gegner vor Euch mit einem Schwall Druckwasser.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q]\"Das Geräusch brechender Wellen erklingt mit jedem Schwung.\""},
[204809] = {name = "[q2]Rune des wütenden Donners", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Hosen mit der Rune 'Wütender Donner':\n\n\n'Donnerknall' erhöht nun die Zeit zwischen Angriffen um zusätzliche 6%, kann in jeder Haltung eingesetzt werden, verursacht 100% mehr Schaden und erzeugt 75% mehr Bedrohung.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[204864] = {name = "[q2]Notizen eines Lehrlings aus Azora", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (6)\n[q2]Benutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen."},
[204905] = {name = "Ominöser Foliant", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Soboz beschwören\n[q]\"Bringt den Kiefer eines Wolfs und das Blut eines Gnolls zum Bauch des Lamms. Beginnt dann die Anrufung.\""},
[204906] = {name = "Gnollblut", additional_info = "Einzigartig\n[q]\"Ein in einem Beschwörungsritual eingesetztes Reagenz.\""},
[204907] = {name = "Wolfskieferknochen", additional_info = "Einzigartig\n[q]\"Ein in einem Beschwörungsritual eingesetztes Reagenz.\""},
[204910] = {name = "[q0]Monster - Dreizack, Naga (Gold)", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{2 - 4 Schaden} {Tempo 3.00}\n(1.00 Schaden pro Sekunde)\nHaltbarkeit 20 / 20"},
[204912] = {name = "[q2]Rune der Anmut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Hosen mit der Rune 'Dämonische Anmut':\n\n\nEin Anstieg der Teufelsenergie erhöht Eure Ausweichchance und die Eures Begleiters um 20% und Eure Chance, mit allen Angriffen kritisch zu treffen, um 20%. Hält 6 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205019] = {name = "Besudelter Seelensplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[205020] = {name = "Reiner Seelensplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[205022] = {name = "[q2]Rune des Seelenentzugs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Umhang mit der Rune 'Seelenentzug':\n\n\n'Blutsauger' verursacht 3-mal schneller Schaden. Erhöht die durch Eure Zauber 'Blutsauger' und 'Seelendieb' abgezogene Menge um zusätzliche 6% für jeden Eurer Hexenmeister-Schatteneffekte, von dem das Ziel betroffen ist, bis zu einem zusätzlichen Effekt von maximal 18%. Wenn 'Seelendieb' gegen ein Ziel mit weniger als 20% Gesundheit eingesetzt wird, wird die abgezogene Menge um 50% pro Effekt erhöht, bis maximal 150%. Zusätzlich kann 'Seelendieb' das Talent 'Einbruch der Nacht' auslösen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205181] = {name = "Nicht identifiziertes Artefakt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Irgendein esoterisches magisches Objekt. Ein erfahrenerer Hexenmeister könnte Euch vermutlich mehr dazu sagen.\""},
[205182] = {name = "Machtloses Artefakt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Opfert Euer Blut, um das Artefakt zu ermächtigen."},
[205183] = {name = "Teufelsverstärktes Artefakt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[205184] = {name = "Notiz eines Akolythen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Lesen rechtsklicken>"},
[205215] = {name = "[q2]Rune der Taktiken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Dämonische Taktiken':\n\n\nErhöht die Chance für einen kritischen Nahkampf- oder Zaubertreffer von Euch und Eurem Dämon um 10%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205218] = {name = "[q2]Buchband der Entdeckung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nKlassen: Paladin\nBenötigt Stufe 5\n[q2]Prägt Euren Umhang mit der Rune 'Seelenentzug':\n\n\n'Blutsauger' verursacht 3-mal schneller Schaden. Erhöht die durch Eure Zauber 'Blutsauger' und 'Seelendieb' abgezogene Menge um zusätzliche 6% für jeden Eurer Hexenmeister-Schatteneffekte, von dem das Ziel betroffen ist, bis zu einem zusätzlichen Effekt von maximal 18%. Wenn 'Seelendieb' gegen ein Ziel mit weniger als 20% Gesundheit eingesetzt wird, wird die abgezogene Menge um 50% pro Effekt erhöht, bis maximal 150%. Zusätzlich kann 'Seelendieb' das Talent 'Einbruch der Nacht' auslösen.\n[q]\"Erreicht einen Zustand der Inspiration, indem Ihr fünf Gegner tötet, dann benutzt dies, um eine neue Fähigkeit zu erlernen.\""},
[205228] = {name = "[q2]Rune des Chaosblitzes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Handschuhe mit der Rune 'Chaosblitz':\n\n\nSchleudert einen Blitz chaotischen Feuers auf den Gegner und fügt ihm [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] bis [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] Chaosschaden zu. 'Chaosblitz' trifft immer, dem Zauber kann nicht widerstanden werden und sein Wissen sorgt dafür, dass alle Eure Feuerzauber Absorptionseffekte durchschlagen. Es besteht eine hohe Chance, dass dem 'Chaosblitz' widerstanden wird, wenn er gegen Monster eingesetzt wird, die mehr als 3 Stufen über Euch sind.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205230] = {name = "[q2]Rune der Heimsuchung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Handschuhe mit der Rune 'Heimsuchung':\n\n\nJagt eine geisterhafte Seele auf den Gegner, die [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100] bis [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] Schaden verursacht und sämtlichen regelmäßigen Schattenschaden, den Ihr dem Ziel zufügt, 15 Sek. lang um 40% erhöht. Wenn 'Heimsuchung' endet oder gebannt wird, werdet Ihr in Höhe des Schadens geheilt, die der Zauber dem Ziel zugefügt hat.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205364] = {name = "Knappsack des Akolythen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]<Zum Öffnen rechtsklicken>"},
[205420] = {name = "[q2]Buchband des Richturteils", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nKlassen: Paladin\n[q2]Prägt Eure Handschuhe mit der Rune 'Kreuzfahrerstoß':\n\n\nEin sofortiger Stoß, der 75% Waffenschaden als Heiligschaden verursacht und 5% Eures maximalen Manas regeneriert. Die Dauer aller Richturteilseffekte auf dem Ziel wird auf 30 Sek. zurückgesetzt.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 Siegel auf Eure Gegner entfesselt habt.\""},
[205683] = {name = "[q2]Rune der Zurechtweisung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Hosen mit der Rune 'Zurechtweisung':\n\n\nUnterbricht das Wirken von Zaubern und verhindert 3 Sek. lang, dass Zauber dieser Art gewirkt werden können.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205685] = {name = "[q2]Rune der Aegis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euer Brustteil mit der Rune 'Aegis':\n\n\nErhöht Euren Blockwert um 30% und modifiziert Euer Talent 'Verschanzen'. 'Verschanzen' hat nun eine Chance von 10%, von jedem Nahkampf- oder Distanzangriff gegen Euch ausgelöst zu werden, und wird immer ausgelöst, wenn Ihr einen kritischen Nahkampftreffer erzielt. Zusätzlich erhält Euer 'Abrechnung'-Talent eine Chance von 2% pro Talentpunkt, durch Nah- oder Fernkampfangriffe gegen Euch ausgelöst zu werden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205863] = {name = "Verderbter Buchband", additional_info = "Klassen: Paladin"},
[205864] = {name = "Verkohlte Notiz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]<Zum Lesen rechtsklicken>"},
[205897] = {name = "[q2]Rune des göttlichen Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Umhang mit der Rune 'Göttliches Licht':\n\n\nHeilt ein verbündetes Ziel um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] bis [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100] Gesundheit. 50% der überschüssigen Heilung auf dem Ziel werden zu einem Absorptionsschild umgewandelt, der 15 Sek. lang anhält. Mehrere Einsätze von 'Göttliches Licht' steigern den Wert des Schilds nicht.\n\n 'Göttliches Licht' profitiert von allen Talenten und Effekten, die von 'Heiliges Licht' ausgelöst werden oder es modifizieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205905] = {name = "[q2]Erinnerung an einen ergebenen Champion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Okkultismus':\n\n\n'Gedankenschinden' und 'Gedankenschlag' verursachen 50% mehr Schaden, wenn das Ziel von Eurem 'Schattenwort: Schmerz' betroffen ist.\n[q2]Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist."},
[205932] = {name = "[q2]Prophezeiung des Tods eines Königs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Handschuhe mit der Rune 'Schattenwort: Tod':\n\n\nEin Wort der bindenden Dunkelheit, das dem Ziel [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100] bis [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] Schattenschaden zufügt. Wenn das Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet der Zaubernde Schaden in Höhe von 50% des Schadens, der dem Ziel zugefügt werden sollte.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[205940] = {name = "[q2]Erinnerung an einen dunklen Zweck", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Graviert Eure Stiefel mit der Rune 'Pest der Leere':\n\n\nInfiziert das Ziel mit einer Krankheit zu, die im Verlauf von 18 Sek. [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 129 / 100 * 6] Schattenschaden verursacht.\n[q2]Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist."},
[205942] = {name = "Chimärische Offenbarung", additional_info = "[q2]Prägt Eure Hosen mit der Rune 'Gebet der Besserung':\n\n\nBelegt das Ziel mit einem Zauber, der es um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden."},
[205943] = {name = "Prophezeiung einer entweihten Zitadelle", additional_info = "Einzigartig\n[q2]Prägt Eure Hosen mit der Rune 'Homunculi':\n\n\nBricht Splitter aus Eurer Seele, um 3 Miniaturkopien von Euch zum Leben zu erwecken, die versuchen, Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt anzugreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung aller getroffenen Ziele.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[205944] = {name = "[q2]Gegenseitige Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Hosen mit der Rune 'Gebet der Besserung':\n\n\nBelegt das Ziel mit einem Zauber, der es um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.\n[q]\"Erlernt eine neue Runenschnitzenfähigkeit.\""},
[205945] = {name = "[q2]Erinnerung an einen eingekerkerten Retter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Hosen mit der Rune 'Geteilter Schmerz':\n\n\nEuer 'Schattenwort: Schmerz' wirkt jetzt zusätzlich auf bis zu 2 zusätzliche Ziele im Umkreis von 15 Metern.\n[q2]Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist."},
[205946] = {name = "[q2]Erinnerung an den Verrat eines Anführers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Stiefel mit der Rune 'Schmerzunterdrückung':\n\n\nVerringert sofort sämtlichen Schaden, den ein verbündetes Ziel erleidet, um 40% und erhöht den Widerstand gegen Bannzauber 8 Sek. lang um 65%.\n[q2]Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist."},
[205947] = {name = "[q2]Prophezeiung einer entweihten Zitadelle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Hosen mit der Rune 'Homunculi':\n\n\nBricht Splitter aus Eurer Seele, um 3 Miniaturkopien von Euch zum Leben zu erwecken, die versuchen, Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt anzugreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung aller getroffenen Ziele.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[205948] = {name = "Wohltuende Offenbarung", additional_info = "[q2]Prägt Euren Umhang mit der Rune 'Vampirberührung':\n\n\nBelegt Euer Ziel mit Eurer 'Vampirumarmung'. Fügt dem Ziel im Verlauf von 15 Sek. [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] Schattenschaden zu und gewährt allen Gruppenmitgliedern Mana in Höhe von 2% des Schattenzauberschadens, den Ihr dem Ziel zufügt."},
[205949] = {name = "Vielfache Offenbarung", additional_info = "Klassen: Priester\n[q2]Prägt Eure Handschuhe mit der Rune 'Kreis der Heilung':\n\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100] bis [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] Gesundheit.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205950] = {name = "[q2]Finstere Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Handschuhe mit der Rune 'Gedankenbrand':\n\n\nLöst eine Explosion von Schattenmagie aus, die dem Ziel und Gegnern innerhalb von 10 Metern um das Ziel herum 6 Sek. lang alle 1 Sek. [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] bis [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] Schattenschaden zufügt.\n[q]\"Erlernt eine neue Runenschnitzenfähigkeit.\""},
[205951] = {name = "[q2]Erinnerung an einen besorgten Akolythen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Handschuhe mit der Rune 'Sühne':\n\n\nSchleudert eine Salve heiligen Lichts auf das Ziel, die einem Gegner [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100] Heiligschaden zufügt oder ein verbündetes Ziel sofort sowie 2 Sek. lang alle 1 Sek. um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100] Gesundheit heilt.\n[q2]Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist."},
[205952] = {name = "Erinnerung an eine zerschmetterte Welt", additional_info = "[q2]Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist."},
[205953] = {name = "[q2]Prophezeiung eines gebrochenen Schwurs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\n\nFügt dem Ziel [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] bis [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[205961] = {name = "Vogelfleisch aus Mulgore", additional_info = "Einzigartig\n[q2]Benutzen: Platziert einen Köder in der Nähe eines Bergkatzenbaus."},
[205979] = {name = "[q2]Rune des Flankierens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Hosen mit der Rune 'Flankenangriff':\n\n\nIhr und Euer Tier verursacht sofort und gleichzeitig 100% Nahkampfschaden. Anschließend verursacht Ihr 10 Sek. lang 8% mehr Schaden. Bis zu 3-mal stapelbar. Die einfachen Angriffe Eures Tiers haben eine Chance von 50%, die Abklingzeit von 'Flankenangriff' abzuschließen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[205995] = {name = "Präriehundmoschus", additional_info = "Klassen: Jäger\n[q2]Benutzen: Eure Fähigkeit 'Wildtier zähmen' wirkt auch bei Präriehunden (als Haustier). (10 Min Abklingzeit)"},
[206032] = {name = "[q2]Rune des Zerlegens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Handschuhe mit der Rune 'Zerlegen':\n\n\nEin weitreichender Angriff, der allen Gegnern vor Euch mit Euren Nahkampfwaffen 65% Waffenschaden zufügt. Euer Primärziel erleidet 50% mehr Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206155] = {name = "[q2]Rune der Treffsicherheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Meister der Treffsicherheit':\n\n\nErhöht Eure kritische Trefferchance um 5% und verringert die Manakosten aller Eurer Schussfähigkeiten um 25%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206157] = {name = "Zephyriumbergbauladung", additional_info = "Questgegenstand\nEinzigartig (5)"},
[206159] = {name = "Verkleidung der Venture Co.", additional_info = "Questgegenstand\n[q]\"Sieht nicht wie eine besonders gute Verkleidung aus...\""},
[206168] = {name = "[q2]Rune der Chimäre", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Handschuhe mit der Rune 'Schimärenschuss':\n\n\nVerursacht 135% Waffenschaden, erneuert die Dauer des auf das Ziel wirkenden Stiches oder Bisses und löst einen Effekt aus:\n\n Schlangenbiss - Verursacht sofort 48% des von Eurem Schlangenbiss verursachten Schadens.\n\n Vipernbiss - Stellt sofort 60% des von Eurem Vipernbiss abgezogenen Manas bei Euch wieder her.\n\n Skorpidstich - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nur einmal pro Minute auftreten.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206169] = {name = "[q2]Rune des Explosivschusses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Handschuhe mit der Rune 'Explosivschuss':\n\n\nFeuert ein Explosivgeschoss in das gegnerische Ziel, das allen Gegnern innerhalb von 8 Metern [Fernkampfangriffskraft * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] bis [Fernkampfangriffskraft * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Feuerschaden zufügt. Die Sprengladung verursacht 2 Sek. lang pro Sekunde weiteren Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206170] = {name = "Windzornzapfen", additional_info = "Questgegenstand"},
[206175] = {name = "Piniensalbe", additional_info = "Questgegenstand\nEinzigartig"},
[206176] = {name = "Mörser und Stößel", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Zerstampft 8 Windzornzapfen, um eine giftige Waffensalbe herzustellen. Theoretisch."},
[206177] = {name = "Pinienkernbutter", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Stellt im Verlauf von 18 Sek. 61.2 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Punkt(e) Ausdauer und Willenskraft."},
[206264] = {name = "[q2]Rune der Inspiration", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Hosen mit der Rune 'Inspirationsvorbild':\n\n\nEure inspirierende Präsenz bannt regelmäßig Furcht- und Schlafeffekte von Gruppenmitgliedern in der Nähe.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206344] = {name = "Messersatz", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Versucht, einen rohen glänzenden Kleinfisch zu filetieren."},
[206345] = {name = "Fischstücke", additional_info = "Questgegenstand\nEinzigartig"},
[206376] = {name = "[q2]Bollwerksymbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\nBenötigt Stufe 3\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Schildmeisterschaft':\n\n\nJedes Mal, wenn Ihr blockt, regeneriert Ihr Mana in Höhe von 8% Eures maximalen Manas und erhaltet Rüstung in der Höhe von 30% des Rüstungswertes Eures Schildes. Bis zu 5-mal stapelbar. Ihr erhaltet außerdem immer eine um 10% erhöhte Blockchance und einen um 15% erhöhten Blockwert.\n\n Außerdem erhaltet Ihr immer, wenn Ihr eine Schockfähigkeit einsetzt, 4 Zauberschaden pro Punkt Eurer Verteidigungsfertigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\""},
[206381] = {name = "[q2]Dyadisches Symbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Überladung':\n\n\nVerleiht Euren Zaubern 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' eine Chance von 60%, kostenlos einen zweiten, ähnlichen Zauber auf das gleiche Ziel auszulösen. Dieser verursacht nur halben Schaden bzw. halbe Heilung und erzeugt keine Bedrohung.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 10-mal Naturschaden erlitten habt.\""},
[206382] = {name = "[q2]Orkansymbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\n[q2]Prägt Eure Handschuhe mit der Rune 'Wasserschild':\n\n\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 1% Eures maximalen Manas gewähren. Trifft ein Zauber-, Nahkampf- oder Distanzangriff den Zaubernden, werden 4% seines maximalen Manas wiederhergestellt und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 Gegner, die keine Spielercharaktere sind, mit drei verschiedenen Elementen getroffen habt (Natur, Frost, Feuer).\""},
[206383] = {name = "[q2]Lithisches Symbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\nBenötigt Stufe 3\n[q2]Prägt Eure Hosen mit der Rune 'Erdschild':\n\n\nSchützt das Ziel mit einem Erdschild, der die Erhöhung der Zauberzeit oder Verringerung der Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] Gesundheit heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 9 Aufladungen. Hält 10 Min. lang an. Der Erdschild kann immer nur auf jeweils einem Ziel aktiv sein.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 20 Angriffe mit Eurem Schild geblockt habt.\""},
[206384] = {name = "[q2]Astralsymbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\nBenötigt Stufe 3\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\""},
[206385] = {name = "[q2]Klastisches Symbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\nBenötigt Stufe 3\n[q2]Prägt Eure Hosen mit der Rune 'Weg der Erde':\n\n\nWährend 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist und Ihr einen Schild ausgerüstet habt, erzeugt Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit, aber seine Reichweite wird auf Nahkampfreichweite verringert. Die Reichweite Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' ist jedoch um 20 Meter verringert.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 20 Gegner mit 'Erdschock' besiegt habt.\""},
[206386] = {name = "[q2]Galvanisches Symbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Schildmeisterschaft':\n\n\nJedes Mal, wenn Ihr blockt, regeneriert Ihr Mana in Höhe von 8% Eures maximalen Manas und erhaltet Rüstung in der Höhe von 30% des Rüstungswertes Eures Schildes. Bis zu 5-mal stapelbar. Ihr erhaltet außerdem immer eine um 10% erhöhte Blockchance und einen um 15% erhöhten Blockwert.\n\n Außerdem erhaltet Ihr immer, wenn Ihr eine Schockfähigkeit einsetzt, 4 Zauberschaden pro Punkt Eurer Verteidigungsfertigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 10-mal mit 'Blitzschlag' besiegt habt.\""},
[206387] = {name = "[q2]Kajarisches Symbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\n[q2]Prägt Eure Handschuhe mit der Rune 'Lavaeruption':\n\n\nIhr schleudert flüssige Lava auf das Ziel, die [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] bis [605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] Feuerschaden verursacht. Wenn das Ziel von 'Flammenschock' betroffen ist, wird 'Lavaeruption' einen kritischen Treffer erzielen.\n[q]\"Lernt eine neue Fähigkeit, nachdem Ihr 5-mal Schaden von Lava erlitten habt. (Verringert den Schaden einiger Lavaquellen)\""},
[206388] = {name = "[q2]Schwefliges Symbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\n[q2]Prägt Eure Handschuhe mit der Rune 'Schmelzschlag':\n\n\nÜberzieht bis zu 10 Gegner in einem kegelförmigen Bereich vor Euch mit [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Angriffskraft] bis [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Angriffskraft] Feuerschaden. Diese Fähigkeit generiert eine große Menge Bedrohung. Der regelmäßige Schaden von 'Flammenschock' hat eine Chance von 10%, die Abklingzeit von 'Schmelzschlag' abzuschließen.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 Gegner mit 'Erdschock' besiegt habt.\""},
[206389] = {name = "[q2]Schwefelsymbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\nBenötigt Stufe 3\n[q2]Prägt Euren Gürtel mit der Rune 'Feuernova':\n\n\nEuer Totem der Feuernova wird durch 'Feuernova' ersetzt. Dadurch verursacht Euer derzeitiges Feuertotem Schaden an seinem Standort.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\""},
[206390] = {name = "[q2]Ichthyosymbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\nBenötigt Stufe 3\n[q2]Prägt Eure Handschuhe mit der Rune 'Wasserschild':\n\n\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 1% Eures maximalen Manas gewähren. Trifft ein Zauber-, Nahkampf- oder Distanzangriff den Zaubernden, werden 4% seines maximalen Manas wiederhergestellt und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\""},
[206391] = {name = "[q2]Syzygiensymbol", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\nBenötigt Stufe 3\n[q2]Prägt Eure Armschienen mit der Rune 'Springflut':\n\n\nHeilt ein verbündetes Ziel um [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] bis [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] Gesundheit und im Verlauf von 15 Sek. um weitere [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] Gesundheit. Wenn Ihr innerhalb von 15 Sek. 'Kettenheilung' auf dieses Hauptziel wirkt, wird die hervorgerufene Heilung um 25% erhöht. Dieser Zauber löst außerdem 'Erwachen der Ahnen' aus.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\""},
[206466] = {name = "Präriekrone", additional_info = "[q2]Benutzen: Erweckt einen Geist der Ebenen."},
[206469] = {name = "Prärieblume", additional_info = "Klassen: Druide\n[q2]Benutzen: Verflechtet 3 Prärieblumen zu einer Krone."},
[206954] = {name = "[q2]Götze der Bärenwut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nKlassen: Druide\n[q2]Prägt Eure Handschuhe mit der Rune 'Zerfleischen':\n\n\nZerfleischt das Ziel, fügt ihm 160% des normalen Schadens zu und lässt es 1 Min. lang 30% zusätzlichen Schaden durch Blutungseffekte und 'Schreddern' erleiden. Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus.\n\n Wenn Ihr ein Ziel mit 'Zerfleischen (Bär)' trefft, erhaltet Ihr zudem 4 Angriffskraft für jeden Punkt Eurer Verteidigungsfertigkeit über ( 60 * 5). Hält 15 Sek. lang an.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr Eure Wut in Bärengestalt 60 Sek. lang auf 50 oder höher gehalten habt.\""},
[206963] = {name = "[q2]Rune des Naturpotenzials", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Samenkorn des Lebens':\n\n\nWenn Ihr mit Euren nicht regelmäßigen Heilzaubern einen kritischen Treffer erzielt, pflanzt Ihr dem Ziel für 50% des geheilten Wertes ein 'Samenkorn des Lebens' ein. Das Samenkorn wird erblühen, wenn das Ziel das nächste Mal Schaden erleidet oder nicht regelmäßige Heilung erhält. Hält 15 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206966] = {name = "Satyrkrautknolle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Der Setzling einer invasiven Pflanzengattung.\""},
[206970] = {name = "[q2]Rune des Lebens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Hosen mit der Rune 'Blühendes Leben':\n\nVerringert die globale Abklingzeit Eurer Fähigkeiten 'Verjüngung' und 'Blühendes Leben' um 0.5 Sek. und Ihr erhaltet die Fähigkeit 'Blühendes Leben':\n\n\nHeilt das Ziel im Verlauf von 7 Sek. um [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] Gesundheit. Wenn 'Blühendes Leben' endet oder gebannt wird, wird das Ziel sofort um [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] Gesundheit geheilt und der Druide erhält die Hälfte der Zauberkosten erstattet. Dieser Effekt ist bis zu 3-mal auf einem Ziel stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206975] = {name = "Artefaktlagertruhenschlüssel", additional_info = "Einzigartig\n[q]\"Öffnet die Artefaktlagertruhe.\""},
[206985] = {name = "[q2]Echo des Alphas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBenötigt Stufe 3\n[q2]Prägt Eure Stiefel mit der Rune 'Geist des Alphas':\n\n\nErfüllt das Ziel mit dem Geist eines Alphawolfes, was die generierte Bedrohung des Ziels 30 Min. lang um 45% erhöht. Maximal 1 Ziel. Wenn der Schamane diesen Zauber nicht auf sich selbst wirkt, erhält er 'Treuer Beta', was 30 Min. lang seinen verursachten körperlichen Schaden um 5% erhöht und jegliche erzeugte Bedrohung um 30% verringert. Ein Ziel kann nicht gleichzeitig mit 'Geist des Alphas' und 'Treuer Beta' belegt sein.\n[q]\"Erlernt eine neue Fähigkeit.\""},
[206989] = {name = "[q2]Rune der Sonne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Handschuhe mit der Rune 'Sonnenfeuer':\n\n\nVerbrennt den Gegner und fügt ihm [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] bis [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Naturschaden sowie im Verlauf von 12 Sek. [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] zusätzlichen Naturschaden zu.\n\n Außerdem wird, während Ihr in Bärengestalt, Katzengestalt oder Terrorbärengestalt seid, Euer 'Mondfeuer' durch 'Sonnenfeuer (Bär)' oder 'Sonnenfeuer (Katze)' ersetzt. Dieser Zauber profitiert von allen Effekten von 'Mondfeuer' und löst diese aus.\n\n 'Sonnenfeuer (Bär)'\nVerbrennt den Gegner und fügt ihm [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] bis [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Naturschaden sowie im Verlauf von 12 Sek. [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] zusätzlichen Naturschaden zu.\n\n 'Sonnenfeuer (Katze)'\nVerbrennt den Gegner und fügt ihm [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] bis [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Naturschaden sowie im Verlauf von 12 Sek. [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] zusätzlichen Naturschaden zu. Generiert 1 Combopunkt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206992] = {name = "[q2]Rune des Schädelstoßes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Handschuhe mit der Rune 'Schädelstoß':\n\n\nStürmt auf ein Ziel innerhalb von 13 Metern zu und schlagt ihm gegen den Schädel, was das Wirken von Zaubern unterbricht und 2 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können. Gemeinsame Abklingzeit mit 'Wilde Attacke'.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[206994] = {name = "Abgetrennter Stacheleberkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[206995] = {name = "Abgetrennter Harpyienkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[207062] = {name = "Abgetrennter Zentaurenkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[207098] = {name = "Notiz von Ba'so", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q]\"Eine in Diebesschrift verfasste Nachricht.\"\n[q2]<Zum Lesen rechtsklicken>"},
[207106] = {name = "Linkes unteres Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
