[207110] = {name = "Schatzkarte von Durotar", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q2]Benutzen: Gräbt einen Schatz an dem markierten Ort aus. (1 Min Abklingzeit)\n[q]\"Vor dem Affenkopf auf der südlichsten Echoinsel.\""},
[207590] = {name = "Schweinefleisch aus Durotar", additional_info = "Einzigartig\n[q2]Benutzen: Platziert einen Köder in der Nähe eines Inselkatzenbaus."},
[207631] = {name = "Otterpheromone", additional_info = "Klassen: Jäger\n[q2]Benutzen: Eure Fähigkeit 'Wildtier zähmen' wirkt auch bei Ottern (als Haustier). (10 Min Abklingzeit)"},
[207731] = {name = "Ominöser Foliant", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Soboz beschwören\n[q]\"Bringt das Bein eines Makruras und den Schädel eines Kul Tiraners zur größten Echoinsel. Findet den Kreis der Macht und führt das Ritual durch.\""},
[207732] = {name = "Makrurabein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Ein in einem Beschwörungsritual eingesetztes Reagenz.\""},
[207733] = {name = "Schädel eines Kul Tiraners", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Ein in einem Beschwörungsritual eingesetztes Reagenz.\""},
[207972] = {name = "Die Lehren von Ta'zo", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine Abschrift der Schnitzereien eines großen Trollmagiers. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[207973] = {name = "Hundekieferknochen", additional_info = "Einzigartig"},
[207974] = {name = "Ominöser Foliant", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Soboz beschwören\n[q]\"Bringt den Kiefer eines Hundes und das Blut eines Gnolls in die Kanalisation. Beginnt dann die Anrufung.\""},
[207975] = {name = "Abgetrennter Fledermauskopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[208005] = {name = "Reliktkastenschlüssel von Agamand", additional_info = "Einzigartig\n[q]\"Öffnet Reliktkasten.\""},
[208007] = {name = "Schiffswracktruhenschlüssel", additional_info = "Einzigartig"},
[208034] = {name = "Schatzkarte von Tirisfal", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q2]Benutzen: Gräbt einen Schatz an dem markierten Ort aus. (1 Min Abklingzeit)\n[q]\"Westlich von Brill, unter der Brücke, westliche Seite.\""},
[208035] = {name = "Rechtes oberes Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
