[208085] = {name = "Signet des Scharlachroten Leutnants", additional_info = "Einzigartig\n[q2]Benutzen: Erstellt gefälschte Dokumente, die den Scharlachroten Kreuzzug gegen die Allianz belasten. Benötigt Schreibutensilien, die im Rathaus von Brill zu finden sind."},
[208086] = {name = "Gefälschtes scharlachrotes Memorandum", additional_info = "Einzigartig\n[q]\"Eine unfassbare Sammlung von Gedanken menschlicher Extremisten, die die Führung der Allianz sicher aufrütteln wird.\""},
[208139] = {name = "Ominöser Foliant", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Soboz beschwören\n[q]\"Bringt den Kiefer eines Wolfs und das Blut eines Wendigos zum Schimmergrat. Stellt Euch auf den Ritualstein und ruft den Dämon herbei.\""},
[208140] = {name = "Wendigoblut", additional_info = "Einzigartig\n[q]\"Ein in einem Beschwörungsritual eingesetztes Reagenz.\""},
[208158] = {name = "Makelloses Troggherz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[208159] = {name = "Abgetrennter Trollkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[208160] = {name = "Abgetrennte Wendigopfote", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[208180] = {name = "Kaninchenmoschus", additional_info = "Klassen: Jäger\n[q2]Benutzen: Eure Fähigkeit 'Wildtier zähmen' wirkt auch bei Hasen (als Haustier). (10 Min Abklingzeit)"},
[208183] = {name = "[q2]Apothekernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (6)\n[q2]Benutzen: Kombiniert 6 Apothekernotizen, um eine neue Runenschnitzenvorlage zu erschaffen."},
[208185] = {name = "Metaphysische Fibel des Apothekers", additional_info = "Einzigartig\n[q]\"Grundlegende Notizen zu Arkantheorie und Zauberforschung, zusammengestellt von Erzmagier Rotwick von der königlichen Apothekervereinigung. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[208192] = {name = "Schweinefleisch aus Dun Morogh", additional_info = "Einzigartig\n[q2]Benutzen: Platziert einen Köder in der Höhle eines großen Bären."},
[208196] = {name = "[q3]Moa'kin-Band", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+7 Ausdauer\n+7 Willenskraft\nBenötigt Stufe 60\n[q2]Benutzen: Die versprochene Seele holen. (3 Std. Abklingzeit)"},
[208205] = {name = "Schwarzrattes Notiz", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q]\"Eine in Diebesschrift verfasste Nachricht.\"\n[q2]<Zum Lesen rechtsklicken>"},
