[208218] = {name = "Rechte unteres Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[208219] = {name = "Linkes unteres Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[208220] = {name = "Schatzkarte von Dun Morogh", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q2]Benutzen: Gräbt einen Schatz an dem markierten Ort aus. (1 Min Abklingzeit)\n[q]\"Unter der Brücke von Kharanos nach Ironforge.\""},
[208222] = {name = "[q3]Vergelter der alten Wache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Axt}\n{163 - 245 Schaden} {Tempo 3.90}\n(52.31 Schaden pro Sekunde)\n+8 Stärke\n+10 Beweglichkeit\n+41 Ausdauer\nHaltbarkeit 100 / 100\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Anlegen: Wird ein Todesstoß ausgeführt, der Erfahrung oder Ehre gewährt, trifft Euer nächster Angriff kritisch.\n[q]\"Der vorherige Besitzer hat sich sehr sorgfältig um diese Waffe gekümmert.\""},
[208223] = {name = "Knappsack des Akolythen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]<Zum Öffnen rechtsklicken>"},
[208224] = {name = "Notiz eines Akolythen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Lesen rechtsklicken>"},
[208414] = {name = "[q2]Mondgötze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nKlassen: Druide\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Furor von Sturmgrimm':\n\n\nVerringert die Manakosten von 'Zorn' um 100%. Jedes Mal, wenn Ihr Schaden mit 'Zorn' verursacht, besteht eine Chance von 12%, dass Eure nächste 'Heilende Berührung' innerhalb von 15 Sek. ein Spontanzauber ist und in allen Gestaltwandelgestalten einsetzbar ist. Erlaubt in Baum-des-Lebens-Gestalt 'Zorn' zu zaubern.\n[q]\"Besiegt sechs Kreaturen, die von Eurem Mondfeuer betroffen sind, um eine neue Fähigkeit zu erlernen.\""},
[208425] = {name = "[q7]Glänzende archaische Überreste", additional_info = "Accountgebunden\nEinzigartig\nHals\n+6 Willenskraft\n[q2]Benutzen: Bringt Euch zurück nach Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern. (1 Stunde Abklingzeit)"},
[208484] = {name = "[q3]Sonnenlicht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig\n{10 - 14 Schaden} {Tempo 1.70}\n(7.06 Schaden pro Sekunde)\n+11 Ausdauer\n+34 Willenskraft\n+17 Schattenwiderstand"},
[208601] = {name = "Rechtes oberes Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[208602] = {name = "Linkes oberes Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[208603] = {name = "Rechte unteres Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[208604] = {name = "Linkes unteres Kartenteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n[q]\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\""},
[208605] = {name = "Schatzkarte von Teldrassil", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q2]Benutzen: Gräbt einen Schatz an dem markierten Ort aus. (1 Min Abklingzeit)\n[q]\"Der hohle Stumpf von Ruth'theran.\""},
[208607] = {name = "Rehmoschus", additional_info = "Klassen: Jäger\n[q2]Benutzen: Eure Fähigkeit 'Wildtier zähmen' wirkt auch bei Rehen (als Haustier). (10 Min Abklingzeit)"},
[208608] = {name = "Vogelfleisch von Teldrassil", additional_info = "Einzigartig\n[q2]Benutzen: Platziert einen Köder in der Höhle eines großen Bären."},
[208609] = {name = "Lichtungsblume", additional_info = "Klassen: Druide\n[q2]Benutzen: Verflicht 3 Lichtungsblumen zu einer Krone."},
[208610] = {name = "Abgetrennter Eulenkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[208611] = {name = "Abgetrennter Tigerkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[208612] = {name = "Abgetrennter Spinnenkopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\""},
[208682] = {name = "Verlassenes Schnappkieferei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q]\"Braucht ein neues Zuhause.\""},
[208687] = {name = "[q2]Rune des Aufschlitzens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Hosen mit der Rune 'Aufschlitzen':\n\n\nSchlitzt ein gegnerisches Ziel auf, was im Verlauf von 15 Sek. [(9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) * 20 / 100 * 5] Blutungsschaden und pro existierender Anwendung von 'Aufschlitzen' auf dem Ziel 20% Waffenschaden verursacht. Generiert hohe Bedrohung. Dieser Effekt ist bis zu 5-mal auf demselben Ziel stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208689] = {name = "[q2]Wilder Götze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nKlassen: Druide\n[q2]Prägt Eure Hosen mit der Rune 'Wildes Brüllen':\n\n\nFinishing-Move, der den verursachten körperlichen Schaden in Katzengestalt um 30% erhöht. Hält pro Combopunkt länger an:\n 1 Punkt: 14 Sek.\n 2 Punkte: 19 Sek.\n 3 Punkte: 24 Sek.\n 4 Punkte: 29 Sek.\n 5 Punkte: 34 Sek.\n[q]\"Belegt Humanoide 20-mal mit Blutungsschaden und setzt dann diesen Götzen ein, um eine neue Fähigkeit zu erlernen.\""},
[208701] = {name = "[q2]Rune des Meisters der Tiere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Meister der Tiere':\n\n\nErhöht Schaden und Gesundheit Eures Tiers um 15% und seine Fokusregeneration um 50%. Außerdem verspottet das 'Knurren' Eures Tiers das Ziel 3 Sek. lang.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208739] = {name = "Kriegsbanner der Horde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q]\"Stoßt dies in den Boden Eurer Gegner.\""},
[208741] = {name = "[q2]Rune der endlosen Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Helm mit der Rune 'Endlose Wut':\n\n\nIhr erhaltet 25% mehr Wut durch sämtlichen von Euch verursachten Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208743] = {name = "Seele der Gier", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister"},
[208744] = {name = "[q2]Rune der Schattenblitze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Handschuhe mit der Rune 'Schattenblitzsalve':\n\n\nEuer 'Schattenblitz' trifft jetzt bis zu 5 Ziele in einer Kette innerhalb von 10 Metern, aber mit um 30% verringertem Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208749] = {name = "Kistenschlüssel der Knarzklauen", additional_info = "Einzigartig\n[q]\"Auf den Griff ist grobschlächtig ein Ast geschnitzt.\""},
[208750] = {name = "[q2]Rune des Kanalisierens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Meisterkanalisierer':\n\n\nEuer Zauber 'Blutsauger' wird nicht mehr kanalisiert, hält 15 Sek. lang an mit einer Abklingzeit von 15 Sek., kostet 100% mehr Mana und heilt Euch jedes Mal, wenn er Schaden verursacht, um 50% mehr.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208753] = {name = "[q2]Zaubernotizen: Regeneration", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Regeneration':\n\n\nHeilt das Ziel im Verlauf von 3 Sek. um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] Gesundheit und belegt es für 30 Sek. mit 'Zeitenleuchtfeuer'.\n\n Zeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.\n[q]\"Teaches you a new Engraving ability.\""},
[208754] = {name = "[q2]Zaubernotizen: TENGIRONEERA", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen."},
[208758] = {name = "[q2]Irdene Rune", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Hosen mit der Rune 'Weg der Erde':\n\n\nWährend 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist und Ihr einen Schild ausgerüstet habt, erzeugt Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit, aber seine Reichweite wird auf Nahkampfreichweite verringert. Die Reichweite Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' ist jedoch um 20 Meter verringert.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208760] = {name = "Lichtungskrone", additional_info = "[q2]Benutzen: Erweckt einen Geist der Ebenen."},
[208764] = {name = "[q2]Rune der Gedanken", additional_info = "Einzigartig\nKlassen: Priester\n[q2]Prägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\n\nFügt dem Ziel [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] bis [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar."},
[208765] = {name = "[q2]Helfende Hand", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q]\"Die Hand wird sich für einen Retter öffnen.\""},
[208766] = {name = "[q2]Helfende Hand", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q]\"Die Hand hat sich für Euch geöffnet.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[208767] = {name = "[q2]Rune der Besserung", additional_info = "Einzigartig\nKlassen: Priester\n[q2]Prägt Eure Hosen mit der Rune 'Gebet der Besserung':\n\n\nBelegt das Ziel mit einem Zauber, der es um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208768] = {name = "Streichholzkästchen des Bukaniers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q]\"Zum Entzünden brennbarer Materialien.\""},
[208771] = {name = "[q2]Rune des Klingentanzes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Hosen mit der Rune 'Klingentanz':\n\n\nFinishing-Move, der Eure Parierchance um 10% erhöht und Euch 4 Angriffskraft pro Punkt Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus gewährt. Hält pro Combopunkt länger an:\n\n 1 Punkt: 14 Sek.\n 2 Punkte: 18 Sek.\n 3 Punkte: 22 Sek.\n 4 Punkte: 26 Sek.\n 5 Punkte: 30 Sek.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208772] = {name = "[q2]Rune des Säbelschlitzers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Handschuhe mit der Rune 'Säbelschlitzer':\n\n\nSchlitzt einen Gegner brutal auf, fügt ihm 100% Waffenschaden zu und lässt das Ziel 12 Sek. lang alle 2 Sek. (Angriffskraft * 5 / 100) Blutungsschaden erleiden. Bis zu 3-mal stapelbar. Jeder Stapel erhöht außerdem den durch 'Säbelschlitzer' und 'Finsterer Stoß' verursachten Schaden um 50%. Gewährt 1 Combopunkt.\n\n 'Säbelschlitzer' nutzt die Vorteile aller Talente und Effekte, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208773] = {name = "Fischfangharpune", additional_info = "Wird beim Aufheben gebunden\nKlassen: Krieger , Jäger\n[q2]Benutzen: Wirft die Harpune auf das Ziel (40 Meter Reichweite).\n[q]\"Ein Muss für jeden angehenden Haijäger!\""},
[208777] = {name = "[q2]Rune des Scharfschützen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Hosen mit der Rune 'Scharfschützentraining':\n\n\nDie kritische Trefferchance Eurer Schussfähigkeiten ist um 2% erhöht, wenn Ihr Euch in den letzten 2 Sek. nicht bewegt habt. Dieser Effekt stapelt sich pro Sekunde bis auf maximal 5 Stapel. Bei 2 oder mehr Stapeln kann 'Gezielter Schuss' sofort eingesetzt werden. Während Ihr Euch bewegt, verliert Ihr 1 Stapel pro Sekunde.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208778] = {name = "[q2]Rune des rasanten Schlags", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Handschuhe mit der Rune 'Rasanter Schlag':\n\n\nEin tollkühner, sofortiger Nahkampfangriff mit Eurer Zweihandwaffe, der (Angriffskraft * 30 / 100) bis (Angriffskraft * 40 / 100) körperlichen Schaden verursacht. Diese Fähigkeit profitiert von allen Effekten von 'Heldenhafter Stoß' und löst diese aus.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208799] = {name = "[q2]Zaubernotizen: Lebende Bombe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Handschuhe mit der Rune 'Lebende Bombe':\n\n\nDas Ziel wird zu einer lebenden Bombe und erleidet im Verlauf von 12 Sek. [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] Feuerschaden. Nach Ablauf von 12 Sek., oder wenn der Zauber gebannt wird, explodiert das Ziel und fügt allen Gegnern innerhalb von 10 Metern [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] Feuerschaden zu.\n\n 'Lebende Bombe' profitiert von allen Talenten und Effekten, die durch 'Versengen' ausgelöst werden oder 'Versengen' verändern.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208800] = {name = "Baxtan: Über zerstörerische Magie", additional_info = "Einzigartig\n[q]\"Die Aufzeichnungen eines namhaften Goblinmagiers. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[208823] = {name = "Opfermünze", additional_info = "Wird beim Aufheben gebunden\nKlassen: Priester\n[q2]Benutzen: Wirft die Rune in einen Brunnen in der Nähe werfen, um einen Wunsch zu erhalten."},
[208828] = {name = "Erinnerung an einen gebrochenen Schwur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\n\nFügt dem Ziel [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] bis [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar.\n[q2]Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist."},
[208833] = {name = "Böswilliger Kuchen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q]\"Ein Gebäck mit fieser Energie.\""},
[208838] = {name = "[q2]Dunkeleisenschließkassette", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q0]Verschlossen\n Benötigt Schlossknacken (1)"},
[208843] = {name = "Kampftotem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Benutzen: Fordert einen Tauren zu einem Duell heraus.\n[q]\"Ein Symbol der Aggression zwischen Mitgliedern der Horde.\""},
[208847] = {name = "Schädelförmige Geode", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q]\"Könnte mit einem ordentlichen Schlag aufgebrochen werden.\""},
[208848] = {name = "Aufgebrochene schädelförmige Geode", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q]\"Die Geode wurde aufgebrochen.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[208849] = {name = "[q2]Segensbuchband", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nKlassen: Paladin\n[q2]Prägt Euer Brustteil mit der Rune 'Geheiligter Boden':\n\n\nEure 'Weihe' heilt Gruppenmitglieder im Effektbereich um 200% des Schadenswerts von 'Weihe'.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr fünf verschiedene Spielercharaktere gesegnet habt.\""},
[208851] = {name = "[q2]Gerechtigkeitsbuchband", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nKlassen: Paladin\n[q2]Prägt Eure Handschuhe mit der Rune 'Hand der Abrechnung':\n\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\n Während Ihr diese Fähigkeit kennt, ist der Bedrohungsbonus von 'Zorn der Gerechtigkeit' auf 80% erhöht. Wenn Ihr von anderen Charakteren geheilt werdet, sorgt 'Zorn der Gerechtigkeit' dafür, dass Ihr Mana in Höhe von 25% der hervorgerufenen Heilung erhaltet. Zusätzlich wird Schaden, der Eure Gesundheit unter 35% senkt, um 20% verringert, während 'Zorn der Gerechtigkeit' aktiv ist. 'Zorn der Gerechtigkeit' bleibt aktiv, bis er abgebrochen wird.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 durch 'Hammer der Gerechtigkeit' betäubte Gegner getötet habt.\""},
[208853] = {name = "[q2]Zaubernotizen: Hirnfrost", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigtRunenschnitzen\n(1)\n[q2]Prägt Eure Stiefel mit der Rune 'Hirnfrost':\n\n\nEure Frostzauber mit Kälteeffekten haben eine Chance von 20%, Euren nächsten Einsatz von 'Feuerball', 'Zauberfrostblitz', 'Qualfeuerblitz' oder 'Frostfeuerblitz' zu einem Spontanzauber werden zu lassen, der kein Mana kostet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[208854] = {name = "[q2]Zerkaute Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen.\n[q]\"Troggschamanen sind wirklich unersättliche Leser.\""},
[208855] = {name = "Köder aus Regenbogenflossenthunfisch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Füttert das Ziel mit dem Köder.\n[q]\"Ein schönes Leckerli für Seemonster.\""},
[208860] = {name = "Rumi von Gnomeregan: Die gesammelten Werke", additional_info = "Einzigartig\n[q]\"Die Aufzeichnungen eines namhaften Gnomenmagiers. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[209027] = {name = "Krabbenleckerli", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger , Druide\n[q2]Benutzen: Füttert das Ziel mit dem Leckerli.\n[q]\"Die Furbolgs fangen junge Riffkriecher damit.\""},
[209028] = {name = "[q2]Zaubernotizen: BEMBENE DELBO", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen."},
[209029] = {name = "Nachricht von Emily", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q2]<Zum Lesen rechtsklicken>"},
[209030] = {name = "Ausrüstungslagerschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke"},
[209031] = {name = "Diskreter Umschlag", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]<Zum Öffnen rechtsklicken>"},
