[209848] = {name = "Goaz' Schriftrollen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Geschrieben in einer verlorenen Titanenschrift, aber trotzdem eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[209849] = {name = "Verbrechen gegen die Anatomie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Geschrieben von Doktor Krastinov. Eine fragwürdige Erweiterung für die Sammlung jeder Bücherei.\""},
[209850] = {name = "Runen der Zaubererkönige", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Ein Relikt der mächtigen Ogerkönigreiche von Draenor. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[209851] = {name = "Zorn des Landes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Streng bewachte schamanische Geheimnisse des Grimmtotemklans. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[209852] = {name = "[q2]Rune des Tötungsbefehls", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Hosen mit der Rune 'Tödlicher Schuss':\n\n\nIhr versucht, ein verletztes Ziel mit einem Distanzangriff zu töten, der 100% Waffenschaden plus [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] verursacht. 'Tödlicher Schuss' hat keine Minimaldistanz, und seine Abklingzeit wird zurückgesetzt, wenn er gegen einen Gegner mit 20% oder weniger Gesundheit eingesetzt wird.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[209872] = {name = "Helm des Drachentöters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[209873] = {name = "Schild des Drachentöters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[209874] = {name = "Lanze des Drachentöters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[210015] = {name = "[q2]Rune des wütenden Schlags", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euer Brustteil mit der Rune 'Wütender Schlag':\n\n\nEin wilder Schlag, der 115% Waffenschaden verursacht, jedoch nur eingesetzt werden kann, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist. Jede andere Nahkampffähigkeit, die eingesetzt wird, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist, verringert die verbleibende Abklingzeit von 'Wütender Schlag' um 1 Sek.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210026] = {name = "Symbol der dritten Eule", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q]\"Ihr beherrscht das Reich des Meeres.\""},
[210043] = {name = "Symbol der zweiten Eule", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q]\"Agons Seele hat endlich Frieden gefunden.\""},
[210044] = {name = "Symbol der ersten Eule", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q]\"Das Zeichen eines echten Wächters.\""},
