[210080] = {name = "Voodoo-Opfergabe", additional_info = "Questgegenstand\nEinzigartig"},
[210137] = {name = "[q2]Rune des Wildwuchses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Handschuhe mit der Rune 'Wildwuchs':\n\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum im Verlauf von 7 Sek. um [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] Gesundheit. Die Heilung wird zunächst schnell und mit zunehmender Dauer von 'Wildwuchs' langsamer angewendet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210138] = {name = "Verordnung der Dunkeleisenzwerge", additional_info = nil},
[210146] = {name = "Schredderturbolader", additional_info = nil},
[210147] = {name = "Automatische Bergungseinheit Schredder", additional_info = "[q2]Benutzen: Birgt das Wrack eines Schredders für Ersatzteile."},
[210177] = {name = "Ataeric: Arkane Merkwürdigkeiten", additional_info = "Einzigartig\n[q]\"Die Aufzeichnungen eines namhaften Erzmagiers der Kirin Tor. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[210178] = {name = "[q2]Bauplan: Automatische Bergungseinheit Schredder", additional_info = "Benötigt Ingenieurskunst (135)"},
[210179] = {name = "[q2]Zaubernotizen: SCEAGHSLSVESO", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Übersetzt die Zaubernotizen in eine neue Runenschnitzenvorlage. Erfordert eine Referenz für die Kurzschrift des Autors."},
[210183] = {name = "Horn von Xelthos", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Daraus ertönt ein sanfter und eindringlicher Ton.\""},
[210186] = {name = "Sprengladung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Öffnet ein schweres Tor auf Goblinweise!"},
[210187] = {name = "Arbeitsauftrag der Venture Co.", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[210188] = {name = "[q0]Zerfetzter Arbeitsauftrag", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Anscheinend im Kampf kaputt gegangen.\""},
[210195] = {name = "[q2]Unausgewuchteter Götze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nKlassen: Druide\nBenötigt Stufe 10\n[q2]Benutzen: Gleicht die Mächte des Mondes, des Smaragdgrünen Traums und der Wildnis aus, um eine neue Fähigkeit zu erlernen."},
[210209] = {name = "Zwillingsschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke"},
[210210] = {name = "[q0]Gründerzertifikat von Grizzwerks Verteidigungsvertrieb", additional_info = "[q]\"Das Kleingedruckte macht deutlich, dass mit diesem Zertifikat keinerlei Börsenwert oder Rechtsanspruch verbunden ist. Wenn Ihr Euren Daumen auf diesen Teil legt, könnte es jemand kaufen.\""},
[210212] = {name = "Bruders Halbschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert Bruders und Schwesters Halbschlüssel."},
[210213] = {name = "Schwesters Halbschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert Bruders und Schwesters Halbschlüssel."},
[210229] = {name = "[q2]Rune der Verstümmelung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Handschuhe mit der Rune 'Verstümmeln':\n\n\nGreift sofort mit beiden Waffen an, verursacht 95% Waffenschaden sowie mit jeder Waffe zusätzlich [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] Schaden. Der Schaden gegen vergiftete Ziele ist um 20% erhöht. Gewährt 2 Combopunkte.\n\n Sofern nicht anders angegeben, profitiert 'Verstümmeln' von allen Talenten und Effekten, die durch 'Meucheln' ausgelöst werden oder 'Meucheln' modifizieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210250] = {name = "Gravierter Goldring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n[q]\"Die Gravierung lautet: Kniet __ der __ auf __ Friedhof, __ Ihr __ Ringe __\""},
[210251] = {name = "Gravierter Silberring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n[q]\"Die Gravierung lautet: __ vor __ Statue __ dem __ während __ beide __ tragt.\""},
[210252] = {name = "[q2]Rune der Klinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Handschuhe mit der Rune 'Halsabschneider':\n\n\nFür den Einsatz Eurer Fähigkeiten 'Hinterhalt', 'Meucheln' und 'Erdrosseln' müsst Ihr nicht mehr hinter Eurem Gegner sein, und 'Meucheln' hat eine Chance von 15%, dass Ihr bei Eurem nächsten Einsatz von 'Hinterhalt' innerhalb von 10 Sek. nicht in Verstohlenheit sein müsst.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210253] = {name = "[q2]Verfalltotem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ruft die Geister der Elemente an.\n[q]\"Ein traditionelles Totem... verdreht und krumm durch dunkle Magie, kaum wiederzuerkennen für jene, die Zwiesprache mit den Elementen halten.\""},
[210322] = {name = "[q2]Rune des Toxins", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Hosen mit der Rune 'Vergiften':\n\n\nFinishing-Move, der sofort Giftschaden abhängig von den Dosen 'Tödliches Gift' auf dem Ziel verursacht. Nach einem Angriff mit 'Vergiften' ist die Frequenz, mit der das Ziel mit 'Sofort wirkendes Gift' belegt werden kann, für 1 Sek. plus je 1 weitere Sekunde pro Combopunkt um 75% erhöht. Pro Combopunkt wird eine Dosis aktiviert:\n 1 Dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Angriffskraft * 0.072] Schaden\n 2 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Angriffskraft * 0.144] Schaden\n 3 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Angriffskraft * 0.216] Schaden\n 4 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Angriffskraft * 0.288] Schaden\n 5 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Angriffskraft * 0.36] Schaden\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210323] = {name = "Tresorkombination", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q]\"0-4-5-1\""},
[210329] = {name = "Hillsbradschatzkarte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q]\"Folgt dem Fluss nach Norden, am Alteracgebirge vorbei. Was Ihr sucht, befindet sich unterhalb der Stromschnellen.\""},
[210330] = {name = "Heißer Tipp", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Gute Informationen sind nicht billig.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[210410] = {name = "Süßwasserschnapperköder", additional_info = "Klassen: Jäger\n[q2]Benutzen: Wirft einen Köder. (5 Min Abklingzeit)\n[q]\"Werft ein paar ins Wasser, um einen Großen hervorzulocken!\""},
[210499] = {name = "Moorcheln", additional_info = "[q2]Benutzen: Essen (auf eigene Gefahr)."},
[210500] = {name = "[q2]Rune der Sterne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Hosen mit der Rune 'Sternensog':\n\n\nEntfesselt eine Sogwelle stellarer Energien, die [248 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] bis [304 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] Arkanschaden verursacht und 15 Sek. lang für 1 Einsatz den verursachten Schaden von 'Sternenfeuer' um 80% erhöht.\n\n 'Sternensog' profitiert von den meisten Talenten und Effekten und löst diese aus, die auch 'Zorn' oder 'Sternenfeuer' auslösen oder davon profitieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210534] = {name = "[q2]Götze der Wildnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nKlassen: Druide\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Wilde Stöße':\n\n\nWährend Ihr in Katzengestalt, Bärengestalt oder Terrorbärengestalt seid, erlangen Gruppen- oder Schlachtzugsmitglieder im Umkreis von 100 Metern erhöhte Kampfwildheit. Bei jedem Nahkampftreffer besteht eine Chance von 20%, dem Angreifer einen Zusatzangriff mit 20% höherer Angriffskraft zu gewähren. Kein Effekt, wenn das Ziel bereits vom Totem des Windzorns profitiert.\n[q]\"Heilt 10 verschiedene Wildtiere und benutzt anschließend diesen Götzen, um eine neue Fähigkeit zu erlernen.\""},
[210568] = {name = "Schwächelndes Phylakterium", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine abscheuliche Aura dringt aus dem Artefakt.\""},
[210569] = {name = "[q2]Rune der Geißelung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euer Brustteil mit der Rune 'Geißelung':\n\n\nIhr erlangt Wut von erlittenem körperlichen Schaden, als ob Ihr keine Rüstung tragen würdet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210573] = {name = "[q2]Rune der verzehrenden Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Hosen mit der Rune 'Von Wut zerfressen':\n\n\nVersetzt Euch 12 Sek. lang in einen Wutzustand (und aktiviert Fähigkeiten, die einen Wutzustand erfordern), nachdem Ihr 60 Wut überschritten habt. Außerdem trifft 'Wirbelwind' auch mit Schildhandwaffen, während Ihr Euch in einem Wutzustand befindet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210589] = {name = "[q2]Echo der Urahnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Hosen mit der Rune 'Führung der Ahnen':\n\n\nFür die nächsten 10 Sek. werden 25% Eures Schadens in Heilung für bis zu 3 Gruppenmitglieder in der Nähe umgewandelt. 100% Eurer Heilung werden in Schaden umgewandelt und dem letzten Ziel von Eurem 'Flammenschock' zugefügt.\n[q]\"Erlernt eine neue Runenschnitzenfähigkeit.\""},
[210596] = {name = "[q2]Rune der Kobrastöße", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Kobrastöße':\n\n\nEure kritischen Treffer mit Euren Schuss- und Stoßfähigkeiten sowie 'Mungobiss' lassen die nächsten 2 Spezialangriffe Eures Tiers kritisch treffen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210653] = {name = "[q2]Rune des Parierdolchs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Handschuhe mit der Rune 'Parierdolch':\n\n\nGreift sofort mit Eurer Schildhandwaffe an und verursacht normalen Schildhandwaffenschaden. Erhöht Eure Parierchance 5 Sek. lang um 100% oder bis Ihr erfolgreich pariert. Nach dem Einsatz von 'Parierdolch' kostet 'Finsterer Stoß' 20 Sek. lang 20 weniger Energie, verursacht 50% mehr Bedrohung, gewährt Stapel von 'Schläge abschwächen', und sowohl 'Finsterer Stoß' als auch 'Ausweiden' verursachen 50% mehr Schaden. Gewährt 1 Combopunkt.\n\n 'Parierdolch' nutzt die Vorteile der meisten Talente und Effekte, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren. Der Effekt von 'Parierdolch' wird 'Parierdolch' selbst nicht verstärken oder günstiger machen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210654] = {name = "[q2]Zaubernotizen: Zeit zurückdrehen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Armschienen mit der Rune 'Zeit zurückdrehen':\n\n\nEuer aktuelles mit Eurem 'Zeitenleuchtfeuer' belegtes Ziel wird sofort um sämtlichen Schaden geheilt, den es in den letzten 5 Sek. erlitten hat. Wirkungslos bei Zielen, die vor 5 Sek. nicht mit 'Zeitenleuchtfeuer' belegt waren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210655] = {name = "[q2]Zaubernotizen: ZÜDE RHENZUCKITER", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen."},
[210665] = {name = "Partikel strömender Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[210667] = {name = "Partikel teuflischer Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[210668] = {name = "Partikel seismischer Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[210696] = {name = "[q2]Moderbann", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Schwert}\n{18 - 34 Schaden} {Tempo 2.60}\n(10.00 Schaden pro Sekunde)\nHaltbarkeit 60 / 60\nKlassen: Krieger\nBenötigt Stufe 14\n[q]\"Blutverkrustet wie sie ist, hat diese Klinge lange ihren Glanz im Licht verloren und dient nun stattdessen als Warnung...\""},
[210708] = {name = "Elixier der verschmolzenen Reue", additional_info = "Benötigt Stufe 20\n[q2]Benutzen: Ermöglicht es dem Anwender, mit dem Leichnam eines Individuums zu sprechen, das in der Welt der Sterblichen noch unerledigte Angelegenheiten hat. Kann außerdem bei Verdauungsstörungen helfen. (3 Sek. Abklingzeit)"},
[210709] = {name = "[q2]Rezept: Elixier der verschmolzenen Reue", additional_info = "Benötigt Alchimie (90)\n[q2]Benutzen: Lehrt euch, wie man ein Elixier der verschmolzenen Reue herstellt.\nElixier der verschmolzenen Reue\nBenötigt Stufe 20\n[q2]Benutzen: Ermöglicht es dem Anwender, mit dem Leichnam eines Individuums zu sprechen, das in der Welt der Sterblichen noch unerledigte Angelegenheiten hat. Kann außerdem bei Verdauungsstörungen helfen. (3 Sek. Abklingzeit)\nBenötigt Würgetang (5), Verbleite Phiole , Grabmoos (5), Seelenstaub"},
[210712] = {name = "Elixier der Einsicht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Vernehmt eine Vision an Je'neus Freudenfeuer."},
[210713] = {name = "Gequälte Seele", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Reicht eine Opfergabe des Blutes dar, um diese gequälte Seele freizugeben."},
[210724] = {name = "Hirzeks Stab", additional_info = "Wird beim Aufheben gebunden"},
[210741] = {name = "[q3]Automatischer Meuteverprügler", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{53 - 85 Schaden} {Tempo 2.00}\n(34.50 Schaden pro Sekunde)\n+22 Stärke\n+8 Beweglichkeit\nHaltbarkeit 100 / 100\nKlassen: Paladin , Schamane , Druide\nBenötigt Stufe 40\n[q2]Anlegen: +69 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Benutzen: Erhöht Euer Angriffstempo 30 Sek. lang um 50%. Keine Wirkung auf Charaktere über Stufe 55. (3 Min Abklingzeit)\n[q]\"Es wurden eine Vielzahl an Verbesserungen vorgenommen, um die Funktionalität des diesjährigen Modells zu verbessern.\""},
[210746] = {name = "[q2]Rune des Erdschilds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Hosen mit der Rune 'Erdschild':\n\n\nSchützt das Ziel mit einem Erdschild, der die Erhöhung der Zauberzeit oder Verringerung der Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] Gesundheit heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 9 Aufladungen. Hält 10 Min. lang an. Der Erdschild kann immer nur auf jeweils einem Ziel aktiv sein.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210763] = {name = "Alteks Zweig", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Ein gesplittertes Fragment der Macht. Es scheint, als wäre dies einst Teil einer bedeutenden Waffe gewesen.\""},
[210765] = {name = "Kugel von Des", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Flammen und dunkle Magie wirbeln durch die Kugel, hypnotisierend und doch zutiefst bedrückend. Es scheint, als wäre dies einst Teil einer bedeutenden Waffe gewesen.\""},
[210771] = {name = "[q2]Abgefangene Vorräte: Kupferbarren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 20 Kupferbarren hinzu, um die Lieferung zu vervollständigen."},
[210772] = {name = "[q2]Versorgungslieferung: Kupferbarren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Supply Shipment] (1)\n[q]\"Liefert sie an einen Versorgungsoffizier, um eine beträchtliche Belohnung zu erhalten.\""},
[210773] = {name = "[q3]Mantel des Zweiten Krieges", additional_info = "Wird beim Anlegen gebunden\n{Schulter} {Kette}\n163 Rüstung\n+8 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 11."},
[210779] = {name = "[q2]Pläne: Mantel des Zweiten Krieges", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (150)\n[q2]Benutzen: Lehrt Euch, wie man einen Mantel des Zweiten Krieges herstellt.\n[q3]Mantel des Zweiten Krieges\nWird beim Anlegen gebunden\n{Schulter} {Kette}\n163 Rüstung\n+8 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 11.\nBenötigt Bronzebarren (20), Moosachat (2), Geringer Mondstein (2), Schillernde Perle (2), Silberbarren (4)"},
[210781] = {name = "[q3]Phönixbindungen", additional_info = "Wird beim Anlegen gebunden\n{Handgelenke} {Stoff}\n21 Rüstung\nHaltbarkeit 30 / 30\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 13."},
[210794] = {name = "[q4]Veränderliche silberne Brustplatte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\n{Brust} {Kette}\n238 Rüstung\n+12 Stärke\n+5 Ausdauer\nHaltbarkeit 145 / 145\nBenötigt Stufe 25\nBenötigt Schmiedekunst (100)\n[q2]Anlegen: Dieser Gegenstand ist mit der rohen Macht der Leere erfüllt. Wenn der Träger angegriffen wird, hat dieser Gegenstand eine hohe Chance, einen schrecklichen Fluch zu wirken, durch den der Angreifer 15 Sek. lang zusätzlichen Schaden aus allen Quellen erleidet. (Procchance: 25%)\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[210795] = {name = "[q4]Extraplanare Spinnenseidenstiefel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\n{Füße} {Stoff}\n35 Rüstung\n+5 Ausdauer\n+5 Intelligenz\n+6 Willenskraft\nHaltbarkeit 50 / 50\nBenötigt Stufe 25\nBenötigt Schneiderei (100)\n[q2]Benutzen: Tretet zeitweise in eine andere Existenzebene ein, was sofort die Bedrohung reduziert und allen erlittenen und verursachten Schaden 6 Sek. lang um 30% verringert. (10 Min Abklingzeit)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[210811] = {name = "[q2]Rune des urzeitlichen Zorns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Hosen mit der Rune 'Großer Geisterwolf':\n\n\nEure Fähigkeit 'Geisterwolf' kann nun drinnen benutzt werden und verringert sämtlichen erlittenen Schaden um 10%, so lange sie aktiv ist.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210817] = {name = "[q2]Rune des Überlebens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Überleben des Stärkeren':\n\n\nVerringert die Chance, dass Ihr einen kritischen Treffer durch Nahkampfangriffe erleidet, um 6% und verringert jeglichen erlittenen Schaden um 10%. Verringert den erlittenen Schaden zusätzlich um 10%, während Ihr in Bärengestalt oder Terrorbärengestalt seid.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210818] = {name = "[q2]Rune des einsamen Wolfs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Einsamer Wolf':\n\n\nIhr verursacht mit allen Angriffen 25% mehr Schaden, während Ihr kein Tier aktiviert habt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210820] = {name = "[q2]Rune der Opferung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Hosen mit der Rune 'Hand der Aufopferung':\n\n\nLässt das anvisierte Gruppen- oder Schlachtzugsmitglied pro Treffer 30% des erlittenen Schadens auf den Zaubernden übertragen. Hält 12 Sek. lang an oder bis Schaden in Höhe von 100% der maximalen Gesundheit des Zaubernden übertragen wurde.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210822] = {name = "[q2]Harmonische Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Glücksfall':\n\n\nEure Heilung mit 'Blitzheilung' verringert die Zauberzeit Eures nächsten Einsatzes von 'Geringe Heilung', 'Heilung', 'Große Heilung' oder 'Gebet der Heilung' 20 Sek. lang um 20%. Bis zu 3-mal stapelbar.\n[q]\"Erlernt eine neue Runenschnitzenfähigkeit.\""},
[210823] = {name = "[q2]Rune der Beidhändigkeitsspezialisierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Beidhändigkeitsspezialisierung':\n\n\nErhöht beim beidhändigen Führen Eure Chance, mit Zaubern und Nahkampfangriffen Treffer zu landen, um 5%. Außerdem trifft Eure Fähigkeit 'Sturmschlag' jetzt mit beiden Waffen, wenn Ihr beidhändig führt, und erhöht den verursachten Schaden Eurer Schildhandwaffe um 60%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210824] = {name = "[q2]Rune des Pakts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Hosen mit der Rune 'Dämonischer Pakt':\n\n\nEure Feuer- und Schattenzauber verursachen 10% mehr Schaden und die kritischen Treffer Eures Begleiters belegen Eure Gruppen- oder Schlachtzugsmitglieder 45 Sek. lang mit dem Effekt 'Dämonischer Pakt'. Der dämonische Pakt erhöht den Zauberschaden und die Heilung um 10% Eures Zauberschadens oder um ( 60 / 2), je nachdem, welcher Wert höher ist. Unterworfene Dämonen können diesen Effekt nicht auslösen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210825] = {name = "[q2]Rune des Kriegshetzers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euer Brustteil mit der Rune 'Kriegstreiber':\n\n\nEure Fähigkeiten 'Sturmangriff', 'Abfangen' und 'Einschreiten' sind nun während des Kampfes und in jeder Haltung nutzbar und werden bei Aktivierung jegliche bewegungseinschränkenden Effekte entfernen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210953] = {name = "Auge von Bhossca", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Obwohl das Auge leblos ist, fühlt Ihr Euch dennoch beobachtet...\""},
[210955] = {name = "Uniform eines scharlachroten Initianden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verkleidet Euch als ein Mitglied des Scharlachroten Kreuzzugs. Verdächtiges Verhalten lässt die Verkleidung auffliegen."},
[210963] = {name = "Seherschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke"},
[210966] = {name = "Blut der Legion", additional_info = "Questgegenstand\nEinzigartig (10)\n[q]\"Dunkel und dick... Dieses Blut reicht zurück zu großen Kommandanten der Legion.\""},
[210967] = {name = "Vertrauliche Nachricht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]<Zum Lesen rechtsklicken>"},
[210968] = {name = "Reliquiarschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke"},
[210979] = {name = "[q2]Rune des Schattenschritts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euren Gürtel mit der Rune 'Schattenschritt':\n\n\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen. Erhöht 3 Sek. lang die Bewegungsgeschwindigkeit um 70%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[210980] = {name = "[q2]Rune der Metamorphose", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Handschuhe mit der Rune 'Metamorphose':\n\n\nVerwandelt Euch in einen Dämon. Eure Rüstung wird um 500% und Eure Gesundheit um 15% erhöht und die Chance, kritische Treffer zu erleiden, um 6% verringert. Eure Bedrohung wird um 50% erhöht und 'Aderlass' gewährt 100% mehr Mana, doch Euer sämtlicher verursachter Schaden wird um 10% verringert. 'Metamorphose' verändert einige Fähigkeiten und gewährt neue:\n\n 'Sengender Schmerz': Wird zu einem Spontanzauber.\n\n 'Schattenblitz': Wird zu 'Schattenspalten', einem Nahkampfangriff, der bis zu 10 Gegner in der Nähe mit Schattenschaden trifft, aber eine Abklingzeit von 6 Sek. hat.\n\n 'Furcht': Wird durch 'Plagegeist' ersetzt.\n\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\n 'Dämonischer Ansturm'\n\n\nStürmt auf einen Gegner zu und betäubt ihn für 1 Sek. Kann nicht im Kampf verwendet werden.\n\n 'Dämonisches Heulen'\n\n\nZwingt alle Gegner in der Nähe 6 Sek. lang, ihre Angriffe auf Euch zu konzentrieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211205] = {name = "[q2]Rune des Kobraschlächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Handschuhe mit der Rune 'Kobraschlächter':\n\n\n'Mungobiss' hat bei jedem Eurer Nahkampfangriffe eine Chance von 10%, aktiviert zu werden, sowie eine Chance von 100%, wenn der Gegner ausweicht. Diese Chance sammelt sich an und steigt durch jeden Angriff in Folge, bei dem sie nicht zurückgesetzt wird, um 10%. 'Mungobiss' verursacht zusätzlichen Schaden in Höhe von 45% Eurer Angriffskraft.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211247] = {name = "[q2]Muster: Phönixbindungen", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (125)\n[q2]Benutzen: Lehrt Euch, wie man Phönixbindungen näht.\n[q3]Phönixbindungen\nWird beim Anlegen gebunden\n{Handgelenke} {Stoff}\n21 Rüstung\nHaltbarkeit 30 / 30\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 13.\nBenötigt Wollstoffballen (6), Fläschchen Öl (2), Feiner Faden (2)"},
[211263] = {name = "[q0]Brustschutz des Richturteils", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Platte}\n857 Rüstung\n+17 Stärke\n+25 Ausdauer\n+20 Intelligenz\n+10 Feuerwiderstand\n+10 Naturwiderstand\nHaltbarkeit 165 / 165\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Verteidigung +6.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 14.\n[q2]Anlegen: Erhöht den Blockwert Eures Schilds um 32.\n\n[q]Bollwerk des Richturteils (0/1)\n[q0]Brustschutz des Richturteils\n[q0](3) Set : Eure Aura der Hingabe verringert zusätzlich jeglichen erlittenen Zauberschaden um 5%.\n(5) Set : 'Richturteil' generiert zusätzlich 50% Bedrohung beim Ziel.\n(8) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 47."},
[211269] = {name = "Einfache Zeichnung", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest."},
[211272] = {name = "Leerer Köderkäfig", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fangt ein Kleintier, das als Köder genutzt werden kann."},
[211273] = {name = "Gefangenes Kleintier", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert ein Kleintier als Köder."},
[211293] = {name = "Blutrote Trophäenfeder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[211301] = {name = "[q2]Rune der aufgedeckten Schwäche", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Euren Gürtel mit der Rune 'Schwäche aufdecken':\n\n\nEure kritischen Treffer mit Nahkampf- und Distanzangriffen erhöhen 7 Sek. lang Eure Angriffskraft um 40% Eurer aktuellen Beweglichkeit.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211315] = {name = "[q2]Abgefangene Vorräte: Leichtes Leder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 14 Stücke leichtes Leder hinzu, um die Lieferung zu vervollständigen."},
