[211384] = {name = "[q2]Robuste Kuriertasche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n12 Platz Behälter"},
[211385] = {name = "[q2]Rune der Schlangenspur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Hosen mit der Rune 'Schlangenspur':\n\n\nZiele, die von Eurem 'Mehrfachschuss' getroffen werden, werden ebenfalls 12 Sek. lang mit 'Schlangenbiss' belegt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211386] = {name = "[q2]Zaubernotizen: Arkane Woge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Hosen mit der Rune 'Arkane Woge':\n\n\nKanalisiert all Euer verbleibendes Mana in einer Woge aus Energie auf das Ziel. Verursacht [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 226 / 100] bis [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 264 / 100] Arkanschaden, der abhängig von Eurem verbleibenden Mana um bis zu 300% erhöht ist. Anschließend wird Eure normale Manaregeneration aktiviert und ist 8 Sek. lang um 300% erhöht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211387] = {name = "[q2]Rune des lockenden Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Handschuhe mit der Rune 'Flamme des Glaubens':\n\n\nDas Ziel wird für alle Gruppen- und Schlachtzugsmitglieder in einem Radius von 40 Metern zu einer Flamme des Glaubens. Alle auf diese Mitglieder gewirkten Heilungen heilen auch die Flamme um 75% der gewirkten Heilung. Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein. Hält 1 Stunde lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211390] = {name = "[q2]Rune des Reizens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Nur eine Fleischwunde':\n\n\nIhr erleidet 20% weniger körperlichen Schaden, während 'Klingentanz' aktiv ist, verringert um weitere 1% pro 12 Punkte Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus. Außerdem wird Eure Ausweichchance mit 50% multipliziert und die Chance, dass Ihr kritische Treffer durch Nahkampfangriffe erleidet, um 6% verringert, Ihr verursacht 20% weniger Schaden, die Bedrohung durch all Eure Aktionen ist massiv erhöht und Eure Fähigkeit 'Finte' wird durch 'Reizen' ersetzt. 'Reizen' verspottet das Ziel, damit es Euch angreift.\n\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211391] = {name = "[q2]Rune des heilenden Regens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Heilender Regen':\n\n\nWählt einen Bereich von 15 Metern um den anvisierten Spielercharakter aus und heilt alle Gruppenmitglieder des anvisierten Spielercharakters im Bereich pro Sekunde um [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] Gesundheit.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211392] = {name = "[q2]Rune der immerwährenden Gebrechen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Hosen mit der Rune 'Immerwährende Gebrechen':\n\n\n'Blutsauger', 'Seelendieb', 'Schattenblitz', 'Schattenspalten', 'Sengender Schmerz', 'Einäschern' und 'Heimsuchung' setzen die Dauer Eurer 'Verderbnis' auf dem Ziel auf das Maximum zurück.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211393] = {name = "[q2]Rune des zielstrebigen Furors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Handschuhe mit der Rune 'Zielstrebiger Furor':\n\n\nWenn Ihr mit zwei Waffen kämpft, wird Eure Bewegungsgeschwindigkeit um 10% erhöht und Ihr erhaltet immer, wenn Euer automatischer Angriff das selbe Ziel wie Euer vorheriger automatischer Angriff trifft, 4% Angriffstempo, bis zu einem Maximum von 5 Stapeln. Hält 10 Sek. lang an oder bis Eure automatischen Angriffe ein anderes Ziel treffen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211419] = {name = "[q2]Handvoll veränderlicher Schuppen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Diese seltsamen Schuppen schimmern leicht, als wären sie nicht ganz körperlich. Hier ist sicherlich wundersame Magie am Spiel... wenn Ihr nur jemanden finden könntet, der mehr über sie weiß.\""},
[211420] = {name = "[q3]Veränderlicher Schuppentalisman", additional_info = "Wird beim Aufheben gebunden\nSchmuck\n+5 Willenskraft\nBenötigt Stufe 25\n[q2]Anlegen: Schützt den Träger vor den Effekten von 'Erdrückende Dunkelheit'."},
[211421] = {name = "Die Kiste", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Versucht, eine mächtige Quelle des Lichts einzusetzen, um die Kiste zu zerstören.\n[q]\"Wenn Ihr die Kiste mit bloßen Händen berührt, werdet Ihr sofort von tiefem Unwohlsein erfüllt... aber auch von einem Gefühl der kreativen Inspiration, das Ihr noch nie verspürt habt.\""},
[211422] = {name = "[q4]Splitter der Leere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Alles, was von der Kiste noch übrig ist, ist ein kleiner Splitter eines pechschwarzen Kristalls. Er scheint, das Licht anzuziehen und zu verschlucken.\""},
[211423] = {name = "[q4]Leerenberührte Lederhandschuhe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\n{Hände} {Leder}\n[q2]110 Rüstung\n+6 Beweglichkeit\n+6 Ausdauer\n+4 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nBenötigt Lederverarbeitung (100)\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Benutzen: Verfallt in Wahnsinn und erhöht so 10 Sek. lang Euer Angriffstempo um 10% sowie Eure erzeugte Bedrohung. (10 Min Abklingzeit)"},
[211426] = {name = "[q2]Zweig der Schatten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Dieser vom Smaragdgrünen Alptraum besudelte Splitter entzieht seinem Träger das Leben.\""},
[211427] = {name = "[q3]Seelengefäß", additional_info = "[q]\"Fängt Dämonenseelen ein und entzieht ihnen Macht.\""},
[211443] = {name = "[q2]Klinge des Zorns", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{31 - 47 Schaden} {Tempo 3.50}\n(11.14 Schaden pro Sekunde)\n50 Rüstung\n+3 Stärke\nHaltbarkeit 60 / 60\nBenötigt Stufe 13"},
