[211450] = {name = "[q3]Leerenperle des Herbeirufers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Void Pearl] (1)\nSchmuck\n+10 Schattenwiderstand\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 11."},
[211451] = {name = "[q3]Leerenperle des Akolythen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Void Pearl] (1)\nSchmuck\n+10 Schattenwiderstand\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 20."},
[211452] = {name = "[q3]Perfekte Blackfathom-Perle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 25\n[q]\"Aku'mai, Diener der Alten Götter, ist tot. Bashana Runetotem wird davon hören wollen.\""},
[211454] = {name = "Seltsame Wasserkugel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 25"},
[211455] = {name = "[q3]Glatte fingerlose Handschuhe", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Leder}\n68 Rüstung\n+7 Ausdauer\n+5 Intelligenz\nHaltbarkeit 35 / 35\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 22.\n[q2]Anlegen: Erhöht durch Naturzauber und Natureffekte zugefügten Schaden um bis zu 14."},
[211456] = {name = "[q3]Dolch des willigen Opfers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n{12 - 27 Schaden} {Tempo 1.50}\n(13.00 Schaden pro Sekunde)\n60 Rüstung\n+4 Ausdauer\n+3 Intelligenz\nHaltbarkeit 65 / 65\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12."},
