[211468] = {name = "[q3]Zerfetzter kastanienbrauner Mantel", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Stoff}\n30 Rüstung\n+2 Ausdauer\n+6 Intelligenz\nHaltbarkeit 40 / 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 5."},
[211471] = {name = "Cliffspring-Schlüssel", additional_info = "Einzigartig"},
[211472] = {name = "[q2]Buchband der Verbannung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nKlassen: Paladin\n[q2]Prägt Eure Hosen mit der Rune 'Aurenmeisterschaft':\n\n\nVerleiht allen durch Eure Fähigkeit 'Aura der Konzentration' gestärkten Zielen Immunität gegen Unterbrechungs- und Stilleeffekte. Die Effekte aller anderen Auren werden um 100% erhöht. Hält 6 Sek. lang an.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 'Untote vertreiben' auf 5 Gegner gewirkt und diese dann mit 'Exorzismus' getötet habt.\""},
[211476] = {name = "[q2]Rune des Feuersees", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'See des Feuers':\n\n\nEuer 'Feuerregen' wird nicht mehr kanalisiert, aber erhält eine Abklingzeit von 8 Sek.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211477] = {name = "[q2]Rune des Verbrennens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Armschienen mit der Rune 'Verbrennen':\n\n\nVerbrennt Euren Gegner, fügt ihm [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] bis [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] Schaden zu und erhöht jeglichen von Euch verursachten Feuerschaden 15 Sek. lang um 40%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211482] = {name = "Opfergabe der Shatterspear", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[211487] = {name = "[q2]Sprengladungen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Platziert eine Bombe mit einer kurzen Lunte auf dem Boden vor Euch.\n[q]\"Scheint nur zum Entfernen von Schutt und Geröll gut zu sein.\""},
[211488] = {name = "[q2]Rune des Rächers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Hosen mit der Rune 'Schild des Rächers':\n\n\nSchleudert einen heiligen Schild auf den Gegner, der [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] bis [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] Heiligschaden verursacht, ihn benommen macht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 3 Ziele. Hält 5 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211490] = {name = "[q2]Prophezeiung der tausend Lichter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Handschuhe mit der Rune 'Kreis der Heilung':\n\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100] bis [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] Gesundheit.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist.\n[q]\"Erlernt eine neue Runenschnitzenfähigkeit.\""},
[211491] = {name = "[q4]Bodenlose Tasche aus Murlochaut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n14 Platz Behälter"},
[211492] = {name = "[q4]Kelris' Beutel", additional_info = "Wird beim Aufheben gebunden\n16 Platz Seelentasche\nKlassen: Hexenmeister"},
[211498] = {name = "[q3]Nachtsäbler des Schildwachenrekruten", additional_info = "Wird beim Aufheben gebunden\nReittier\nBenötigt eine Allianz-Rasse\nBenötigt Stufe 25\n[q2]Benutzen: Beschwört einen Nachtsäbler des Schildwachenrekruten. Kann nur in Ashenvale verwendet werden. (3 Sek. Abklingzeit)"},
[211499] = {name = "[q3]Vorhutwolf des Rekruten", additional_info = "Wird beim Aufheben gebunden\nReittier\nBenötigt eine Horde-Rasse\nBenötigt Stufe 25\n[q2]Benutzen: Beschwört einen Vorhutwolf des Rekruten. Kann nur in Ashenvale verwendet werden. (3 Sek. Abklingzeit)"},
[211500] = {name = "[q3]Zähes Stirnband", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Kopf} {Stoff}\n50 Rüstung\nHaltbarkeit 50 / 50\nBenötigt Stufe 20\n[q2]Anlegen: Reduziert jeglichen erlittenen Schaden und die Chance, kritische Treffer zu erleiden in der Warsongschlucht um 5%."},
[211501] = {name = "[q4]Brustschutz der Macht", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Platte}\n749 Rüstung\n+27 Stärke\n+18 Ausdauer\n+10 Feuerwiderstand\nHaltbarkeit 165 / 165\nKlassen: Krieger\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\n[q2]Anlegen: Verbessert Eure Trefferchance um 1%."},
[211502] = {name = "[q4]Leerenberührte Lederstulpen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\n{Hände} {Leder}\n70 Rüstung\n+5 Ausdauer\n+7 Intelligenz\n+6 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nBenötigt Lederverarbeitung (100)\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Benutzen: Verfallt in Wahnsinn und erhöht so 10 Sek. lang Euren Zauberschaden um 10% sowie Eure erzeugte Bedrohung. (10 Min Abklingzeit)"},
[211504] = {name = "[q3]Kettenpanzer des Twilight-Rächers", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Kette}\n218 Rüstung\n+9 Stärke\n+6 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 25\n[q2]Anlegen: Verteidigung +4.\n\n[q]Kettenrüstung des Blackfathom-Rächers (0/3)\n[q0]Stiefel des Twilight-Rächers\nKettenpanzer des Twilight-Rächers\nHelm des Twilight-Rächers\n[q0](2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211505] = {name = "[q0]Helm des Twilight-Rächers", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Kette}\n176 Rüstung\n+9 Stärke\n+11 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\n[q2]Anlegen: Verteidigung +4.\n\n[q]Kettenrüstung des Blackfathom-Rächers (0/3)\n[q0]Stiefel des Twilight-Rächers\nKettenpanzer des Twilight-Rächers\nHelm des Twilight-Rächers\n[q0](2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211506] = {name = "[q3]Stiefel des Twilight-Rächers", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Kette}\n150 Rüstung\n+10 Stärke\n+5 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 25\n\n[q]Kettenrüstung des Blackfathom-Rächers (0/3)\n[q0]Stiefel des Twilight-Rächers\nKettenpanzer des Twilight-Rächers\nHelm des Twilight-Rächers\n[q0](2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211507] = {name = "[q3]Gugel des Twilight-Elementaristen", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Leder}\n84 Rüstung\n+9 Ausdauer\n+10 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 8.\n\n[q]Lederrüstung des Blackfathom-Elementaristen (0/3)\n[q0]Gugel des Twilight-Elementaristen\nFußpolster des Twilight-Elementaristen\nRobe des Twilight-Elementaristen\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211508] = {name = "[q3]Fußpolster des Twilight-Elementaristen", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Leder}\n71 Rüstung\n+5 Beweglichkeit\n+7 Intelligenz\n+7 Willenskraft\nHaltbarkeit 55 / 55\nBenötigt Stufe 25\n\n[q]Lederrüstung des Blackfathom-Elementaristen (0/3)\n[q0]Gugel des Twilight-Elementaristen\nFußpolster des Twilight-Elementaristen\nRobe des Twilight-Elementaristen\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211509] = {name = "[q0]Robe des Twilight-Elementaristen", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Leder}\n103 Rüstung\n+10 Ausdauer\n+10 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\n\n[q]Lederrüstung des Blackfathom-Elementaristen (0/3)\n[q0]Gugel des Twilight-Elementaristen\nFußpolster des Twilight-Elementaristen\nRobe des Twilight-Elementaristen\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211510] = {name = "[q3]Gugel des Twilight-Schlächters", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Leder}\n84 Rüstung\n+10 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 25\n[q2]Anlegen: +14 Angriffskraft.\n\n[q]Lederrüstung des Blackfathom-Schlächters (0/3)\n[q0]Gugel des Twilight-Schlächters\nFußpolster des Twilight-Schlächters\nTunika des Twilight-Schlächters\n[q0](2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211511] = {name = "[q3]Fußpolster des Twilight-Schlächters", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Leder}\n71 Rüstung\n+5 Stärke\n+7 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 55 / 55\nBenötigt Stufe 25\n\n[q]Lederrüstung des Blackfathom-Schlächters (0/3)\n[q0]Gugel des Twilight-Schlächters\nFußpolster des Twilight-Schlächters\nTunika des Twilight-Schlächters\n[q0](2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211512] = {name = "[q0]Tunika des Twilight-Schlächters", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Leder}\n103 Rüstung\n+13 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\n\n[q]Lederrüstung des Blackfathom-Schlächters (0/3)\n[q0]Gugel des Twilight-Schlächters\nFußpolster des Twilight-Schlächters\nTunika des Twilight-Schlächters\n[q0](2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[211514] = {name = "[q2]Zaubernotizen: Massenregeneration", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Hosen mit der Rune 'Massenregeneration':\n\n\nHeilt alle verbündeten Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um den anvisierten Spielercharakter im Verlauf von 3 Sek. um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] Gesundheit und belegt jedes Ziel für 15 Sek. mit 'Zeitenleuchtfeuer'.\n\n Zeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211527] = {name = "[q3]Gemütlicher Schlafsack", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ihr rollt einen Schlafsack aus. Wenn Ihr Euch darin mindestens eine Minute lang ausruht, erhaltet Ihr einen Bonus auf die verdiente Erfahrung. Der Effekt ist 3-mal stapelbar. (1 Stunde Abklingzeit)\n[q]\"Alt, aber noch brauchbar.\""},
[211528] = {name = "Dunkle Einsicht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Benutzen: Meditiert über ein gewisses abgelegenes Grab im Dämmerwald, um eine Prophezeiung zu erhalten."},
[211530] = {name = "[q2]Prophezeiung der ergriffenen Stadt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Armschienen mit der Rune 'Machtwort: Barriere':\n\n\nBeschwört eine heilige Barriere, die alle Gruppenmitglieder am Zielort 10 Sek. lang beschützt. Die Barriere verringert sämtlichen erlittenen Schaden um 25% und verhindert, dass erlittener Schaden das Zaubern verzögert.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[211531] = {name = "[q2]Prophezeiung der sieben Besucher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Kraftvolle Seele':\n\n\n'Geringe Heilung', 'Heilung', 'Große Heilung' und 'Blitzheilung' verringern die verbleibende Dauer von 'Geschwächte Seele' auf den geheilten Zielen um 2 Sek. Zusätzlich erhalten Ziele Eures Zaubers 'Machtwort: Schild' 'Wut', wenn sie trotz absorbierten Schadens Schaden erleiden, und 'Zorn der Gerechtigkeit' wird durch von 'Machtwort: Schild' absorbiertem Schaden ausgelöst, als wäre es eine Heilung.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[211534] = {name = "Ursprüngliche Eingebung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Benutzen: Meditiert über einen Traumfänger der Distelfelle hoch in den Bäumen, um eine Prophezeiung zu erhalten."},
[211691] = {name = "[q2]Zaubernotizen: Arkanschlag", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Handschuhe mit der Rune 'Arkanschlag':\n\n\nÜberzieht das Ziel mit Energie und verursacht [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 453 / 100] bis [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 527 / 100] Arkanschaden. Mit jedem Wirken von 'Arkanschlag' wird der verursachte Schaden aller anderen Arkanzauber um 15% und die Manakosten von 'Arkanschlag' werden um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an oder bis ein anderer Arkanschadenszauber gewirkt wird.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[211777] = {name = "Nagamanuskript", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q2]<Zum Lesen rechtsklicken>"},
[211779] = {name = "Verständnisamulett", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q]\"Hilft bei der Übersetzung von Schriftrollen und Zaubernotizen.\""},
[211780] = {name = "Schriftrolle: KWYJIBO", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[211784] = {name = "Schriftrolle: WUBBA WUBBA", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[211785] = {name = "Schriftrolle: CWAL", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[211786] = {name = "Schriftrolle: CHAP BALK WELLES", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[211787] = {name = "Schriftrolle: UNTERPING SONSTWEM", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[211789] = {name = "[q3]Artemisgugel", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Leder}\n84 Rüstung\n+7 Beweglichkeit\n+6 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 25\n[q2]Anlegen: +24 Angriffskraft."},
[211799] = {name = "Sack voller gestohlener Waren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q]\"Wahrscheinlich aus der Kathedrale, als Ada davongelaufen ist.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[211800] = {name = "Schriftrolle der Reintegration", additional_info = "Klassen: Magier\nBenötigt Stufe 12\n[q2]Benutzen: Bringt einen toten Spielercharakter mit 15% Gesundheit und Mana wieder ins Leben zurück. Kann nicht im Kampf verwendet werden."},
[211809] = {name = "Verständnisfibel", additional_info = "Questgegenstand\nKlassen: Magier\n[q]\"Hilft bei der Übersetzung elementarer Zaubernotizen.\""},
[211813] = {name = "[q2]Amulett der Schildwache der Silverwing", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ihr habt das von einem gefallenen Kämpfer der Schildwachen der Silverwing erhalten. Der Scharfseher könnte daran interessiert sein.\""},
[211814] = {name = "[q2]Abzeichen der Warsongvorhut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ihr habt das von einem gefallenen Kämpfer der Warsongvorhut erhalten. Die Mondpriesterin könnte daran interessiert sein.\""},
[211815] = {name = "Schlachthymne der Silverwing", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht sämtlichen verursachten Schaden und sämtliche gewirkte Heilung 2 Stunden lang um 5%.\n[q]\"Ein ergreifendes Arrangement, um vor der Schlacht die Moral zu steigern.\""},
[211816] = {name = "Warsongkampftrommel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht sämtlichen verursachten Schaden und sämtliche gewirkte Heilung 2 Stunden lang um 5%.\n[q]\"Kriegstrommeln, um sich auf die Schlacht vorzubereiten.\""},
[211818] = {name = "Seltsame Wasserkugel", additional_info = "Questgegenstand\nEinzigartig"},
[211819] = {name = "[q2]Abgefangene Vorräte: Bronzebarren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 12 Bronzebarren hinzu, um die Lieferung zu vervollständigen."},
[211820] = {name = "[q2]Abgefangene Vorräte: Silberbarren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 6 Silberbarren hinzu, um die Lieferung zu vervollständigen."},
[211821] = {name = "[q2]Abgefangene Vorräte: Mittleres Leder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 12 Stücke mittleres Leder hinzu, um die Lieferung zu vervollständigen."},
[211822] = {name = "[q2]Abgefangene Vorräte: Beulengras", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 20 Bündel Beulengras hinzu, um die Lieferung zu vervollständigen."},
[211823] = {name = "[q2]Abgefangene Vorräte: Flitzdistel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 20 Bündel Flitzdistel hinzu, um die Lieferung zu vervollständigen."},
[211824] = {name = "[q2]Abgefangene Vorräte: Geringe Manatränke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 20 geringe Manatränke hinzu, um die Lieferung zu vervollständigen."},
[211825] = {name = "[q2]Abgefangene Vorräte: Raue bronzene Stiefel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 3 raue bronzene Stiefel hinzu, um die Lieferung zu vervollständigen."},
[211826] = {name = "[q2]Abgefangene Vorräte: Silberdietriche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 14 Silberdietriche hinzu, um die Lieferung zu vervollständigen."},
[211827] = {name = "[q2]Abgefangene Vorräte: Runenverzierte Silberruten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 1 runenverzierte Silberruten hinzu, um die Lieferung zu vervollständigen."},
