[211842] = {name = "[q3]Rakkamars zerfledderte Denkkappe", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Stoff}\n38 Rüstung\n+8 Intelligenz\n+6 Willenskraft\nHaltbarkeit 55 / 55\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 14."},
[211843] = {name = "[q3]Maske der Verachtung", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Kette}\n177 Rüstung\n+9 Stärke\n+7 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\n[q2]Anlegen: Verteidigung +7."},
[211845] = {name = "[q2]Blackfathom-Wetzstein", additional_info = "[q2]Benutzen: Erhöht die Trefferchance 30 Min. lang um 2%, wenn es auf eine Waffe angewendet wird. Dies hat außerhalb der Blackfathom-Tiefe keinen Effekt.\n[q]\"Diese geheimnisvollen verzauberten Steine scheinen immer heller zu leuchten, je tiefer Ihr in Blackfathom hinabsteigt.\""},
[211846] = {name = "[q3]Pläne: Blackfathom-Wetzstein", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (100)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Blackfathom-Wetzsteins.\n\n\n[q2]Blackfathom-Wetzstein\n[q2]Benutzen: Erhöht die Trefferchance 30 Min. lang um 2%, wenn es auf eine Waffe angewendet wird. Dies hat außerhalb der Blackfathom-Tiefe keinen Effekt.\n[q]\"Diese geheimnisvollen verzauberten Steine scheinen immer heller zu leuchten, je tiefer Ihr in Blackfathom hinabsteigt.\"\nBenötigt Grober Wetzstein , Geringe Magieessenz"},
[211848] = {name = "[q2]Blackfathom-Manaöl", additional_info = "Benötigt Stufe 25\n[q2]Benutzen: Stellt 5 Min. lang alle 5 Sek. 12 Mana wieder her und erhöht dabei den Zaubertrefferwert um 2%, wenn es auf eine Waffe angewendet wird. Dieser Effekt funktioniert nur in der Blackfathom-Tiefe.\n5 Aufladungen"},
[211849] = {name = "[q3]Formel: Blackfathom-Manaöl", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (100)\n[q2]Benutzen: Lehrt Euch die Herstellung von Blackfathom-Manaöl.\n\n\n[q2]Blackfathom-Manaöl\nBenötigt Stufe 25\n[q2]Benutzen: Stellt 5 Min. lang alle 5 Sek. 12 Mana wieder her und erhöht dabei den Zaubertrefferwert um 2%, wenn es auf eine Waffe angewendet wird. Dieser Effekt funktioniert nur in der Blackfathom-Tiefe.\n5 Aufladungen\nBenötigt Verbleite Phiole , Große Magieessenz , Seltsamer Staub (5)"},
[211852] = {name = "[q3]Handlappen des besudelten Wassers", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Stoff}\n[q2]69 Rüstung\n+6 Ausdauer\n+4 Intelligenz\nHaltbarkeit 35 / 35\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 9."},
[211853] = {name = "Schriftrolle: VOCE WELL", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[211854] = {name = "Schriftrolle: OMIT KESA", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
