[211856] = {name = "[q3]Zähe Kettenhaube", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Kopf} {Kette}\n175 Rüstung\nHaltbarkeit 50 / 50\nBenötigt Stufe 20\n[q2]Anlegen: Reduziert jeglichen erlittenen Schaden und die Chance, kritische Treffer zu erleiden in der Warsongschlucht um 5%."},
[211857] = {name = "[q3]Zähe Ledermaske", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Kopf} {Leder}\n80 Rüstung\nHaltbarkeit 50 / 50\nBenötigt Stufe 20\n[q2]Anlegen: Reduziert jeglichen erlittenen Schaden und die Chance, kritische Treffer zu erleiden in der Warsongschlucht um 5%."},
[211933] = {name = "[q2]Abgefangene Vorräte: Rauer Stein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 10 raue Steine hinzu, um die Lieferung zu vervollständigen."},
[211934] = {name = "[q2]Abgefangene Vorräte: Heiltränke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 10 Heiltränke hinzu, um die Lieferung zu vervollständigen."},
[211935] = {name = "[q2]Abgefangene Vorräte: Elixier der Feuermacht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\n[q2]Benutzen: Fügt 15 Elixiere der Feuermacht hinzu, um die Lieferung zu vervollständigen."},
[211940] = {name = "[q3]Ecks'avs Stammeswächter", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{155 - 231 Schaden} {Tempo 3.70}\n(52.16 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 59\n[q2]Anlegen: Gibt in der Nähe befindlichen Gruppenmitgliedern 4 Min. lang 40 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen."},
[211941] = {name = "[q3]Yari des Windläufers", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{147 - 223 Schaden} {Tempo 3.60}\n(51.39 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 58\n[q2]Trefferchance: Überzieht den Feind mit der Macht des Windes, des Feuers und all solchen Dingen!"},
[211944] = {name = "[q3]Tojaras Karma", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{158 - 234 Schaden} {Tempo 3.50}\n(56.00 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 58\n[q2]Trefferchance: Eine Flammenwelle geht vom Zaubernden aus, fügt allen Feinden, die da hineingeraten, 208 bis 249 Punkt(e) Feuerschaden zu und macht sie 6 Sek. lang benommen."},
[211953] = {name = "[q2]Schriftrolle der arkanen Erholung I", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\n[q2]Benutzen: Stellt alle 5 Sek. 8 Mana wieder her."},
[211954] = {name = "[q2]Schriftrolle der arkanen Präzision I", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\n[q2]Benutzen: Erhöht Eure Chance auf Treffer mit Zaubern um 1%."},
[211955] = {name = "[q2]Schriftrolle des Arkanschutzes - Feuer I", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\n[q2]Benutzen: Erhöht 30 Min. lang Euren Feuerwiderstand um 20."},
[211956] = {name = "[q2]Schriftrolle des Arkanschutzes - Frost I", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\n[q2]Benutzen: Erhöht 30 Min. lang Euren Frostwiderstand um 20."},
[211957] = {name = "[q2]Schriftrolle der arkanen Macht I", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\n[q2]Benutzen: Erhöht Eure Chance auf kritische Treffer mit Zaubern um 1%."},
[212160] = {name = "Chronostärkungsversetzer", additional_info = "Saison der Entdeckungen\n[q2]Benutzen: Verändert das Gewebe der Zeit und schiebt positive Welteffekte auf, die aus Düsterbruch, Zul'Gurub und dem Teufelswald, sowie vom Drachentöten stammen. (5 Min Abklingzeit)"},
[212225] = {name = "[q3]Endloses Seelengefäß", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Euer nächster Einsatz eines Zaubers, der Seelensplitter verbraucht, kostet keine Seelensplitter. (5 Min Abklingzeit)"},
[212230] = {name = "[q3]Bauplan: Seelengefäß", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Seelengefäßes.\n[q3]Seelengefäß\n[q]\"Fängt Dämonenseelen ein und entzieht ihnen Macht.\"\nBenötigt Schattenedelstein (4), Schwarzes Vitriol , Dämonenstatuette"},
[212347] = {name = "Illaris Schlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[212548] = {name = "[q2]Rune der Finsternis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euren Gürtel mit der Rune 'Finsternis':\n\n\n'Sternenfeuer' erhöht die Chance auf kritische Treffer bei Euren nächsten beiden Einsätzen von 'Zorn' um 30%, und 'Zorn' verringert die Zauberzeit Eures nächsten Einsatzes von 'Sternenfeuer' um 1.0 Sek. Beide Effekte lassen sich bis zu 4-mal stapeln. Bei beiden Zaubern besteht außerdem jederzeit eine Chance von 70%, dass Ihr keine Zauberzeit verliert, wenn Ihr Schaden erleidet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212549] = {name = "[q2]Rune des Fallenstellers", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Eure Stiefel mit der Rune 'Fallenschleuder':\n\n\nEure Eiskältefallen, Feuerbrandfallen und Sprengfallen können jetzt an jedem Ort innerhalb von 35 Metern ausgelegt werden. Außerdem haben Eure feuer- und frostbasierten Fallen jetzt getrennte gemeinsame Abklingzeiten.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212551] = {name = "[q2]Rune der Kriegskunst", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Stiefel mit der Rune 'Die Kunst des Krieges':\n\n\nEure kritischen Nahkampftreffer verringern die verbleibende Abklingzeit von 'Exorzismus' um 2 Sek., und die Manakosten von 'Exorzismus' werden um 80% verringert.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212552] = {name = "[q2]Psychosophische Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\n\nFügt dem Ziel [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] bis [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212553] = {name = "Juwelenbesetzte Schatulle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Öffnen rechtsklicken>"},
[212559] = {name = "[q2]Rune der vergifteten Klinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euren Gürtel mit der Rune 'Vergiftetes Messer':\n\n\nWirft sofort Eure Schildhandwaffe auf das Ziel und fügt ihm den normalen Schaden dieser Waffe zu. Außerdem besteht eine Chance von 100%, das Ziel mit dem Gift Eurer Schildhandwaffe zu belegen. Gewährt 1 Combopunkt. Erstattet 5 Energie pro Anwendung von 'Tödliches Gift' auf dem Ziel.\n\n 'Vergiftetes Messer' nutzt die Vorteile aller Talente und Effekte, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212560] = {name = "[q2]Rune des Erwachens der Ahnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Stiefel mit der Rune 'Erwachen der Ahnen':\n\n\nWenn Ihr mit 'Welle der Heilung' oder 'Geringe Welle der Heilung' einen kritischen Effekt erzielt, wird ein Ahnengeist beschworen, der sofort das Gruppenmitglied mit der geringsten Gesundheit innerhalb von 40 Metern um 30% des von Euch geheilten Wertes heilt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212561] = {name = "[q2]Rune der brennenden Dunkelheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Gürtel mit der Rune 'Schatten und Flamme':\n\n\nKritische Treffer Eurer Feuer- und Schattenzauber erhöhen den von Euch verursachten Feuer und Schattenschaden 10 Sek. lang um 10%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212562] = {name = "[q2]Rune des heilenden Zorns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Stiefel mit der Rune 'Wütende Regeneration':\n\n\nHeilt Euch im Verlauf von 10 Sek. um 30% Eurer maximalen Gesundheit, kann jedoch nur eingesetzt werden, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist. Kann auch während Betäubung eingesetzt werden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[212568] = {name = "[q3]Wolfskopftrophäe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenötigt Stufe 40\n[q2]Benutzen: Einen Gegenstand für den Helmplatz dauerhaft verzaubern, sodass Ihr 20 Energie oder 5 Wut erhaltet, wenn Ihr Euch in die Katzen- oder Bärengestalt verwandelt."},
[212580] = {name = "[q3]Stab des Wissenshüters", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{57 - 87 Schaden} {Tempo 2.90}\n(24.83 Schaden pro Sekunde)\n+10 Ausdauer\n+6 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her."},
