[212996] = {name = "[q3]Bindungen des Blitzrufers", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Leder}\n53 Rüstung\n+5 Ausdauer\n+7 Intelligenz\nHaltbarkeit 35 / 35\nKlassen: Schamane\nBenötigt Stufe 35\n[q2]Anlegen: Erhöht Eure Chance mit Zaubern zu treffen um 1%."},
[212997] = {name = "[q3]Bindungen des Gezeitenrufers", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Leder}\n53 Rüstung\n+5 Ausdauer\n+7 Intelligenz\nHaltbarkeit 35 / 35\nKlassen: Schamane\nBenötigt Stufe 35\n[q2]Anlegen: Stellt alle 5 Sek. 3 Punkt(e) Mana wieder her."},
[213036] = {name = "Wasser aus Elune'ara", additional_info = "Questgegenstand\nDauer: 1 Stunde (Realzeit)\n[q2]Benutzen: Gebt einem Urtumschössling Wasser. (1 Min Abklingzeit)\n[q]\"Eine zerbrechliche Kugel mit Wasser, gesegnet vom Urtum Orokai.\""},
[213074] = {name = "[q2]Rune der Pflege", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euren Gürtel mit der Rune 'Pflege':\n\n\nHeilt ein verbündetes Ziel um [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] bis [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] Gesundheit. Wenn ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen', 'Wildwuchs' oder 'Blühendes Leben' auf dem Ziel aktiv ist, erhöht sich die Heilung um zusätzliche 20%. Dieser Zauber profitiert von allen Effekten von 'Heilende Berührung' oder 'Nachwachsen' und löst diese aus.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213086] = {name = "[q2]Rune des Stroms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euren Gürtel mit der Rune 'Waffe des Mahlstroms':\n\n\nWenn Ihr mit einem Nahkampfangriff Schaden verursacht, besteht eine Chance, dass die Zauberzeit und Manakosten Eures nächsten Einsatzes von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung' oder 'Lavaeruption' um 20% verringert werden. Diese Chance ist um 50% erhöht, während Eure Waffenhandwaffe mit 'Waffe des Windzorns' belegt ist, und um weitere 50% erhöht, wenn Ihr eine Zweihandwaffe führt. Bis zu 5-mal stapelbar. Hält 30 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213087] = {name = "[q3]Umhang des Waffenträgers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n24 Rüstung\n+4 Stärke\n+4 Beweglichkeit\n+4 Ausdauer\n+4 Intelligenz\n+4 Willenskraft\nBenötigt Stufe 25"},
[213088] = {name = "[q3]Umhang des Waffenträgers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n24 Rüstung\n+4 Stärke\n+4 Beweglichkeit\n+4 Ausdauer\n+4 Intelligenz\n+4 Willenskraft\nBenötigt Stufe 25"},
[213090] = {name = "[q2]Rune der Synergie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Gürtel mit der Rune 'Grimoire der Synergie':\n\n\nWenn Ihr oder Euer beschworener Dämon Schaden verursacht, besteht eine Chance von 10%, den verursachten Schaden des anderen 15 Sek. lang um 10% zu erhöhen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213092] = {name = "[q2]Rune des Alphas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Stiefel mit der Rune 'Geist des Alphas':\n\n\nErfüllt das Ziel mit dem Geist eines Alphawolfes, was die generierte Bedrohung des Ziels 30 Min. lang um 45% erhöht. Maximal 1 Ziel. Wenn der Schamane diesen Zauber nicht auf sich selbst wirkt, erhält er 'Treuer Beta', was 30 Min. lang seinen verursachten körperlichen Schaden um 5% erhöht und jegliche erzeugte Bedrohung um 30% verringert. Ein Ziel kann nicht gleichzeitig mit 'Geist des Alphas' und 'Treuer Beta' belegt sein.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213093] = {name = "[q2]Rune der Kraft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euren Gürtel mit der Rune 'Kraftwoge':\n\n\nJedes Mal, wenn Euer 'Flammenschock' Schaden verursacht, besteht eine Chance von 5%, dass die Abklingzeiten von 'Lavaeruption' und 'Kettenblitzschlag' abgeschlossen werden und Euer nächster Einsatz von 'Lavaeruption' oder 'Kettenblitzschlag' innerhalb von 10 Sek. ein Spontanzauber ist. Jedes Mal, wenn Eure 'Springflut' heilt, besteht eine Chance von 5%, dass Euer nächster Einsatz von 'Kettenheilung' innerhalb von 10 Sek. ein Spontanzauber ist. Zusätzlich erhaltet Ihr alle 5 Sek. Mana in Höhe von 15% Eurer Intelligenz.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213094] = {name = "[q2]Rune der Feuernova", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euren Gürtel mit der Rune 'Feuernova':\n\n\nEuer Totem der Feuernova wird durch 'Feuernova' ersetzt. Dadurch verursacht Euer derzeitiges Feuertotem Schaden an seinem Standort.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213096] = {name = "[q2]Rune der Täuschung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Stiefel mit der Rune 'Täuschtotem':\n\n\nBeschwört zu Füßen des Ziels ein Täuschtotem mit 5 Gesundheit, das 10 Sek. lang bestehen bleibt und den nächsten Nahkampf- oder Distanzangriff auf das Ziel stattdessen auf das Totem ablenkt. Das Totem gewährt dem Ziel außerdem 10 Sek. lang Immunität gegen bewegungseinschränkende Effekte.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213098] = {name = "[q2]Rune der Anrufung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Gürtel mit der Rune 'Anrufung':\n\n\nWenn Ihr 'Verderben', 'Feuerbrand', 'Fluch der Pein', 'Instabiles Gebrechen', 'Schattenflamme' oder 'Lebensentzug' anwendet, fügt dies dem Ziel sofortigen Schaden in Höhe eines Ticks des regelmäßigen Schadens des Zaubers zu. Wenn die verbleibende Effektdauer weniger als 6 Sek. beträgt, fügt das Erneuern eines dieser Zauber dem Ziel sofortigen Schaden in Höhe des verbleibenden regelmäßigen Schadens des Zaubers zu.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213100] = {name = "[q2]Rune des verbotenen Wissens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Stiefel mit der Rune 'Dämonisches Wissen':\n\n\nErhöht Zauberschaden und -heilung um einen Wert, der 3% der maximalen Ausdauer plus der Intelligenz Eures Dämons entspricht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213101] = {name = "[q2]Rune der Schattenflammen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Stiefel mit der Rune 'Schattenflamme':\n\n\nVerbrennt den Gegner und fügt ihm [173 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100 * ( ( ( 1 ) ) ) ] Schattenflammenschaden sowie zusätzlich [64 * 5 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] Schattenflammenschaden im Verlauf von 15 Sek. zu.\n\n 'Schattenflamme' wird ausgelöst und profitiert von allen Effekten, die 'Feuerbrand' modifizieren oder damit oder mit Gebrechen-, Zerstörungs-, Feuer- oder Schattenzaubern interagieren. Auf einem Ziel kann immer nur ein Effekt von 'Feuerbrand' oder 'Schattenflamme' pro Hexenmeister aktiv sein. Zusätzlich kann 'Schattenflamme' das Talent 'Verbesserter Schattenblitz' auslösen und gewährt diesem 26 zusätzliche Aufladungen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213102] = {name = "[q2]Rune der Tücke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Stiefel mit der Rune 'Tanz des Tückischen':\n\n\nIhr und Euer Dämon erhaltet jedes Mal, wenn Ihr einem Gegner einen kritischen Treffer zufügt, eine Ausweichchance in Höhe von 70% Eurer kritischen Zaubertrefferchance. Ihr beide gewinnt außerdem 2% Eures maximalen Manas zurück.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213103] = {name = "[q2]Rune der Blutwoge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Gürtel mit der Rune 'Blutwoge':\n\n\nBeim Einsatz von 'Heldenhafter Stoß', 'Blutdurst' und 'Wirbelwind' besteht eine Chance von 30%, dass Euer nächster Einsatz von 'Zerschmettern' innerhalb von 15 Sek. sofort eingesetzt wird, mit beiden Nahkampfwaffen zuschlägt und keine Wut kostet.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213104] = {name = "[q2]Rune der unbarmherzigen Präzision", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Gürtel mit der Rune 'Genau zur rechten Zeit':\n\n\n'Zerschmettern' wird jetzt sofort eingesetzt, hat allerdings eine Abklingzeit von 6 Sek.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213105] = {name = "[q3]Schawarmageddon", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Streitkolben}\n{50 - 93 Schaden} {Tempo 2.60}\n(27.50 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nKlassen: Krieger\nBenötigt Stufe 40\n[q2]Benutzen: Erhöht das Angriffstempo um 4% und verleiht allen Nahkampfangriffen eine Chance, zusätzlich 7 Feuerschaden zu verursachen. (2 Min Abklingzeit)"},
[213109] = {name = "[q2]Rune der fokussierten Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Gürtel mit der Rune 'Fokussierte Wut':\n\n\nVerringert die Wutkosten aller Angriffsfähigkeiten um 3.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213110] = {name = "[q2]Rune des Kommandanten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Stiefel mit der Rune 'Anspornender Schrei':\n\n\nStoßt einen anspornenden Schrei aus, der die maximale Gesundheit aller Gruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern 10 Sek. lang um 15% erhöht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213111] = {name = "[q2]Rune des Einschreitens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Stiefel mit der Rune 'Einschreiten':\n\n\nLauft mit hoher Geschwindigkeit auf ein Gruppenmitglied zu, um den nächsten Nahkampf- oder Distanzangriff gegen diese Person abzufangen und seine gesamte Bedrohung um 10% zu verringern.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213112] = {name = "[q2]Zaubernotizen: Geschosssalve", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Gürtel mit der Rune 'Geschosssalve':\n\n\nVerleiht Eurem Zauber 'Arkanschlag' eine Chance von 40% sowie Euren Zaubern 'Feuerball' und 'Frostblitz' eine Chance von 20%, die Kanalisierungsdauer Eures nächsten Einsatzes von 'Arkane Geschosse' um 50% zu verringern, die Manakosten um 100% zu verringern und alle 0,5 Sek. Geschosse abzufeuern.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213113] = {name = "[q2]Zaubernotizen: Kampfeshitze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Helm mit der Rune 'Kampfeshitze':\n\n\nJedes Mal, wenn Ihr mit 'Feuerball', 'Frostfeuerblitz', 'Qualfeuerblitz', 'Feuerschlag', 'Versengen' oder 'Lebende Bombe' 2 unregelmäßige kritische Zaubertreffer in Folge erzielt, wird Euer nächster Einsatz von 'Pyroschlag' innerhalb von 10 Sek. zu einem Spontanzauber und kostet 100% weniger Mana.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213116] = {name = "[q2]Zaubernotizen: Chronostatische Bewahrung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Stiefel mit der Rune 'Chronostatische Bewahrung':\n\n\nVerbindet Arkan-, Feuer- und Frostmagie, um chronomantische Energie zur Aufbewahrung und späteren Verwendung einzufrieren. Ihr könnt diese Energie bis zu 20 Sek. lang speichern, bevor sie explodiert und verschwindet. Heilt bei Freisetzung ein verbündetes Ziel um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 220 / 100] bis [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 330 / 100] Gesundheit.\n\n Dieser Zauber gilt in Interaktionen mit anderen Zaubern, Talenten und Effekten als Arkan, Feuer und Frost.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213117] = {name = "[q2]Rune des Berserkers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euren Gürtel mit der Rune 'Berserker':\n\n\nWenn aktiviert, lässt diese Fähigkeit 'Zerfleischen (Bär)' und 'Aufschlitzen' bis zu 3 Ziele treffen. 'Aufschlitzen' kostet keine Wut und 'Zerfleischen (Bär)' unterliegt keiner Abklingzeit. In Katzengestalt werden die Energiekosten aller Eurer Fähigkeiten um 50% verringert. Hält 15 Sek. lang an. Erfordert Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n\n Entfernt sofort Furchteffekte und macht Euch während seiner Dauer gegen sie immun.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213118] = {name = "[q2]Rune des Königs des Dschungels", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Stiefel mit der Rune 'König des Dschungels':\n\n\n'Tigerfuror' erhöht nun jeglichen von Euch verursachten körperlichen Schaden um 15% statt eines festen Werts und gewährt Euch sofort 60 Energie. Der Zauber ist nicht mehr an die globale Abklingzeit gebunden, hat aber nun seine eigene Abklingzeit von 30 Sekunden. Zusätzlich bleibt 'Tigerfuror' bestehen, wenn Ihr Euch nicht mehr in Katzengestalt befindet, wird jedoch entfernt, sobald Ihr in Bären- oder Terrorbärengestalt wechselt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213119] = {name = "[q2]Rune des Instinkts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Stiefel mit der Rune 'Überlebensinstinkte':\n\n\nNach Aktivierung erhaltet Ihr 20 Sek. lang 30% Eurer maximalen Gesundheit. Während dieser Zeit wird zudem sämtliche von Euch hervorgerufene nichtkörperliche Heilung um 20% erhöht. Nachdem der Effekt abgelaufen ist, geht die Gesundheit verloren. Kann in jeder Gestalt mit Ausnahme der Moonkingestalt eingesetzt werden.\n\n Zusätzlich regeneriert Ihr bei jedem Ausweichen in Bärengestalt oder Terrorbärengestalt 5 Wut, in Katzengestalt 10 Energie oder in jeder anderen Gestalt 1% Eures maximalen Manas.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213120] = {name = "[q2]Rune des Träumers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Stiefel mit der Rune 'Traumzustand':\n\n\nKritische Treffer Eurer nicht regelmäßigen Schadenszauber und jeglicher Schaden von Eurem 'Sternensog' gewähren Euch 8 Sek. lang 50% Manaregeneration, während Ihr Zauber wirkt. Der Arkan- und Naturschaden gegen Ziele, bei denen es sich nicht um Spielercharaktere handelt, wird außerdem 12 Sek. lang um 20% erhöht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213121] = {name = "[q2]Konservierter Tannenzweig", additional_info = "Benötigt Stufe 25\n[q2]Benutzen: Verwandelt Euer Reittier in eine etwas festlichere Gestalt. (1 Min Abklingzeit)"},
[213122] = {name = "[q2]Rune des zuverlässigen Schusses", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Euren Gürtel mit der Rune 'Zuverlässiger Schuss':\n\n\nEin zuverlässiger Schuss, der 100% Schaden mit Distanzwaffen verursacht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213123] = {name = "[q2]Rune des Aufdeckens", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Euren Gürtel mit der Rune 'Schwäche aufdecken':\n\n\nEure kritischen Treffer mit Nahkampf- und Distanzangriffen erhöhen 7 Sek. lang Eure Angriffskraft um 40% Eurer aktuellen Beweglichkeit.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213124] = {name = "[q2]Rune des Nahkampfs", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Euren Gürtel mit der Rune 'Nahkampfspezialist':\n\n\n'Raptorstoß' ist nun ein Spontanzauber, und 'Mungobiss' und 'Raptorstoß' haben bei jedem Angriff eine Chance von 40%, die Abklingzeiten von 'Mungobiss' und 'Raptorstoß' abzuschließen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213125] = {name = "[q2]Rune der Kräftigung", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Eure Stiefel mit der Rune 'Flügeldrachenstoß':\n\n\nErsetzt Eure Fähigkeit 'Stich des Flügeldrachen' durch 'Flügeldrachenstoß', einen grausamen Stoß, der 140% Waffenschaden verursacht und dem Ziel regelmäßigen Blutungsschaden zufügt.\n\n 'Flügeldrachenstoß' erfordert, dass Ihr das Talent 'Stich des Flügeldrachen' erlernt und ersetzt die 'Stich des Flügeldrachen'-Fähigkeiten aus dem Überleben-Zauberbuch.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213126] = {name = "[q2]Rune des Streiters", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Eure Stiefel mit der Rune 'Beidhändigkeitsspezialisierung':\n\n\nErhöht den von Eurer Schildhandwaffe verursachten Schaden um 60% und führt dazu, dass Euer 'Raptorstoß' mit beiden Waffen trifft, wenn Ihr beidhändig kämpft.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213127] = {name = "[q2]Zaubernotizen: BLAUBERZORFSTITZ", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen."},
[213128] = {name = "[q2]Rune der Frömmigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Gürtel mit der Rune 'Formbarer Schutz':\n\n\nIhr könnt handeln, während 'Göttlicher Schutz' aktiv ist, und die Dauer ist um 50% erhöht. Die Fähigkeit verringert Euren erlittenen Schaden jedoch nur um 50%, anstatt Euch immun zu machen. Das Aktivieren von 'Heiliger Schild' gewährt Euch außerdem 4 Angriffskraft pro Punkt Eurer Verteidigungsfähigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213129] = {name = "[q2]Rune der Umarmung des Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Gürtel mit der Rune 'Ummantelung des Lichts':\n\n\nWenn Ihr mit Eurer Nahkampfwaffe Schaden verursacht, erhöht sich Euer Zauberschaden 1 Min. lang um einen Betrag in Höhe von 30% Eurer Angriffskraft.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213130] = {name = "[q2]Rune der Infusion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Gürtel mit der Rune 'Lichtinfusion':\n\n\nErhöht den Schaden und die Heilung, die Euer 'Heiliger Schock' verursacht, um 50%, und reduziert die Abklingzeit von 'Heiliger Schock' auf 6 Sek. Zudem erstatten Eure kritischen Treffer mit 'Heiliger Schock' die Manakosten und verringern die verbleibende Abklingzeit um 3 Sek.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213131] = {name = "[q2]Rune des geheiligten Schildes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Stiefel mit der Rune 'Geheiligter Schild':\n\n\nJedes Mal, wenn das Ziel Schaden erleidet, wird es von einem geheiligten Schild umhüllt, der [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] Schaden absorbiert und die Chance des Paladins, mit 'Lichtblitz' einen kritischen Treffer zu erzielen, bis zu 6 Sek. lang um 50% erhöht. Zusätzlich heilen Eure Einsätze von 'Lichtblitz' Ziele mit 'Geheiligter Schild' im Verlauf von 12 Sek. um weitere 100% Gesundheit. Dieser Effekt kann nur einmal alle 6 Sek. auftreten. Hält 1 Min. lang an. Es kann immer nur jeweils ein Ziel mit diesem Zauber belegt sein.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213132] = {name = "[q2]Rune des Behüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Stiefel mit der Rune 'Vom Licht behütet':\n\n\nJedes Mal, wenn Ihr ein Ziel mit Eurer Nahkampfwaffe trefft, gewinnt Ihr 15 Sek. lang alle 3 Sek. 5% Eures maximalen Manas. Während dieser Manaregeneration ist der durch Eure Heilzauber geheilte Wert jedoch um 50% verringert.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213136] = {name = "[q2]Rune des hinterhältigen Angriffs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Stiefel mit der Rune 'Meister des hinterhältigen Angriffs':\n\n\nAngriffe, die aus dem Verstohlenheitsmodus und bis zu 6 Sek. nach Verlassen des Verstohlenheitsmodus ausgeführt werden, verursachen 10% zusätzlichen Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213137] = {name = "[q2]Rune des Auflauernden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Stiefel mit der Rune 'Auflauern':\n\n\nDie Treffer Eurer Fähigkeiten 'Hinterhalt' und 'Meucheln' bringen Euer Ziel aus dem Gleichgewicht, was die Zeit zwischen seinen Nahkampfangriffen um 10% erhöht sowie seine Bewegungsgeschwindigkeit um 50% verringert. Hält 8 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213138] = {name = "[q2]Rune des Rechtsauslegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Stiefel mit der Rune 'Schläge abschwächen':\n\n\nJedes Mal, wenn Ihr ausweicht oder pariert, erhaltet Ihr 5% mehr Gesundheit. Bis zu 5-mal stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213139] = {name = "[q2]Rune des Assassinen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euren Gürtel mit der Rune 'Shurikenwurf':\n\n\nWirft einen Shuriken auf Euren Gegner, der Schaden in Höhe von 50% Eurer Angriffskraft verursacht und bis zu 4 weitere Gegner in der Nähe trifft. Gewährt 1 Combopunkt pro getroffenem Ziel.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213140] = {name = "[q2]Prophezeiung des beschleunigten Pfads", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Gürtel mit der Rune 'Machterfüllte Erneuerung':\n\n\nEuer Einsatz von 'Erneuerung' heilt sofort ein weiteres Mal und profitiert bei jeder Heilung um 15% mehr von Eurem Bonus für Heilungseffekte.\n\n Darüber hinaus kann Eure 'Erneuerung' jetzt auf Zielen aktiv sein, die von 'Erneuerung' eines anderen Priesters betroffen sind.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[213141] = {name = "[q2]Rune der Hoffnung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Gürtel mit der Rune 'Erneuerte Hoffnung':\n\n\nErhöht die Effekte Eurer Einsätze von 'Blitzheilung', 'Geringe Heilung', 'Heilung', 'Große Heilung' und 'Sühne' um 20%, wenn Ihr sie auf Ziele anwendet, die mit 'Geschwächte Seele' belegt sind.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213142] = {name = "[q2]Prophezeiung der gefangenen Bösartigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Stiefel mit der Rune 'Dispersion':\n\n\nLöst Euch zu reiner Schattenenergie auf und verringert jeglichen erlittenen Schaden um 90%. Ihr könnt weder angreifen noch Zauber wirken, regeneriert jedoch 6 Sek. lang alle 1 Sek. 6% Mana. 'Dispersion' kann gewirkt werden, während Betäubungs-, Furcht- oder Stilleeffekte auf Euch wirken. Bei Anwendung werden alle wirkenden Verlangsamungs- und bewegungseinschränkenden Effekte entfernt und Ihr werdet für die Dauer des Effektes von 'Dispersion' gegen sie immun.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[213143] = {name = "[q2]Apokryphische Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Stiefel mit der Rune 'Schmerzunterdrückung':\n\n\nVerringert sofort sämtlichen Schaden, den ein verbündetes Ziel erleidet, um 40% und erhöht den Widerstand gegen Bannzauber 8 Sek. lang um 65%.\n[q]\"Erlernt eine neue Runenschnitzenfähigkeit.\""},
[213144] = {name = "[q2]Leuchtende Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Stiefel mit der Rune 'Geist des Erlösers':\n\n\nAktivieren, um 10 Sek. lang zum Geist der Erlösung zu werden. In dieser Gestalt könnt Ihr alle Heilzauber kostenlos wirken, Ihr könnt Euch aber nicht bewegen, nicht angreifen, nicht angegriffen werden oder von Zaubern oder Effekten als Ziel ausgewählt werden. Erfordert das Talent 'Geist der Erlösung', um aktiviert zu werden, und wenn Ihr sterbt, nehmt Ihr die Gestalt 'Geist der Erlösung' nicht mehr an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[213165] = {name = "Basilisken: Muss man Angst vor der Versteinerung haben?", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Ein Versuch einer Forschungsarbeit über die Verwendung von Basiliskenteilen als Reagenzien. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[213168] = {name = "[q2]Kupferblutmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Transmutiert 100 Kupferblutmünzen in 1 Silberblutmünze.\n[q]\"Ein Zeichen für Eure bescheidenen Dienste für den Blutloa.\""},
[213169] = {name = "[q3]Silberblutmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Transmutiert 100 Silberblutmünzen in 1 Goldblutmünze.\n[q]\"Ein Zeichen für Eure Dienste für den Blutloa.\""},
[213170] = {name = "[q4]Goldblutmünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein Symbol Eurer herausragenden Dienste für den Blutloa.\""},
