[213279] = {name = "[q3]Reflektierende Schädelkappe", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Kette}\n222 Rüstung\n+11 Ausdauer\n+13 Intelligenz\n+8 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 13."},
[213280] = {name = "[q3]Schützensuchervisier", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Kette}\n222 Rüstung\n+9 Beweglichkeit\n+13 Ausdauer\n+8 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%."},
[213281] = {name = "[q3]Elektromagnetischer Hyperflux-Reaktivator", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Stoff}\n55 Rüstung\n+15 Intelligenz\n+12 Willenskraft\nHaltbarkeit 50 / 50\nBenötigt Stufe 40\n[q2]Benutzen: Kanalisiert einen Blitzschlag, schleudert ihn auf alle Feinde vor dem Zaubernden und fügt dabei 152 bis 172 Punkt(e) Naturschaden zu. Der Zaubernde ist danach 10 Minuten lang von einer Barriere aus Elektrizität umgeben. (30 Min Abklingzeit)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 16."},
[213282] = {name = "[q4]Hochaufgeladene Ausrüstung der Innovation", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Hypercharged Gear] (1)\nFinger\n+5 Intelligenz\n+8 Willenskraft\n+5 Arkanwiderstand\n+5 Naturwiderstand\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 13.\n[q2]Anlegen: Stellt alle 5 Sek. 3 Punkt(e) Mana wieder her."},
[213283] = {name = "[q4]Hochaufgeladene Ausrüstung der Feuersbrunst", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Hypercharged Gear] (1)\nFinger\n+4 Intelligenz\n+5 Arkanwiderstand\n+5 Naturwiderstand\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 11.\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her."},
