[213288] = {name = "[q3]Grubbis schmierige Stulpen", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Platte}\n300 Rüstung\n+9 Stärke\n+5 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%."},
