[213291] = {name = "[q4]Toxinvergelter II", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Einhändig} {Dolch}\n{43 - 80 Schaden} {Tempo 1.80}\n(34.17 Schaden pro Sekunde)\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\n[q2]Trefferchance: Fügt allen Gegnern in einem Radius von 8 Metern um den Zaubernden 15 Sek. lang alle 5 Sek. 30 Naturschaden zu."},
[213292] = {name = "[q3]Gizmotronisches Gigahackbeil", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{102 - 153 Schaden} {Tempo 3.20}\n(39.84 Schaden pro Sekunde)\n+22 Stärke\n+9 Beweglichkeit\nHaltbarkeit 100 / 100\nBenötigt Stufe 40"},
[213293] = {name = "[q3]Hightech-Superschusswaffe V7", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Schusswaffe}\n{38 - 71 Schaden} {Tempo 2.30}\n(23.70 Schaden pro Sekunde)\n+4 Ausdauer\n[q2]+ 12 Angriffskraft.\nHaltbarkeit 75 / 75\nBenötigt Stufe 40"},
[213294] = {name = "[q3]Sabatons der Tiefentroggs", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Platte}\n330 Rüstung\n+7 Stärke\n+9 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 65 / 65\nBenötigt Stufe 40\n[q2]Anlegen: Verteidigung +4."},
[213295] = {name = "[q3]Ultraschallvibroklinge", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Axt}\n{49 - 91 Schaden} {Tempo 2.30}\n(30.43 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 40\n[q2]Trefferchance: Durchsticht die Rüstung des Ziels und verringert sie um 160."},
[213296] = {name = "[q3]Überladener Kopffäller", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Axt}\n{89 - 133 Schaden} {Tempo 2.80}\n(39.64 Schaden pro Sekunde)\n+13 Stärke\n+12 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\n[q2]Trefferchance: Trifft ein Ziel mit 80 bis 100 Naturschaden."},
[213297] = {name = "[q3]Oszillierender Sprenghammer", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Streitkolben}\n{52 - 94 Schaden} {Tempo 2.40}\n(30.42 Schaden pro Sekunde)\n+5 Stärke\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 40\n[q2]Anlegen: Verteidigung +4."},
[213298] = {name = "[q3]Overall des Robobauers", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Stoff}\n[q2]185 Rüstung\n+6 Beweglichkeit\n+14 Ausdauer\n+12 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40"},
[213299] = {name = "[q3]Petroleumpfützenhose", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Leder}\n117 Rüstung\n[q2]<Zufällige Verzauberung>\n+21 Beweglichkeit\n+11 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 40\n[q]\"Von Feuer fernhalten.\""},
[213300] = {name = "[q3]Kämpferasshandschuhe", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Stoff}\n[q2]111 Rüstung\n+6 Ausdauer\n+10 Intelligenz\nHaltbarkeit 30 / 30\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 9."},
[213301] = {name = "[q3]Synthetischer Mantel", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Stoff}\n[q2]99 Rüstung\n+8 Ausdauer\n+9 Intelligenz\nHaltbarkeit 50 / 50\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12."},
[213302] = {name = "[q3]Mantel des raffinierten Verhandlers", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Leder}\n100 Rüstung\n+14 Beweglichkeit\n+11 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 40"},
[213303] = {name = "[q3]Blitzableiterschiftung", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Kette}\n205 Rüstung\n+7 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht durch Naturzauber und Natureffekte zugefügten Schaden um bis zu 17."},
[213304] = {name = "[q3]Troggtöterschulterstücke", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Kette}\n205 Rüstung\n+12 Beweglichkeit\n+5 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\n[q2]Anlegen: +22 Angriffskraft."},
[213305] = {name = "[q3]Schulterplatten aus bearbeiteter Legierung", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Platte}\n[q2]410 Rüstung\n+12 Stärke\n+11 Ausdauer\nHaltbarkeit 80 / 80\nBenötigt Stufe 40"},
[213306] = {name = "[q3]Bedeckung des Einfallsreichtums", additional_info = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+4 Ausdauer\n+9 Intelligenz\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 9."},
[213307] = {name = "[q3]Tuch des Zerlegens", additional_info = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+8 Stärke\n+6 Beweglichkeit\n+7 Ausdauer\nBenötigt Stufe 40"},
[213308] = {name = "[q3]Fallschirmumhang-Prototyp", additional_info = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+12 Beweglichkeit\n+4 Ausdauer\nBenötigt Stufe 40\n[q2]Benutzen: Reduziert 10 Sek. lang Euer Falltempo. (30 Min Abklingzeit)\n[q]\"Dieser Umhang ist fantastisch gearbeitet. Er wird an Euch hervorragend aussehen, bis es zur unvermeidlichen Fehlfunktion kommt und er in Flammen aufgeht.\""},
[213309] = {name = "[q3]Umhang des Erfindungsreichtums", additional_info = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+7 Intelligenz\n+6 Willenskraft\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 15.\n[q2]Anlegen: Stellt alle 5 Sek. 2 Punkt(e) Mana wieder her."},
[213310] = {name = "[q3]Hyperleitendes Schimmerhemd", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Stoff}\n65 Rüstung\n+6 Ausdauer\n+10 Willenskraft\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 29.\n[q2]Anlegen: Stellt alle 5 Sek. 6 Punkt(e) Mana wieder her.\n\n[q]Hyperleitende Heilermeditation (0/3)\n[q0]Hyperleitendes Schimmerhemd\nHyperleitende Pantalons\nHyperleitende Sandalen\n[q0](2) Set : +14 Willenskraft.\n(3) Set : Stellt alle 5 Sek. 7 Punkt(e) Mana wieder her."},
[213311] = {name = "[q3]Hyperleitende Robe", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Stoff}\n[q2]145 Rüstung\n+10 Ausdauer\n+11 Intelligenz\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 18.\n\n[q]Hyperleitende Zaubererkleidung (0/3)\n[q0]Hyperleitende Robe\nHyperleitende Laufschuhe\nHyperleitender Rock\n[q0](2) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n(2) Set : +100 Rüstung.\n(3) Set : Beim Wirken eines Zaubers besteht die Chance, dass Euer Schaden und Eure Heilung 10 Sek. lang um bis zu 40 erhöht werden. (Procchance: 10%)"},
