[213352] = {name = "[q3]Gunst des Getriebemechanikers", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Streitkolben}\n{53 - 99 Schaden} {Tempo 2.50}\n(30.40 Schaden pro Sekunde)\n+4 Intelligenz\n+3 Willenskraft\nHaltbarkeit 90 / 90\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 20."},
[213353] = {name = "[q4]Defibrilationsstab", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{102 - 160 Schaden} {Tempo 3.30}\n(39.70 Schaden pro Sekunde)\n+11 Ausdauer\n+14 Intelligenz\n+15 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 35.\n[q2]Anlegen: Erhöht durch Arkanzauber und Arkaneffekte zugefügten Schaden um bis zu 26.\n[q2]Benutzen: Mit diesem Stab kann man manchmal einen toten Spielercharakter ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)"},
[213354] = {name = "[q3]Stab des bösen Genies", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{80 - 121 Schaden} {Tempo 3.30}\n(30.45 Schaden pro Sekunde)\n+4 Ausdauer\n+4 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 20.\n[q]\"Auf dem Schaft steht der Name \"T. Ückisch\".\""},
[213355] = {name = "[q3]Falcos Stachel", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Armbrust}\n{33 - 62 Schaden} {Tempo 2.00}\n(23.75 Schaden pro Sekunde)\n+8 Beweglichkeit\nHaltbarkeit 75 / 75\nBenötigt Stufe 40\n[q]\"In die Schulterstütze ist ein kleiner Mantikor graviert.\""},
[213356] = {name = "[q4]Thermapluggs maßgefertigter Blaster", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Schusswaffe}\n{54 - 100 Schaden} {Tempo 2.90}\n(26.55 Schaden pro Sekunde)\nHaltbarkeit 95 / 95\nBenötigt Stufe 40\n[q2]Anlegen: +26 Distanzangriffskraft."},
[213369] = {name = "[q3]Schwach leuchtendes Leder", additional_info = nil},
[213370] = {name = "[q2]Bestrahlte Lederfetzen", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein geschickter Lederer könnte daraus etwas Nützliches herstellen.\""},
[213371] = {name = "[q2]Kiste mit besudelter Gniodin-Lösung", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein geschickter Alchimist könnte daraus etwas Nützliches herstellen.\""},
[213372] = {name = "[q3]Isolierendes Gniodin", additional_info = nil},
[213373] = {name = "[q2]Reflektierender Metallschrott", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein geschickter Schmied könnte daraus etwas Nützliches herstellen.\""},
[213376] = {name = "[q3]Echtsilberplatten mit geringer Grundstrahlung", additional_info = nil},
[213378] = {name = "[q2]Instabiler Mikrofaden", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein geschickter Schneider könnte daraus etwas Nützliches herstellen.\""},
[213379] = {name = "[q3]Hyperleitender Arkanfaden", additional_info = nil},
[213381] = {name = "[q2]Haufen aus stumpfen Zahnrädern", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein geschickter Ingenieur könnte daraus etwas Nützliches herstellen.\""},
[213383] = {name = "[q3]Polierte Echtsilberzahnräder", additional_info = nil},
[213390] = {name = "[q4]Wirbelnder Echtsilberzahnradschild", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n1760 Rüstung\n29 Blocken\n+9 Stärke\n+10 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\n[q2]Anlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 1%.\n[q2]Anlegen: Bei erfolgreichem Blocken fügen die wirbelnden rasiermesserscharfen Zahnräder dieses Schilds dem Angreifer 5 bis 10 körperlichen Schaden und dem Träger 2 bis 10 körperlichen Schaden zu.\n[q]\"Die rotierenden Schneiden dieses Schilds sind überraschend scharfkantig. Er wirkt genauso gefährlich für den Träger wie für den Angreifer.\""},
[213391] = {name = "[q4]UNBENUTZTE elektrifizierte Mithrilstulpen", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Platte}\n300 Rüstung\n+16 Stärke\n+7 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Stufe 40"},
[213407] = {name = "Katzenminze", additional_info = "Klassen: Druide\nBenötigt Stufe 20\n[q2]Benutzen: Erhöht Euer Angriffstempo 30 Sek. lang um 50%. (3 Min Abklingzeit)\n[q]\"Ursprünglich von Ristell Klaue kultiviert, um die Druiden der Klaue vor dem Kampf anzustacheln.\""},
[213408] = {name = "[q3]Gyromatischer Makroregler", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{101 - 152 Schaden} {Tempo 3.20}\n(39.53 Schaden pro Sekunde)\n+15 Beweglichkeit\n+9 Ausdauer\n+15 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40"},
[213409] = {name = "[q4]Mekkatorques Arkanoschredder", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Faustwaffe}\n{62 - 115 Schaden} {Tempo 2.60}\n(34.04 Schaden pro Sekunde)\n+2 Stärke\n+3 Beweglichkeit\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\n[q2]Trefferchance: Entlädt eine Explosion arkaner Energie, die 30 Arkanschaden verursacht, sämtliche Widerstände um 45 verringert und sämtlichen erlittenen Zauberschaden 20 Sek. lang um 6% erhöht. Wirkt nur bei Gegnern der Stufe 45 oder niedriger."},
[213410] = {name = "[q4]Gleißende Dingsdaklinge", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Dolch}\n{20 - 41 Schaden} {Tempo 1.20}\n(25.42 Schaden pro Sekunde)\n70 Rüstung\n+7 Ausdauer\n+4 Intelligenz\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 19."},
[213411] = {name = "[q3]Izzleflicks unlöschbarer Anzünder", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Zauberstab}\n{59 - 110 Feuerschaden} {Tempo 2.00}\n(42.25 Schaden pro Sekunde)\n+8 Intelligenz\nHaltbarkeit 65 / 65\nBenötigt Stufe 40\n[q]\"Jetzt sicher lagerbar!\""},
[213412] = {name = "[q4]Dielektrischer Sicherheitsschild", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n1760 Rüstung\n29 Blocken\n+9 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 22.\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her."},
[213413] = {name = "[q3]Großzügig gefütterte Schulterpolster", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Leder}\n100 Rüstung\n+8 Intelligenz\n+14 Willenskraft\nHaltbarkeit 50 / 50\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 11."},
[213414] = {name = "[q3]Schärpe des Mechheilers", additional_info = "Wird beim Aufheben gebunden\n{Taille} {Stoff}\n37 Rüstung\n+6 Intelligenz\n+6 Willenskraft\nHaltbarkeit 30 / 30\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 24.\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her."},
[213415] = {name = "[q3]Handgelenkwickel des Tüftlers", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Stoff}\n28 Rüstung\n+6 Intelligenz\n+7 Willenskraft\nHaltbarkeit 30 / 30\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 18."},
[213416] = {name = "[q4]Thermapluggs Raketenspaltbeil", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Axt}\n{117 - 175 Schaden} {Tempo 3.30}\n(44.24 Schaden pro Sekunde)\n+29 Stärke\n+12 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 40"},
[213417] = {name = "[q3]Echtsilberfadenkappe", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Platte}\n390 Rüstung\n+8 Ausdauer\n+12 Intelligenz\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Stellt alle 5 Sek. 5 Punkt(e) Mana wieder her."},
[213418] = {name = "[q3]Geschweißte Echtsilberlocken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Platte}\n210 Rüstung\n+6 Ausdauer\n+5 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 14."},
[213419] = {name = "[q3]9-60-Reparaturhandbuch", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+6 Ausdauer\n+6 Intelligenz\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 22."},
[213421] = {name = "Angesengte Notiz", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q2]<Zum Lesen rechtsklicken>"},
[213422] = {name = "Unleserliches Rezept", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest."},
[213426] = {name = "Ogerblitzschlagrute", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: In weicher Erde aufstellen."},
[213427] = {name = "[q2]Schmutzverkrustetes Bergungsgut", additional_info = nil},
[213442] = {name = "[q3]Klaue des Zahnradmeisters", additional_info = "Wird beim Aufheben gebunden\n{Schildhand} {Faustwaffe}\n{60 - 111 Schaden} {Tempo 2.80}\n(30.54 Schaden pro Sekunde)\n+6 Stärke\n+6 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 40"},
[213443] = {name = "Tickendes Geschenk", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[213444] = {name = "Matte Gebetsperle I", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Mögen jene, die sich gegen uns wenden, unsere Macht zu spüren bekommen.\""},
[213445] = {name = "Matte Gebetsperle II", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Möge das Licht uns schützen, wenn wir verwundet sind.\""},
[213446] = {name = "Matte Gebetsperle III", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Mögen die Frevler und Feiglinge zur Rechenschaft gezogen werden.\""},
[213447] = {name = "Gebetsperlenkranz des Lichts", additional_info = "Wird beim Aufheben gebunden\n[q]\"Wird von Mitgliedern der Kirche des Heiligen Lichts oft in Gebeten verwendet.\""},
[213448] = {name = "Göttliche Gebetsperle I", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert drei göttliche Gebetsperlen, um einen Gebetsperlenkranz herzustellen."},
[213449] = {name = "Göttliche Gebetsperle II", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert drei göttliche Gebetsperlen, um einen Gebetsperlenkranz herzustellen."},
[213450] = {name = "Göttliche Gebetsperle III", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert drei göttliche Gebetsperlen, um einen Gebetsperlenkranz herzustellen."},
[213451] = {name = "Verderbtes Feuertotem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Befleckt durch den Einfluss der Burning Blade ist dieses Totem knorrig, geschwärzt und vernarbt, und doch könnt Ihr das Element darin spüren. Jemand anderes wird über diese Entdeckung sicherlich genauso besorgt sein wie Ihr.\""},
[213452] = {name = "[q2]Inaktive heilige Rune", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q]\"Zunächst müsst Ihr Euer Leben für jemand anderes geben. Und dann, bevor Euer Geist loslässt, soll es Euch auf gleiche Weise vergolten werden.\""},
[213513] = {name = "[q2]Buchband der Erlösung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nKlassen: Paladin\nBenötigt Stufe 18\n[q2]Prägt Eure Stiefel mit der Rune 'Geheiligter Schild':\n\n\nJedes Mal, wenn das Ziel Schaden erleidet, wird es von einem geheiligten Schild umhüllt, der [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] Schaden absorbiert und die Chance des Paladins, mit 'Lichtblitz' einen kritischen Treffer zu erzielen, bis zu 6 Sek. lang um 50% erhöht. Zusätzlich heilen Eure Einsätze von 'Lichtblitz' Ziele mit 'Geheiligter Schild' im Verlauf von 12 Sek. um weitere 100% Gesundheit. Dieser Effekt kann nur einmal alle 6 Sek. auftreten. Hält 1 Min. lang an. Es kann immer nur jeweils ein Ziel mit diesem Zauber belegt sein.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 5-mal 'Segen der Freiheit' eingesetzt habt, um andere Charaktere von bewegungseinschränkenden Effekten zu befreien.\""},
[213526] = {name = "Hybride Keule", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Schmeckt wie Rind *und* Hühnchen.\""},
[213527] = {name = "Gewürzmischung des Schmugglers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Das Kronjuwel in jeder Kombüse. Könnte sogar einem Stiefel Wohlgeschmack verleihen.\""},
[213528] = {name = "Mildes Gebräu", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Nicht das, was man unter einem \"Kühlen Blonden\" versteht.\""},
[213529] = {name = "Viskoses Gift", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Frisst sich problemlos durch Sumpfkreaturen. Fantastisch für Marinaden.\""},
[213542] = {name = "[q3]Das Nekro-Gnomikon", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+2 Intelligenz\n+2 Willenskraft\n+3 Schattenwiderstand\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 14."},
[213543] = {name = "Schriftrolle: UPDOG", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[213544] = {name = "Schriftrolle: TOPAZ YORAK", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[213545] = {name = "Schriftrolle: ZAEHLEZ STARKDEUTIEN", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[213546] = {name = "Schriftrolle: SCHUBIDU", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[213547] = {name = "Schriftrolle: WELCH SCHWESTER", additional_info = "Klassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[213548] = {name = "Schriftrolle des Schwellenübergangs", additional_info = "Klassen: Magier\nBenötigt Stufe 6\n[q2]Benutzen: Teleportiert zu einem Gruppenmitglied. Ihr und das Ziel müsst in einem Gasthaus oder einer Stadt rasten."},
[213549] = {name = "Schriftrolle des arkanen Angelns", additional_info = "Klassen: Magier\nBenötigt Stufe 12"},
[213550] = {name = "Schriftrolle der Verwandlung: Seltsame Melone", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 16\n[q2]Benutzen: Verwandelt das Ziel in eine seltsame Melone. (5 Sek. Abklingzeit)"},
[213551] = {name = "Schriftrolle der kontrollierten Verzerrung", additional_info = "Klassen: Magier\nBenötigt Stufe 12"},
[213552] = {name = "Träne von Theradras", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Diese werden vom Zentaurenstamm der Gelkis gehortet und streng bewacht und es heißt, sie würden dem Nutzer den Schutz der irdenen Geister gewähren.\""},
[213553] = {name = "Träne von Theradras", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Diese werden vom Zentaurenstamm der Gelkis gehortet und streng bewacht und es heißt, sie würden dem Nutzer den Schutz der irdenen Geister gewähren.\""},
[213554] = {name = "Phiole mit Kristallwasser", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Mit den Tränen von Theradras mischen, um eine Elementarsalbe herzustellen, die Verderbnis läutern kann.\n[q]\"Das Wasser ist so kristallklar, dass die Phiole leer erscheint.\""},
[213558] = {name = "Elementarsalbe", additional_info = "[q2]Benutzen: Über verderbte Objekte gießen, um sie zu läutern.\n[q]\"Eine wirkungsvolle Salbe, die tiefsitzende Verderbnis läutern kann.\""},
[213559] = {name = "[q3]Roboschreiterkuppler", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Zauberstab}\n{44 - 83 Arkanschaden} {Tempo 1.50}\n(42.33 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 9.\n[q]\"Dieser Gegenstand setzt die Existenz von Roboschreitern mit Schaltgetriebe voraus.\""},
[213560] = {name = "[q3]Roboschreiterdämpfer", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Streitkolben}\n{51 - 95 Schaden} {Tempo 2.40}\n(30.42 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 40\n[q2]Anlegen: +16 Angriffskraft."},
[213562] = {name = "Insektenfangnetz", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fangt ein exotisches Insekt und behaltet es als Versuchsobjekt. (30 Sek. Abklingzeit)"},
[213563] = {name = "Leitfaden", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Lesen rechtsklicken>"},
[213564] = {name = "Schriftrolle der geringeren Hervorrufung", additional_info = "Klassen: Magier\n[q2]Benutzen: Stellt Mana wieder her. (8 Min Abklingzeit)"},
[213565] = {name = "Einsteigerpaket für Entomologen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger , Druide\n[q2]<Zum Öffnen rechtsklicken>"},
[213566] = {name = "Versuchsobjekt: Laubengangtarantel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[213567] = {name = "Versuchsobjekt: Fleischpflücker", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[213568] = {name = "Versuchsobjekt: Heurüsselkäfer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[213572] = {name = "Seele der Leere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Reine Leerenenergie.\""},
[213573] = {name = "Amulett des Herbeizauberers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q2]Benutzen: Kombiniert 10 Amulette des Herbeizauberers und eine Seele der Leere in der Nähe eines Leerenprismas."},
[213574] = {name = "Ausgetrocknete Samenkapsel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Muss rehydriert werden, bevor sie eingepflanzt werden kann.\""},
[213583] = {name = "[q2]Schwefelschnitzerei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Es scheint, als hätte der vorherige Besitzer etwas zu häufig mit Feuer gespielt.\""},
[213594] = {name = "[q2]Götze der Zwischenrufe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nKlassen: Druide\nBenötigt Stufe 28\n[q2]Prägt Euren Gürtel mit der Rune 'Berserker':\n\n\nWenn aktiviert, lässt diese Fähigkeit 'Zerfleischen (Bär)' und 'Aufschlitzen' bis zu 3 Ziele treffen. 'Aufschlitzen' kostet keine Wut und 'Zerfleischen (Bär)' unterliegt keiner Abklingzeit. In Katzengestalt werden die Energiekosten aller Eurer Fähigkeiten um 50% verringert. Hält 15 Sek. lang an. Erfordert Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n\n Entfernt sofort Furchteffekte und macht Euch während seiner Dauer gegen sie immun.\n[q]\"Verspottet 2 oder mehr Gegner mit 'Herausforderndes Gebrüll' und tötet mindestens einen der beiden. Setzt nach 3 Siegen diesen Götzen ein, um eine neue Fähigkeit zu erlernen.\""},
[213599] = {name = "[q2]Beunruhigende Vision", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Gürtel mit der Rune 'Erneuerte Hoffnung':\n\n\nErhöht die Effekte Eurer Einsätze von 'Blitzheilung', 'Geringe Heilung', 'Heilung', 'Große Heilung' und 'Sühne' um 20%, wenn Ihr sie auf Ziele anwendet, die mit 'Geschwächte Seele' belegt sind.\n[q2]Benutzen: Konzentriert Euch auf die Vision, um einen neuen Zauber zu lernen. Erfordert einen Blick auf verderbtes Wissen."},
[213632] = {name = "[q2]Unvollständige Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Kombiniert alle gesammelten unvollständigen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Zwei Drittel fehlen.\""},
[213633] = {name = "[q2]Unvollständige Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Kombiniert alle gesammelten unvollständigen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Zwei Drittel fehlen.\""},
[213634] = {name = "[q2]Unvollständige Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Kombiniert alle gesammelten unvollständigen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Zwei Drittel fehlen.\""},
[213641] = {name = "[q3]Kiste mit Bergungsgut aus Gnomeregan", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Kiste mit Bergungsgut aus Gnomeregan könnte etwas enthalten, was Euch in Eurem Beruf nützt.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[213701] = {name = "Kräftige Harpyienfeder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q2]Benutzen: Kombiniert 10 kräftige Harpyienfedern und 3 Wolkenschlangenfangzähne mit einem Seidenfaden, um eine Opfergabe für den Windgeist herzustellen."},
[213709] = {name = "Wolkenschlangenreißzahn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (3)\n[q2]Benutzen: Kombiniert 10 kräftige Harpyienfedern und 3 Wolkenschlangenfangzähne mit einem Seidenfaden, um eine Opfergabe für den Windgeist herzustellen."},
[213735] = {name = "[q3]Makelloser G-7-K.E.R.N.-Prozessor", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dieses Ding kann über 4 Millionen Gigaflops an relationalen Codebündeln niedriger Varianz vorberechnen. Wow!\""},
[213736] = {name = "[q2]Korrodierter G-7-K.E.R.N.-Prozessor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Dieser Prozessorkern ist voller verkrusteter Korrosionsrückstände und überzogen mit einer klebrigen schwarzen Substanz. Eine Modellnummer und ein paar unleserliche Worte lassen sich wegen der zähen Masse kaum noch entziffern. Ihr werdet wohl einen Spezialisten brauchen, um ihn wieder auf Vordermann zu bringen.\""},
[213737] = {name = "Opfergabe für den Windgeist", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Bringt dem Windgeist eine Opfergabe dar und beweist Euren Glauben."},
[214435] = {name = "Schlüssel zum Pumakäfig", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Öffnet den Pumakäfig."},
[215111] = {name = "[q4]Gneuro-verkettetes Arkanfaden-Monokel", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Stoff}\n58 Rüstung\n+10 Ausdauer\n+11 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Stufe 40\nBenötigt Schneiderei (225)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 22.\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\n[q2]Benutzen: Ihr macht Euch die latente Arkanenergie in der Umgebungsluft zunutze und erhaltet 'Aufgeladene Inspiration', was 12 Sek. lang die Manakosten aller Zauber um 50% verringert und ihren verursachten Schaden und die durch sie hervorgerufene Heilung um bis zu 50 erhöht. (10 Min Abklingzeit)"},
[215114] = {name = "[q4]Leuchtende hyperleitende Schuppenkappe", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Kette}\n242 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\n[q2]Benutzen: Belegt Euch mit 'Hyperleitender Schock', was Euch sofort 312 bis 688 Schaden zufügt, aber auch Euer Zauberwirken 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)"},
[215115] = {name = "[q4]Hyperleitendes Goldnetz", additional_info = "Wird beim Aufheben gebunden\n{Taille} {Stoff}\n40 Rüstung\n+9 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Benutzen: Ihr zieht eine hyperleitende Münze aus Eurem Gürtel und werft sie hoch. Kopf: Erhöht Eure kritische Trefferchance mit allen Zaubern und Angriffen 30 Sek. lang um 3%. Zahl: Erhöht Eure Bewegungsgeschwindigkeit 30 Sek. lang um 10%. (15 Min Abklingzeit)\n[q]\"Dieser Gürtel klickt leise, während Ihr Euch bewegt.\""},
[215127] = {name = "[q2]Hoch wirksame Strahlungsbombe", additional_info = "Benötigt Stufe 35\nBenötigt Ingenieurskunst (200)\n{[q2]Benutzen: Verursacht im Explosionsradius 150 bis 250 Feuerschaden} und zusätzlich 10 Sek. lang alle 2 Sek. 25 {Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen bis Abbruch lang um 25%. (1 Min Abklingzeit)}"},
[215129] = {name = "[q4]Formel: Waffe - Zerlegen", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (225)\n[q2]Benutzen: Eine Waffe dauerhaft verzaubern, sodass alle Zauber und Angriffe mechanischen Kreaturen manchmal 60 bis 90 zusätzlichen Schaden zufügen."},
[215138] = {name = "[q4]Formel: Brust - Vergelter", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (225)\n[q2]Benutzen: Lehrt Euch, wie man eine Brustrüstung dauerhaft so verzaubert, dass sie bei eingehenden Nahkampfangriffen 9 Schaden auf den Angreifer zurückwirft."},
[215141] = {name = "[q2]Verzaubertes Siegel: Innovation", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (225)\n[q2]Benutzen: Lehrt Euch, wie man ein Siegel der Innovation beschwört.\n[q2]Verzaubertes Siegel: Innovation\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 40\nBenötigt Verzauberkunst (225)\n[q2]Benutzen: Erhaltet ein verzaubertes Siegel der Innovation, das Euch ermächtigt, wodurch 30 Min. lang der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 20 und Eure Angriffskraft um 20 erhöht wird. Dieser Effekt kann nur außerhalb des Kampfes angewandt werden. (30 Min Abklingzeit)\nBenötigt Visionenstaub (5)"},
[215149] = {name = "[q4]Muster: Gneuro-verkettetes Arkanfaden-Monokel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (225)\n[q2]Benutzen: Lehrt Euch, wie man ein Gneuro-verkettetes Arkanfaden-Monokel herstellt.\n[q4]Gneuro-verkettetes Arkanfaden-Monokel\nWird beim Aufheben gebunden\n{Kopf} {Stoff}\n58 Rüstung\n+10 Ausdauer\n+11 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Stufe 40\nBenötigt Schneiderei (225)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 22.\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\n[q2]Benutzen: Ihr macht Euch die latente Arkanenergie in der Umgebungsluft zunutze und erhaltet 'Aufgeladene Inspiration', was 12 Sek. lang die Manakosten aller Zauber um 50% verringert und ihren verursachten Schaden und die durch sie hervorgerufene Heilung um bis zu 50 erhöht. (10 Min Abklingzeit)\nBenötigt Hyperleitender Arkanfaden (5), Schwach leuchtendes Leder , Isolierendes Gniodin , Visionenstaub (10), Magiestoffballen (10)"},
[215152] = {name = "[q4]Muster: Leuchtende Gneuro-verkettete Gugel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (225)\n[q2]Benutzen: Lehrt Euch, wie man eine leuchtende Gneuro-verkettete Gugel herstellt.\n[q4]Leuchtende Gneuro-verkettete Gugel\nWird beim Aufheben gebunden\n{Kopf} {Leder}\n118 Rüstung\n+14 Beweglichkeit\n+14 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: +3 Waffenschaden.\n[q2]Benutzen: Belegt Euch mit 'Gneurologischer Schock', was Euch sofort 343 bis 757 Schaden zufügt, aber auch Eure Nahkampf- und Distanzangriffe 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)\nBenötigt Hyperleitender Arkanfaden , Geschmeidiger dicker Balg (5), Seidenfaden (2), Schwach leuchtendes Leder (5)"},
[215153] = {name = "[q4]Bauplan: Wirbelnder Echtsilberzahnradschild", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\n[q2]Benutzen: Lehrt Euch, wie man einen wirbelnden Echtsilberzahnradschild herstellt.\n[q4]Wirbelnder Echtsilberzahnradschild\nWird beim Aufheben gebunden\n{Schild}hand} {Schild}\n1760 Rüstung\n29 Blocken\n+9 Stärke\n+10 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\n[q2]Anlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 1%.\n[q2]Anlegen: Bei erfolgreichem Blocken fügen die wirbelnden rasiermesserscharfen Zahnräder dieses Schilds dem Angreifer 5 bis 10 körperlichen Schaden und dem Träger 2 bis 10 körperlichen Schaden zu.\n[q]\"Die rotierenden Schneiden dieses Schilds sind überraschend scharfkantig. Er wirkt genauso gefährlich für den Träger wie für den Angreifer.\"\nBenötigt Echtsilberplatten mit geringer Grundstrahlung (3), Polierte Echtsilberzahnräder (5), Schwach leuchtendes Leder (2), Mithrilgehäuse (2), Gyrochronatom (2), Mithrilbarren (15)"},
[215155] = {name = "[q4]Pläne: Gehärteter Interferenzen-negierender Helm", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (225)\n[q2]Benutzen: Lehrt Euch, wie man einen gehärteten Interferenzen-negierenden Helm herstellt.\n[q4]Gehärteter Interferenzen-negierender Helm\nWird beim Aufheben gebunden\n{Kopf} {Platte}\n426 Rüstung\n+20 Stärke\n+14 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Benutzen: Gewährt höchste Konzentration, die 10 Sek. lang die Bewegungsgeschwindigkeit um 20% verringert, aber währenddessen Euren Zauberwiderstand gegen alle Magiearten um 50 sowie das Angriffstempo im Nahkampf um 20% erhöht. (10 Min Abklingzeit)\n[q]\"Schützt Euer Hirn garantiert vor allen Bedrohungen, physischen wie anderen!\"\nBenötigt Mithrilbarren (25), Echtsilberplatten mit geringer Grundstrahlung (4), Hyperleitender Arkanfaden , Schwach leuchtendes Leder (2)"},
[215156] = {name = "[q4]Bauplan: Hyperleitendes Goldnetz", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\n[q2]Benutzen: Lehrt Euch, wie man ein hyperleitendes Goldnetz herstellt.\n[q4]Hyperleitendes Goldnetz\nWird beim Aufheben gebunden\n{Taille} {Stoff}\n40 Rüstung\n+9 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Benutzen: Ihr zieht eine hyperleitende Münze aus Eurem Gürtel und werft sie hoch. Kopf: Erhöht Eure kritische Trefferchance mit allen Zaubern und Angriffen 30 Sek. lang um 3%. Zahl: Erhöht Eure Bewegungsgeschwindigkeit 30 Sek. lang um 10%. (15 Min Abklingzeit)\n[q]\"Dieser Gürtel klickt leise, während Ihr Euch bewegt.\"\nBenötigt Polierte Echtsilberzahnräder (3), Hyperleitender Arkanfaden (3), Schwach leuchtendes Leder , Goldbarren (10)"},
[215161] = {name = "[q4]Gehärteter Interferenzen-negierender Helm", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Platte}\n426 Rüstung\n+20 Stärke\n+14 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Benutzen: Gewährt höchste Konzentration, die 10 Sek. lang die Bewegungsgeschwindigkeit um 20% verringert, aber währenddessen Euren Zauberwiderstand gegen alle Magiearten um 50 sowie das Angriffstempo im Nahkampf um 20% erhöht. (10 Min Abklingzeit)\n[q]\"Schützt Euer Hirn garantiert vor allen Bedrohungen, physischen wie anderen!\""},
[215162] = {name = "Leicht bestrahlter Verjüngungstrank", additional_info = "Benötigt Stufe 35\n[q2]Benutzen: Stellt 262 bis 438 Mana und 340 bis 460 Gesundheit wieder her. Erhöht zudem 20 Sek. lang die Angriffskraft um 40 und den durch alle Zauber verursachten Schaden um 35. (2 Min Abklingzeit)\n[q]\"Mögliche Nebenwirkungen: Schwindel, Mundtrockenheit, Erschöpfung, Appetitlosigkeit, akute Strahlenvergiftung, Mutation und Tod. Bei der Anwendung den Anweisungen folgen.\""},
[215163] = {name = "[q4]Rezept: Leicht bestrahlter Verjüngungstrank", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (225)\n[q2]Benutzen: Lehrt Euch, wie man einen leicht bestrahlten Verjüngungstrank aufbrüht.\nLeicht bestrahlter Verjüngungstrank\nBenötigt Stufe 35\n[q2]Benutzen: Stellt 262 bis 438 Mana und 340 bis 460 Gesundheit wieder her. Erhöht zudem 20 Sek. lang die Angriffskraft um 40 und den durch alle Zauber verursachten Schaden um 35. (2 Min Abklingzeit)\n[q]\"Mögliche Nebenwirkungen: Schwindel, Mundtrockenheit, Erschöpfung, Appetitlosigkeit, akute Strahlenvergiftung, Mutation und Tod. Bei der Anwendung den Anweisungen folgen.\"\nBenötigt Kiste mit besudelter Gniodin-Lösung , Schwacher Verjüngungstrank , Ablagerung von Gnomeregan (3), Kristallphiole (5)"},
[215166] = {name = "[q4]Leuchtende Gneuro-verkettete Gugel", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Leder}\n118 Rüstung\n+14 Beweglichkeit\n+14 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: +3 Waffenschaden.\n[q2]Benutzen: Belegt Euch mit 'Gneurologischer Schock', was Euch sofort 343 bis 757 Schaden zufügt, aber auch Eure Nahkampf- und Distanzangriffe 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)"},
[215167] = {name = "[q4]Reflektierender Echtsilbergehirnkäfig", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Platte}\n426 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\n[q2]Benutzen: Gewährt verstärkte Willenskraft, die 10 Sek. lang Stille- und Unterbrechungseffekte sowie Zauberverzögerungen verhindert. (10 Min Abklingzeit)"},
[215168] = {name = "[q2]EZ-Thro-Strahlungsbombe", additional_info = "Benötigt Stufe 40\n{[q2]Benutzen: Verursacht im Explosionsradius 112 bis 188 Feuerschaden} und zusätzlich 10 Sek. lang alle 2 Sek. 10 {Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen 10 Sek. lang um 25%. (1 Min Abklingzeit)}\n[q]\"Eine abgeschwächte, aber nicht weniger tödliche Version ihres komplexeren Gegenstücks, für diejenigen, denen zwar die Kompetenz fehlt, die aber dafür Zuversicht im Überfluss haben.\""},
[215257] = {name = "Schriftrolle des Verständnis", additional_info = "Klassen: Magier\n[q2]Benutzen: Erschafft 2 Verständnisamulette, oder 4, wenn Ihr in einem Gasthaus oder einer Stadt rastet."},
[215365] = {name = "[q2]Mantel des Herbeirufers", additional_info = "Wird beim Anlegen gebunden\n{Schulter} {Stoff}\n32 Rüstung\n+5 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7."},
[215366] = {name = "[q2]Kordel des Herbeirufers", additional_info = "Wird beim Anlegen gebunden\n{Taille} {Stoff}\n24 Rüstung\n+5 Intelligenz\nHaltbarkeit 25 / 25\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7."},
[215367] = {name = "[q3]Muster: Schwach leuchtendes Leder", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (200)\n[q2]Benutzen: Lehrt Euch, wie man ein Bündel schwach leuchtendes Leder herstellt.\n[q3]Schwach leuchtendes Leder\nBenötigt Geschmeidiger dicker Balg , Bestrahlte Lederfetzen (5)"},
[215368] = {name = "[q3]Muster: Hyperleitender Arkanfaden", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (200)\n[q2]Benutzen: Lehrt Euch, wie man einen hyperleitenden Arkanfaden herstellt.\n[q3]Hyperleitender Arkanfaden\nBenötigt Magiestoffballen (2), Instabiler Mikrofaden (5), Schwerer Seidenfaden (5)"},
[215369] = {name = "[q2]Muster: Kordel des Herbeirufers", additional_info = "Benötigt Schneiderei (150)\n[q2]Benutzen: Lehrt Euch, wie man die Kordel des Herbeirufers näht.\n[q2]Kordel des Herbeirufers\nWird beim Anlegen gebunden\n{Taille} {Stoff}\n24 Rüstung\n+5 Intelligenz\nHaltbarkeit 25 / 25\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\nBenötigt Seidenstoffballen (3), Schattenedelstein , Feiner Faden , Grauer Farbstoff"},
[215370] = {name = "[q2]Muster: Mantel des Herbeirufers", additional_info = "Benötigt Schneiderei (150)\n[q2]Benutzen: Lehrt Euch, wie man den Mantel des Herbeirufers näht.\n[q2]Mantel des Herbeirufers\nWird beim Anlegen gebunden\n{Schulter} {Stoff}\n32 Rüstung\n+5 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Stufe 25\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\nBenötigt Seidenstoffballen (4), Grauer Farbstoff (4), Feiner Faden , Blauer Farbstoff (4)"},
[215371] = {name = "[q2]Janis Amulett", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\nSchmuck\nKlassen: Schurke"},
[215373] = {name = "Übungshammer der Silbernen Hand", additional_info = "{Zweihändig} {Streitkolben}\n{17 - 54 Schaden} {Tempo 3.40}\n(10.44 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n[q]\"Gefunden auf der Insel Theramore, wo sein Besitzer im Kampf gegen blutrünstige Orc-Horden fiel.\""},
[215374] = {name = "Schwert der Ahnen", additional_info = "{Zweihändig} {Schwert}\n{17 - 46 Schaden} {Tempo 3.10}\n(10.16 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n[q]\"Ein Erbstück einer adligen Familie aus Lordaeron. Einst in den Sümpfen um Kyross verloren geglaubt, zusammen mit dem letzten Krieger, der es schwang.\""},
[215375] = {name = "Stab es Taktikers", additional_info = "{Zweihändig} {Stab}\n{16 - 49 Schaden} {Tempo 3.50}\n(9.29 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n[q]\"Die scharfsinnige Auffassungsgabe der Besitzerin in Bezug auf Schlachtfeldtaktiken wurde nur übertroffen durch ihre furchteinflößende Beherrschung von Frost und Feuer.\""},
[215376] = {name = "Streitkolben des Kreuzfahrers", additional_info = "{Waffenhand} {Streitkolben}\n{21 - 36 Schaden} {Tempo 2.90}\n(9.83 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n[q]\"Gesprenkelt mit getrockneten Resten von Insektenpanzern.\""},
[215377] = {name = "[q3]Bestrahlte Robe", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Stoff}\n65 Rüstung\n-5 Stärke\n-10 Ausdauer\n+7 Intelligenz\n+8 Willenskraft\n+7 Naturwiderstand\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 23.\n\n[q]Bestrahlte Gewänder (0/3)\n[q0]Bestrahlte Robe\nBestrahlte Beinkleider\nBestrahlte Stiefel\n[q0](2) Set : -5 Ausdauer.\n(2) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(3) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 11."},
[215378] = {name = "[q0]Bestrahlte Stiefel", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Stoff}\n45 Rüstung\n-5 Beweglichkeit\n-10 Ausdauer\n+12 Intelligenz\n+11 Willenskraft\nHaltbarkeit 40 / 40\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 11.\n\n[q]Bestrahlte Gewänder (0/3)\n[q0]Bestrahlte Robe\nBestrahlte Beinkleider\nBestrahlte Stiefel\n[q0](2) Set : -5 Ausdauer.\n(2) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(3) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 11."},
[215379] = {name = "[q3]Bestrahlte Beinkleider", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Stoff}\n57 Rüstung\n-5 Beweglichkeit\n-10 Ausdauer\n+10 Intelligenz\n+13 Willenskraft\n+10 Naturwiderstand\nHaltbarkeit 75 / 75\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 16.\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\n\n[q]Bestrahlte Gewänder (0/3)\n[q0]Bestrahlte Robe\nBestrahlte Beinkleider\nBestrahlte Stiefel\n[q0](2) Set : -5 Ausdauer.\n(2) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(3) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 11."},
[215380] = {name = "[q4]Servo-unterstützter Hebegürtel", additional_info = "Wird beim Aufheben gebunden\n{Taille} {Kette}\n168 Rüstung\n+14 Stärke\n+15 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Stufe 40\n[q2]Anlegen: Zweihandäxte +3.\n[q2]Anlegen: Zweihandschwerter +3.\n[q2]Anlegen: Zweihandstreitkolben +3."},
[215381] = {name = "[q4]Gneuro-leitende Kapuze des Kanalisierers", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Leder}\n118 Rüstung\n+11 Ausdauer\n+12 Intelligenz\n+11 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\n[q2]Benutzen: Gewährt 'Gneuromantische Meditation', wodurch 20 Sek. lang 100% Eurer Manaregeneration während des Zauberwirkens erhalten bleibt und der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 50 erhöht werden. (10 Min Abklingzeit)"},
[215382] = {name = "[q4]Strahlungsresistente Schuppenkapuze", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Kette}\n[q2]342 Rüstung\n+10 Ausdauer\n+10 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: +32 Angriffskraft.\n[q2]Benutzen: Aktiviert die Protokolle zur Strahlungsabschwächung in diesem Helm, die sofort alle aktiven Gifteffekte von Euch entfernen und Euch 3 Sek. lang immun gegen jeglichen Naturschaden machen. (10 Min Abklingzeit)"},
[215383] = {name = "[q4]Pläne: Reflektierender Echtsilbergehirnkäfig", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (225)\n[q2]Benutzen: Lehrt Euch, wie man einen reflektierenden Echtsilbergehirnkäfig herstellt.\n[q4]Reflektierender Echtsilbergehirnkäfig\nWird beim Aufheben gebunden\n{Kopf} {Platte}\n426 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\n[q2]Benutzen: Gewährt verstärkte Willenskraft, die 10 Sek. lang Stille- und Unterbrechungseffekte sowie Zauberverzögerungen verhindert. (10 Min Abklingzeit)\nBenötigt Mithrilbarren (25), Echtsilberplatten mit geringer Grundstrahlung (4), Hyperleitender Arkanfaden (2), Polierte Echtsilberzahnräder"},
[215384] = {name = "[q3]Pläne: Echtsilberplatten mit geringer Grundstrahlung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (200)\n[q2]Benutzen: Lehrt Euch, wie man Echtsilberplatten mit geringer Grundstrahlung herstellt.\n[q3]Echtsilberplatten mit geringer Grundstrahlung\nBenötigt Echtsilberbarren , Reflektierender Metallschrott (5)"},
