[215429] = {name = "[q3]Bauplan: Polierte Echtsilberzahnräder", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (200)\n[q2]Benutzen: Lehrt Euch, wie man polierte Echtsilberzahnräder herstellt.\n[q3]Polierte Echtsilberzahnräder\nBenötigt Echtsilberbarren , Haufen aus stumpfen Zahnrädern (5)"},
[215430] = {name = "Ablagerung von Gnomeregan", additional_info = nil},
[215431] = {name = "[q4]Bauplan: Hoch wirksame Strahlungsbombe", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\n[q2]Benutzen: Lehrt Euch, wie man eine hoch wirksame Strahlungsbombe herstellt.\n[q2]Hoch wirksame Strahlungsbombe\nBenötigt Stufe 35\nBenötigt Ingenieurskunst (200)\n{[q2]Benutzen: Verursacht im Explosionsradius 150 bis 250 Feuerschaden} und zusätzlich 10 Sek. lang alle 2 Sek. 25 {Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen bis Abbruch lang um 25%. (1 Min Abklingzeit)}\nBenötigt Robustes Sprengpulver , Ablagerung von Gnomeregan , Mithrilbarren (2)"},
[215432] = {name = "[q4]Bauplan: EZ-Thro-Strahlungsbombe", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\n[q2]Benutzen: Lehrt Euch, wie man eine EZ-Thro-Strahlungsbombe herstellt.\n[q2]EZ-Thro-Strahlungsbombe\nBenötigt Stufe 40\n{[q2]Benutzen: Verursacht im Explosionsradius 112 bis 188 Feuerschaden} und zusätzlich 10 Sek. lang alle 2 Sek. 10 {Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen 10 Sek. lang um 25%. (1 Min Abklingzeit)}\n[q]\"Eine abgeschwächte, aber nicht weniger tödliche Version ihres komplexeren Gegenstücks, für diejenigen, denen zwar die Kompetenz fehlt, die aber dafür Zuversicht im Überfluss haben.\"\nBenötigt Robustes Sprengpulver (2), Ablagerung von Gnomeregan , Mithrilbarren (2)"},
[215433] = {name = "[q3]Rezept: Isolierendes Gniodin", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (200)\n[q2]Benutzen: Lehrt Euch, wie man eine Phiole isolierendes Gniodin herstellt.\n[q3]Isolierendes Gniodin\nBenötigt Verbleite Phiole , Kiste mit besudelter Gniodin-Lösung (5)"},
[215434] = {name = "[q4]UNBENUTZT", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (200)\n[q2]Benutzen: Lehrt Euch, wie man eine Phiole isolierendes Gniodin herstellt.\n[q3]Isolierendes Gniodin\nBenötigt Verbleite Phiole , Kiste mit besudelter Gniodin-Lösung (5)"},
[215435] = {name = "[q3]Buchband der Segnung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nBenötigt Stufe 40\n[q2]Anlegen: Verringert die Manakosten Eurer Siegelzauber um 10."},
[215436] = {name = "[q3]Totem der kräftigenden Flamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nBenötigt Stufe 40\n[q2]Anlegen: Verringert die Manakosten Eures Zaubers 'Flammenschock' um 10."},
[215437] = {name = "[q3]Troggwandler 3000", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 40\n[q2]Benutzen: Verwandelt den Zaubernden in einen Trogg. (30 Min Abklingzeit)\n[q]\"Wird gewöhnlich zur Aufklärung verwendet.\""},
[215441] = {name = "[q2]Kaputter Hammer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Auf diesem verzierten Kriegshammer sind die Insignien der Silbernen Hand eingestanzt.\""},
[215443] = {name = "Zerschmettertes Kugelfragment", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Die Überreste der zerschmetterten Kugel geben ein leichtes Leuchten und etwas Wärme ab.\""},
[215444] = {name = "[q0]Monster - Streitkolben - Kaputte Rohre", additional_info = "Einzigartig\n{Waffenhand} {Streitkolben}\n{1 - 2 Feuerschaden} {Tempo 2.80}\n(0.54 Schaden pro Sekunde)\nHaltbarkeit 18 / 18"},
[215449] = {name = "[q2]Weltschrumpfer", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 40\n[q2]Benutzen: Verkleinert die gesamte Welt 5 Min. lang oder bis Ihr angreift. (1 Stunde Abklingzeit)\n[q]\"Scheint auf Grundlage eines zerlegten Weltvergrößerers gebaut worden zu sein?\""},
[215450] = {name = "Wappenrockprojekt (Aidan)", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nWappenrock\nBenötigtDer Bund von Arathor\n- Ehrfürchtig"},
