[215454] = {name = "Winzige Schließkassette", additional_info = "Wird beim Aufheben gebunden\n[q0]Verschlossen\n Benötigt Schlossknacken (55)"},
[215456] = {name = "Angesengte Nachricht", additional_info = "[q]\"Wer nicht hören will...\""},
[215458] = {name = "Beigefügte Nachricht", additional_info = "Klassen: Schurke\n[q]\"Ernsthaft, versucht JA NICHT, die letzte Schachtel zu öffnen. Ihr habt bereits, was Ihr wolltet.\""},
[215459] = {name = "Beigefügte Nachricht", additional_info = "Klassen: Schurke\n[q]\"Schluss jetzt. Das ist Eure letzte Warnung.\""},
[215460] = {name = "Beigefügte Nachricht", additional_info = "Klassen: Schurke\n[q]\"VORSICHT! Die Schachtel neben dieser Notiz sollte nie geöffnet werden.\""},
[215461] = {name = "[q3]Gezähmtes Angriffshuhn", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 40\n[q2]Benutzen: Lässt Euer gezähmtes Angriffshuhn los, das 1.50 Min. lang oder bis es besiegt wurde für Euch kämpft. (30 Min Abklingzeit)"},
[215465] = {name = "Explodierte Schließkassette", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[215468] = {name = "Befehle des Obersten Kreuzzüglers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Der Brief ist zerknittert und weist getrocknete Blutflecken auf.\""},
[215683] = {name = "Geomantie: Der steinige Weg zur Wahrheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Theorien über den Ursprung und den Gebrauch elementarer Magie. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[215815] = {name = "Das Einmaleins der Verteidigungsmagie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine Einführung in verteidigende Magie und Barrieren. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[215816] = {name = "Ein Netz aus Lügen: Die Entzauberung von Mythen und Legenden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine wissenschaftliche Arbeit, die zu belegen versucht, dass Spinnen im Grunde harmlos sind. Unvollständig, aber dennoch eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[215817] = {name = "Dämonen und Ihr", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Ein merkwürdiger Text, der Dämonen verteidigt, aber dennoch eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[215820] = {name = "Mumien: Ein Ratgeber zu unappetitlichen Untoten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Geschichten, die sogar den abgehärtetsten Kämpfern Angst einjagen. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[215822] = {name = "RwlRwlRwlRwl!", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Die seltsamen Ausführungen sind verblasst, aber trotz der Schäden durch die Nässe dennoch lesbar. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[215824] = {name = "Anleitung zur Pflege eines dämonischen Begleiters für Anfänger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Enthält nützliche Tipps, um Wichtelbegleiter von den eigenen Reagenzien fernzuhalten. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[216483] = {name = "Schlaghammer der Witherbark", additional_info = "Einzigartig\n[q2]Benutzen: Schlägt den Gong im Bau der Witherbark."},
[216484] = {name = "[q0]Schockgeschmiedete Kampfstiefel", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Platte}\n330 Rüstung\n+7 Ausdauer\n+11 Intelligenz\nHaltbarkeit 65 / 65\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 13.\n\n[q]Schockgeschmiedete Kriegsplatte (0/3)\n[q0]Schockgeschmiedete Beinplatten\nSchockgeschmiedete Brustplatte\nSchockgeschmiedete Kampfstiefel\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht die kritische Trefferchance Eures Zaubers 'Heiliger Schock' um 2%."},
[216485] = {name = "[q3]Schockgeschmiedete Brustplatte", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Platte}\n480 Rüstung\n+3 Ausdauer\n+8 Intelligenz\nHaltbarkeit 125 / 125\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 19.\n\n[q]Schockgeschmiedete Kriegsplatte (0/3)\n[q0]Schockgeschmiedete Beinplatten\nSchockgeschmiedete Brustplatte\nSchockgeschmiedete Kampfstiefel\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht die kritische Trefferchance Eures Zaubers 'Heiliger Schock' um 2%."},
[216486] = {name = "[q3]Schockgeschmiedete Beinplatten", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Platte}\n420 Rüstung\n+8 Ausdauer\n+12 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 22.\n\n[q]Schockgeschmiedete Kriegsplatte (0/3)\n[q0]Schockgeschmiedete Beinplatten\nSchockgeschmiedete Brustplatte\nSchockgeschmiedete Kampfstiefel\n[q0](2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht die kritische Trefferchance Eures Zaubers 'Heiliger Schock' um 2%."},
[216490] = {name = "[q3]Götze des Zorns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht den von Eurem Zauber 'Zorn' verursachten Schaden um bis zu 2%."},
[216491] = {name = "Lieferung Schlingendornholz", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eine Lieferung Holz aus dem Schlingendorntal. Könnte Eurer Fraktion im Arathihochland zugutekommen.\""},
[216492] = {name = "[q3]Pfeife des scheckigen Blutraptors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\n[q2]Benutzen: Beschwört einen reitbaren Raptor oder gibt ihn wieder frei. (3 Sek. Abklingzeit)"},
[216494] = {name = "[q3]Aragriars launenhafter Weltenkrümmer", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 40\n[q2]Benutzen: Wo könnte Euch dieses Gerät nur hinbringen? ...Ach, was soll's. Wen interessiert's?!? (4 Std. Abklingzeit)"},
[216495] = {name = "[q4]Blutknacker", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Zweihändig} {Streitkolben}\n{110 - 165 Schaden} {Tempo 3.40}\n(40.44 Schaden pro Sekunde)\n+18 Stärke\n+12 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Krieger\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%."},
[216496] = {name = "[q4]Blutschädelknacker", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Einhändig} {Streitkolben}\n{50 - 93 Schaden} {Tempo 2.30}\n(31.09 Schaden pro Sekunde)\n+10 Stärke\n+6 Beweglichkeit\nHaltbarkeit 105 / 105\nKlassen: Krieger\nBenötigt Stufe 40"},
[216497] = {name = "[q4]Exsanguinar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Waffenhand} {Schwert}\n{44 - 81 Schaden} {Tempo 2.00}\n(31.25 Schaden pro Sekunde)\n+6 Ausdauer\nHaltbarkeit 105 / 105\nKlassen: Krieger\nBenötigt Stufe 40\n[q2]Benutzen: Entfesselt ein Feuerwerk aus Stahl und Blut, das alle gegnerischen Zielen innerhalb von 8 Metern trifft, ihnen 65 Schattenschlagschatten zufügt und sie 30 Sek. lang alle 2 Sek. für 5 zusätzlichen Schaden bluten lässt. (3 Min Abklingzeit)"},
[216498] = {name = "[q4]Zauberfoliant des verzauberten Blutes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nIn Schildhand geführt\nKlassen: Druide\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Arkanzauber und Arkaneffekte zugefügten Schaden um bis zu 16.\n[q2]Anlegen: Erhöht durch Naturzauber und Natureffekte zugefügten Schaden um bis zu 16."},
[216499] = {name = "[q4]Blutrindenknacker", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Zweihändig} {Streitkolben}\n{54 - 86 Schaden} {Tempo 2.00}\n(35.00 Schaden pro Sekunde)\n30 Rüstung\n+17 Stärke\n+11 Beweglichkeit\n+6 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 40\n[q2]Anlegen: +80 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Benutzen: Verleiht Euren Nahkampfangriffen zusätzlich 5 Sturmschlagschaden, der das Ziel und dessen nächsten Verbündeten trifft. Wirkt sich auf bis zu 3 Ziele aus. Verursacht zusätzliche Bedrohung. Hält 20 Sek. lang an. (3 Min Abklingzeit)"},
[216500] = {name = "[q4]Blutgebundener Haintalisman", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchmuck\nKlassen: Druide\nBenötigt Stufe 40\n[q2]Benutzen: Heilt den anvisierten Verbündeten sofort um 300 Gesundheit, allerdings opfert Ihr dafür nach 2 Sek. 300 Eurer eigenen Gesundheit. (5 Min Abklingzeit)"},
