[216520] = {name = "[q4]Klinge der Bluternte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Einhändig} {Dolch}\n{41 - 77 Schaden} {Tempo 1.90}\n(31.05 Schaden pro Sekunde)\n+9 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 65 / 65\nKlassen: Schurke\nBenötigt Stufe 40"},
[216521] = {name = "[q4]Flinke Blutschläger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Schildhand} {Faustwaffe}\n{30 - 57 Schaden} {Tempo 1.40}\n(31.07 Schaden pro Sekunde)\n+8 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 90 / 90\nKlassen: Schurke\nBenötigt Stufe 40"},
[216522] = {name = "[q4]Blutbeschmiertes Stilett", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Schildhand} {Dolch}\n{44 - 81 Schaden} {Tempo 2.00}\n(31.25 Schaden pro Sekunde)\n+6 Ausdauer\nHaltbarkeit 65 / 65\nKlassen: Schurke\nBenötigt Stufe 40\n[q2]Benutzen: Entfesselt einen wilden Sturm aus Stahl und Blut, der allen Gegnern innerhalb von 8 Metern 140 Schattenschlagschaden zufügt. (3 Min Abklingzeit)"},
[216523] = {name = "Rostiger Käfigschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Öffnet einen rostigen Käfig."},
[216549] = {name = "[q3]Zügel des Bengaltigers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\n[q2]Benutzen: Beschwört einen reitbaren Bengaltiger oder gibt ihn wieder frei. (3 Sek. Abklingzeit)"},
[216570] = {name = "[q3]Zügel der goldenen Säblerkatze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\n[q2]Benutzen: Beschwört eine reitbare goldene Säblerkatze oder gibt sie wieder frei. (3 Sek. Abklingzeit)"},
[216606] = {name = "[q2]Rune der Zweihandmeisterschaft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euer Brustteil oder Eure Robe mit der Rune 'Zweihandmeisterschaft':\n\n\nJedes Mal, wenn Ihr einen Gegner mit einer Zweihandwaffe angreift, wird 10 Sek. lang Euer Angriffstempo mit Zweihandwaffen um 45%, Eure Angriffskraft um 10% und Eure Trefferchance mit Zaubern um 10% erhöht. Dieser Effekt geht verloren, wenn Ihr einen Gegner mit einer Einhandwaffe angreift.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[216607] = {name = "[q4]Blutlichtopfergabe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchmuck\nKlassen: Paladin\nBenötigt Stufe 40\n[q2]Benutzen: Heilt den anvisierten Verbündeten sofort um 300 Gesundheit, allerdings opfert Ihr dafür nach 2 Sek. 300 Eurer eigenen Gesundheit. (5 Min Abklingzeit)"},
[216608] = {name = "[q4]Strahlende Strahlenreflektoren", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Stoff}\n1 Rüstung\nHaltbarkeit 50 / 50\n[q]\"Die Worte \"Kommt damit klar\" sind in die Seite graviert.\""},
[216610] = {name = "Befehle des obersten Kreuzzüglers", additional_info = "Questgegenstand\nEinzigartig\n[q2]<Zum Lesen rechtsklicken>"},
[216615] = {name = "[q4]Leuchtfeuer des Blutsturms der Ahnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchmuck\nKlassen: Schamane\nBenötigt Stufe 40\n[q2]Benutzen: Entfesselt eine verzögerte Explosion aus Blut und Natur, die allen Zielen in einem Umkreis von 10 Metern 150 Seuchenschaden zufügt. (5 Min Abklingzeit)"},
[216616] = {name = "Lagerkäfigschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[216617] = {name = "Kurzens Kämpferuniform", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[216618] = {name = "Kapitänin Aransas' Belohnung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Öffnen rechtsklicken>"},
[216619] = {name = "[q2]Studentenfutter", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Esst eine Handvoll und holt verlorene Zeit auf dem Weg wieder rein! (30 Min Abklingzeit)\n[q]\"Leckere Rosinen und Erdnüsse... und mehr!\""},
[216620] = {name = "[q3]Blutfäulnisumhang", additional_info = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+7 Ausdauer\n+6 Intelligenz\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 11."},
[216621] = {name = "[q3]Blutdurchnässtes Tuch", additional_info = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%."},
[216622] = {name = "[q3]Geronnener Umhang", additional_info = "Wird beim Aufheben gebunden\nRücken\n[q2]82 Rüstung\n+12 Ausdauer\nBenötigt Stufe 40"},
[216623] = {name = "[q3]Cape der Hämostase", additional_info = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+7 Ausdauer\n+6 Intelligenz\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 18."},
[216633] = {name = "Hydraulische Echtsilberstrebe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[216634] = {name = "GG12-082-Sicherungseinsatz", additional_info = "Questgegenstand"},
[216635] = {name = "[q2]Erschöpfter Leerenkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Mit einer angemessenen Energiequelle kombinieren, um einen aufgeladenen Leerenkern zu erschaffen. (3 Sek. Abklingzeit)\n[q]\"Der Beschreibung nach sieht dies aus wie der Leerenkern, den Wirdal benötigt, doch scheint er komplett inaktiv zu sein. Es muss eine Möglichkeit geben, ihn aufzuladen...\""},
[216636] = {name = "Aufgeladener Leerenkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Dieses Objekt scheint alles Licht und sämtliche Wärme in der Umgebung aufzusaugen und ist dennoch eiskalt.\""},
[216637] = {name = "Ein Haufen gemischter Teile", additional_info = "[q]\"Es gibt sicher irgendjemanden irgendwo, der damit etwas anfangen könnte, aber für Euch sieht es nur nach Schrott aus.\""},
[216645] = {name = "[q2]Partikel der Dunkelheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Dunkle Energie durchfließt dieses winzige, schwebende Energiepartikel. Welch unglaubliche Magie man damit wohl wirken könnte?\""},
[216646] = {name = "[q2]Ziris Überraschungskiste", additional_info = "Wird beim Aufheben gebunden\n[q]\"Irgendwer wird den Inhalt sicher nützlich finden... vermutlich.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[216661] = {name = "Schmutzverkrusteter Ring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 40"},
[216662] = {name = "[q2]Blitzender Goldring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+6 Ausdauer\n+6 Willenskraft"},
[216673] = {name = "[q3]Talvashs blitzender Goldring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n70 Rüstung\n+16 Ausdauer"},
[216674] = {name = "[q3]Noggs blitzender Goldring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n70 Rüstung\n+16 Ausdauer"},
[216675] = {name = "[q3]Makellose Civinad-Roben", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Stoff}\n65 Rüstung\n+9 Ausdauer\n+22 Willenskraft\nHaltbarkeit 80 / 80"},
[216676] = {name = "[q3]Behände Latzhose des Stolperläufers", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Leder}\n117 Rüstung\n+5 Stärke\n+21 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 75 / 75"},
[216678] = {name = "[q3]Dreifach verstärkte Gamaschen", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Kette}\n[q2]460 Rüstung\nHaltbarkeit 90 / 90\n[q2]Anlegen: Verteidigung +6."},
[216679] = {name = "[q3]Shonis Zerlegungswerkzeug", additional_info = "Wird beim Aufheben gebunden\n{Schildhand} {Axt}\n{37 - 68 Schaden} {Tempo 1.90}\n(27.63 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n[q2]Trefferchance: Entwaffnet den Gegner 5 Sek. lang."},
[216680] = {name = "[q3]Fäustlinge der Entschlossenheit", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Stoff}\n41 Rüstung\n+12 Intelligenz\n+11 Willenskraft\nHaltbarkeit 30 / 30"},
[216698] = {name = "[q3]Drachenlederarmsplinte des Fähnrichs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Leder}\n64 Rüstung\n+8 Ausdauer\n+4 Intelligenz\nHaltbarkeit 35 / 35\nKlassen: Druide\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 6."},
[216699] = {name = "[q3]Kettenarmschützer des Fähnrichs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Kette}\n131 Rüstung\n+5 Beweglichkeit\n+12 Ausdauer\nHaltbarkeit 40 / 40\nKlassen: Jäger\nBenötigt Stufe 40"},
[216700] = {name = "[q3]Lederarmsplinte des Fähnrichs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Leder}\n64 Rüstung\n+5 Beweglichkeit\n+12 Ausdauer\nHaltbarkeit 35 / 35\nKlassen: Schurke\nBenötigt Stufe 40"},
[216701] = {name = "[q3]Plattenhandgelenksschützer des Fähnrichs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Platte}\n231 Rüstung\n+5 Stärke\n+12 Ausdauer\nHaltbarkeit 45 / 45\nKlassen: Krieger , Paladin\nBenötigt Stufe 40"},
[216702] = {name = "[q3]Seidenmanschetten des Fähnrichs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Stoff}\n31 Rüstung\n+6 Ausdauer\n+3 Intelligenz\nHaltbarkeit 30 / 30\nKlassen: Priester , Magier , Hexenmeister\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 8."},
[216703] = {name = "[q3]Panzerhandgelenksschützer des Rottenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Kette}\n131 Rüstung\n+5 Beweglichkeit\n+10 Ausdauer\n+7 Intelligenz\nHaltbarkeit 40 / 40\nKlassen: Jäger , Schamane\nBenötigt Stufe 40"},
[216704] = {name = "[q3]Drachenlederarmschützer des Rottenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Leder}\n64 Rüstung\n+8 Ausdauer\n+4 Intelligenz\nHaltbarkeit 35 / 35\nKlassen: Druide\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 6."},
[216705] = {name = "[q3]Plattenarmschienen des Rottenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Platte}\n231 Rüstung\n+5 Stärke\n+12 Ausdauer\nHaltbarkeit 45 / 45\nKlassen: Krieger\nBenötigt Stufe 40"},
[216706] = {name = "[q3]Lederarmschützer des Rottenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Leder}\n64 Rüstung\n+5 Beweglichkeit\n+12 Ausdauer\nHaltbarkeit 35 / 35\nKlassen: Schurke\nBenötigt Stufe 40"},
[216707] = {name = "[q3]Seidenmanschetten des Rottenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Handgelenke} {Stoff}\n31 Rüstung\n+6 Ausdauer\n+3 Intelligenz\nHaltbarkeit 30 / 30\nKlassen: Priester , Magier , Hexenmeister\nBenötigt Stufe 40\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 8."},
[216738] = {name = "[q2]Handbuch des Umleitens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Entfernt all Eure bestehenden Combopunkte von Eurem Ziel und speichert sie bis zu 15 Sek. lang. Diese gespeicherten Combopunkte werden auf das nächste gegnerische Nichtspieler-Ziel übertragen, das Ihr mit einer Nahkampf- oder Distanzfähigkeit trefft.\n[q]\"Lehrt Euch 'Umleiten'.\""},
[216740] = {name = "[q2]Foliant der erweiterten Intelligenz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Senkt die Manakosten von 'Arkane Intelligenz' um 50% und verlängert dessen Dauer um 50%.\n[q]\"Lehrt Euch 'Erweiterte Intelligenz'.\""},
[216744] = {name = "[q2]Schriftrolle der erhöhten Seelenstärke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Senkt die Manakosten von 'Machtwort: Seelenstärke' um 50% und verlängert dessen Dauer um 50%.\n[q]\"Lehrt Euch 'Erhöhte Seelenstärke'.\""},
[216745] = {name = "[q2]Schriftrolle des Schattengeistes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Erschafft einen schattenhaften Geist, der das Ziel angreift. Der Zaubernde erhält bei einem Angriff des Schattengeists 5% Mana. Hält 15 Sek. lang an.\n[q]\"Lehrt Euch 'Schattengeist'.\""},
[216746] = {name = "[q2]Handbuch des Befehlsrufs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Der Krieger schreit, wodurch sich die Ausdauer aller Gruppenmitglieder innerhalb von 30 Metern um 2 erhöht. Hält 5 Min. lang an.\n[q]\"Lehrt Euch 'Befehlsruf'.\""},
[216747] = {name = "[q2]Zauberfoliant der Seelenernte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Immer wenn 'Seelendieb' Schaden verursacht, habt Ihr eine Chance, einen zusätzlichen Seelensplitter zu erhalten. Diese Chance steigt jedes Mal, wenn Ihr keinen Seelensplitter erhaltet.\n[q]\"Lehrt Euch 'Seelenernte'.\""},
[216748] = {name = "[q2]Zauberfoliant des Portals der Beschwörung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Beginnt ein Ritual, das ein Beschwörungsportal erstellt, welches von zwei Gruppen- oder Schlachtzugsmitgliedern benutzt werden kann, um ein ausgewähltes Gruppen- oder Schlachtzugsmitglied zu beschwören. Um das Ritual zu vervollständigen, werden der Zaubernde und zwei zusätzliche Gruppen- oder Schlachtzugsmitglieder benötigt. Um teilzunehmen, müssen sich alle Spielercharaktere außerhalb eines Kampfes befinden, auf das Portal rechtsklicken und dürfen sich nicht bewegen, bis das Ritual abgeschlossen ist.\n[q]\"Lehrt Euch 'Portal der Beschwörung'.\""},
[216764] = {name = "[q2]Handzettel der tiefen Wildnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Senkt die Manakosten von 'Mal der Wildnis' um 50% und verlängert dessen Dauer um 50%.\n[q]\"Lehrt Euch 'Tiefe Wildnis'.\""},
[216767] = {name = "[q2]Handzettel der Wiederbelebung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Bringt einen toten Spielercharakter mit 15% Gesundheit und Mana wieder ins Leben zurück. Kann nicht im Kampf verwendet werden.\n[q]\"Lehrt Euch 'Wiederbelebung'.\""},
[216768] = {name = "[q2]Bekenntnis der verbesserten Segen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Erhöht die Dauer Eurer Zauber 'Segen der Macht', 'Segen der Weisheit', 'Segen der Rettung', 'Segen des Refugiums', 'Segen des Lichts' und 'Segen der Könige' um 100% und verringert ihre Manakosten um 50%.\n[q]\"Lehrt Euch 'Verbesserte Segen'.\""},
[216769] = {name = "[q2]Offenbarung der totemischen Projektion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Bewegt Eure aktiven Totems an die angegebene Position.\n[q]\"Lehrt Euch 'Totemische Projektion'.\""},
[216770] = {name = "[q2]Abhandlung zum Aspekt der Viper", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n{[q2]Der Jäger nimmt die Aspekte einer Viper an. Jeder Eurer automatischen Distanz- und Nahkampfangriffe regeneriert Mana, der gesamte verursachte Schaden} wird jedoch um 10% verringert. Zusätzlich erhaltet Ihr alle 3 Sek. 10% Eures maximalen Manas. Das gewonnene Mana basiert auf dem {Tempo Eurer Waffe. Es kann immer nur jeweils ein Aspekt aktiv sein.}\n[q]\"Lehrt Euch 'Aspekt der Viper'.\""},
[216771] = {name = "[q2]Handzettel der verbesserten Wiederherstellung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Eure Zauber 'Verjüngung' und 'Nachwachsen' können auf Zielen aktiv sein, die von 'Verjüngung' oder 'Nachwachsen' eines anderen Druiden betroffen sind.\n[q]\"Lehrt Euch 'Verbesserte Wiederherstellung'.\""},
[216879] = {name = "Mysteriöse Trollschriftrolle", additional_info = "Einzigartig\nKlassen: Magier\n[q2]Benutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält."},
[216880] = {name = "Entzifferte Trollschriftrolle", additional_info = "Einzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Priester"},
[216884] = {name = "[q4]Blutdurstklinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: (Unbekannt #636) (0)\n{Zweihändig} {Schwert}\n{649 - 764 Schaden} {Tempo 4.20}\n(168.21 Schaden pro Sekunde)\n+333 Stärke\nHaltbarkeit 120 / 120\nBenötigt Stufe 125\n[q2]Trefferchance: Die versprochene Seele holen."},
[216914] = {name = "[q0]Befleckte Belobigung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 30\n[q]\"Sie hat ihren Glanz verloren...\""},
[216918] = {name = "[q4]Teufelsherzstiefel", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Stoff}\n[q2]150 Rüstung\n+25 Ausdauer\n+5 Intelligenz\n+5 Feuerwiderstand\nHaltbarkeit 50 / 50\nKlassen: Hexenmeister\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n[q2]Anlegen: Verteidigung +10.\n\n[q]Sündhaftes Teufelsherz (0/8)\n[q0]Teufelsherzbindungen\nTeufelsherzstiefel\nTeufelsherzkrone\nTeufelsherzumarmung\nTeufelsherzhandschutz\nTeufelsherzgamaschen\nTeufelsherzmantel\nTeufelsherzschärpe\n[q0](2) Set : 'Verbannen' ist ein Spontanzauber und kann auf Euch selbst gewirkt werden, während Ihr ein Dämon seid. Ihr könnt 'Verbannen' nicht auf Euch selbst wirken, solange 'Vorahnung' auf Euch wirkt, und 'Verbannen' belegt Euch 1 Min. lang mit 'Vorahnung'.\n(4) Set : Jedes Mal, wenn Ihr Schaden erleidet, erhaltet Ihr und Euer Diener Mana in Höhe des erlittenen Schadens, bis zu maximal 420 Mana pro Ereignis. Kann nur einmal alle paar Sekunden auftreten. (3.5s Abklingzeit)\n(6) Set : Eure Treffer mit 'Schattenspalten' haben eine Chance von 20%, Euch einen Seelensplitter zu gewähren, die Abklingzeit von 'Seelenfeuer' abzuschließen und Euren nächsten Einsatz von 'Seelenfeuer' innerhalb von 10 Sek. zu einem Spontanzauber zu machen. (Procchance: 20%, 100ms Abklingzeit)"},
