[217345] = {name = "Zähes Gift", additional_info = "Klassen: Schurke\nBenötigt Stufe 60\n[q2]Benutzen: Überzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\n Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was dessen Rüstung 15 Sek. lang um 1700 verringert.\n\n 'Zähes Gift' profitiert vom Talent 'Verbessertes Rüstung schwächen'. (Procchance: 30%)"},
[217346] = {name = "Betäubendes Gift", additional_info = "Klassen: Schurke\nBenötigt Stufe 60\n[q2]Benutzen: Überzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\n Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was die Zeit zwischen dessen Nahkampfangriffen 15 Sek. lang um 20% erhöht. (Procchance: 30%)"},
[217347] = {name = "Atrophisches Gift", additional_info = "Klassen: Schurke\nBenötigt Stufe 60\n[q2]Benutzen: Überzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\n Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was dessen Nahkampfangriffskraft 15 Sek. lang um 205 verringert. (Procchance: 30%)"},
[217350] = {name = "[q4]Thermapluggs Ingenieursnotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 40\n[q]\"Das zerfledderte Notizbuch enthält Baupläne für eine schockierende Vielfalt an zerstörerischen Waffen. Ihr solltet diese Notizen so bald wie möglich zu König Mekkatorque bringen.\""},
[217351] = {name = "[q4]Thermapluggs Ingenieursnotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 40\n[q]\"Das zerfledderte Notizbuch enthält Baupläne für eine schockierende Vielfalt an zerstörerischen Waffen. Nogg wird mit Sicherheit großes Interesse daran haben.\""},
[217398] = {name = "Geringes Arkanelixier", additional_info = "Benötigt Stufe 28\n[q2]Benutzen: Erhöht den Zauberschaden 30 Min. lang um bis zu 14. (3 Sek. Abklingzeit)"},
[217399] = {name = "[q2]Rezept: Geringes Arkanelixier", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (190)\n[q2]Benutzen: Lehrt Euch die Herstellung eines geringen Arkanelixiers.\nGeringes Arkanelixier\nBenötigt Stufe 28\n[q2]Benutzen: Erhöht den Zauberschaden 30 Min. lang um bis zu 14. (3 Sek. Abklingzeit)\nBenötigt Königsblut , Golddorn , Kristallphiole"},
[217495] = {name = "Schriftrolle des Kryoschlags", additional_info = "Klassen: Magier\nBenötigt Stufe 26\n[q2]Benutzen: Verursacht in einem Radius von 5 Metern 183 bis 247 Frostschaden. (1 Min Abklingzeit)"},
[217496] = {name = "[q3]Schriftrolle der Klinge", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 30\n[q2]Benutzen: Auf Hypnoseklinge einsetzen, um eine mächtige Waffe zu erhalten."},
[217497] = {name = "[q3]Narpasschwert", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Schwert}\n{40 - 75 Schaden} {Tempo 2.00}\n(28.75 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 34\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 15."},
[217609] = {name = "Talisman von Kazdor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Der Talisman zeigt ein Abbild purer Bösartigkeit. Ihr vermeidet es, ihn direkt anzusehen.\""},
[217693] = {name = "Unsichtbarkeitstrank", additional_info = "Questgegenstand\n[q2]Benutzen: Gewährt dem Anwender 30 Sek. lang Unsichtbarkeit. (2 Min Abklingzeit)"},
[217704] = {name = "[q3]Eisenbeschlagener Knüttel", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{68 - 106 Schaden} {Tempo 2.50}\n(34.80 Schaden pro Sekunde)\n+8 Stärke\n+20 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 37\n[q2]Anlegen: +36 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
[217716] = {name = "Ekelhaftes Gebräu", additional_info = "[q2]Benutzen: Wirft das Gebräu einen blubbernden Kessel, um eine Explosion übler Gase auszulösen. Hebt Verstohlenheit nicht auf. (30 Sek. Abklingzeit)"},
[217717] = {name = "Leeres Emblem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verzaubert ein leeres Emblem mit Blutmagieessenz."},
[217718] = {name = "Emblem der Blutmagie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[217719] = {name = "Blutmagieessenz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verzaubert ein leeres Emblem mit Blutmagieessenz."},
[217720] = {name = "Opfergabe des Fleisches", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert Opfergaben aus Fleisch und Knochen."},
[217721] = {name = "Opfergabe der Knochen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert Opfergaben aus Fleisch und Knochen."},
[217727] = {name = "Schutz der Toten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Anlegen: Enthüllt das Grab, das eine Opfergabe enthält."},
[217736] = {name = "[q2]Rune des Zirkels", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euren Helm mit der Rune 'Ehre unter Dieben':\n\n\nErzielt ein Spielercharakter in Eurer Gruppe mit einem Zauber oder einer Fähigkeit einen kritischen Treffer, gewinnt Ihr einen zusätzlichen Combopunkt auf Eurem aktuellen Ziel dazu. Dieser Effekt kann nur einmal pro Sekunde auftreten.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[217737] = {name = "Angepasster Talisman", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[218083] = {name = "[q4]Eranikus' Schwanz", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{176 - 264 Schaden} {Tempo 3.40}\n(64.71 Schaden pro Sekunde)\n+42 Stärke\nHaltbarkeit 120 / 120\nBenötigt Stufe 50\n[q2]Anlegen: Zweihandschwerter +8."},
[219021] = {name = "[q3]Große Kuriertasche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n16 Platz Behälter"},
[219022] = {name = "[q2]Ring des Trägers", additional_info = "Accountgebunden\nEinzigartig\nFinger\n+2 Stärke\n+2 Ausdauer"},
[219023] = {name = "[q2]Ring des Amtmanns", additional_info = "Accountgebunden\nEinzigartig\nFinger\n+2 Ausdauer\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 2."},
[219024] = {name = "[q2]Ring des Boten", additional_info = "Accountgebunden\nEinzigartig\nFinger\n+2 Beweglichkeit\n+2 Ausdauer"},
[219135] = {name = "[q3]Anhänger der Neugier", additional_info = "Accountgebunden\nHals\n+4 Ausdauer\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 4."},
[219136] = {name = "[q3]Anhänger der Hartnäckigkeit", additional_info = "Accountgebunden\nHals\n+4 Stärke\n+4 Ausdauer"},
[219137] = {name = "[q3]Anhänger der Initiative", additional_info = "Accountgebunden\nHals\n+4 Beweglichkeit\n+4 Ausdauer"},
[219147] = {name = "[q2]Rune der Anmut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Armschienen mit der Rune 'Anmut des Lichts':\n\n\nEuer Zauber 'Heiliges Licht' verringert die Zauberzeit Eures nächsten Einsatzes von 'Heiliges Licht' um 0.5 Sek. Hält 15 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[219223] = {name = "[q3]Zorn des Klingenmeisters", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{104 - 157 Schaden} {Tempo 3.00}\n(43.50 Schaden pro Sekunde)\n+17 Stärke\n+10 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 50\n[q2]Benutzen: Greift bis zu 4 Gegner innerhalb von 8 Metern an, fügt jedem Gegner Waffenschaden zu und setzt die Abklingzeit Eurer Fähigkeit 'Wirbelwind' zurück. (2 Min Abklingzeit)"},
[219326] = {name = "[q3]Saat der Erneuerung", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 50\n[q2]Anlegen: Chance, ein Samenkorn in gegnerische Humanoide, Wildtiere oder Drachkin zu säen, die von Euren Fähigkeiten oder Zaubern getroffen werden. Wenn die Kreatur innerhalb von 30 Sekunden nach dem Einpflanzen der Saat getötet wird, wächst eine Heilblume aus ihrer Leiche. (Procchance: 40%, 2Min. Abklingzeit)"},
[219343] = {name = "[q3]Diebesgugel", additional_info = "Wird beim Aufheben gebunden\nRücken\n36 Rüstung\n+11 Beweglichkeit\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht Eure effektive Verstohlenheitsstufe um 3. Erhöht die Reichweite von 'Falle entschärfen' und 'Taschendieb' um 2 Meter und die Reichweite von 'Ablenken' um 5 Meter."},
[219345] = {name = "[q3]Höllenlasso", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 50\n[q2]Benutzen: Wurzelt einen Dämon oder ein Wildtier an Ort und Stelle fest und verursacht im Verlauf von 24 Sek. insgesamt 200 Feuerschaden. Mit einem Lasso eingefangene Kernhunde können gezähmt werden. (1 Min Abklingzeit)"},
[219399] = {name = "Alptraummoos", additional_info = "[q]\"Vergänglich und instabil.\""},
