[220106] = {name = "[q2]Ernennungsbefugnis: Feralasmission XVIII", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\n[q2]Benutzen: Ernennt ein Gruppenmitglied und teilt diese Quest mit ihm, damit Ihr sie gemeinsam abschließen könnt.\n4 Aufladungen\n[q]\"Befähigt Euch, diese Mission mit Gruppenmitgliedern zu teilen.\""},
[220164] = {name = "[q2]Rune des Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Stiefel mit der Rune 'Gladiatorhaltung':\n\n\nEine aggressive Haltung, die beim Tragen eines Schildes den Schaden um 10% und die Blockchance um 10% erhöht, dabei jedoch die Rüstung um 30% und die erzeugte Bedrohung um 30% verringert. Zusätzlich erhaltet Ihr 50% mehr Wut, wenn Eure Nahkampfangriffe einem Gegner Schaden zufügen, der Euch nicht als Ziel hat.\n\n Während Ihr in der 'Gladiatorhaltung' einen Schild tragt, könnt Ihr sämtliche Fähigkeiten einsetzen, die auf andere Haltungen beschränkt sind.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220165] = {name = "[q2]Rune des Zorns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Helm mit der Rune 'Zorn':\n\n\nDer Schaden Eurer 'Weihe' kann nun kritisch treffen, und der Schaden Eurer Zauber 'Exorzismus', 'Heiliger Schock', 'Sonnenlicht', 'Heiliger Zorn' und 'Weihe' erhält eine zusätzliche Chance auf kritische Treffer, die der kritischen Trefferchance Eurer Nahkampftreffer entspricht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220166] = {name = "Feuriger Höllenbestienkern", additional_info = "Questgegenstand"},
[220167] = {name = "Schimmernder Grabstaub", additional_info = "Questgegenstand\n[q]\"Grabstaub von der Ruhestätte eines Mordopfers einer geliebten Person...\""},
[220168] = {name = "Dreifach gebrautes Schmelzlagerbier", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ein Elixier des Feuers, erschaffen mit ruhigen Händen und einem unruhigen Gemüt...\""},
[220169] = {name = "Symbol des Glaubens", additional_info = "Questgegenstand\n[q]\"Ein Symbol des Glaubens, ein Geschenk von jemandem mit neu entdeckter Bestimmung...\""},
[220170] = {name = "Notiz von Gregory", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Lesen rechtsklicken>"},
[220173] = {name = "[q4]Parasomnie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Zweihändig} {Schwert}\n{142 - 213 Schaden} {Tempo 3.40}\n(52.21 Schaden pro Sekunde)\n+15 Stärke\n+11 Beweglichkeit\n+28 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\n[q2]Trefferchance: Belegt das Ziel mit 'Parasomnie', wodurch es bis zu 2 Sek. lang ziellos umherwandert.\n[q]\"Ausgeburt des Alptraums\""},
[220213] = {name = "Teuflisches Lebensblut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[220214] = {name = "Höllischer Kettenverbund", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)"},
[220216] = {name = "Höllenlasso", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Schwächt Calefactus den Entfesselten. (30 Sek. Abklingzeit)"},
[220217] = {name = "[q2]Rune des Gefräßigen", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Euren Helm mit der Rune 'Schneller Tod':\n\n\nVerringert die Abklingzeit von 'Schnellfeuer' um 80%, 'Schnellfeuer' erhöht zusätzlich das Nahkampfangriffstempo um 40% und Eure nächste Schussfähigkeit innerhalb von 20 Sek., nachdem Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, verursacht 20% mehr Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220345] = {name = "Blutige Zauberei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Beschreibt eine Vielzahl von mächtigen Blutritualen. Eine kontroverse Erweiterung für die Sammlung jeder Bücherei.\""},
[220346] = {name = "Legenden der Gezeitenweisen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Vollgekritzelt mit kaum leserlichen Notizen und Diagrammen, die von unruhiger Hand stammen. Könnte trotzdem eine nette Erweiterung für die Sammlung jeder Bücherei bedeuten.\""},
[220347] = {name = "Die Schwelle und das Arkane", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Die Wörter auf der Seite verschwimmen und lassen nicht zu, gelesen zu werden. Eine rätselhafte Erweiterung für die Sammlung jeder Bücherei.\""},
[220348] = {name = "Alltägliche Etikette", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine Abhandlung zur Rolle von Elementarmagie in der feinen Gesellschaft der Hochgeborenen. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[220349] = {name = "Steinwerkentwürfe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Architektonische Techniken zum Bau von stabilen Gebäuden, die selbst die schlimmsten Katastrophen überstehen. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[220350] = {name = "Giftige Reisen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Notizen zu bewusstseinsverändernden Eigenschaften verschiedener Toxine und Gifte. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[220351] = {name = "Düsteres Luftsapta", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht dem Schamanen, Elementargeister zu sehen."},
[220352] = {name = "Möglichkeiten des Metalls", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Zwergentechniken für die Anwendung von Magie in der Metallurgie, beim Ressourcenabbau und in der Schwerindustrie. Eine informative, wenn auch eher fade Erweiterung für die Sammlung jeder Bücherei.\""},
[220353] = {name = "Beschwörerkodex", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine Ansammlung von Zaubern und Arkantheorien, die aus der Zeit vor dem Krieg stammen und schon lange nicht mehr angewendet werden. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\""},
[220360] = {name = "[q2]Rune des Erblühens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Armschienen mit der Rune 'Erblühen':\n\n\nEure 'Rasche Heilung' löst nun auch 'Erblühen' aus und heilt alle Mitglieder der Gruppe innerhalb von 15 Metern um den Zielort von 'Rasche Heilung' 15 Sek. lang alle 1 Sek um [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] Gesundheit.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220375] = {name = "Fragment der Luft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert das Fragment der Luft mit Elementaressenzen. Kann dabei helfen, den verderbten Schrein zu finden."},
[220379] = {name = "Zerrissene Notizen des Schamanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Schamane\n[q]\"Hastig geschriebene, fast unleserliche Notizen. Die Seiten scheinen um etwas anderes gewickelt zu sein.\""},
[220446] = {name = "[q2]Überirdischer Schatz", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
