[220611] = {name = "[q3]Hukkus Hexerumhang", additional_info = "Wird beim Aufheben gebunden\nRücken\n39 Rüstung\n+10 Intelligenz\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 15."},
[220612] = {name = "[q2]Rune der Flutwellen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euren Helm mit der Rune 'Flutwellen':\n\n\nWenn Ihr 'Kettenheilung' oder 'Springflut' wirkt, gewinnt Ihr 2 Aufladungen von 'Flutwelle' hinzu, was die Zauberzeit Eurer 'Welle der Heilung' um 30% und die Zauberzeit Eurer 'Kettenheilung' um 15% verringert und die kritische Trefferchance Eures Zaubers 'Geringe Welle der Heilung' um 25% erhöht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220613] = {name = "[q2]Rune des rollenden Donners", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Armschienen mit der Rune 'Rollender Donner':\n\n\n'Blitzschlag' und 'Kettenblitzschlag' haben eine Chance von 50%, Eurem aktiven 'Blitzschlagschild' eine zusätzliche Aufladung zu gewähren, bis zu 9 Aufladungen.\n\n 'Erdschock' entfesselt nun alle Aufladungen von 'Blitzschlagschild' über 3, was dem Ziel ihren Schaden zufügt und Euch pro Aufladung Energie in Höhe von 2% Eures maximalen Manas gewährt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220614] = {name = "[q2]Rune des statischen Schocks", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Armschienen mit der Rune 'Statischer Schock':\n\n\nEuer 'Blitzschlagschild' hat jetzt 9 Aufladungen und Eure Nahkampfangriffe haben eine Chance von 12% (beim Kämpfen mit zwei Waffen eine Chance von 6% ), eine dieser Aufladungen auszulösen und Eurem Ziel sofort Schaden zuzufügen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220615] = {name = "[q3]Pantherfellumhang", additional_info = "Wird beim Aufheben gebunden\nRücken\n39 Rüstung\n+6 Stärke\n+15 Beweglichkeit\nBenötigt Stufe 50"},
[220616] = {name = "[q2]Rune der Überladung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Armschienen mit der Rune 'Überladen':\n\n\nEuer 'Blitzschlagschild' verliert nie seine Aufladungen, hat jetzt eine Abklingzeit von 3 Sek. und fügt allen Gegnern innerhalb von 8 Metern Schaden zu.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220617] = {name = "[q2]Rune der Pandemie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Helm mit der Rune 'Pandemie':\n\n\nRegelmäßiger Schaden durch Eure Fähigkeiten 'Verderbnis', 'Instabiles Gebrechen', 'Fluch der Pein', 'Feuerbrand', 'Fluch der Verdammnis' und 'Lebensentzug' kann jetzt kritisch treffen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220618] = {name = "[q2]Rune der Feuerbrandaura", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Armschienen mit der Rune 'Feuerbrandaura':\n\n\nImmer wenn ein Gegner Euch im Nahkampf angreift, werden Gegner in der Nähe verbrannt und erleiden [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100] Schaden. Kann nicht häufiger als einmal pro Sekunde auftreten. Verringert außerdem sämtlichen erlittenen Magieschaden um 10% und erhöht den verursachten Feuerschaden um 10%. Hält bis Abbruch lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[220619] = {name = "[q4]Blutzeremonie der Atal'ai", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Ein Opferdolch, auf dem der Gesang einer uralten Blutzeremonie der Atal'ai eingraviert ist. (35 Sek. Abklingzeit)\n[q]\"Der Blutloa wählt nur Würdige aus.\""},
[220620] = {name = "[q4]Schädel der Windnatter", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Mit Rechtsklick Eure Windnatter beschwören oder wieder freigeben."},
[220621] = {name = "[q4]Alptraumresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Ehrfürchtig\n[q2]Benutzen: Der Kristall resoniert mit dem Alptraum.\n[q]\"Kristallisierte Essenz des Alptraums. Sie vibriert als Reaktion auf den Traum. Anscheinend verlangt sie nach... Verderbnis?\""},
[220622] = {name = "[q4]Perfekt erhaltenes Drachenauge", additional_info = "Wird beim Aufheben gebunden\nHals\n+8 Ausdauer\n+10 Intelligenz\n+8 Willenskraft\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 24."},
