[220625] = {name = "[q3]Abhärtung des Exilierten", additional_info = "Wird beim Aufheben gebunden\nHals\n90 Rüstung\n+8 Ausdauer\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[220626] = {name = "[q4]Drachenklauenband des Berserkers", additional_info = "Wird beim Aufheben gebunden\nFinger\n+13 Ausdauer\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: +20 Angriffskraft."},
