[220629] = {name = "[q4]Drachenklauenband des Blutpropheten", additional_info = "Wird beim Aufheben gebunden\nFinger\n+12 Intelligenz\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 20.\n[q2]Anlegen: Stellt alle 5 Sek. 5 Punkt(e) Mana wieder her."},
[220630] = {name = "[q4]Drachenklauenband des Molochs", additional_info = "Wird beim Aufheben gebunden\nFinger\n[q2]60 Rüstung\n+16 Ausdauer\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[220632] = {name = "[q4]Blutritualmedaillon der Atal'ai", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht 20 Sek. lang Euren Nahkampf- und Distanzschadensbonus um 20 Punkte. Jedes Mal, wenn Ihr ein Ziel trefft, wird dieser Bonus um 1 verringert. (2 Min Abklingzeit)"},
[220633] = {name = "[q4]Blutritualabzeichen der Atal'ai", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht Eure Rüstung 20 Sek. lang um 1.000 und Eure Verteidigungsfertigkeit um 20. Jedes Mal, wenn Euch Nahkampf- oder Distanzschaden zugefügt wird, wird dieser Bonus um 100 Rüstung und 2 Verteidigung verringert. (2 Min Abklingzeit)"},
[220634] = {name = "[q4]Blutritualamulett der Atal'ai", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht 20 Sek. lang Euren Zauberschaden um bis zu 96 Schaden und Eure Heilung um bis zu 192 Gesundheit. Bei jedem Einsatz eines Zaubers wird der Bonus um 8 Zauberschaden und 16 Heilung verringert. (2 Min Abklingzeit)"},
[220635] = {name = "[q4]Atal'alarions verzauberter Fels", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Fokussiert Euren Geist auf Atal'alarions Lieblingsfelsen, verzaubert mit den letzten Echos seiner Seele. (15 Min Abklingzeit)"},
[220636] = {name = "[q3]Blutsymbol der Atal'ai", additional_info = "Wird beim Aufheben gebunden\nKlassen: Krieger , Paladin , Jäger , Schurke , Schamane"},
[220637] = {name = "[q3]Ritualzeichen der Atal'ai", additional_info = "Wird beim Aufheben gebunden\nKlassen: Priester , Magier , Hexenmeister , Druide"},
[220638] = {name = "[q4]Unorthodoxer Hexerstecken", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Führt eine uralte Verhexung der Atal'ai bei Euch selbst durch. (15 Min Abklingzeit)\n[q]\"A test for only the strongest of bonds.\""},
[220639] = {name = "[q4]Lledras Lebloser", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Werdet leblos! (3 Sek. Abklingzeit)"},
