[221017] = {name = "Keldaras Aufzeichnungen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Lesen rechtsklicken>"},
[221018] = {name = "Feldsanitäterset", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert 3 Satyrkrautproben, um eine Tinktur zu brauen."},
[221019] = {name = "Satyrkrautprobe", additional_info = "Wird beim Aufheben gebunden"},
[221020] = {name = "[q2]Rune der Mondgöttin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Armschienen mit der Rune 'Feuer Elunes':\n\n\nEinige Eurer Zauber und Fähigkeiten verlängern die Dauer Eurer regelmäßigen Schadens- und Heileffekte auf ihrem Ziel:\n\n 'Sternenfeuer' verlängert 'Mondfeuer' um 6 Sek.\n 'Zorn' verlängert 'Sonnenfeuer' um 3 Sek.\n 'Nachwachsen' verlängert 'Verjüngung' um 6 Sek.\n 'Schreddern' verlängert 'Zerfetzen' um 2 Sek.\n\n Jeder Effekt kann nur bis zur ursprünglichen Dauer verlängert werden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221021] = {name = "[q2]Alptraumsaat", additional_info = nil},
[221024] = {name = "[q4]Fläschchen der unvergänglichen Alpträume", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenötigt Alchimie (250)\n[q2]Benutzen: Erhöht die Distanz- und Nahkampfangriffskraft um 45. Die Vorteile dieses Fläschchens wirken nur in Gebieten, die unter dem Einfluss des Alptraums stehen. (30 Sek. Abklingzeit)\n[q]\"Die Flasche scheint nie leer zu werden, egal, wie viel man davon trinkt.\""},
[221025] = {name = "[q4]Leerenaufgeladene Unterarmschienen des Herbeirufers", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Stoff}\n37 Rüstung\n+7 Ausdauer\n+8 Intelligenz\nHaltbarkeit 35 / 35\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (250)\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\n[q2]Anlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\n[q2]Benutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n[q]\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\""},
[221026] = {name = "[q4]Leerenaufgeladene Unterarmschienen des Rächers", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Leder}\n75 Rüstung\n+9 Stärke\n+18 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 40 / 40\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (250)\n[q2]Anlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\n[q2]Benutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n[q]\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\""},
[221027] = {name = "[q4]Leerenaufgeladene Unterarmschienen des Beschützers", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Platte}\n275 Rüstung\n+10 Stärke\n+12 Ausdauer\nHaltbarkeit 55 / 55\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (250)\n[q2]Anlegen: Erhöht den Blockwert Eures Schildes um 19.\n[q2]Anlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\n[q2]Benutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n[q]\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\""},
[221028] = {name = "[q2]Verzaubertes Siegel: Lebendige Träume", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 50\nBenötigt Verzauberkunst (250)\n[q2]Benutzen: Erhaltet ein verzaubertes Siegel der lebendigen Träume, das Euch ermächtigt, wodurch 30 Min. lang der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 30 und Eure Angriffskraft um 30 erhöht wird. Dieser Effekt kann nur außerhalb des Kampfes angewandt werden. (30 Min Abklingzeit)"},
[221030] = {name = "[q2]Atal'aimojo der verbotenen Magie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (2)\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht die Zaubermacht um 40. Erfolgreiche Zaubertreffer haben eine Chance, einen Schattenblitz auf das Ziel zu entfesseln. Es kann immer nur ein Trank der Atal'ai zur selben Zeit aktiv sein. Dies hat außerhalb des Versunkenen Tempels keinen Effekt. (Procchance: 25%, 40s Abklingzeit) (3 Sek. Abklingzeit)\n[q]\"Die flackernden Schatten in diesem verzauberten Wasser, umgewandelt aus der Essenz des Atal'aimojos, verschleiern, was sich darin befindet...\""},
[221191] = {name = "[q3]Traumstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[221192] = {name = "[q4]Traumtagebuch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Lesen rechtsklicken>"},
[221193] = {name = "[q3]Smaragdring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+12 Ausdauer\n+5 Arkanwiderstand\nBenötigt Stufe 45\nBenötigtSmaragdwärter\n- Wohlwollend\n[q2]Anlegen: +14 Angriffskraft.\n[q2]Benutzen: Begebt Euch in den Traum eines anvisierten Verbündeten. (1 Stunde Abklingzeit)\n[q]\"Im Inneren des prachtvollen Smaragds pulsiert ein Licht.\""},
[221196] = {name = "[q2]Atal'aimojo des Krieges", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (2)\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht die Nahkampf- und Distanzangriffskraft um 48. Bei Nahkampf- und Distanzangriffen besteht eine Chance, größer zu werden, wodurch 10 Sek. lang die Stärke oder Beweglichkeit um 35 erhöht wird (je nach dem, welcher Wert höher ist). Es kann immer nur ein Trank der Atal'ai zur selben Zeit aktiv sein. Dies hat außerhalb des Versunkenen Tempels keinen Effekt. (Procchance: 15%, 40s Abklingzeit) (3 Sek. Abklingzeit)\n[q]\"Ihr wollt in die Schlacht ziehen, als Ihr den reizenden roten Schein des Tranks erblickt...\""},
[221199] = {name = "Satyrkrauttinktur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Heilt eine Kreatur von Satyrverderbnis."},
[221256] = {name = "Rechter Arm des Vernichters", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert ein Stück mit 4 anderen, um Iodac wiederaufzubauen."},
[221257] = {name = "Linker Arm des Vernichters", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert ein Stück mit 4 anderen, um Iodac wiederaufzubauen."},
[221258] = {name = "Rechter Fuß des Vernichters", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert ein Stück mit 4 anderen, um Iodac wiederaufzubauen."},
[221259] = {name = "Linker Fuß des Vernichters", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert ein Stück mit 4 anderen, um Iodac wiederaufzubauen."},
[221260] = {name = "Kopf des Vernichters", additional_info = "Wird beim Aufheben gebunden"},
[221261] = {name = "[q2]Wildgeflüstergebräu", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört den Geist von Agamaggan. Kann nur oben auf der Wendel der Dornen in den Hügeln von Razorfen verwendet werden, nachdem alle Gegner in der Nähe besiegt wurden. (5 Sek. Abklingzeit)"},
[221262] = {name = "[q2]Wilde Opfergabe", additional_info = "Wird beim Aufheben gebunden"},
[221267] = {name = "[q2]Rune des Blutdurstigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Helm mit der Rune 'Verlangen nach Blut':\n\n\nImmer wenn Eure Fähigkeit 'Verwunden' Schaden verursacht, wird Eure Fähigkeit 'Überwältigen' 9 Sek. lang oder für 1 Angriff aktiviert. Dieser Effekt tritt alle 6 Sek. höchstens einmal ein.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
