[221307] = {name = "[q4]Dunkelmond-Karte: Verfall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\n[q2]Anlegen: Zauber und Angriffe entziehen dem Ziel manchmal 40 Gesundheit und belegen es mit einem Stapel 'Verfall'. Bei 5 Stapeln von 'Verfall' erleidet das Ziel 225 bis 375 Schaden. (3s Abklingzeit)"},
[221308] = {name = "[q4]Dunkelmond-Karte: Wildes Wachstum", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\n[q2]Anlegen: Bei Euren direkten Heilzaubern und effektiven Ticks Eurer regelmäßiger Heilung besteht eine Chance, beim Ziel 8 Energie, 1% Mana oder 4 Wut wiederherzustellen. (Procchance: 10%)"},
[221309] = {name = "[q4]Dunkelmond-Karte: Sandsturm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\n[q2]Anlegen: Chance, dass Zauber und Angriffe einen Sandsturm heraufbeschwören, der Euch umkreist und Zielen in seiner Bahn 50 bis 100 Naturschaden zufügt. (Procchance: 30%, 8s Abklingzeit)"},
[221310] = {name = "[q4]Dunkelmond-Karte: Qual", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\n[q2]Anlegen: Bei Angriffen und Zaubern des Trägers besteht eine Chance, das Ziel zu quälen und es 3 Sek. lang ziellos umherwandern zu lassen. (Procchance: 5%, 15s Abklingzeit)"},
[221311] = {name = "[q2]Atal'aimojo des Lebens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (2)\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht die verursachte Heilung um 45, die Manaregeneration alle 5 Sek. um 11 und Eure Heilungen haben eine Chance, 8 Energie, 1% Mana oder 4 Wut wiederherzustellen. Es kann immer nur ein Trank der Atal'ai zur selben Zeit aktiv sein. Dies hat außerhalb des Versunkenen Tempels keinen Effekt. (Procchance: 25%, 20s Abklingzeit) (3 Sek. Abklingzeit)\n[q]\"Ein tiefes Blau steigt aus dem Inhalt dieser Phiole hervor. Es fühlt sich fast so an, als wollte die Flüssigkeit, dass Ihr sie trinkt.\""},
[221312] = {name = "[q2]Fläschchen mit Atal'aimojo", additional_info = "[q]\"Das beste Mojo der Atal'aitrolle\""},
[221313] = {name = "[q3]Fläschchen des alptraumhaften Mojo", additional_info = "[q]\"Machtvolles alptraumerfülltes Voodoo der Atal'ai wirbelt in der Phiole herum.\""},
[221314] = {name = "Steckbrief", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Die grobe Skizze eines Dunkeleisenzwergs.\"\n[q2]<Zum Lesen rechtsklicken>"},
[221315] = {name = "[q3]Regenbogengenerator", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Regenbogenkraft! (30 Min Abklingzeit)"},
[221316] = {name = "Premos haltungswahrende Uniform", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nHemd\n[q2]Benutzen: Konzentriert Euch."},
[221317] = {name = "Feralas-Leykristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen."},
[221318] = {name = "Azshara-Leykristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen."},
[221319] = {name = "Blackrock-Leykristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen."},
[221320] = {name = "Hinterland-Leykristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen."},
[221321] = {name = "[q3]Atal'aisiegel der Macht", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Fügt einem Gegenstand für den Schulterplatz dauerhaft 15 Angriffskraft hinzu."},
[221322] = {name = "[q3]Atal'aisiegel des Mojo", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Fügt einem Gegenstand für den Schulterplatz dauerhaft eine um bis zu 9 erhöhte Schadens- und Heilwirkung durch Zauber und magische Effekte hinzu."},
[221323] = {name = "[q3]Atal'aisiegel der inneren Ruhe", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Fügt einem Gegenstand für den Schulterplatz dauerhaft eine um bis zu 18 erhöhte Heilwirkung durch Zauber und magische Effekte hinzu."},
[221324] = {name = "Spröder Schlüssel zur Schattenschmiede", additional_info = "Questgegenstand\nEinzigartig\nDauer: 15 min\n[q]\"Es wäre unmöglich, diesen zerbröselnden Schlüssel Eurem Bund hinzuzufügen.\""},
[221325] = {name = "Leichtplodier-Sprengsatz", additional_info = "Wird beim Aufheben gebunden\nDauer: 15 min\n[q2]Benutzen: Sprengt schwere verschlossene Türen auf.\n[q]\"Die langsam abfackelnde Zündschnur brennt bereits!\""},
[221326] = {name = "Heiliges Hirschherz", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bietet die Opfergabe am Schrein des Tieres dar."},
[221327] = {name = "[q2]Bauplan: Gnomenschrumpfstrahl", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGnomen-Schrumpfstrahl\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen: Lässt das Ziel schrumpfen und verringert seine Angriffskraft um 250. Zumindest ist das meistens der Fall... (5 Min Abklingzeit)\nBenötigt Mithrilrohr , Instabiler Auslöser , Mithrilbarren (4), Fläschchen Mojo (4), Jade (2)"},
[221328] = {name = "[q2]Bauplan: Gnomenschutzbrille", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\n[q2]Gnomen-Schutzbrille\nWird beim Aufheben gebunden\n{Kopf} {Stoff}\n45 Rüstung\n+9 Beweglichkeit\n+9 Ausdauer\n+9 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (210)\nBenötigt Feuerschutzbrille , Mithrilrohr , Goldkraftkern (2), Fläschchen Mojo (2), Schweres Leder (2)"},
[221329] = {name = "[q2]Bauplan: Gnomen-Net-o-Matik-Projektor", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGnomen-Net-o-Matik-Projektor\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (210)\n[q2]Benutzen: Hält das Ziel 10 Sek. lang in einem Netz fest. Das Netz ist allerdings mit einer Menge Haken bestückt und verfängt sich manchmal auch in der Kleidung des Benutzers, wenn es abgefeuert wird... (10 Min Abklingzeit)\nBenötigt Mithrilrohr , Schattenseide (2), Dicke Spinnenseide (4), Robustes Sprengpulver (2), Mithrilbarren (4)"},
[221330] = {name = "[q2]Bauplan: Gnomenunglücksverhinderungsgürtel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\n[q2]Gnomen-Unglücksverhinderungsgürtel\nWird beim Anlegen gebunden\n{Taille} {Leder}\n66 Rüstung\n+6 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Ingenieurskunst (215)\n[q2]Benutzen: Ein Kraftfeldschild beschützt Euch vor dem nächsten zugefügten 500-Schaden im Verlauf der nächsten 10 Min.. WARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)\nBenötigt Schwärzlicher Gürtel , Mithrilbarren (4), Echtsilberbarren (2), Instabiler Auslöser , Aquamarin (2)"},
[221331] = {name = "[q2]Bauplan: Gnomenraketenstiefel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\n[q2]Gnomen-Raketenstiefel\nWird beim Anlegen gebunden\n{Füße} {Stoff}\n41 Rüstung\nHaltbarkeit 35 / 35\nBenötigt Ingenieurskunst (225)\n[q2]Benutzen: Diese Stiefel erhöhen Euer Lauftempo 20 Sek. lang erheblich. WARNUNG: Ihre Stromversorgung und Gyros funktionieren nicht immer so, wie sie eigentlich sollten. (30 Min Abklingzeit)\nBenötigt Schwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Robustes Sprengpulver (8), Gyrochronatom (4)"},
[221332] = {name = "[q2]Bauplan: Gnomenkampfhuhn", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGnomen-Kampfhuhn\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst (230)\n[q2]Benutzen: Erschafft ein Kampfhuhn, dass für 1.50 Min. oder bis es zerstört wird, für euch kämpfen wird. (30 Min Abklingzeit)\nBenötigt Mithrilgehäuse , Echtsilberbarren (6), Mithrilbarren (6), Veredelter Mithrilzylinder (2), Goldkraftkern , Jade (2)"},
[221333] = {name = "[q2]Bauplan: Gnomische Gedankenkontrollkappe", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\n[q2]Gnomen-Gedankenkontrollkappe\nWird beim Anlegen gebunden\n{Kopf} {Stoff}\n50 Rüstung\n+14 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (215)\n[q2]Benutzen: Beginnt einen mentalen Kampf gegen ein humanoides Ziel und versucht, Kontrolle über dessen Gedanken zu erlangen. Wenn alles gut geht, werdet Ihr die Gedanken des Ziels 20 Sek. lang kontrollieren... (30 Min Abklingzeit)\nBenötigt Mithrilbarren (10), Echtsilberbarren (4), Goldkraftkern , Sternrubin (2), Magiestoff (4)"},
[221334] = {name = "[q2]Bauplan: Gnomentodesstrahl", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGnomentodesstrahl\nWird beim Aufheben gebunden\nSchmuck\n[q2]Benutzen: Der Todesstrahl benötigt einige Zeit, um sich mit Eurer Lebenskraft aufzuladen und feuert Â dann einen Energiestoß auf Euren Gegner ab. (5 Min Abklingzeit)\n[q]\"Verwendung dieses Geräts kann zum Tod oder zu schweren Verletzungen führen.\"\nBenötigt Mithrilrohr (2), Instabiler Auslöser , Essenz des Untodes , Sekret des Untodes (4), Veredelter Mithrilzylinder"},
[221335] = {name = "[q2]Bauplan: Goblinschutzhelm", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\n[q2]Goblinscher Schutzhelm\nWird beim Aufheben gebunden\n{Kopf} {Stoff}\n44 Rüstung\n+15 Feuerwiderstand\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen: Absorbiert 300 bis 500 Punkt(e) Feuerschaden. Hält 1 Min. lang an. (1 Stunde Abklingzeit)\nBenötigt Mithrilbarren (8), Citrin , Elementarfeuer (4)"},
[221336] = {name = "[q2]Bauplan: Goblinbergbauhelm", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGoblin-Bergbauhelm\nWird beim Aufheben gebunden\n{Kopf} {Kette}\n190 Rüstung\n+15 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (205)\nAnlegen: Bergbau +5.\nBenötigt Mithrilbarren (8), Citrin , Elementarerde (4)"},
[221337] = {name = "[q2]Bauplan: Goblinmörser", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGoblin-Mörser\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen: Fügt 383 bis 517 Punkt(e) Feuerschaden zu und betäubt 3 Sek. lang die Ziele in einem Umkreis von 5 Metern. (10 Min Abklingzeit)\n6 Aufladungen\nBenötigt Mithrilrohr (2), Mithrilbarren (4), Robustes Sprengpulver (5), Goldkraftkern , Elementarfeuer"},
[221338] = {name = "[q2]Bauplan: Goblinpioniersprengladung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGoblinsche Pioniersprengladung\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen: Explodiert bei Auslösung und verursacht 450 bis 750 Punkt(e) Feuerschaden bei allen in der Nähe befindlichen feindlichen Einheiten und 375 bis 625 Punkt(e) Schaden bei Euch. (5 Min Abklingzeit)\nBenötigt Magiestoff , Robustes Sprengpulver (3), Instabiler Auslöser"},
[221339] = {name = "[q2]Bauplan: Goblinraketenstiefel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\n[q2]Goblin-Raketenstiefel\nWird beim Anlegen gebunden\n{Füße} {Stoff}\n41 Rüstung\nHaltbarkeit 35 / 35\n[q2]Benutzen: Diese gefährlich aussehenden Stiefel erhöhen Euer Lauftempo 20 Sek. lang erheblich. Sie explodieren allerdings leicht, sind also mit Vorsicht zu verwenden. (5 Min Abklingzeit)\nBenötigt Schwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Goblin-Raketentreibstoff (2), Instabiler Auslöser"},
[221340] = {name = "[q2]Bauplan: Goblinbombenspender", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGoblin-Bombenspender\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst (230)\n[q2]Benutzen: Lässt eine mobile Bombe entstehen, die den nächstbefindlichen Feind angreift, explodiert und dabei 315 bis 385 Punkt(e) Feuerschaden verursacht. (30 Min Abklingzeit)\nBenötigt Mithrilgehäuse (2), Robustes Sprengpulver (4), Echtsilberbarren (6), Instabiler Auslöser , Genaues Zielfernrohr (2)"},
[221341] = {name = "[q2]Bauplan: Die Große", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nDer Große\nBenötigt Ingenieurskunst (225)\n[q2]Benutzen: Fügt 340 bis 460 Feuerschaden zu und betäubt Ziele 5 Sek. lang in einem Umkreis von 10 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\nBenötigt Mithrilgehäuse , Goblin-Raketentreibstoff , Robustes Dynamit (6), Instabiler Auslöser"},
[221342] = {name = "[q2]Bauplan: Goblindrachengewehr", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\nGoblinscher Drachenwerfer\nWird beim Aufheben gebunden\nSchmuck\n[q2]Benutzen: Fügt jedem Feind in einem Kegel vor dem Ingenieur, der die Waffe benutzt, 10 Sek. lang 61 bis 69 Punkt(e) Feuerschaden zu. Es sei denn, sie explodiert... (5 Min Abklingzeit)\nBenötigt Mithrilrohr (2), Goblin-Raketentreibstoff (4), Mithrilbarren (6), Echtsilberbarren (6), Instabiler Auslöser"},
[221343] = {name = "[q2]Bauplan: Goblinraketenhelm", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\n[q2]Benutzen:\n\n\n[q2]Goblin-Raketenhelm\nWird beim Anlegen gebunden\n{Kopf} {Stoff}\n50 Rüstung\n+15 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (235)\n[q2]Benutzen: Einen Feind attackieren und ihn für 30 Sekunden außer Gefecht setzen. Ihr werdet ebenfalls niedergeschlagen und für kurze Zeit betäubt. Jeglicher erlittener Schaden wird das Ziel wiederbeleben. (20 Min Abklingzeit)\nBenötigt Goblinscher Schutzhelm , Goblin-Raketentreibstoff (4), Mithrilbarren (4), Instabiler Auslöser"},
[221344] = {name = "[q3]Persönliches Zauberbuch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nIn Schildhand geführt\nKlassen: Magier\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\n[q2]Benutzen: Beschwört 5 Verständnisamulette. (4 Std. Abklingzeit)"},
[221345] = {name = "[q3]Verderbtes Blut des Eranikus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 50"},
[221346] = {name = "[q4]Schulterblatt des gefallenen Avatars", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 50\n[q]\"Ein gut erhaltenes, wunderschön geformtes Schulterblatt, das keine Schäden aufweist.\""},
[221347] = {name = "Düsteres Feuersapta", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht dem Schamanen, Elementargeister zu sehen."},
[221348] = {name = "Düsteres Wassersapta", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht dem Schamanen, Elementargeister zu sehen."},
