[221350] = {name = "Verkohlte Notizen des Schamanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Schamane\n[q]\"Die Seiten sind bis zur Unleserlichkeit verkohlt. Sie scheinen um etwas anderes gewickelt zu sein.\""},
[221351] = {name = "Durchnässte Notizen des Schamanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Schamane\n[q]\"Wasser hat die Tinte unleserlich gemacht. Die Seiten scheinen um etwas anderes gewickelt zu sein.\""},
[221352] = {name = "Verschmierte Notizen des Schamanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Schamane\n[q]\"Schmutz und Abnutzung haben die Notizen unleserlich gemacht. Die Seiten scheinen um etwas anderes gewickelt zu sein.\""},
[221353] = {name = "Feuerfragment", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert das Feuerfragment mit Elementaressenzen. Kann dabei helfen, den verderbten Schrein zu finden."},
