[221360] = {name = "Papyrus der Farraki", additional_info = "Wird beim Aufheben gebunden"},
[221361] = {name = "Harz der Zukk'ash", additional_info = "Wird beim Aufheben gebunden"},
[221362] = {name = "Waffenreinigungstuch", additional_info = "BenötigtSmaragdwärter\n- Freundlich\n[q2]Benutzen: Reinigt Eure Waffe. Alle zeitlich begrenzten Verzauberungen werden entfernt. So gut wie neu!"},
[221363] = {name = "[q4]Schulterblatt des gefallenen Avatars", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 50\n[q]\"Ein gut erhaltenes, wunderschön geformtes Schulterblatt, das keine Schäden aufweist.\""},
[221364] = {name = "[q2]Kupfermassakermünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Transmutiert 100 Kupfermassakermünzen in 1 Silbermassakermünze.\n[q]\"Ein Zeichen für Eure bescheidenen Dienste für den Blutloa.\""},
[221365] = {name = "[q3]Silbermassakermünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Transmutiert 100 Silbermassakermünzen in 1 Goldmassakermünze.\n[q]\"Ein Zeichen für Eure Dienste für den Blutloa.\""},
[221366] = {name = "[q4]Goldmassakermünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein Symbol Eurer herausragenden Dienste für den Blutloa.\""},
[221367] = {name = "Säckchen mit Kupfermassakermünzen", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält 100 Kupfermassakermünzen.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[221368] = {name = "Säckchen mit Silbermassakermünzen", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält 100 Silbermassakermünzen.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[221369] = {name = "[q3]Alptraumsog", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 20\nBenötigtSmaragdwärter\n- Freundlich\n[q2]Anlegen: Stellt 150 Gesundheit und Mana wieder her, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt. Dieser Effekt kann nur einmal alle 10 Sek. auftreten. (10s Abklingzeit)"},
[221370] = {name = "Wertvolles Medaillon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Auf der Rückseite steht: 'Stupser + Enie'\""},
[221371] = {name = "Münzbeutel des Entführers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Öffnen rechtsklicken>"},
[221372] = {name = "[q0]Zerfetzter Münzbeutel", additional_info = "[q]\"Der Inhalt wurde wahrscheinlich im Kampf beschädigt.\""},
[221374] = {name = "[q3]Qual des Traums", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 30\nBenötigtSmaragdwärter\n- Freundlich\n[q2]Anlegen: Erhöht den Schaden oder die Heilung Eures nächsten Angriffs, Eurer nächsten Fähigkeit oder Eures nächsten Zaubers um 40, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt. Dieser Effekt kann nur einmal alle 10 Sek. auftreten. (10s Abklingzeit)"},
[221376] = {name = "[q0]Helm des Smaragdgrünen Traums", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Platte}\n429 Rüstung\n+10 Stärke\n+11 Ausdauer\nHaltbarkeit 80 / 80\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Wohlwollend\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n\n[q]Plattenrüstung des Smaragdgrünen Traums (0/6)\n[q0]Schulterstücke des Smaragdgrünen Traums\nBrustplatte des Smaragdgrünen Traums\nSabatons des Smaragdgrünen Traums\nStulpen des Smaragdgrünen Traums\nBeinplatten des Smaragdgrünen Traums\nHelm des Smaragdgrünen Traums\n[q0](3) Set : +10 Ausdauer.\n(6) Set : +20 Angriffskraft."},
[221377] = {name = "[q3]Beinplatten des Smaragdgrünen Traums", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Platte}\n462 Rüstung\n+11 Stärke\n+8 Beweglichkeit\n+12 Ausdauer\nHaltbarkeit 100 / 100\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Wohlwollend\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n\n[q]Plattenrüstung des Smaragdgrünen Traums (0/6)\n[q0]Schulterstücke des Smaragdgrünen Traums\nBrustplatte des Smaragdgrünen Traums\nSabatons des Smaragdgrünen Traums\nStulpen des Smaragdgrünen Traums\nBeinplatten des Smaragdgrünen Traums\nHelm des Smaragdgrünen Traums\n[q0](3) Set : +10 Ausdauer.\n(6) Set : +20 Angriffskraft."},
[221378] = {name = "[q3]Stulpen des Smaragdgrünen Traums", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Platte}\n330 Rüstung\n+13 Stärke\n+14 Ausdauer\nHaltbarkeit 45 / 45\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Freundlich\n\n[q]Plattenrüstung des Smaragdgrünen Traums (0/6)\n[q0]Schulterstücke des Smaragdgrünen Traums\nBrustplatte des Smaragdgrünen Traums\nSabatons des Smaragdgrünen Traums\nStulpen des Smaragdgrünen Traums\nBeinplatten des Smaragdgrünen Traums\nHelm des Smaragdgrünen Traums\n[q0](3) Set : +10 Ausdauer.\n(6) Set : +20 Angriffskraft."},
[221379] = {name = "[q3]Sabatons des Smaragdgrünen Traums", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Platte}\n363 Rüstung\n+8 Stärke\n+6 Beweglichkeit\n+16 Ausdauer\nHaltbarkeit 65 / 65\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Freundlich\n\n[q]Plattenrüstung des Smaragdgrünen Traums (0/6)\n[q0]Schulterstücke des Smaragdgrünen Traums\nBrustplatte des Smaragdgrünen Traums\nSabatons des Smaragdgrünen Traums\nStulpen des Smaragdgrünen Traums\nBeinplatten des Smaragdgrünen Traums\nHelm des Smaragdgrünen Traums\n[q0](3) Set : +10 Ausdauer.\n(6) Set : +20 Angriffskraft."},
