[221441] = {name = "[q3]Wächter des Traums", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{60 - 94 Schaden} {Tempo 2.00}\n(38.50 Schaden pro Sekunde)\n+18 Stärke\n+14 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 43\nBenötigtSmaragdwärter\n- Respektvoll\n[q2]Anlegen: +73 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
