[221463] = {name = "[q4]Voodoopuppe der Ahnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchmuck\n+8 Ausdauer\nKlassen: Schamane\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 29.\n[q2]Anlegen: Stellt alle 5 Sek. 7 Punkt(e) Mana wieder her."},
[221464] = {name = "[q4]Totem der feurigen Präzision", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nRelikt\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht die Reichweite Eures Zaubers 'Flammenschock' um 5 Meter."},
[221465] = {name = "[q4]Verderbter Schadensbringer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Zweihändig} {Streitkolben}\n{150 - 226 Schaden} {Tempo 3.60}\n(52.22 Schaden pro Sekunde)\n+15 Stärke\n+28 Ausdauer\n+6 Intelligenz\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 50\n[q2]Trefferchance: Setzt das Ziel 2 Sek. lang außer Gefecht."},
[221466] = {name = "[q4]Schleife des brennenden Bluts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Hexenmeister\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 17."},
[221467] = {name = "[q4]Auge des Blutmonds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Hexenmeister\nBenötigt Stufe 50\n[q2]Anlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 17."},
[221468] = {name = "[q4]Mauer des Flüsterns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Schild}hand} {Schild}\n1902 Rüstung\n34 Blocken\n+6 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Krieger\nBenötigt Stufe 50\n[q2]Anlegen: Bei einem Treffer durch einen gegnerischen Zauber besteht eine Chance von 5%, dass der Angreifer 3 Sek. lang zum Schweigen gebracht wird. (Procchance: 5%, 20s Abklingzeit)"},
[221469] = {name = "[q4]Stachelspeer des Kopfjägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\n{Wurfwaffe} {Wurfwaffe}\n{70 - 130 Schaden} {Tempo 3.00}\n(33.33 Schaden pro Sekunde)\nKlassen: Krieger\nBenötigt Stufe 50\n[q2]Benutzen: Schleudert den Speer auf das Ziel und macht es bis zu 5 Sek. lang bewegungsunfähig. (5 Min Abklingzeit)"},
[221470] = {name = "[q3]Traumsmaragd", additional_info = nil},
[221471] = {name = "[q2]Truhe des Smaragdwärters", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[221473] = {name = "[q2]Rune des Wachmanns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Helm mit der Rune 'Wachsamkeit':\n\n\nFokussiert Euren schützenden Blick auf ein Gruppen- oder Schlachtzugsmitglied, verringert so seinen erlittenen Schaden um 3% und überträgt 10% seiner erzeugten Bedrohung auf Euch. Zusätzlich wird jedes Mal, wenn das Ziel von einem Angriff getroffen wird, die Abklingzeit Eurer Fähigkeit 'Spott' abgeschlossen. Hält 30 Min. lang an. Dieser Effekt kann nur auf jeweils einem Ziel wirken.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221474] = {name = "[q3]Gebundene Essenz des Eranikus", additional_info = "Wird beim Aufheben gebunden\nSchmuck\n+10 Ausdauer\n+10 Naturwiderstand\nBenötigt Stufe 50\n[q2]Benutzen: Vergiftet alle Gegner im Umkreis von 8 Metern um den Zaubernden. Die Opfer des Giftes erleiden 45 Sek. lang alle 5 Sek. 50 Naturschaden. (10 Min Abklingzeit)"},
[221475] = {name = "[q2]Essenz des Eranikus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 50\n[q]\"Grüne Nebel wirbeln in den Facetten dieses Edelsteins.\""},
[221480] = {name = "[q2]Zaubernotizen: Geschmolzene Rüstung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Armschienen mit der Rune 'Glühende Rüstung':\n\n\nFügt einem Gegner [10 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)] Feuerschaden zu, wenn Ihr getroffen werdet. Erhöht Eure kritische Zaubertrefferchance um 5% und verringert die Chance, dass Ihr kritische Treffer erleidet, um 5%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221481] = {name = "[q2]Nihilistische Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Armschienen mit der Rune 'Zone der Leere':\n\n\nBeschwört eine 'Zone der Leere' im Zielbereich, die allen Gegnern, die sich darin befinden, 10 Sek. lang pro Sekunde [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 51 / 100] Schattenschaden zufügt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221482] = {name = "[q2]Rune des Gebrechens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Armschienen mit der Rune 'Instabiles Gebrechen':\n\n\nSchattenenergie zerstört langsam das Ziel und verursacht im Verlauf von 18 Sek. insgesamt [242 * 6 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] Schaden. Sollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende [242 * 227 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] Schaden und wird 5 Sek. lang zum Schweigen gebracht. Es kann pro Hexenmeister jeweils nur ein Effekt von 'Instabiles Gebrechen' oder 'Feuerbrand' gleichzeitig auf einem beliebigen Ziel aktiv sein.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221483] = {name = "[q2]Rune des Brands", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euren Helm mit der Rune 'Brennen':\n\n\nEuer 'Flammenschock' trifft jetzt bis zu 5 Ziele, hat eine 6 Sek. längere Effektdauer und verursacht 100% mehr Schaden. Zusätzlich wird Euer Zauberschaden um 150% Eurer Intelligenz erhöht, während Eure ausgerüstete Waffenhandwaffe mit 'Waffe der Flammenzunge' verzaubert ist.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221484] = {name = "[q4]Hexerstecken des Hexendoktors", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Verhext Euch selbst, um im Versunkenen Tempel etwas schwerer entdeckt zu werden. (3 Sek. Abklingzeit)"},
[221487] = {name = "[q2]Zaubernotizen: Fortgeschrittener Schutzzauber", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Helm mit der Rune 'Fortgeschrittener Schutzzauber':\n\n\nEure Zauber 'Manaschild', 'Frostzauberschutz' und 'Feuerzauberschutz' können jetzt auf verbündete Ziele gewirkt werden und absorbieren 100% mehr Schaden. 'Manaschild' verbraucht 50% weniger Mana pro absorbiertem Schaden. Außerdem wird 'Geringen Fluch aufheben' durch 'Großen Fluch aufheben' ersetzt.\n\n\nEntfernt 1 Fluch und 1 schädlichen Magieeffekt von einem verbündeten Ziel.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221488] = {name = "[q2]Resolute Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Helm mit der Rune 'Göttliche Aegis':\n\n\nKritische Heilungen hüllen das Ziel in einen schützenden Schild, der Schaden in Höhe von 30% des geheilten Wertes absorbiert. Hält 12 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221489] = {name = "[q2]Rune der Rache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Helm mit der Rune 'Rache':\n\n\nWenn diese Fähigkeit aktiviert wird, gewährt sie Euch 20 Sek. lang vorübergehend um 30% erhöhte maximale Gesundheit. Wenn der Effekt abklingt, geht die zusätzliche Gesundheit wieder verloren. Außerdem sorgt 'Rache' dafür, dass Eure Flügel, während 'Metamorphose' aktiv ist, Eure Fallgeschwindigkeit verringern.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221490] = {name = "[q2]Rune der Springflut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Eure Armschienen mit der Rune 'Springflut':\n\n\nHeilt ein verbündetes Ziel um [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] bis [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] Gesundheit und im Verlauf von 15 Sek. um weitere [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] Gesundheit. Wenn Ihr innerhalb von 15 Sek. 'Kettenheilung' auf dieses Hauptziel wirkt, wird die hervorgerufene Heilung um 25% erhöht. Dieser Zauber löst außerdem 'Erwachen der Ahnen' aus.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221491] = {name = "[q2]Schattenzahntasche", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält eine zufällige Dunkelmond-Karte.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[221497] = {name = "Alter Schlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Benutzen: Öffnet eine alte Truhe."},
[221498] = {name = "Stabile Vesperdose", additional_info = "Wird beim Aufheben gebunden\n12 Platz Behälter"},
[221499] = {name = "[q2]Rune der Teufelswache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Armschienen mit der Rune 'Teufelswache beschwören':\n\n\nBeschwört eine Teufelswache, die unter dem Befehl des Hexenmeisters steht.\n\n Die Teufelswache profitiert von allen Talenten und Effekten, die von anderen Dämonendienern ausgelöst werden oder die daraus einen Vorteil ziehen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221510] = {name = "[q2]Rune des Ritters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Eure Armschienen mit der Rune 'Schwert und Schild':\n\n\nWenn Eure Fähigkeiten 'Verwüsten' und 'Rache' Schaden verursachen, besteht eine Chance von 30%, die Abklingzeit von 'Schildschlag' abzuschließen und die Wutkosten der Fähigkeit 5 Sek. lang um 100% zu verringern.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221511] = {name = "[q2]Rune des Beschützers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Helm mit der Rune 'Schildmeisterschaft':\n\n\nErhöht den gesamten von Euch verursachten körperlichen Schaden um 10%, während Ihr ein Schild ausgerüstet habt, und verringert die Dauer aller auf Euch angewandten Entwaffnungseffekte um 50%. Dieser Effekt ist mit anderen Effekten, welche die Entwaffnungsdauer verringern, nicht stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221512] = {name = "[q2]Rune des Eifers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Eure Armschienen mit der Rune 'In Stücke schneiden':\n\n\nEure Fähigkeiten 'Ausweiden' und 'Vergiften' erneuern die Dauer Eurer Fähigkeit 'Zerhäckseln' oder 'Klingentanz' auf ihre maximalen Combopunkte von 5. Wenn beide aktiv sind, wird nur die geringste verbleibende Dauer erneuert.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221513] = {name = "[q2]Rune der Kraft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euren Helm mit der Rune 'Kampfkraft':\n\n\nIhr habt eine Chance von 20%, jedes Mal 15 Energie zu erhalten, wenn Ihr Nahkampfschaden mit Eurer Schildhandwaffe verursacht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221514] = {name = "[q2]Rune der Feuerkraft", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\n[q2]Prägt Euren Helm mit der Rune 'Sichern und Laden':\n\n\nJedes Mal, wenn Ihr eine Falle platziert, kostet Eure nächste Schussfähigkeit (mit Ausnahme von 'Streuschuss') innerhalb von 20 Sek. kein Mana und löst keine Abklingzeit aus.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221515] = {name = "[q2]Rune der Detonation", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Eure Armschienen mit der Rune 'T.N.T.':\n\n\nErhöht von 'Explosivschuss' und all Euren Schadensfallen verursachten Schaden um 10%. Zudem werden der anfängliche Schaden von 'Sprengfalle' sowie der gesamte regelmäßige Schaden Eurer 'Feuerbrandfalle' um 25% Eurer Nahkampf- oder Distanzangriffskraft erhöht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221516] = {name = "[q2]Rune der urtümlichen Energie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Eure Armschienen mit der Rune 'Verbesserte rasende Regeneration':\n\n\nEure 'Rasende Regeneration' kann jetzt in allen Gestalten mit Ausnahme der Moonkingestalt oder im unverwandelten Zustand genutzt werden. Sie konvertiert nun Eure aktive Ressource 10 Sek. lang sekündlich in Gesundheit. Bis zu 10 Wut, 10 Energie oder 20% Grundmana werden pro Sekunde in bis zu 10% Gesundheit konvertiert.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221517] = {name = "[q2]Rune des Blutvergießens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euren Helm mit der Rune 'Aufspießen':\n\n\nWenn Ihr ein Ziel mit 'Aufschlitzen', 'Prankenhieb' oder 'Zermalmen' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Zerfleischen (Bär)' abgeschlossen und 10 Wut erzeugt wird. Wenn Ihr ein Ziel mit 'Zerfleischen' (Katze) oder 'Schreddern' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Tigerfuror' abgeschlossen wird.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[221518] = {name = "[q3]Flüstern", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{109 - 163 Schaden} {Tempo 2.60}\n(52.31 Schaden pro Sekunde)\n+20 Stärke\n+12 Ausdauer\nHaltbarkeit 100 / 100\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%."},
[221519] = {name = "[q3]Kugel der Mannoroc", additional_info = "Questgegenstand\nEinzigartig"},
[221544] = {name = "Sturmkrähenei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[221545] = {name = "Entschlüsselte Hexenmeisternotizen", additional_info = "Einzigartig\nKlassen: Priester , Schamane"},
[221547] = {name = "Verschlüsselte Hexenmeisternotizen", additional_info = "Einzigartig\n[q2]Benutzen: Um die Notizen des Hexenmeisters zu verstehen, ist eine Glyphe erforderlich. Wer weiß, welche Magie sie enthält?"},
[221549] = {name = "Chiffre der Wüstenläufer", additional_info = "[q]\"Hilft bei der Übersetzung der von den Banditen der Wüstenläufer geschriebenen Dokumente.\""},
[221780] = {name = "[q3]Prinzessin Theradras' Szepter", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{111 - 174 Schaden} {Tempo 3.40}\n(41.91 Schaden pro Sekunde)\n90 Rüstung\n+13 Stärke\n+10 Beweglichkeit\n+15 Ausdauer\n+9 Willenskraft\nHaltbarkeit 100 / 100\nBenötigt Stufe 46\n[q2]Anlegen: +67 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
[221781] = {name = "[q3]Avenwachthelm", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Platte}\n469 Rüstung\n+10 Stärke\n+5 Beweglichkeit\n+25 Ausdauer\nHaltbarkeit 80 / 80"},
[221782] = {name = "[q3]Helm des Banns", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Kette}\n266 Rüstung\n+11 Beweglichkeit\n+18 Intelligenz\nHaltbarkeit 70 / 70\n[q2]Anlegen: +36 Angriffskraft."},
[221783] = {name = "[q4]Schiftung der Gerechtigkeit", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Platte}\n562 Rüstung\n+17 Stärke\n+15 Ausdauer\n+7 Feuerwiderstand\nHaltbarkeit 100 / 100\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 21.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n\n[q]Strahlen der Gerechtigkeit (0/8)\n[q0]Kampfstiefel der Gerechtigkeit\nBrustplatte der Gerechtigkeit\nKrone der Gerechtigkeit\nGurt der Gerechtigkeit\nHandschutz der Gerechtigkeit\nGamaschen der Gerechtigkeit\nSchiftung der Gerechtigkeit\nKriegsbänder der Gerechtigkeit\n[q0](2) Set : 'Richturteil des Lichts' und 'Richturteil der Weisheit' gewähren zusätzlich die Effekte von 'Richturteil des Kreuzfahrers'.\n(4) Set : Erhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%.\n(6) Set : Eure Fähigkeiten 'Siegel des Befehls', 'Siegel der Rechtschaffenheit', 'Siegel des Märtyrertums' und 'Sonnenlicht' verursachen 35% weniger Schaden, halten jetzt allerdings nach Einsatz eines weiteren Siegels noch 6 Sek. an, oder bis Ihr ein drittes Siegel einsetzt. 'Richturteil' kann mehrere Siegel auslösen, wenn sie aktiv sind."},
[221785] = {name = "[q0]Gewand des Cenarius", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Leder}\n200 Rüstung\n+11 Ausdauer\n+17 Intelligenz\n+15 Willenskraft\n+10 Feuerwiderstand\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 62.\n\n[q]Fülle des Cenarius (0/8)\n[q0]Gürtel des Cenarius\nStiefel des Cenarius\nArmschienen des Cenarius\nHandschuhe des Cenarius\nHelm des Cenarius\nGamaschen des Cenarius\nSchiftung des Cenarius\nGewand des Cenarius\n[q0](2) Set : Wenn Ihr 'Anregen' auf einen anderen Spielercharakter wirkt, ist auch Euer Charakter betroffen.\n(4) Set : Wenn Ihr Eure Zauber 'Heilende Berührung' oder 'Pflege' wirkt, erhaltet Ihr mit einer Chance von 25% Mana in Höhe von 35% der Grundkosten des Zaubers. (Procchance: 25%, 1s Abklingzeit)\n(6) Set : Verringert die Abklingzeit von 'Gelassenheit' um 100% und erhöht ihre Heilung um 100%. (Procchance: 25%, 1s Abklingzeit)"},
[221971] = {name = "[q2]Traumschwurhorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Kombiniert alle gesammelten Reagenzien zu einer Rune, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Ein einzigartiges Reagenz, das eine feurige Essenz in sich trägt. Ihr könnt eine neue Rune schnitzen, wenn Ihr ähnliche Komponenten findet.\""},
[221972] = {name = "[q2]Traumloderfeuer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Kombiniert alle gesammelten Reagenzien zu einer Rune, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Ein einzigartiges Reagenz, das eine feurige Essenz in sich trägt. Ihr könnt eine neue Rune schnitzen, wenn Ihr ähnliche Komponenten findet.\""},
[221973] = {name = "[q2]Traumjägerreißzahn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Kombiniert alle gesammelten Reagenzien zu einer Rune, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Ein einzigartiges Reagenz, das eine feurige Essenz in sich trägt. Ihr könnt eine neue Rune schnitzen, wenn Ihr ähnliche Komponenten findet.\""},
[221974] = {name = "[q2]Halskette der Grimmtotem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Fügt die gesammelten Reagenzien zu einem zerbrechlichen Stab zusammen, der den unvergänglichen Schlummer beenden kann.\n[q]\"Eine Halskette, die von einem erkrankten Schamanen der Grimmtotem gesammelt wurde.\""},
[221975] = {name = "[q2]Zerbrochener Stab der Waldpfoten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Fügt die gesammelten Reagenzien zu einem zerbrechlichen Stab zusammen, der den unvergänglichen Schlummer beenden kann.\n[q]\"Teil eines Stabs, der von einem erkrankten Mystiker der Waldpfoten gesammelt wurde.\""},
[221976] = {name = "[q2]Verseuchter Naturstab", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Erweckt das aktuelle Ziel aus unvergänglichem Schlummer.\n[q]\"Der Stab hält kaum zusammen, aber die uralte Magie im Inneren könnte trotzdem noch zu gebrauchen sein.\""},
[221978] = {name = "Seele des Forschers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Beschwört einen Wichtelforscher. Er kann zwar nicht kämpfen, dafür reist er aber durch Portale, um andere Welten zu erforschen und Schätze mitzubringen.\n[q]\"Erlernt, wie man einen Wichtelforscher beschwört.\""},
[221979] = {name = "[q2]Prophezeiung des tiefgrünen Winters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Helm mit der Rune 'Schmerz und Leid':\n\n\n'Gedankenschlag', 'Gedankenstachel' und 'Gedankenschinden' setzen die Dauer von 'Schattenwort: Schmerz', 'Pest der Leere' oder 'Vampirberührung' auf Eurem Ziel auf das Maximum zurück. Es wird immer die Fähigkeit mit der geringsten verbleibenden Dauer aufgefrischt.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[221980] = {name = "[q2]Prophezeiung des erwachten Chaos", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Helm mit der Rune 'Auge der Leere':\n\n\nRuft ein Auge der Leere, das 30 Sek. lang für Euch kämpft. Das Auge kann verschiedene Flüche auf Euer Ziel wirken.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[221981] = {name = "[q2]Prophezeiung des verlorenen Stammes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Armschienen mit der Rune 'Woge des Lichts':\n\n\nKritische Zaubertreffer sorgen dafür, dass Ihr 'Heilige Pein' oder 'Blitzheilung' beim nächsten Mal innerhalb von 15 Sek. sofort wirkt.\n[q2]Benutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist."},
[222952] = {name = "[q4]Fläschchen der ruhelosen Träume", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenötigt Alchimie (250)\n[q2]Benutzen: Erhöht 1 Stunde lang den durch Zauber verursachten Schaden um 30, die verursachte Heilung um bis zu 45 Gesundheit und die Manaregeneration um 12 Mana pro 5 Sek. Die Vorteile dieses Fläschchens wirken nur in Gebieten, die unter dem Einfluss des Alptraums stehen. (30 Sek. Abklingzeit)\n[q]\"Die Flasche scheint nie leer zu werden, egal, wie viel man davon trinkt.\""},
[222962] = {name = "Weisheit des Hyjal", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Erlernt eine neue Runenschnitzenfähigkeit."},
