[224279] = {name = "[q4]Terrestris", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n2964 Rüstung\n55 Blocken\n+17 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 60\n[q2]Anlegen: Verteidigung +7.\n[q2]Anlegen: Beschworene Totems gewähren einen Segen ihres Elements.\n[q2]Benutzen: Entfacht die Flammen von Terrestris und heizt ihn für die Offensive an. (1 Min Abklingzeit)"},
[224280] = {name = "[q4]Suzerain, Verteidiger der Drachenschwärme", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n2964 Rüstung\n55 Blocken\n+15 Stärke\nHaltbarkeit 120 / 120\nKlassen: Krieger\nBenötigt Stufe 60\n[q2]Anlegen: Schützt den Träger davor, vollständig von der Schattenflamme verzehrt zu werden.\n[q2]Anlegen: Verteidigung +10.\n[q2]Anlegen: Erhöht den Blockwert Eures Schildes um 18.\n[q2]Benutzen: Hebt Suzerain 5 Sek. lang empor, wodurch Ihr 50% weniger Zauberschaden erleidet. Wenn Ihr von 'Drachenodem' getroffen werdet, erhaltet Ihr 'Suzerains Zorn', was Euch 10 Sek. lang 30% Bonusschaden gegen Drachen verleiht. (1 Min Abklingzeit)"},
[224281] = {name = "[q4]Gla'sir", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n{140 - 241 Schaden} {Tempo 3.20}\n(59.53 Schaden pro Sekunde)\n+12 Ausdauer\n+26 Intelligenz\n+14 Willenskraft\n+10 Naturwiderstand\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 144 und den verursachten Schaden um bis zu 77.\n[q2]Anlegen: Kritische Effekte von Heilungen haben eine Chance, 3 Verbündete in der Nähe um 200 bis 350 Gesundheit zu heilen, und kritische Treffer mit Zaubern haben eine Chance, 3 Gegnern in der Nähe 100 bis 175 Naturschaden zuzufügen. (Procchance: 15%, 15s Abklingzeit)\n[q2]Benutzen: Verwandelt Gla'sir in Rae'lar. (1 Min Abklingzeit)"},
[224282] = {name = "[q4]Rae'lar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n{125 - 226 Schaden} {Tempo 3.20}\n(54.84 Schaden pro Sekunde)\n+26 Stärke\n+23 Beweglichkeit\n+12 Ausdauer\n+10 Naturwiderstand\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 60\n[q2]Anlegen: +338 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Anlegen: Chance bei automatischen Nahkampfangriffen, dem anvisierten Gegner bei einem Treffer 140 bis 220 Leben zu rauben.\n[q2]Benutzen: Verwandelt Rae'lar in Gla'sir. (1 Min Abklingzeit)"},
[224409] = {name = "[q0]Schlangenschläger", additional_info = "Wird beim Aufheben gebunden\n{Schildhand} {Faustwaffe}\n{73 - 136 Schaden} {Tempo 2.60}\n(40.19 Schaden pro Sekunde)\n+9 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 50\n[q2]Trefferchance: Vergiftet den Gegner und verursacht 50 Naturschaden, verringert den Naturwiderstand um 60 und erhöht sämtlichen erlittenen Heilig- und Naturschaden 20 Sek. lang um 8%. Wirkt nur bei Gegnern der Stufe 55 oder niedriger.\n\n[q]Aufstieg der Schlange (0/2)\n[q0]Kobragiftzahnklaue\nSchlangenschläger\n[q0](2) Set : Gewährt dem Benutzer beim Verursachen von Distanz- oder Nahkampfschaden eine kleine Chance, mit dem Segen der Schlange erfüllt zu werden. Distanz- und Nahkampfangriffskraft 12 Sek. lang um 150 erhöht. (Procchance: 3%, 2Min. Abklingzeit)"},
[224806] = {name = "[q2]Portalempfänger der Legion", additional_info = "[q2]Benutzen: Verbindet eine Teufelsnarbe oder einen Teufelsriss mit einer Welt tief im Raum der Legion. Das kann unvorhersehbare und gefährliche Auswirkungen haben.\n5 Aufladungen"},
[224836] = {name = "[q2]Überirdischer Schatz", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[224848] = {name = "[q2]Überirdischer Schatz", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[224849] = {name = "[q2]Überirdischer Schatz", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[224850] = {name = "[q2]Überirdischer Schatz", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[224851] = {name = "[q2]Überirdischer Schatz", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"},
[224893] = {name = "[q2]Überladener Portalempfänger", additional_info = "[q2]Benutzen: Verbindet eine Teufelsnarbe oder einen Teufelsriss mit einer Welt tief im Raum der Legion. Das kann unvorhersehbare und gefährliche Auswirkungen haben.\n2 Aufladungen"},
[224912] = {name = "[q2]Portalempfängerempfänger", additional_info = "[q2]Benutzen: Überladet einen Portalempfänger der Legion."},
[225675] = {name = "Rußbedeckter Obsidiankern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Poliert den Ruß ab."},
[225676] = {name = "Geschmolzener Obsidiankern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 10 min (Realzeit)\n[q]\"Kühlt ihn ab, bevor er schmilzt!\""},
[225686] = {name = "[q2]Rune der Dezimierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Eure Stiefel mit der Rune 'Dezimierung':\n\n\nEuer Zauber 'Seelenfeuer' hat keine Abklingzeit mehr. Wenn Ihr Eure Zauber 'Schattenblitz', 'Schattenspalten', 'Verbrennen' oder 'Seelenfeuer' auf ein Ziel wirkt, das 35% Gesundheit oder weniger besitzt, wird die Zauberzeit von 'Seelenfeuer' 10 Sek. lang um 40% verringert. Wenn Ihr 'Seelenfeuer' einsetzt, während Ihr unter dem Effekt von 'Dezimierung' steht, kostet der Zauber keinen Seelensplitter.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225687] = {name = "[q2]Rune der höllischen Rüstung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Umhang mit der Rune 'Höllische Rüstung':\n\n\nEuer Geist wird von dämonischer Energie erfüllt, was Euren sämtlichen erlittenen magischen Schaden um einen Prozentsatz verringert, der 60% Eurer körperlichen Schadensverringerung durch Rüstung entspricht. Hält 10 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225688] = {name = "[q2]Rune des Mals des Chaos", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Umhang mit der Rune 'Mal des Chaos':\n\n\nMit Ausnahme von 'Fluch der Schatten' und 'Fluch der Elemente' belegen all Eure Flüche das Ziel nun mit 'Mal des Chaos', wodurch dessen Arkan-, Feuer-, Frost-, Natur- und Schattenwiderstand um [Max(Min( 56 + 19, 75), 27)] verringert und sämtlicher erlittener Zauberschaden dieser Magiearten um [Max(Min(( 56 - 8) * 0.125 + 4, 10), 4)]% erhöht wird, solange der Fluch andauert.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225689] = {name = "[q2]Zaubernotizen: Arkanbeschuss", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Umhang mit der Rune 'Arkanbeschuss':\n\n\nSchleudert mehrere Geschosse auf das gegnerische Ziel und verursacht [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 358 / 100] bis [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 438 / 100] Arkanschaden. Dieser Zauber hat außerdem eine Chance von 25%, 'Geschosssalve' auszulösen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225690] = {name = "[q2]Zaubernotizen: Gefrorene Kugel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Umhang mit der Rune\n 'Gefrorene Kugel':\n\n\nSchleudert eine Kugel aus wirbelndem Eis, die sich im Verlauf von 16 Sek. schnell nach vorne bewegt. Während sie sich bewegt, verursacht die Kugel alle 1 Sek. [90 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] Frostschaden und belegt alle Gegner, durch die sie sich bewegt, mit 'Kühlung' und verringert ihre Bewegungsgeschwindigkeit um 30%. Sobald sie einem Gegner zum ersten Mal Schaden zufügt, verlangsamt sie ihre Bewegung und hat eine Chance von 100%, die Rune 'Eisige Finger' auszulösen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225691] = {name = "[q2]Zaubernotizen: Überhitzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Umhang mit der Rune 'Überhitzen':\n\n\n'Feuerschlag' trifft immer kritisch, kann gewirkt werden, während Ihr einen anderen Zauber wirkt, und ist nicht von der globalen Abklingzeit betroffen. Die Abklingzeit ist jedoch um 15 Sek. erhöht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225740] = {name = "[q2]Rune der Beherrschung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euren Umhang mit der Rune 'Kohärenz':\n\n\nDie Effektivität Eurer 'Kettenheilung' wird nur um 35% pro Übersprung verringert und die Effektivität von 'Kettenblitzschlag' nur um 20% Prozent pro Übersprung. Springt außerdem auf 1 zusätzliches Ziel über.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225838] = {name = "[q2]Voltaische Ikone", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nKlassen: Schamane\n[q2]Prägt Euren Umhang mit der Rune 'Sturm, Erde und Feuer':\n\n\nVerringert die Abklingzeit Eures Zaubers 'Kettenblitzschlag' um 25%, verleiht Eurem Totem der Erdbindung eine Chance, Ziele 5 Sek. lang festzuwurzeln, wenn es aufgestellt wird, und erhöht den regelmäßigen Schaden Eures Zaubers 'Flammenschock' um 60%.\n[q]\"Erlernt eine neue Fähigkeit, nachdem Ihr 3 Gegner mit einem einzelnen Einsatz von 'Kettenblitzschlag' besiegt.\""},
[225893] = {name = "[q4]Epochenende", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: (Unbekannt #636) (0)\n{Zweihändig} {Schwert}\n{300 - 415 Schaden} {Tempo 4.20}\n(85.12 Schaden pro Sekunde)\n-322 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 77"},
[225914] = {name = "[q2]Rune des gebundenen Geistes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Prägt Euren Umhang mit der Rune 'Wildgeist':\n\n\nBeschwört zwei Geisterwölfe, die unter dem Befehl des Schamanen stehen. Hält 45 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[225929] = {name = "Verseuchter Seelensplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (3)"},
[225938] = {name = "[q2]Zerrissene Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\""},
[225939] = {name = "[q2]Zerrissene Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\""},
[225940] = {name = "[q2]Zerrissene Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\""},
[225941] = {name = "[q2]Zerrissene Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n[q]\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\""},
[225942] = {name = "Besudeltes Eberfleisch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Mit Sekret beschichtet.\n[q]\"Braucht vermutlich nur etwas Soße.\""},
[225943] = {name = "Ranziger Fleischbrocken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: ???\n[q]\"Würde selbst den niedersten Aasfresser zum Würgen bringen.\""},
[225954] = {name = "[q2]Verkohlte Zaubernotizen", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q]\"Eine verkohlte, zerrissene Seite, die einst arkane Geheimnisse zu Runenschnitzenfähigkeiten barg, doch durch den Brandschaden unbrauchbar gemacht wurde.\""},
[225955] = {name = "[q2]Rune des Einfallsreichen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Euren Umhang mit der Rune 'Improvisation':\n\n\nVerringert die Manakosten Eurer Fallen um 100% und ihre Abklingzeiten um 40%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226122] = {name = "[q3]Daltons Horn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt\nBenötigt Stufe 50\n[q2]Benutzen: Stößt in Daltons Horn, um Euren Knappen zu beschwören. Euer Knappe wird Euch im Kampf beistehen und bei gemeinsamen Abenteuern von Euch lernen. (Procchance: 3%) (15 Sek. Abklingzeit)\n[q]\"Kokosnüsse nicht enthalten.\""},
[226201] = {name = "Klinge von Knappe Cuthbert", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Das Schwert ist verbeult und beschädigt, liegt allerdings gut in der Hand.\""},
[226207] = {name = "Echo von Anastari", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226208] = {name = "Echo von Barthilas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226209] = {name = "Echo von Dathrohan", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226210] = {name = "Echo von Maleki", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226211] = {name = "Echo von Nerub'enkan", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226212] = {name = "Echo von Ramstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226213] = {name = "Echo von Rivendare", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226214] = {name = "Echo von Willey", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\n[q2]Benutzen: Bietet das Echo dar."},
[226252] = {name = "[q2]Rune des Guerrillas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Prägt Euren Umhang mit der Rune 'Drauf und weg':\n\n\nNach dem Einsatz von 'Raptorstoß' wird Eure Bewegungsgeschwindigkeit 15 Sek. lang um 30% erhöht.\n\n Die Schaden verursachenden Fähigkeiten Eures Begleiters belegen das Ziel 2 Min. lang mit 'Tollwütige Raserei', wodurch dessen Nahkampfangriffskraft um 91 erhöht und dessen Rüstung um 640 verringert wird. Tollwütige Gegner flüchten nicht und ignorieren Furcht- und Entsetzenseffekte.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226374] = {name = "Okkultes Gift I", additional_info = "Klassen: Schurke\nBenötigt Stufe 54\n{[q2]Benutzen: Überzieht eine Waffe mit Gift, das 30 Min. lang wirkt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, ihm so 108 {Naturschaden im Verlauf von 12 Sek. zuzufügen und dabei seinen erlittenen Arkan-, Feuer-, Frost-, Natur- und Schattenschaden} um 4% zu erhöhen. Bis zu 5-mal auf einem Ziel stapelbar.\n\n 'Okkultes Gift' zählt als 'Tödliches Gift' und profitiert von allen Talenten, die durch 'Tödliches Gift' ausgelöst werden oder dieses modifizieren. (Procchance: 30%)}"},
[226394] = {name = "[q2]Handbuch für atrophisches Gift", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Überzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\n Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was dessen Nahkampfangriffskraft 15 Sek. lang um 205 verringert. 105 Aufladungen.\n[q]\"Lehrt Euch 'Atrophisches Gift'.\""},
[226395] = {name = "[q2]Handbuch für betäubendes Gift", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Überzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\n Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was die Zeit zwischen dessen Nahkampfangriffen 15 Sek. lang um 20% erhöht. 105 Aufladungen.\n[q]\"Lehrt Euch 'Betäubendes Gift'.\""},
[226396] = {name = "[q2]Handbuch für okkultes Gift", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n{[q2]Überzieht eine Waffe mit Gift, das 30 Min. lang wirkt.\n Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, ihm so 108 {Naturschaden im Verlauf von 12 Sek. zuzufügen und dabei seinen erlittenen Arkan-, Feuer-, Frost-, Natur- und Schattenschaden} um 4% zu erhöhen. Bis zu 5-mal auf einem Ziel stapelbar.\n\n 'Okkultes Gift' zählt als 'Tödliches Gift' und profitiert von allen Talenten, die durch 'Tödliches Gift' ausgelöst werden oder dieses modifizieren.}\n[q]\"Lehrt Euch 'Okkultes Gift'.\""},
[226397] = {name = "[q2]Handbuch für zähes Gifts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Überzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\n Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was dessen Rüstung 15 Sek. lang um 1700 verringert. 105 Aufladungen.\n\n 'Zähes Gift' profitiert vom Talent 'Verbessertes Rüstung schwächen'.\n[q]\"Lehrt Euch 'Zähes Gift'.\""},
[226398] = {name = "[q2]Testament des Märtyrertums", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Erfüllt den Paladin 30 Sek. lang mit heiligem Geist, wodurch alle Eure Nahkampfangriffe Eurem Ziel 50% Waffenschaden zufügen. Ihr verliert dabei jedoch Gesundheit in Höhe von 10% des verursachten Schadens. Während dieses Siegel aktiv ist, gewinnen Eure Gruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern Mana in Höhe von 65% des Schadens hinzu, den Ihr durch dieses Siegel erleidet.\n\n Die Entfesselung der Energie dieses Siegels richtet einen Gegner und verursacht sofort 85% Waffenschaden auf Kosten von Gesundheit in Höhe von 10% des verursachten Schadens.\n\n Das Siegel und das Richturteil dieser Fähigkeit profitieren von Talenten und Effekten, die das Siegel oder Richturteil von 'Siegel der Rechtschaffenheit' beeinflussen.\n[q]\"Lehrt Euch 'Siegel des Märtyrertums'.\""},
[226399] = {name = "[q2]Testament der zornigen Vergeltung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Erhöht 20 Sek. lang jeglichen verursachten Schaden und Heilung um 20%. Verursacht 'Vorahnung' und kann nicht eingesetzt werden, während 'Vorahnung' aktiv ist.\n[q]\"Lehrt Euch 'Zornige Vergeltung'.\""},
[226400] = {name = "[q2]Testament des Exorzisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]'Exorzismus' kann jetzt auf jegliche Ziele gewirkt werden und hat eine 100% höhere kritische Trefferchance gegen Untote und Dämonen.\n[q]\"Lehrt Euch 'Exorzist'.\""},
[226401] = {name = "[q2]Abhandlung über das Löwenherz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Der Jäger beschwört das Herz eines Löwen, was alle Werte aller Verbündeten in der Nähe um 10% und deren Angriffskraft um 200 und alle Werte des Jägers um zusätzlich 10% erhöht.\n[q]\"Lehrt Euch 'Löwenherz'.\""},
[226402] = {name = "[q2]Offenbarung der schamanistischer Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Reduziert sämtlichen von Euch erlittenen Schaden um 20% und Ihr regeneriert 15 Sek. lang pro Sekunde Mana in Höhe von 5% Eures maximalen Manas. Eure Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern erhalten zudem Mana in Höhe von 18% des von Euch auf diese Weise bezogenen Manas.\n[q]\"Lehrt Euch 'Schamanistische Wut'.\""},
[226403] = {name = "[q2]Handbuch des Fleischhakens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Wirft einen Haken mit einer Kette aus, um das Ziel zu fesseln und zu Euch zu ziehen. Kann nicht gegen Gegner eingesetzt werden, die eine höhere Stufe als ( 60 + 1) haben oder als Bossgegner markiert sind.\n[q]\"Lehrt Euch 'Fleischhaken'.\""},
[226404] = {name = "[q2]Angelaufener Real aus Undermine", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (250)\n[q]\"Diese Währung der Verlorenen Inseln wird langsam aus dem Kreislauf genommen, doch in Kalimdor und den Östlichen Königreichen erfreut sie sich nach wie vor einem überaus vorteilhaften Wechselkurs.\""},
[226405] = {name = "[q2]Beschädigte Vorratskiste aus Undermine", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q]\"Diese verbeulte und beschädigte Kiste sieht aus, als wäre sie buchstäblich von einem Zeppelin gefallen.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[226406] = {name = "[q2]Rune der Schwert-Spezialisierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Jäger , Schurke , Magier , Hexenmeister\n[q2]Prägt Euren Ring mit der Rune 'Schwert-Spezialisierung':\n\n\nFertigkeit mit Schwertern und Zweihandschwertern um 5 erhöht. Dieser Effekt ist nicht mit Volksboni oder anderen Ringrunen stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226407] = {name = "[q2]Rune der Axt-Spezialisierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Jäger , Schamane\n[q2]Prägt Euren Ring mit der Rune 'Axt-Spezialisierung':\n\n\nFertigkeit mit Äxten und Zweihandäxten um 5 erhöht. Dieser Effekt ist nicht mit Volksboni oder anderen Ringrunen stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226408] = {name = "[q2]Rune der Streitkolben-Spezialisierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Schurke , Priester , Schamane , Druide\n[q2]Prägt Euren Ring mit der Rune 'Streitkolben-Spezialisierung':\n\n\nFertigkeit mit Streitkolben und Zweihandstreitkolben um 5 erhöht. Dieser Effekt ist nicht mit Volksboni oder anderen Ringrunen stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226409] = {name = "[q2]Rune der Dolch-Spezialisierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Jäger , Schurke , Priester , Schamane , Magier , Hexenmeister , Druide\n[q2]Prägt Euren Ring mit der Rune 'Dolch-Spezialisierung':\n\n\nFertigkeit mit Dolchen um 5 erhöht. Dieser Effekt ist nicht mit Volksboni oder anderen Ringrunen stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226410] = {name = "[q2]Rune der Distanzwaffen-Spezialisierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Jäger , Schurke\n[q2]Prägt Euren Ring mit der Rune 'Distanzwaffen-Spezialisierung':\n\n\nErhöht die Fertigkeit mit Bögen, Schusswaffen, Armbrüsten und Wurfwaffen um 5. Dieser Effekt ist nicht mit Volksboni oder anderen Ringrunen stapelbar.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
