[226678] = {name = "[q4]Vorahnung und Voraussicht im Kampf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Umhang mit der Rune\n 'Schockwelle':\n\n\nSchickt dem Krieger eine Druckwelle voraus, die (50 / 100 * Angriffskraft) Schaden verursacht und in einem kegelförmigen Bereich von 10 Metern alle gegnerischen Ziele 4 Sek. lang betäubt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226679] = {name = "[q3]Erkenntnisse des Zeitlosen Wanderers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Umhang mit der Rune 'Plötzlicher Tod':\n\n\nEure Nahkampftreffer haben eine Chance von 10%, Euch 'Plötzlicher Tod' zu gewähren. 'Plötzlicher Tod' ermöglicht Euch einen Einsatz von 'Hinrichten' ungeachtet der Gesundheit Eures Ziels. Wenn 'Hinrichten' durch 'Plötzlicher Tod' ermöglicht wurde, behaltet Ihr 10 Wut nach Einsatz von 'Hinrichten'.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226680] = {name = "[q3]Rune des ersten Kriegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Prägt Euren Umhang mit der Rune\n 'Frischfleisch':\n\n\nWenn Ihr einem Ziel mit 'Blutdurst', 'Tödlicher Stoß' oder 'Schildschlag' Schaden zufügt, habt Ihr beim ersten Mal eine Chance von 100% und bei jedem weiteren Mal eine Chance von 10% in einen Wutzustand versetzt zu werden (und darauf, Fähigkeiten zu aktivieren, die einen Wutzustand erfordern). Zudem verursacht Ihr 12 Sek. lang 10% mehr körperlichen Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[226694] = {name = "[q2]Rune der Verteidigungs-Spezialisierung", additional_info = "Accountgebunden\nEinzigartig\nKlassen: Krieger , Paladin , Schurke , Schamane , Hexenmeister , Druide\n[q2]Prägt Euren Ring mit der Rune 'Verteidigungsspezialisierung':\n\n\nErhöht die Verteidigungsfertigkeit um 25. Nicht stapelbar mit anderen Ringrunen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
