[227444] = {name = "[q2]Götze der Jägerin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nKlassen: Druide\n[q2]Prägt Euren Umhang mit der Rune 'Verbesserter Prankenhieb':\n\n\nIn Katzengestalt wird Eure Fähigkeit 'Prankenhieb' zu 'Prankenhieb (Katze)', in Bärengestalt trifft Eure Fähigkeit 'Prankenhieb' bis zu 7 zusätzliche Gegner.\n\n Prankenhieb (Katze)\n\nSchlägt Gegner in der Nähe, verursacht 250% Waffenschaden und generiert 1 Combopunkt auf Eurem aktiven Ziel.\n[q]\"Tötet 5 schlafende Ziele, während Ihr Euch in der Katzengestalt befindet. Verwendet anschließend diesen Götzen, um eine neue Fertigkeit zu erlernen.\""},
[227451] = {name = "Sendesiegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Die Symbole \" > v ^ < \" Â sind entlang des Randes eingraviert.\""},
[227454] = {name = "[q4]Gezeitenschleife", additional_info = "Wird beim Aufheben gebunden\nFinger\n+8 Ausdauer\n+20 Feuerwiderstand\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 13."},
[227455] = {name = "[q4]Meeresbrise", additional_info = "Wird beim Aufheben gebunden\nFinger\n+8 Ausdauer\n+20 Feuerwiderstand\n[q2]Anlegen: +22 Angriffskraft."},
[227456] = {name = "[q2]Rune des blutroten Sturms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Prägt Euren Umhang mit der Rune 'Blutroter Sturm':\n\n\nEin Finishing-Move, der alle Gegner innerhalb von 8 Metern aufschlitzt und Opfer regelmäßig bluten lässt. Erhöht pro Combopunkt die Dauer und den verursachten Schaden.\n\n 1 Punkt: (Angriffskraft * 0.30) Schaden im Verlauf von 4 Sek.\n 2 Punkte: (Angriffskraft * 0.45) Schaden im Verlauf von 6 Sek.\n 3 Punkte: (Angriffskraft * 0.60) Schaden im Verlauf von 8 Sek.\n 4 Punkte: (Angriffskraft * 0.75) Schaden im Verlauf von 10 Sek.\n 5 Punkte: (Angriffskraft * 0.90) Schaden im Verlauf von 12 Sek.\n\n 'Blutroter Sturm' profitiert von allen Talenten und Effekten die 'Blutung' beeinflussen oder dadurch ausgelöst werden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
