[227683] = {name = "[q5]Sulfuras, Hand von Ragnaros", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Streitkolben}\n{229 - 382 Schaden} {Tempo 3.80}\n(80.39 Schaden pro Sekunde)\n+12 Stärke\n+12 Ausdauer\n+32 Feuerwiderstand\nHaltbarkeit 145 / 145\nBenötigt Stufe 60\n[q2]Anlegen: +358 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n{[q2]Trefferchance: Schleudert einen brennenden Ball, der 273 bis 333 Feuerschaden} verursacht und die Seele des Ziels reinigt, was dessen erlittenen Feuer- und {Heiligschaden um bis zu 30 erhöht und zusätzlich 75 Schaden über 10 Sek. verursacht.}\n[q2]Anlegen: Chance von 20%, an allen nahen Gegnern 25 Feuerschaden zu verursachen, wenn Ihr von einem Nahkampfangriff getroffen werdet. (Procchance: 20%)"},
[227684] = {name = "[q4]Sulfuronhammer", additional_info = "Wird beim Anlegen gebunden\n{Zweihändig} {Streitkolben}\n{181 - 303 Schaden} {Tempo 3.80}\n(63.68 Schaden pro Sekunde)\n+10 Stärke\n+10 Ausdauer\n+30 Feuerwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Trefferchance: Schleudert eine glühende Kugel hinaus, die 83 bis 101 Punkt(e) Feuerschaden sowie zusätzlich 8 Sek. lang 16 Punkt(e) Schaden verursacht.\n[q2]Anlegen: Fügt jedem Feind 5 Punkt(e) Feuerschaden zu, der Euch mit einem Nahkampfangriff schlägt.\n[q2]Anlegen: +124 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
[227685] = {name = "Modifiziertes Schattenskalpell", additional_info = "Questgegenstand\n[q2]Benutzen: Fokussiert das modifizierte Schattenskalpell auf Arkonos den Verfluchten, um seine schützende Barriere aufzulösen.\n[q]\"Cuthbert hat Daltons letzten Segen auf dieses Instrument übertragen. Hoffentlich gelingt es so, die Barriere einzureißen, die Arkonos schützt.\""},
[227686] = {name = "Verzierter Kriegshammer", additional_info = "Questgegenstand\nEinzigartig"},
[227687] = {name = "[q2]Orthas Lieblingsgoldzahn", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ihr könnt Orthas Zahn... reiben. Eklig. (2 Min Abklingzeit)\n[q]\"Riecht fürchterlich.\""},
[227688] = {name = "Blutschrei", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Axt}"},
[227689] = {name = "Halbverdaute Plattenrüstung", additional_info = "Questgegenstand\nEinzigartig"},
[227690] = {name = "Nekrotischer Runenstein", additional_info = "Questgegenstand\n[q]\"Euch wird speiübel, als Euer nacktes Fleisch mit diesem Runenstein in Kontakt kommt.\""},
[227691] = {name = "[q4]Klinge von Hanna", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n{101 - 152 Schaden} {Tempo 2.10}\n(60.24 Schaden pro Sekunde)\n+11 Stärke\n+11 Beweglichkeit\n+11 Ausdauer\n+11 Intelligenz\n+11 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 59"},
[227724] = {name = "[q0]Blutbeschmierte Belobigung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 30\n[q]\"Einst mag es sich hierbei um eine Auszeichnung gehandelt haben, die für Heldentaten im Kampf verliehen wurde. Auch wenn sie mittlerweile Flecken aufweist und stark mit getrocknetem und verkrustetem Blut überzogen ist, hallt darin vielleicht nach wie vor das leise Echo des Stolzes und der Ehre ihres längst verstorbenen Besitzers wider.\""},
[227727] = {name = "[q4]Pläne: Sulfuronhammer", additional_info = "Einzigartig\nBenötigt Schmiedekunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Sulfuronhammers.\n[q4]Sulfuronhammer\nWird beim Anlegen gebunden\n{Zweihändig} {Streitkolben}\n{181 - 303 Schaden} {Tempo 3.80}\n(63.68 Schaden pro Sekunde)\n+10 Stärke\n+10 Ausdauer\n+30 Feuerwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Trefferchance: Schleudert eine glühende Kugel hinaus, die 83 bis 101 Punkt(e) Feuerschaden sowie zusätzlich 8 Sek. lang 16 Punkt(e) Schaden verursacht.\n[q2]Anlegen: Fügt jedem Feind 5 Punkt(e) Feuerschaden zu, der Euch mit einem Nahkampfangriff schlägt.\n[q2]Anlegen: +124 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenötigt Sulfuronblock (8), Dunkeleisenbarren (20), Arkanitbarren (50), Essenz des Feuers (25), Blut des Berges (10), Lavakern (10), Feuerkern (10)"},
[227728] = {name = "[q5]Auge von Sulfuras", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Das Auge von Sulfuras kann mit dem Sulfuronhammer kombiniert werden, um Sulfuras zu erschaffen, den legendären Hammer von Ragnaros."},
[227730] = {name = "[q4]Vertrag der Thoriumbruderschaft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Gebunden in Dunkeleisendraht\""},
[227743] = {name = "Obsidiankraftquelle", additional_info = "Questgegenstand"},
[227745] = {name = "Familienerbstück", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[227746] = {name = "[q2]Rune des Weltenbaums", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euren Umhang mit der Rune 'Baum des Lebens':\n\n\nVerwandelt Euch in die Gestalt eines Baums des Lebens. In dieser Gestalt erhöht Ihr die erhaltene Heilung aller Gruppenmitglieder innerhalb von 45 Metern um 10%, 'Wildwuchs'-Heilung ist um 60% erhöht, Eure regelmäßigen Heilzauber kosten 20% weniger, Eure Willenskraft wird um 25% und Eure Rüstung um 200% erhöht. Ihr könnt keine schädlichen Zauber wirken.\n\n Der Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[227747] = {name = "Familienchronik", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[227748] = {name = "Tagebuch des Überlebenden", additional_info = "Questgegenstand\nEinzigartig\n[q2]<Zum Lesen rechtsklicken>"},
[227749] = {name = "[q2]Rune der Sternschnuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Prägt Euren Umhang mit der Rune\n 'Sternenregen':\n\n\nIhr beschwört einen Sternenschauer vom Himmel, der 10 Sek. lang anhält und auf Ziele innerhalb von 30 Metern um Eure Position herniedergeht. Jeder Stern fügt seinem Ziel [46 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] bis [54 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Arkanschaden sowie allen anderen Gegnern innerhalb von 5 Metern [8 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Arkanschaden zu. Es werden maximal 20 Sterne beschworen.\n\n Gestaltwandel oder Aufsitzen brechen den Effekt ab. Jedweder Effekt, der Euch die Kontrolle über Euren Charakter verlieren lässt, führt zum Abbruch von 'Sternenregen'.\n\n Profitiert von den meisten Talenten und Effekten und löst diese aus, die auch 'Mondfeuer' auslösen oder davon profitieren.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
