[228120] = {name = "[q3]Muster: Teufelskerngamaschen", additional_info = "Benötigt Lederverarbeitung (300)\nBenötigtStammeslederverarbeitung\n[q2]Benutzen: Lehrt Euch, wie man Teufelskerngamaschen herstellt.\n[q4]Teufelskerngamaschen\nWird beim Anlegen gebunden\n{Beine} {Leder}\n173 Rüstung\n+14 Ausdauer\n+20 Feuerwiderstand\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: +58 Angriffskraft.\n\n[q]Teufelsaurierrüstung (0/2)\n[q0]Teufelskernstulpen\nTeufelskerngamaschen\nBenötigt Unverwüstliches Leder (30), Teufelssaurierleder (20), Geschmeidiger unverwüstlicher Balg , Runenfaden , Essenz des Feuers (10)"},
[228121] = {name = "[q2]Muster: Lederverstärkte Runenstofftasche", additional_info = "Benötigt Schneiderei (300)\n[q2]Benutzen: Lehrt Euch, wie man eine lederverstärkte Runenstofftasche herstellt.\n\n\n[q3]Lederverstärkte Runenstofftasche\n18 Platz Behälter\nBenötigt Runenstoffballen (5), Unverwüstliches Leder (2), Runenfaden , Geschmeidiger unverwüstlicher Balg"},
[228122] = {name = "[q4]Der Geschmolzene Kern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+20 Feuerwiderstand\nBenötigt Stufe 60\n[q2]Anlegen: Euer Tod destabilisiert den Geschmolzenen Kern, wodurch dieser ausbricht und Gegnern in der Nähe 1 bis 2000 Feuerschaden zufügt."},
[228123] = {name = "[q2]Frohlockende Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Umhang mit der Rune 'Verbindende Heilung':\n\n\nHeilt ein verbündetes Ziel und den Zaubernden um [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 161 / 100] bis [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 197 / 100] Gesundheit. Niedrige Bedrohung. Dieser Zauber profitiert von allen Effekten, die mit 'Blitzheilung' verbunden sind, und löst diese aus.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[228124] = {name = "[q2]Traumartige Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Umhang mit der Rune 'Seelenwehr':\n\n\nEuer 'Machtwort: Schild' hat keine Abklingzeit mehr, kostet 15% weniger Mana, gewährt 10% zusätzlichen Basiswert und erhöht Eure Heilkraft um 10%.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[228125] = {name = "[q4]Veredelter Arkanitchampion", additional_info = "Wird beim Anlegen gebunden\n{Zweihändig} {Schwert}\n{107 - 161 Schaden} {Tempo 2.00}\n(67.00 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 60\n[q2]Trefferchance: Sich selbst um 270 bis 450 heilen und Stärke 30 Sek. lang um 120 Punkt(e) erhöhen.\n[q2]Trefferchance: Erhöht den verursachten Schaden um 20 und das Angriffstempo um 5%. Hält 15 Sek. lang an."},
[228126] = {name = "[q2]Eröffnende Offenbarung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Euren Umhang mit der Rune 'Vampirberührung':\n\n\nBelegt Euer Ziel mit Eurer 'Vampirumarmung'. Fügt dem Ziel im Verlauf von 15 Sek. [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] Schattenschaden zu und gewährt allen Gruppenmitgliedern Mana in Höhe von 2% des Schattenzauberschadens, den Ihr dem Ziel zufügt.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[228127] = {name = "[q4]Handgelenksschützer der Instabilität", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Platte}\n328 Rüstung\n+27 Stärke\nHaltbarkeit 40 / 40\nBenötigt Stufe 60"},
