[228955] = {name = "[q4]Zauberfoliant des uralten Grundsteins", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 29.\n[q2]Benutzen: Beschwört ein Skelett, das Euch 1 Min. lang beschützt. (5 Min Abklingzeit)"},
[228978] = {name = "[q3]Verzaubertes Siegel: Fließendes Wasser", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 60\nBenötigt Verzauberkunst (290)\n[q2]Benutzen: Erhaltet ein verzaubertes Siegel des fließenden Wassers, das Euren Schlachtzug ermächtigt, wodurch 1 Stunde lang der verursachte Schaden und die hervorgerufene Heilung mit Zaubern um bis zu 30 und die Angriffskraft um 30 erhöht wird. (1 Min Abklingzeit)"},
[228979] = {name = "[q3]Verzaubertes Siegel: Fließendes Wasser", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (290)\nBenötigtHydraxianer\n- Respektvoll\n[q2]Benutzen: Lehrt Euch, wie man ein Siegel des fließenden Wassers beschwört.\n[q3]Verzaubertes Siegel: Fließendes Wasser\nWird beim Aufheben gebunden\nBenötigt Stufe 60\nBenötigt Verzauberkunst (290)\n[q2]Benutzen: Erhaltet ein verzaubertes Siegel des fließenden Wassers, das Euren Schlachtzug ermächtigt, wodurch 1 Stunde lang der verursachte Schaden und die hervorgerufene Heilung mit Zaubern um bis zu 30 und die Angriffskraft um 30 erhöht wird. (1 Min Abklingzeit)\nBenötigt Illusionsstaub"},
[228980] = {name = "Leitende Schildbeschichtung", additional_info = "Benötigt Stufe 40\n[q2]Benutzen: Während die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 24 erhöht. Hält 30 Min. lang an.\n5 Aufladungen"},
[228981] = {name = "Formel: Leitende Schildbeschichtung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (275)\n[q2]Benutzen: Lehrt Euch, wie man eine leitende Schildbeschichtung herstellt.\nLeitende Schildbeschichtung\nBenötigt Stufe 40\n[q2]Benutzen: Während die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 24 erhöht. Hält 30 Min. lang an.\n5 Aufladungen\nBenötigt Illusionsstaub (2), Feuerblüte , Kristallphiole"},
[228982] = {name = "[q3]Formel: Schild - Naturgesetz", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenötigtHolzschlundfeste\n- Respektvoll\n[q2]Benutzen: Lehrt Euch, wie man einen Schild dauerhaft so verzaubert, dass Schadenszauber bis zu 30 mehr Schaden verursachen und Heilzauber bis zu 55 mehr Gesundheit heilen."},
[228992] = {name = "[q2]Rucksack aus Onyxias Haut", additional_info = "Wird beim Aufheben gebunden\n20 Platz Behälter"},
[228993] = {name = "[q3]Muster: Bodenlose Tasche", additional_info = "Benötigt Schneiderei (300)\n[q2]Benutzen: Lehrt Euch, wie man eine bodenlose Tasche näht.\n[q3]Bodenlose Tasche\nWird beim Anlegen gebunden\n20 Platz Behälter\nBenötigt Runenstoffballen (8), Mondstoff (12), Großer glänzender Splitter (2), Kernleder (2), Runenfaden (2)"},
[228994] = {name = "[q3]Bodenlose Tasche", additional_info = "Wird beim Anlegen gebunden\n20 Platz Behälter"},
[229008] = {name = "Formel: Umhang - Großer Feuerwiderstand", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenötigtThoriumbruderschaft\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch, wie man einen Umhang dauerhaft so verzaubert, dass er den Feuerwiderstand um 15 erhöht."},
[229009] = {name = "Formel: Umhang - Großer Naturwiderstand", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenötigtThoriumbruderschaft\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch, wie man einen Umhang dauerhaft so verzaubert, dass er den Naturwiderstand um 15 erhöht."},
