[229372] = {name = "[q4]Räuderipper", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\n{Einhändig} {Dolch}\n{66 - 123 Schaden} {Tempo 1.80}\n(52.50 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Trefferchance: Schleudert einen Schattenblitz auf den Gegner, verursacht 150 Schattenschaden und verringert 30 Sek. lang alle Werte um 25."},
[229373] = {name = "[q4]Glaubensbringer", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{202 - 303 Schaden} {Tempo 3.70}\n(68.24 Schaden pro Sekunde)\n+17 Stärke\n+14 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 44."},
[229374] = {name = "[q4]Fäuste der Feueranbeter", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\n{Einhändig} {Streitkolben}\n{59 - 110 Schaden} {Tempo 1.70}\n(49.71 Schaden pro Sekunde)\n+10 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 2%.\n[q2]Trefferchance: Überzieht den Gegner mit 70 Feuerschaden."},
[229376] = {name = "[q4]Zauberdolch", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Dolch}\n{36 - 78 Schaden} {Tempo 1.40}\n(40.71 Schaden pro Sekunde)\n60 Rüstung\n+8 Ausdauer\n+16 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 36."},
[229377] = {name = "[q4]Magmadars linke Klaue", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Schildhand} {Faustwaffe}\n{92 - 171 Schaden} {Tempo 2.50}\n(52.60 Schaden pro Sekunde)\n+11 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n\n[q]Ruf des Kernhunds (0/3)\n[q0]Magmadars rechte Klaue\nMagmadars linke Klaue\nMagmadars Horn\n[q0](2) Set : Bei Nahkampftreffern besteht eine geringe Chance, einen Kernhund herbeizurufen, der 1 Min. lang bestehen bleibt. (Procchance: 1%, 1Min. Abklingzeit)\n(3) Set : Bei Nahkampftreffern besteht eine geringe Chance, den Geist Magmadars herbeizurufen, der Euch im Kampf unterstützt. Erhöht Euer Angriffstempo für 20 Sek. um 10%. (Procchance: 1%, 1Min. Abklingzeit)"},
[229378] = {name = "[q4]Magmadars rechte Klaue", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Faustwaffe}\n{92 - 171 Schaden} {Tempo 2.50}\n(52.60 Schaden pro Sekunde)\n+12 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: +20 Angriffskraft.\n\n[q]Ruf des Kernhunds (0/3)\n[q0]Magmadars rechte Klaue\nMagmadars linke Klaue\nMagmadars Horn\n[q0](2) Set : Bei Nahkampftreffern besteht eine geringe Chance, einen Kernhund herbeizurufen, der 1 Min. lang bestehen bleibt. (Procchance: 1%, 1Min. Abklingzeit)\n(3) Set : Bei Nahkampftreffern besteht eine geringe Chance, den Geist Magmadars herbeizurufen, der Euch im Kampf unterstützt. Erhöht Euer Angriffstempo für 20 Sek. um 10%. (Procchance: 1%, 1Min. Abklingzeit)"},
[229379] = {name = "[q4]Eskhandars rechte Klaue", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Faustwaffe}\n{87 - 163 Schaden} {Tempo 2.60}\n(48.08 Schaden pro Sekunde)\n+7 Beweglichkeit\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Trefferchance: Erhöht Euer Angriffstempo 5 Sek. lang um 25%.\n\n[q]Seele des Eskhandar (0/4)\n[q0]Eskhandars rechte Klaue\nEskhandars linke Klaue\nEskhandars Pelz\nEskhandars Halsband\n[q0](2) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n(3) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(4) Set : 1% Chance bei einem Nahkampftreffer den Geist von Eskhandar herbeizurufen, der Euch 2 Min. lang im Kampf unterstützt. (Procchance: 1%, 1Min. Abklingzeit)"},
[229380] = {name = "[q4]Schattenschlag", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{186 - 279 Schaden} {Tempo 3.40}\n(68.38 Schaden pro Sekunde)\n+33 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 58\n[q2]Trefferchance: Stiehlt dem gegnerischen Ziel 180 bis 220 Leben.\n[q2]Anlegen: +189 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Benutzen: Transformiert 'Schattenschlag' zu 'Donnerschlag'. (1 Min Abklingzeit)"},
[229381] = {name = "[q4]Donnerschlag", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{186 - 279 Schaden} {Tempo 3.40}\n(68.38 Schaden pro Sekunde)\n+13 Beweglichkeit\n+33 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 58\n[q2]Trefferchance: Überzieht bis zu 3 Ziele mit 200 bis 300 Naturschaden. Der angerichtete Schaden verringert sich jedoch von Ziel zu Ziel.\n[q2]Anlegen: +189 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Benutzen: Transformiert 'Donnerschlag' zu 'Schattenschlag'. (1 Min Abklingzeit)"},
[229382] = {name = "[q4]Überwärmter Isolierlavagreifer", additional_info = "Geschmolzen\nWird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{140 - 227 Schaden} {Tempo 3.20}\n(57.34 Schaden pro Sekunde)\n+25 Ausdauer\n+24 Intelligenz\n+15 Feuerwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 84.\n[q2]Anlegen: Stellt alle 5 Sek. 9 Punkt(e) Mana wieder her.\n[q]\"Eigentum von Pip Quickwit, Großmeister Abenteurer\""},
[229415] = {name = "Überlebensvorräte", additional_info = "Questgegenstand\n[q2]Benutzen: Legt ein Fundament für einen Überlebenslagerplatz. Bringt weitere Vorräte an diesen Lagerplatz, um einen Unterstand zu bauen. (5 Min Abklingzeit)"},
[229416] = {name = "Warmes Fell", additional_info = "Questgegenstand"},
[229749] = {name = "[q4]Wahrheitsbringer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blazefury] (1)\n{Zweihändig} {Schwert}\n{132 - 199 Schaden} {Tempo 2.10}\n(78.81 Schaden pro Sekunde)\n+30 Stärke\n+21 Beweglichkeit\n+16 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Fügt Euren Nahkampfangriffen 4 Heiligschaden hinzu.\n[q2]Trefferchance: Erhöht den verursachten Schaden um 15 und das Angriffstempo um 30%. Hält 8 Sek. lang an.\n[q2]Benutzen: Ändert Eure Kampfhaltung, um 'Wahrheitsbringer' als Anderthalbhänder zu führen, damit Ihr ihn zusammen mit einem Schild einsetzen könnt. (1 Min Abklingzeit)"},
[229806] = {name = "[q4]Wahrheitsbringer", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Schwert}\n{63 - 118 Schaden} {Tempo 1.50}\n(60.33 Schaden pro Sekunde)\n+14 Ausdauer\n+12 Intelligenz\nHaltbarkeit 105 / 105\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 144 und den verursachten Schaden um bis zu 77.\n[q2]Trefferchance: Erhöht den verursachten Schaden um 15 und das Angriffstempo um 30%. Hält 8 Sek. lang an.\n[q2]Benutzen: Ändert Eure Kampfhaltung, um 'Wahrheitsbringer' als Zweihandschwert zu führen. (1 Min Abklingzeit)"},
[229894] = {name = "[q2]Traumsmaragd", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht dauerhaft Euren Ruf beim Zirkel des Cenarius."},
[229897] = {name = "Rolle: Siegel der Anrufung herstellen", additional_info = "Wird beim Aufheben gebunden\nBenötigtZirkel des Cenarius\n- Freundlich\n[q2]Benutzen: Mit 1 Dunkelrune und 5 Feuerblüten kombinieren, um ein Siegel der Anrufung: Feuer herzustellen."},
[229906] = {name = "[q4]Trübe Bronzeschuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\n[q2]Anlegen: Gewährt eine Chance, seltsame oder übersehene Gegenstände zu bemerken, die von mächtigen Gegnern fallen gelassen wurden.\n[q2]Benutzen: Reist an einen Ort außerhalb der Zeit. Ihr müsst Euch dafür in Tanaris befinden. (5 Min Abklingzeit)"},
[229909] = {name = "[q4]Stab der Ordnung", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{140 - 241 Schaden} {Tempo 3.20}\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Magier\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\n[q2]Anlegen: Immer, wenn Ihr einem Ziel Arkanschaden zufügt, wird die verbleibende Abklingzeit von 'Geistesgegenwart' um 1 Sek. verringert.\n[q2]Benutzen: Stimmt Euren Stab auf Feuermagie ab. (1 Min Abklingzeit)"},
[229910] = {name = "[q4]Sense des Chaos", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{140 - 241 Schaden} {Tempo 3.20}\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Hexenmeister\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 2%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\n[q2]Anlegen: Chance bei direkten Schadenszaubern, Eure nächste Beschwörung eines Begleiters innerhalb von 20 Sek. zu einem Spontanzauber zu machen und keinen Seelensplitter zu kosten. (Procchance: 10%, 1Min. Abklingzeit)\n[q2]Benutzen: Erntet die Seele des von Euch beschworenen Dämons, wodurch Euch ein Effekt gewährt wird, der 15 Sek. lang anhält. Der Effekt wird abgebrochen, wenn ein Dämon beschworen wird. (1 Min Abklingzeit)"},
[229911] = {name = "Caius' Traumfresser", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[229964] = {name = "[q4]Huf eines Dämonenlords", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60"},
[229965] = {name = "[q3]Das Auge von Az'olgothal", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Die letzte nachhallende Kugel gärt vor Teufelsenergie. Es ist, als wüsste sie, dass Ihr sie zerstören wollt, und verströmt im Gegenzug verächtlichen Hass gegen Euch.\""},
[229966] = {name = "[q4]Halsreif der Silbernen Hand", additional_info = "Wird beim Aufheben gebunden\nHals\n+10 Stärke\n+5 Ausdauer\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%."},
[229971] = {name = "[q4]Stab des Infernos", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{140 - 241 Schaden} {Tempo 3.20}\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Magier\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\n[q2]Anlegen: Wenn 'Verbessertes Versengen' als Talent ausgewählt ist, werden Ziele, die von Eurer 'Druckwelle' getroffen werden, zusätzlich mit 5 Stapeln von 'Feuerverwundbarkeit' belegt.\n[q2]Benutzen: Stimmt Euren Stab auf Frostmagie ab. (1 Min Abklingzeit)"},
[229972] = {name = "[q4]Stab des Raureifs", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{140 - 241 Schaden} {Tempo 3.20}\n(59.53 Schaden pro Sekunde)\n+22 Ausdauer\n+26 Intelligenz\n+17 Willenskraft\nHaltbarkeit 120 / 120\nKlassen: Magier\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 77.\n[q2]Anlegen: Erhöht den von Frostzaubern und -effekten verursachten Schaden um bis zu 100, während 'Eisbarriere' aktiv ist.\n[q2]Benutzen: Stimmt Euren Stab auf Arkanmagie ab. (1 Min Abklingzeit)"},
[230002] = {name = "[q4]Tödlicher Vollender", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Einhändig} {Axt}\n{123 - 229 Schaden} {Tempo 2.90}\n(60.69 Schaden pro Sekunde)\n+13 Beweglichkeit\n+18 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Trefferchance: Schleudert einen Gegner mit einem schnellen Aufwärtshaken in die Luft."},
[230003] = {name = "[q5]Hammer des Lichtbringers", additional_info = "Der Brand von Andorhal\nWird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{310 - 466 Schaden} {Tempo 4.00}\n(97.00 Schaden pro Sekunde)\n+14 Stärke\n+20 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Trefferchance: Erhöht den verursachten Schaden um 15 und das Angriffstempo um 30%. Hält 8 Sek. lang an.\n[q2]Anlegen: Fügt Euren Nahkampfangriffen 4 Heiligschaden hinzu.\n[q2]Benutzen: Ändert Eure Kampfhaltung, um 'Wahrheitsbringer' als Anderthalbhänder zu führen, damit Ihr ihn zusammen mit einem Schild einsetzen könnt. (1 Min Abklingzeit)\n[q]\"Diese Waffe zu halten, fühlt sich für Euch irgendwie falsch an. Sie sollte hier verbleiben, wo sie ihrem Besitzer aus der Hand glitt, als der seinen letzten Atemzug tat.\""},
[230018] = {name = "Kugelfragmente der Mannoroc", additional_info = "Questgegenstand\nEinzigartig"},
[230224] = {name = "[q5]Donnerzorn, gesegnete Klinge des Windsuchers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Einhändig} {Schwert}\n{82 - 153 Schaden} {Tempo 1.90}\n(61.84 Schaden pro Sekunde)\n+5 Beweglichkeit\n+8 Ausdauer\n+8 Feuerwiderstand\n+9 Naturwiderstand\nHaltbarkeit 125 / 125\nBenötigt Stufe 60\n[q2]Trefferchance: Deckt Euren Gegner mit Blitzschlägen ein, die 300 Naturschaden verursachen und auf Gegner in der Nähe überspringen. Jeder Sprung verringert den Naturwiderstand des Ziels um 25. Wirkt auf insgesamt 5 Ziele. Euer Hauptziel wird außerdem von einem Wirbelsturm umgeben, welcher dessen Angriffstempo 12 Sek. lang um 20% verringert."},
[230237] = {name = "[q4]Edelstein der arkanen Kraft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Jäger\nBenötigt Stufe 60\n[q2]Benutzen: Erfüllt Euch mit arkaner Energie, wodurch Eure Einsätze von 'Zerlegen' und 'Mehrfachschuss' in den nächsten 15 Sek. bis zu 5 Detonationen pro Einsatz erzeugen. 'Arkane Detonation' fügt Gegnern in der Nähe des Ziels 185 bis 215 Schaden zu. (1 Min, 30 Sek. Abklingzeit)"},
