[231280] = {name = "[q0]Wushoolays Amulett der Natur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Druide\nBenötigt Stufe 60\n[q2]Benutzen: Bringt den Druiden in Einklang mit der Natur. Erhöht 20 Sek. lang den verursachten Schaden durch Zauber um 10%, verbessert Heileffekte um 10% und erhöht die kritische Trefferchance von Zaubern um 10%. (2 Min Abklingzeit)\n\n[q]Gewand des Haruspex (0/5)\n[q0]Haruspex' Zandalariarmschienen\nHaruspex' Zandalarigürtel\nHaruspex' Zandalaritunika\nReiner verzauberter Südmeertang\nWushoolays Amulett der Natur\n[q0](2) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 12.\n(3) Set : Verringert die Zauberzeit und globale Abklingzeit von 'Sternenfeuer' um 0.5 Sek.\n(5) Set : Erhöht die kritische Trefferchance von 'Zorn' um 10%."},
[231281] = {name = "[q0]Wushoolays Amulett der Geister", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Schamane\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht den Schaden Eures Zaubers 'Blitzschlagschild' um 100%. Hält 20 Sek. lang an. (2 Min Abklingzeit)\n\n[q]Ornat des Weissagers (0/5)\n[q0]Armschienen des Zandalariweissagers\nGürtel des Zandalariweissagers\nHalsberge des Zandalariweissagers\nUnversehrte Vision von Voodress\nWushoolays Amulett der Geister\n[q0](2) Set : Erhöhte Verteidigung +7.\n(3) Set : Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 10%.\n(5) Set : Erhöht die Chance, dass Eure Rune 'Kraftwoge' ausgelöst wird, um zusätzliche 5%."},
[231282] = {name = "[q0]Hazza'rahs Amulett der frostigen Magie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Magier\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht die kritische Trefferchance von 'Frostblitz', 'Zauberfrostblitz' und 'Gefrorene Kugel' um 5% und erhöht den kritischen Trefferschaden von 'Frostblitz', 'Zauberfrostblitz' und 'Gefrorene Kugel' um 50%. Hält 20 Sek. lang an. (2 Min Abklingzeit)\n\n[q]Roben des Illusionisten (0/5)\n[q0]Robe des Zandalari-Illusionisten\nMantel des Zandalari-Illusionisten\nHandlappen des Zandalari-Illusionisten\nJuwel von Kajaro\nHazza'rahs Amulett der frostigen Magie\n[q0](2) Set : Erhöht den von Frostzaubern und -effekten verursachten Schaden um bis zu 14.\n(3) Set : Erhöht die Chance, dass Eure Rune 'Eisige Finger' ausgelöst wird, um zusätzliche 15%.\n(5) Set : Erhöht den verursachten Schaden Eurer Zauber 'Frostblitz' und 'Zauberfrostblitz' um 75%."},
[231283] = {name = "[q0]Hazza'rahs Amulett des Schutzes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\n[q2]Benutzen: Verringert die Zauberzeit von 'Große Heilung' um 40%, verringert die Manakosten Eurer Heilzauber um 5% und 'Sühne' trifft bis zu 2 zusätzliche Ziele, wenn es auf Verbündete gewirkt wird. Hält 15 Sek. lang an. (1 Min, 30 Sek. Abklingzeit)\n\n[q]Gewandung des Glaubenshüters (0/5)\n[q0]Handlappen des Zandalariglaubenshüters\nBindungen des Zandalariglaubenshüters\nMantel des Zandalariglaubenshüters\nDas allsehende Auge von Zuldazar\nHazza'rahs Amulett des Schutzes\n[q0](2) Set : Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 22 und den verursachten Schaden um bis zu 7.\n(3) Set : Verringert die Abklingzeit Eures Zaubers 'Sühne' um 6 Sek.\n(5) Set : Erhöht den von Eurem Zauber 'Machtwort: Schild' absorbierten Schaden um 10%."},
[231284] = {name = "[q0]Hazza'rahs Amulett der Zerstörung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Hexenmeister\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht Eure kritische Trefferchance um 10% und die Angriffsgeschwindigkeit Eures Begleiters um 50%. Hält 20 Sek. lang an. Dieser Zauber wirkt sich nicht auf temporäre Begleiter oder unterworfene Dämonen aus. (2 Min Abklingzeit)\n\n[q]Roben des Besessenen (0/5)\n[q0]Mantel des Zandalaribesessenen\nRobe des besessenen Zandalari\nHandlappen des Zandalaribesessenen\nKezans unaufhaltsame Schmach\nHazza'rahs Amulett der Zerstörung\n[q0](2) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht die Angriffskraft und den Zauberschaden, den Euer Dämon durch Eure Attribute erlangt, um 20%.\n(5) Set : Erhöht die Vorteile Eures Talents 'Meister der Dämonologie' um 50%."},
[231285] = {name = "[q4]Gri'leks Amulett der Ehre", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht die kritische Trefferchance von Heiligzaubern 15 Sek. lang um 10%. Gewährt zusätzliche 5%, wenn 'Schockierende Ehrfurcht' eingraviert ist. (1 Min, 30 Sek. Abklingzeit)\n\n[q]Rüstung des Freidenkers (0/5)\n[q0]Brustplatte des Zandalarifreidenkers\nGürtel des Zandalarifreidenkers\nArmschützer des Zandalarifreidenkers\nGri'leks Amulett der Ehre\nEmblem des Helden\n[q0](2) Set : Erhöht den von Heiligzaubern und -effekten verursachten Schaden um bis zu 14.\n(3) Set : Erhöht den verursachten Schaden Eures Zaubers 'Heiliger Schock' um 50%.\n(5) Set : Verringert die Abklingzeit Eures Zaubers 'Exorzismus' um 3 Sek. und erhöht dessen verursachten Schaden um 75%."},
[231286] = {name = "[q0]Gri'leks Amulett der Macht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Krieger\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht Euren Schildblockwert 20 Sek. lang um 200 und Eure Wut sofort um 30. (2 Min Abklingzeit)\n\n[q]Schlachtrüstung des Vollstreckers (0/5)\n[q0]Brustplatte des Zandalarivollstreckers\nGürtel des Zandalarivollstreckers\nArmschützer des Zandalarivollstreckers\nWut Mugambas\nGri'leks Amulett der Macht\n[q0](2) Set : Erhöhte Verteidigung +7.\n(3) Set : Verringert die Abklingzeit Eurer Fähigkeit 'Schildschlag' um 2 Sek.\n(5) Set : Verringert die Abklingzeit Eurer Fähigkeit 'Blutrausch' um 30 Sek., während Ihr in Gladiatorhaltung seid."},
