[231384] = {name = "[q3]Furor des Falken", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenötigt Stufe 60\n[q2]Benutzen: Fügt einem Gegenstand, der sich an einem Bein- oder Kopfplatz befindet, dauerhaft 20 Ausdauer, 10 Beweglichkeit und 10 Stärke hinzu. Ergänzt sich nicht mit anderen Verzauberungen für den ausgewählten Ausrüstungsplatz."},
[231385] = {name = "[q4]Simulakrum der Drachenseele", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Krieger\nBenötigt Stufe 60\n[q2]Anlegen: Tragt das Mal eines drachischen Boten, eines Dragonflight-Verbündeten.\n[q]\"Das Simulakrum wurde verzaubert, um den Träger als Freund des roten Drachenschwarms auszuzeichnen.\""},
[231386] = {name = "[q3]Makellose schwarze Drachenschuppe", additional_info = "Questgegenstand\nEinzigartig\nKlassen: Krieger\nBenötigt Stufe 60\n[q]\"Die Schuppe ist riesig und makellos. Nur die majestätischsten Drachen tragen Schuppen solcher Güte.\""},
[231387] = {name = "[q4]Sturmzorn, geheiligte Kurzklinge des Windsuchers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Dolch}\n{45 - 113 Schaden} {Tempo 1.90}\n(41.58 Schaden pro Sekunde)\n+10 Ausdauer\n+9 Intelligenz\n+7 Willenskraft\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 68.\n[q2]Anlegen: Schaden verursachende Zauber, die keinen regelmäßigen Schaden verursachen, haben eine Chance, bis zu 3 Zielen 181 bis 229 Schaden zuzufügen. (Procchance: 10%, 100ms Abklingzeit)"},
[231452] = {name = "[q4]Blut des Lichtbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Paladin\nBenötigt Stufe 60\n[q]\"Dieses kleine Reliquiar ist mit einer Blutprobe gefüllt. Auf der Unterseite befindet sich ein teilweise abgerissenes Pergamentetikett mit der Aufschrift \"Uther\".\""},
[231460] = {name = "[q4]Ebenenbrecher von Azgaloth", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{146 - 270 Schaden} {Tempo 3.60}\n(57.78 Schaden pro Sekunde)\n+31 Ausdauer\n+32 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 90 und den verursachten Schaden um bis zu 30."},
[231466] = {name = "[q4]Kodex des Pechschwingenhexenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60"},
[231509] = {name = "[q4]Cassandras Foliant", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 47.\n[q2]Anlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 70.\n[q2]Benutzen: Lest eine Prophezeiung aus dem Folianten, was die kritische Trefferchance Eures nächsten Angriffs oder Zaubers, der keinen regelmäßigen Schaden verursacht, um 100% erhöht. (2 Min Abklingzeit)"},
[231512] = {name = "[q3]Urzeitlicher Hakkarigötze", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 58\n[q]\"Etwas uraltes Böses lauert in diesem Götzen...\""},
