[231778] = {name = "Bergquellwasser", additional_info = "Herbeigezauberter Gegenstand\nBenötigt Stufe 55\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. insgesamt 5100 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben."},
[231779] = {name = "[q4]Zorn des Wray", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+10 Naturwiderstand\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Benutzen: Erhöht Eure Stärke 20 Sek. lang um 92. (2 Min Abklingzeit)"},
[231780] = {name = "[q2]Foliant des Wasserherbeizauberns VIII", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigt Stufe 60\n[q2]Zaubert 20 Flaschen Bergquellwasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\n Herbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Min. ausloggt.\n[q]\"Lehrt Euch 'Wasser herbeizaubern' (Rang 8).\""},
