[231828] = {name = "[q2]Rune der Meditationsspezialisierung", additional_info = "Accountgebunden\nEinzigartig\nKlassen: Paladin , Jäger , Priester , Schamane , Magier , Hexenmeister , Druide\n[q2]Prägt Euren Ring mit der Rune 'Meditationsspezialisierung':\n\n\nStellt alle 5 Sek. 5 Mana wieder her. Dieser Effekt ist nicht stapelbar mit anderen Ringrunen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[231829] = {name = "[q2]Rune der Heilungsspezialisierung", additional_info = "Accountgebunden\nEinzigartig\nKlassen: Paladin , Priester , Schamane , Magier , Druide\n[q2]Prägt Euren Ring mit der Rune 'Heilungsspezialisierung':\n\n\nErhöht durch Zauber und Effekte verursachte Heilung um bis zu 26 Gesundheit. Dieser Effekt ist nicht stapelbar mit anderen Ringrunen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
