[231890] = {name = "[q4]Terrestris", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n2964 Rüstung\n55 Blocken\n+7 Ausdauer\n+8 Intelligenz\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 20.\n[q2]Anlegen: Beschworene Totems gewähren einen Segen ihres Elements.\n[q2]Benutzen: Kühlt die Flammen von Terrestris und härtet ihn für die Verteidigung. (1 Min Abklingzeit)"},
[231891] = {name = "[q2]Abhandlung über den Gerfalken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nBenötigt Stufe 60\n[q2]Der Jäger nimmt den Aspekt eines Gerfalken an, wodurch sich seine Nah- und Distanzkampfangriffskraft um einen Wert in Höhe seines höchsten Rangs von 'Aspekt des Falken' erhöht.\n\n Während 'Aspekt des Gerfalken' aktiv ist, kann das Talent 'Verbesserter Aspekt des Falken' nun von Nahkampfangriffen ausgelöst werden und diese stärken. Es kann immer nur jeweils ein Aspekt aktiv sein. (Procchance: 5%)\n[q]\"Lehrt Euch 'Aspekt des Gerfalken'.\""},
[231901] = {name = "[q4]Wahrheitsbringer", additional_info = "Questgegenstand\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60"},
[231902] = {name = "[q4]Adas Amulett", additional_info = "Wird beim Aufheben gebunden\nHals\n+21 Stärke\n+4 Ausdauer\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 7.\n[q]\"Scheint aus Gebetsperlen und einem stark verkratzten Medaillon der Silbernen Hand gefertigt worden zu sein.\""},
[231903] = {name = "Stofffetzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60\n[q]\"Ein kleiner Stofffetzen von der Tunika von Uther dem Lichtbringer, auf dem sich ein paar Blutflecken befinden.\""},
[231904] = {name = "Beflecktes Horn", additional_info = "Questgegenstand\nEinzigartig\nBenötigt Stufe 50\n[q2]Benutzen: Stoßt ins Horn, um Aeonas zu Euch zurückzurufen, solltet Ihr von ihm getrennt werden. Alle magischen Verkleidungen, die auf Euch aktiv sind, werden abgebrochen. (15 Sek. Abklingzeit)"},
[231909] = {name = "[q4]Kristallisiertes Sternenlicht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Bringt Euch in Einklang mit dem Himmel, wodurch Ihr Eure Mondkingestalt durch ein erhabeneres Aussehen ersetzen könnt."},
[231910] = {name = "[q3]Herz von Azgaloth", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 57\n[q2]Anlegen: Stellt alle 5 Sek. 36 Gesundheit wieder her.\n[q2]Anlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 35 und den verursachten Schaden um bis zu 12."},
[231911] = {name = "[q3]Siegel des Legionsgenerals", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+10 Ausdauer\n+5 Intelligenz\n+5 Willenskraft\nBenötigt Stufe 57\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 26 und den verursachten Schaden um bis zu 9."},
[231912] = {name = "[q4]Klinge der Grube", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Dolch}\n{48 - 100 Schaden} {Tempo 1.80}\n(41.11 Schaden pro Sekunde)\n+6 Ausdauer\n+6 Intelligenz\n+6 Willenskraft\nHaltbarkeit 90 / 90\nBenötigt Stufe 57\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 44 und den verursachten Schaden um bis zu 15.\n[q2]Anlegen: Stellt alle 5 Sek. 6 Punkt(e) Mana wieder her."},
[231913] = {name = "[q3]Auge des Beobachters", additional_info = "Wird beim Aufheben gebunden\nHals\n+8 Intelligenz\n+11 Willenskraft\nBenötigt Stufe 57\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 22 und den verursachten Schaden um bis zu 8."},
[231995] = {name = "[q4]Gehärtete Elementiumschlacke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n2964 Rüstung\nKlassen: Schamane\nBenötigt Stufe 60\n[q]\"Diese große flache Scheibe aus Elementiumschlacke surrt vor latenter Energie.\""},
[231996] = {name = "[q3]Überladener Gobmogrifizierer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Benutzen: Aktiviert dies im Pechschwingenhort auf dem Schwarzfels, um Euch als Techniker der Pechschwingen zu verkleiden. (5 Min Abklingzeit)"},
[232018] = {name = "[q5]Schlummernde vom Wind berührte Klinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60"},
