[232390] = {name = "[q4]Götze des himmlischen Fokus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den von 'Sternenregen' verursachten Schaden um 10%, verringert aber den Radius um 50%."},
[232391] = {name = "[q4]Götze des Katzenfokus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nBenötigt Stufe 60\n[q2]Anlegen: Eure Fähigkeit 'Wilder Biss' wandelt zusätzliche Energie nicht mehr in Schaden um, sondern erstattet bei einem Ausweichen, Fehlschlag oder Parieren 30 Energie."},
[232392] = {name = "[q4]Totem des unaufhörlichen Donners", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nBenötigt Stufe 60\n[q2]Anlegen: Wenn Ihr einen Schild tragt, erhöht sich die Häufigkeit, mit der Eure Nahkampfangriffe mit 'Waffe des Felsbeißers' die Rune 'Waffe des Mahlstroms' auslösen, um 100 + (5 * Combopunkte)%."},
[232409] = {name = "[q4]Totem der Elemente", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nBenötigt Stufe 60\n[q2]Anlegen: Euer Talent 'Elementarfokus' hat jetzt maximal 2 Aufladungen und wird bei seiner Auslösung auf 2 Aufladungen gesetzt."},
[232414] = {name = "[q4]Drachenhauerklinge", additional_info = "Questgegenstand\nEinzigartig\nKlassen: Krieger\nBenötigt Stufe 60\n[q2]Benutzen: Schneidet eine Schuppe aus Nefarians Haut. Kann nur eingesetzt werden, wenn Nefarian im Kampf beträchtlich geschwächt wurde. (10 Sek. Abklingzeit)"},
[232416] = {name = "[q4]Totem des Astralflusses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Angriffskraftbonus von Attacken der Waffe des Windzorns um 68."},
[232419] = {name = "[q4]Totem der leitenden Ströme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Totem}\nBenötigt Stufe 60\n[q2]Anlegen: Während 'Frostbrandwaffe' auf Eurer Waffenhandwaffe aktiv ist, verkürzt das Auslösen von 'Wasserschild' die Zauberzeit Eures nächsten Zaubers 'Kettenblitzschlag', der innerhalb von 15 Sek. gewirkt wird, um 20% und erhöht seinen Schaden um 20%. Bis zu 5-mal stapelbar."},
[232420] = {name = "[q4]Buchband des Zorns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nBenötigt Stufe 60\n[q2]Anlegen: Wenn Ihr mit Eurem Zauber 'Heiliger Schock' Schaden verursacht, werden die Zauberzeit und die Manakosten Eures nächsten Einsatzes von 'Heiliger Zorn', der innerhalb von 15 Sek. gewirkt wird, um 20% verringert und dessen Schaden um 20% erhöht. Bis zu 5-mal stapelbar."},
[232421] = {name = "[q4]Buchband des Rächens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Buchband}\nBenötigt Stufe 60\n[q2]Anlegen: Euer 'Schild des Rächers' trifft 2 Ziele weniger, trifft sein Ziel allerdings 2-mal."},
[232423] = {name = "[q4]Götze der Pflege", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch 'Pflege' verursachte Heilung um bis zu 77."},
[232424] = {name = "[q4]Götze der Grausamkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Relikt} {Götze}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den von 'Aufschlitzen' zugefügten Anfangsschaden und regelmäßigen Schaden um 7 pro Anwendung."},
[232433] = {name = "Dichter Runenstoffverband", additional_info = "Benötigt Stufe 50\nBenötigt Erste Hilfe (300)\n[q2]Benutzen: Heilt 8 Sek. lang 3400 Schaden."},
[232434] = {name = "Handbuch: Dichter Runenstoffverband", additional_info = "Benötigt Erste Hilfe (300)\n[q2]Benutzen: Lehrt Euch, wie man einen dichten Runenstoffverband herstellt.\nDichter Runenstoffverband\nBenötigt Stufe 50\nBenötigt Erste Hilfe (300)\n[q2]Benutzen: Heilt 8 Sek. lang 3400 Schaden.\nBenötigt Schwerer Runenstoffverband (2)"},
[232436] = {name = "Dunkelklauensuppe", additional_info = "Benötigt Stufe 45\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. insgesamt 2148 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, wird Euer Zauberschaden 10 Min. lang um 12 erhöht."},
[232437] = {name = "Rezept: Dunkelklauensuppe", additional_info = "Benötigt Kochkunst (300)\n[q2]Benutzen: Lehrt Euch, wie man ein Dunkelklauensuppe zubereitet.\nDunkelklauensuppe\nBenötigt Stufe 45\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. insgesamt 2148 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, wird Euer Zauberschaden 10 Min. lang um 12 erhöht.\nBenötigt Dunkelklauenhummer , Trinkbares Weihwasser von Stratholme"},
[232438] = {name = "Geräucherte Rotkieme", additional_info = "Benötigt Stufe 35\n[q2]Benutzen: Stellt im Verlauf von 30 Sek.1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr 10 Sekunden lang esst, wird außerdem die von Euch verursachte Heilung 10 Min. lang um 22 erhöht."},
[232443] = {name = "Rezept: Geräucherte Rotkieme", additional_info = "Benötigt Kochkunst (300)\n[q2]Benutzen: Lehrt Euch, wie man eine geräucherte Rotkieme zubereitet.\nGeräucherte Rotkieme\nBenötigt Stufe 35\n[q2]Benutzen: Stellt im Verlauf von 30 Sek.1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr 10 Sekunden lang esst, wird außerdem die von Euch verursachte Heilung 10 Min. lang um 22 erhöht.\nBenötigt Roher Rotkiemen"},
[232454] = {name = "[q7]Emblem der wilden Götter", additional_info = "Accountgebunden\n[q]\"Beweis für die Unterstützung der Abgesandten des Schattenzahns. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\""},
[232455] = {name = "[q7]Emblem der Ehrlosigkeit", additional_info = "Accountgebunden\n[q]\"Beweis für die Konfrontation mit Illari Dämmerfeder. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\""},
[232456] = {name = "[q7]Emblem des Violetten Auges", additional_info = "Accountgebunden\n[q]\"Beweis für den Sieg über die Dunklen Reiter. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\""},
[232457] = {name = "[q7]Emblem des Weltenkerns", additional_info = "Accountgebunden\n[q]\"Beweis für die Einstimmung auf die Leylinienzusammenflüsse. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\""},
[232458] = {name = "[q2]Rune des verbesserten Refugiums", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Helm mit der Rune 'Verbessertes Refugium':\n\n\nErhöht den durch Euren 'Segen des Refugiums' verhinderten Schaden um 100% und erhöht den durch Euren 'Segen des Refugiums' verursachten Schaden um 20% Eures Schildblockwerts.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[232459] = {name = "[q2]Rune der Pyrolyse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Prägt Euren Helm mit der Rune 'Pyrolyse':\n\n\nEure Fähigkeit 'Feuersbrunst' gewährt zusätzlich 15 Sek. lang 30% Zauberwirktempo und verbraucht 'Feuerbrand' nicht mehr.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[232460] = {name = "[q2]Rune der Verzerrung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Armschienen mit der Rune 'Verzerrung':\n\n\nTeleportiert Euch dahin zurück, wo Ihr zuletzt 'Blinzeln' gewirkt habt, und schließt die Abklingzeit von 'Blinzeln' ab. Lässt sich nur innerhalb von 10 Sek. nach dem Wirken von 'Blinzeln' nutzen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[232461] = {name = "[q2]Rune der Verzweiflung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Prägt Eure Armschienen mit der Rune 'Verzweiflung':\n\n\nDer regelmäßige Schaden Eurer Zauber kann nun kritischen Schaden verursachen und all Eure kritischen Treffer mit Zaubern verursachen 200% mehr Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[232462] = {name = "[q2]Rune der reinigenden Macht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Armschienen mit der Rune 'Reinigende Macht':\n\n\nVerringert die Abklingzeit von 'Exorzismus' und 'Heiliger Zorn' um 50%. 'Heiliger Zorn' kann jetzt auf jedes Ziel gewirkt werden und betäubt dämonische sowie untote Ziele für 2 Sek.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[232549] = {name = "[q2]Logistikeinsatz VI", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60"},
[232550] = {name = "[q4]Ashkandi, Großschwert der Bruderschaft", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{235 - 354 Schaden} {Tempo 3.60}\n(81.81 Schaden pro Sekunde)\n+20 Stärke\n+23 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: +86 Angriffskraft.\n[q]\"Die Initialen A.L. sind in den Schwertgriff eingeätzt.\""},
[232551] = {name = "[q4]Drachischer Schlägel", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{117 - 176 Schaden} {Tempo 2.00}\n(73.25 Schaden pro Sekunde)\n+33 Stärke\n+21 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: +260 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
[232552] = {name = "[q4]Lok'amir il Romathis", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Streitkolben}\n{47 - 127 Schaden} {Tempo 2.10}\n(41.43 Schaden pro Sekunde)\n+10 Ausdauer\n+18 Intelligenz\n+8 Willenskraft\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 86.\n[q]\"Die Hand von Nefarius.\""},
[232555] = {name = "[q4]Crul'shorukh, Schneide des Chaos", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #668) (1)\n{Einhändig} {Axt}\n{105 - 197 Schaden} {Tempo 2.40}\n(62.92 Schaden pro Sekunde)\n+13 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: +38 Angriffskraft."},
[232556] = {name = "[q4]Stab der Schattenflamme", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{140 - 246 Schaden} {Tempo 3.20}\n(60.31 Schaden pro Sekunde)\n+21 Ausdauer\n+29 Intelligenz\n+18 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 86."},
[232557] = {name = "[q4]Klaue von Chromaggus", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Dolch}\n{36 - 89 Schaden} {Tempo 1.50}\n(41.67 Schaden pro Sekunde)\n+7 Ausdauer\n+17 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 68.\n[q2]Anlegen: Eure offensiven Zauber erhöhen den Zauberschaden einer zufälligen Magieart 10 Sek. lang um 50. (9.5s Abklingzeit)"},
[232558] = {name = "[q4]Chromatisch gehärtetes Schwert", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #665) (1)\n{Einhändig} {Schwert}\n{110 - 205 Schaden} {Tempo 2.70}\n(58.33 Schaden pro Sekunde)\n+14 Stärke\n+15 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60"},
[232559] = {name = "[q4]Herold des Leidens", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{217 - 326 Schaden} {Tempo 3.70}\n(73.38 Schaden pro Sekunde)\n+31 Stärke\n+22 Ausdauer\n+20 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: +260 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
[232561] = {name = "[q4]Klaue des Schwarzdrachen", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Faustwaffe}\n{110 - 206 Schaden} {Tempo 2.80}\n(56.43 Schaden pro Sekunde)\n+6 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: +28 Angriffskraft."},
[232562] = {name = "[q4]Drachenkrallenbeil", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Axt}\n{223 - 335 Schaden} {Tempo 3.80}\n(73.42 Schaden pro Sekunde)\n+22 Stärke\n+17 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Trefferchance: Verursacht eine tödliche Wunde und 300 Schaden."},
[232563] = {name = "[q4]Fokussierstab der Schattenschwingen", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{139 - 234 Schaden} {Tempo 3.20}\n(58.28 Schaden pro Sekunde)\n+19 Ausdauer\n+36 Intelligenz\n+22 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 60.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%."},
[232564] = {name = "[q4]Maladath, runenverzierte Klinge des schwarzen Drachenschwarms", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #664) (1)\n{Einhändig} {Schwert}\n{86 - 162 Schaden} {Tempo 2.20}\n(56.36 Schaden pro Sekunde)\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Verbessert Eure Chance auf Treffer mit allen Zaubern und Angriffen um 2%.\n[q2]Anlegen: Schwerter +3."},
[232565] = {name = "[q4]Drachenzahnklinge", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #666) (1)\n{Einhändig} {Dolch}\n{54 - 101 Schaden} {Tempo 1.40}\n(55.36 Schaden pro Sekunde)\n+18 Beweglichkeit\n+11 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60"},
[232566] = {name = "[q4]Die ungezähmte Klinge", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{198 - 297 Schaden} {Tempo 3.50}\n(70.71 Schaden pro Sekunde)\n+29 Beweglichkeit\n+20 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Trefferchance: Erhöht die Stärke 8 Sek. lang um 300."},
[232567] = {name = "[q4]Wirbelsäulenbrecher", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Streitkolben}\n{99 - 184 Schaden} {Tempo 2.60}\n(54.42 Schaden pro Sekunde)\n+7 Stärke\n+14 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Verteidigung +8."},
[232576] = {name = "[q4]Drachischer Rächer", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Zweihändig} {Axt}\n{201 - 303 Schaden} {Tempo 3.50}\n(72.00 Schaden pro Sekunde)\n+23 Stärke\n+28 Beweglichkeit\n+18 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Verbessert Eure Chance auf Treffer mit allen Zaubern und Angriffen um 2%."},
[232577] = {name = "[q4]Schneide der Verdammnis", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #667) (1)\n{Einhändig} {Axt}\n{100 - 187 Schaden} {Tempo 2.60}\n(55.19 Schaden pro Sekunde)\n+10 Stärke\n+17 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60"},
[232606] = {name = "[q4]Ashjre'thul, Armbrust der Pein", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Distanz} {Armbrust}\n{124 - 186 Schaden} {Tempo 3.40}\n(45.59 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Anlegen: +36 Distanzangriffskraft."},
[232607] = {name = "[q4]Herzensbrecher", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Distanz} {Bogen}\n{98 - 183 Schaden} {Tempo 3.20}\n(43.91 Schaden pro Sekunde)\n+6 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Anlegen: Distanzangriffstreffer haben eine Chance von 2%, einen Zusatzangriff zu gewähren. (Procchance: 2%, 1s Abklingzeit)\n[q2]Anlegen: +18 Angriffskraft."},
[232608] = {name = "[q4]Drachenodemhandkanone", additional_info = "Schattenflamme\nWird beim Aufheben gebunden\n{Distanz} {Schusswaffe}\n{92 - 172 Schaden} {Tempo 3.00}\n(44.00 Schaden pro Sekunde)\n+14 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Benutzen: Ladet die Handkanone 2,5 Sek. lang auf, um Gegnern in einem kegelförmigen Bereich vor Euch 500 Feuerschaden zuzufügen. Erzeugt ein hohes Maß an Bedrohung. (30 Sek. Abklingzeit)"},
[232610] = {name = "Formel: Prächtiger Trollschein", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenötigtStamm der Zandalar\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch, wie man prächtigen Trollschein herstellt.\nPrächtiger Trollschein\nBenötigt Stufe 45\n[q2]Benutzen: Während die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 36 und Eure kritische Zaubertrefferchance um 1% erhöht. Hält 30 Min. lang an.\n5 Aufladungen\nBenötigt Fläschchen Mojo (3), Fläschchen großes Mojo (3), Großer glänzender Splitter (2), Magieerfüllte Phiole"},
[232611] = {name = "Prächtiger Trollschein", additional_info = "Benötigt Stufe 45\n[q2]Benutzen: Während die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 36 und Eure kritische Zaubertrefferchance um 1% erhöht. Hält 30 Min. lang an.\n5 Aufladungen"},
[232652] = {name = "[q4]Zila Amanemodas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Stimmt Euch auf die Dunkelheit in Eurem Innern ein, damit Ihr Euren inneren Dämon besser kontrollieren könnt."},
[233197] = {name = "[q3]Trainingshandbuch der Argentumdämmerung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Das Handbuch wird verwendet, um den Argentumknappen für eine Trainingsstunde im Kampf gegen die Silithiden zu rufen. Silithiden, die in Anwesenheit des Knappen getötet werden, steigern Euren Ruf bei der Argentumdämmerung. (5 Min Abklingzeit)\n3 Aufladungen"},
[233198] = {name = "[q3]Horn der Dämmerung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Spornt Eure Gruppen- oder Schlachtzugsmitglieder in der Nähe an und gewährt ihnen eine um 10% erhöhte Chance auf kritische Zaubertreffer, eine um 5% erhöhte Chance auf kritische Treffer im Nah- und Distanzkampf und eine um 140 erhöhte Angriffskraft. Hält 2 Stunden lang an. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst. (30 Sek. Abklingzeit)"},
[233200] = {name = "[q3]Liedblumensaat", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Beschwört eine Liedblume, die 1 Stunde lang bei allen Gruppen- oder Schlachtzugsmitgliedern die kritische Trefferchance von Nahkampf- und Distanzangriffen sowie von Zaubern um 5% und Attribute um 15 erhöht. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst. (30 Sek. Abklingzeit)"},
[233201] = {name = "[q3]Schimmernde Kugel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht 2 Stunden lang die Angriffskraft aller Mitglieder Eurer Gruppe oder Eures Schlachtzugs in der Nähe um 200, die Ausdauer um 15% und die kritische Trefferchance von Zaubern 3%. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst. (30 Sek. Abklingzeit)"},
[233206] = {name = "[q3]Amboss des Vorarbeiters", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht die Gesundheit um 300. 15% Tempo für Nahkampfangriffe. 10 Mana alle 5 Sek. Hält 1 Stunde lang an. (30 Sek. Abklingzeit)"},
[233208] = {name = "[q3]\"Defekte\" Wahrsagerkugel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht 2 Stunden lang den verursachten Schaden aller Mitglieder Eurer Gruppe oder Eures Schlachtzugs um 10%. (30 Sek. Abklingzeit)\n[q]\"Egal, wie oft Ihr es schüttelt, das Spielzeug landet immer wieder auf demselben grausigen Schicksal: Schmerzhafter Tod.\""},
[233209] = {name = "[q3]Feuerwasserkessel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Beschwört einen Feuerwasserkessel, der 10 Min. lang bestehen bleibt und von allen Mitgliedern Eurer Gruppe oder Eures Schlachtzugs benutzt werden kann, um 1 Stunde lang die Nahkampfangriffskraft um 35 und die Größe zu erhöhen. (30 Sek. Abklingzeit)"},
[233211] = {name = "[q3]Geistschnecke", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Erhöht die Bewegungsgeschwindigkeit aller Gruppen- oder Schlachtzugsmitglieder um 10% und ihre Werte um 15%. Hält 2 Stunden lang an. (30 Sek. Abklingzeit)"},
[233213] = {name = "[q3]Uralter Leitstein", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Schwächt die Elementarmitglieder des Abyssischen Rates in Silithus, wodurch der von ihnen verursachte Schaden um 20% verringert wird. Hält 2 Min. lang an. (1 Min Abklingzeit)\n10 Aufladungen"},
[233215] = {name = "[q3]Explosive Sandfalle", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Platziert eine Falle an einem Ort in der Nähe, die explodiert, wenn sich ein Silithid des Ashischwarms, Regalschwarms oder Zoraschwarms nähert, wodurch der Silithid 15 Sek. lang alle 3 Sek. Schaden in Höhe von 6% seiner Gesundheit erleidet. (1 Min Abklingzeit)\n10 Aufladungen"},
[233216] = {name = "[q3]Frostomatikstrahl", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Friert einen Silithiden im Bau des Ashischwarms, im Bau des Regalschwarms oder im Bau des Zoraschwarms für 1 Min. ein. Effekt wird durch jeden Schaden unterbrochen. (1 Min Abklingzeit)\n10 Aufladungen"},
[233217] = {name = "[q3]Räucherwerk des Tunnelgräbers", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Durch das Einatmen dieses Weihrauchs verschwindet Ihr in die Schatten, was ein unbemerktes Herumschleichen im Bau des Ashischwarms, im Bau des Regalschwarms und im Bau des Zoraschwarms ermöglicht, jedoch wird Eure Geschwindigkeit um 50% verringert. Hält 1 Min. lang an. (1 Min Abklingzeit)\n10 Aufladungen"},
[233226] = {name = "[q3]Uraltes Zandalariseil", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Wirft das uralte Seil, um einen Silithiden des Ashischwarms, Regalschwarms oder Zoraschwarms zu fesseln und zu Euch zu ziehen. Kann nicht gegen Gegner eingesetzt werden, die eine höhere Stufe als ( 60 + 1) haben oder als Bossgegner markiert sind. (1 Min Abklingzeit)\n10 Aufladungen\n[q]\"Wurde in längst vergangenen Tagen von Trollen des Zulimperiums im Kampf gegen die Aqir eingesetzt.\""},
[233250] = {name = "[q3]Uralter Zweig", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\n[q2]Benutzen: Verwendet den Zweig, um ein Urtum des Krieges zu rufen, dass Euch beim Kampf gegen Silithiden hilft. (15 Min Abklingzeit)\n3 Aufladungen"},
[233351] = {name = "[q4]Hellgrüner Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[233352] = {name = "[q4]Dunkelblauer Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[233353] = {name = "[q4]Hellblauer Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[233356] = {name = "[q4]Orangener Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[233357] = {name = "[q4]Zwielichtqirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[233358] = {name = "[q3]Gezähmte Silithidendrohne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Stößt ein Hochfrequenzsignal aus, das eine Silithidendrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithid gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindselige Handlung gegen den Reiter zwingen die Drohne, sich wieder einzugraben. (3 Sek. Abklingzeit)"},
[233362] = {name = "[q4]Hülle des alten Gottes", additional_info = "Wird beim Aufheben gebunden\nKlassen: Paladin , Schamane , Druide"},
