[233796] = {name = "[q4]Obsidianzerstörer", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Obsidian Weapon] (1)\n{Zweihändig} {Streitkolben}\n{117 - 176 Schaden} {Tempo 2.00}\n(73.25 Schaden pro Sekunde)\n+40 Stärke\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: +260 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Trefferchance: Betäubt ein Ziel 3 Sek. lang.\n[q2]Anlegen: Bei Angriffen mit Direktzauberschaden oder Nahkampfangriffen besteht eine Chance, Eurem Ziel 325 bis 500 Feuerschaden zuzufügen. Fügt Silithidkreaturen in Silithus mit nahezu jedem Treffer zusätzlichen Schaden zu. (2.1s Abklingzeit)"},
[233797] = {name = "[q4]Obsidiansturmhammer", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Obsidian Weapon] (1)\n{Waffenhand} {Streitkolben}\n{49 - 117 Schaden} {Tempo 2.00}\n(41.50 Schaden pro Sekunde)\n+10 Ausdauer\n+8 Intelligenz\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Trefferchance: Überzieht bis zu 3 Ziele mit 105 bis 145 Naturschaden.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 60.\n[q2]Anlegen: Bei Angriffen mit Direktzauberschaden oder Nahkampfangriffen besteht eine Chance, Eurem Ziel 325 bis 500 Feuerschaden zuzufügen. Fügt Silithidkreaturen in Silithus mit nahezu jedem Treffer zusätzlichen Schaden zu. (2.1s Abklingzeit)"},
[233798] = {name = "[q4]Obsidianweisenklinge", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Obsidian Weapon] (1)\n{Waffenhand} {Schwert}\n{37 - 88 Schaden} {Tempo 1.50}\n(41.67 Schaden pro Sekunde)\n+14 Ausdauer\n+12 Intelligenz\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 60.\n[q2]Anlegen: Reduziert die Magiewiderstände der Ziele Eurer Zauber um 20.\n[q2]Anlegen: Bei Angriffen mit Direktzauberschaden oder Nahkampfangriffen besteht eine Chance, Eurem Ziel 325 bis 500 Feuerschaden zuzufügen. Fügt Silithidkreaturen in Silithus mit nahezu jedem Treffer zusätzlichen Schaden zu. (2.1s Abklingzeit)"},
[233801] = {name = "[q4]Obsidianverteidiger", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Obsidian Weapon] (1)\n{Waffenhand} {Axt}\n{106 - 198 Schaden} {Tempo 2.70}\n(56.30 Schaden pro Sekunde)\n+11 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Verteidigung +9.\n[q2]Anlegen: Bei Angriffen mit Direktzauberschaden oder Nahkampfangriffen besteht eine Chance, Eurem Ziel 325 bis 500 Feuerschaden zuzufügen. Fügt Silithidkreaturen in Silithus mit nahezu jedem Treffer zusätzlichen Schaden zu. (2.1s Abklingzeit)"},
[233802] = {name = "[q3]Leuchtendes Chitinrüstungsset", additional_info = "Benötigt Stufe 50\n[q2]Benutzen: Zauberschaden und Heilung eines Gegenstands für den Brust-, Bein-, Hand- oder Fußplatz dauerhaft um bis zu 10 erhöhen. Kann nur auf Gegenstände der Stufe 45 oder höher angewendet werden."},
