[233959] = {name = "[q4]Qirajiseidenumhang", additional_info = "Wird beim Anlegen gebunden\nRücken\n56 Rüstung\n+6 Ausdauer\n+7 Intelligenz\n+7 Willenskraft\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 25."},
[233960] = {name = "[q4]Qirajiseidentuch", additional_info = "Wird beim Anlegen gebunden\nRücken\n56 Rüstung\n+7 Ausdauer\n+10 Intelligenz\n+8 Willenskraft\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 31 und den verursachten Schaden um bis zu 11."},
[233962] = {name = "Fläschchen des Wahnsinns", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht 2 Stunden lang die Angriffskraft um 50. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)"},
[233964] = {name = "Fläschchen des uralten Wissens", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 2 Stunden lang um bis zu 180. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)"},
[233965] = {name = "Fläschchen der Alten Götter", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht 2 Stunden lang die Ausdauer um 100 und die Verteidigung um 10. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)"},
[233966] = {name = "Fläschchen des unnachgiebigen Kummers", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht 2 Stunden lang die hervorgerufene Heilung von Zaubern und magischen Effekten um bis zu 80 Gesundheit, den Schaden von Zaubern und magischen Effekten um bis zu 27 und die Manaregeneration um 12 Mana pro 5 Sek. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)"},
[233967] = {name = "Elixier des Honigdachses", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht die Beweglichkeit um 30, die kritische Trefferchance um 2% und den Naturwiderstand um 15. Hält 1 Stunde lang an. (3 Sek. Abklingzeit)"},
[233968] = {name = "Elixier des Magierlords", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht den Zauberschaden um bis zu 40 und den Naturwiderstand um 15. Hält 1 Stunde lang an. (3 Sek. Abklingzeit)"},
[233969] = {name = "Elixier der Eisenflanken", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht die Rüstung um 450, die Verteidigung um 5 und den Naturwiderstand um 15. Hält 1 Stunde lang an. (3 Sek. Abklingzeit)"},
[233977] = {name = "Elixier des Eifers", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Erhöht die Laufgeschwindigkeit 1 Stunde lang um 15%. (3 Sek. Abklingzeit)"},
[233984] = {name = "Arkane Megabombe", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Zieht 1075 bis 1525 Mana von allen ab, die sich im Sprengradius befinden und fügt dem Ziel Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Effektbereich außerdem 5 Sek. lang zum Schweigen. (1 Min Abklingzeit)"},
[233985] = {name = "Der Ausräucherer", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Explodiert bei Auslösung und fügt allen Gegnern in der Nähe 650 bis 950 Feuerschaden sowie Euch 475 bis 725 Schaden zu. Fügt Silithidkreaturen in Silithus zusätzlichen Schaden zu. (5 Min Abklingzeit)"},
[233986] = {name = "Obsidianbombe", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Verursacht 530 bis 670 Feuerschaden innerhalb eines Radius von 5 Metern. (1 Min Abklingzeit)"},
[233987] = {name = "[q3]Generator für 6u73 5chw1n6un63n", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\n[q2]Benutzen: Entfaltet sich zu einem Generator für 6u73 5chw1n6un63n, der beschädigte Gegenstände reparieren kann und der Euch nicht benötigte Gegenstände abkauft. Nach 10 Min. versagt sein innerer Motor und er muss eine Weile ruhen. (4 Std. Abklingzeit)"},
[233988] = {name = "[q4]Gestimmte machtreaktive Scheibe", additional_info = "Wird beim Anlegen gebunden\n{Schild}hand} {Schild}\n2822 Rüstung\n52 Blocken\n+20 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Verteidigung +7.\n[q2]Anlegen: Wenn der Schild blockt, löst er einen Elektroschock aus, der allen Gegnern in der Nähe Schaden zufügt. (1s Abklingzeit)\n[q2]Benutzen: Lädt die Energie des Schilds 3 Sek. lang auf, um allen Gegnern in der Nähe 450 bis 750 Naturschaden zuzufügen. Nach dem Einsatz benötigt der Schild 10 Sek. zum Wiederaufladen. (2 Min Abklingzeit)"},
[233990] = {name = "[q4]Geschwindigkeitsstein", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 2%."},
[233991] = {name = "[q4]Träne des Träumers", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Crystallized Tear] (1)\nSchmuck\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 46."},
[233992] = {name = "[q4]Leitstein der Vergeltung", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+23 Ausdauer\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Verteidigung +11.\n[q2]Anlegen: Bei einem Treffer im Kampf erleidet der Angreifer 80 Naturschaden. Verursacht das Doppelte des verursachten Schadens an Bedrohung."},
[233993] = {name = "[q4]Verzauberte Stoppuhr", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht die Laufgeschwindigkeit 10 Sek. lang um 40%. (2 Min Abklingzeit)"},
[233994] = {name = "[q4]Rubinbesetzte Brosche", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Jeweled Healing Focus] (1)\nSchmuck\n+18 Intelligenz\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 68 und den verursachten Schaden um bis zu 23."},
[233995] = {name = "[q3]Schriftrolle: Zorn des Schwarms", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 60\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lest die Schriftrolle und ruft so den Zorn des Schwarms herbei, der Euren Schlachtzug ermächtigt, wodurch 1 Stunde lang der verursachte Schaden und die hervorgerufene Heilung mit Zaubern um bis zu 40 und die Angriffskraft um 40 erhöht wird. (1 Min Abklingzeit)"},
[233996] = {name = "Verzaubertes Abwehrmittel", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Wird es auf eine Waffe oder einen Schild angewendet, erhöht es den Zauberschaden um bis zu 45 und erhöht die Chance auf einen kritischen Treffer mit Zaubern um 1%. Hält 30 Minuten.\n5 Aufladungen"},
[233997] = {name = "[q3]Formel: Brust - Lebendige Werte", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch, wie man eine Brustrüstung dauerhaft so verzaubert, dass alle Werte um 4 sowie der Naturwiderstand um 15 erhöht werden."},
[233998] = {name = "[q3]Formel: Handschuhe - Heilige Kraft", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch, wie man Handschuhe dauerhaft so verzaubert, dass der Heiligschaden von Zaubern und Fähigkeiten um 20 erhöht wird."},
[233999] = {name = "[q3]Formel: Handschuhe - Arkane Macht", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch, wie man Handschuhe dauerhaft so verzaubert, dass der Arkanschaden von Zaubern und Fähigkeiten um 20 erhöht wird."},
[234000] = {name = "[q4]Verzauberter Gebetsband", additional_info = "Wird beim Anlegen gebunden\n{Relikt} {Buchband}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht die Heilung Eurer Zauber 'Heiliges Licht' und 'Lichtblitz' um 3%."},
