[234252] = {name = "[q2]Rezept: Fläschchen des unnachgiebigen Kummers", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fläschchens des unnachgiebigen Kummers.\nFläschchen des unnachgiebigen Kummers\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht 2 Stunden lang die hervorgerufene Heilung von Zaubern und magischen Effekten um bis zu 80 Gesundheit, den Schaden von Zaubern und magischen Effekten um bis zu 27 und die Manaregeneration um 12 Mana pro 5 Sek. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nBenötigt Große ewige Essenz , Schwarmdistel , Fläschchen mit destillierter Weisheit , Kristallphiole"},
[234253] = {name = "[q2]Rezept: Fläschchen des uralten Wissens", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fläschchens des uralten Wissens.\nFläschchen des uralten Wissens\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 2 Stunden lang um bis zu 180. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nBenötigt Große ewige Essenz , Qirajipirschergift , Fläschchen mit oberster Macht , Kristallphiole"},
[234255] = {name = "[q2]Rezept: Fläschchen der Alten Götter", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fläschchens der Alten Götter.\nFläschchen der Alten Götter\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht 2 Stunden lang die Ausdauer um 100 und die Verteidigung um 10. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nBenötigt Große ewige Essenz , Monströses Silithidenchitin , Fläschchen der Titanen , Kristallphiole"},
[234256] = {name = "[q2]Rezept: Fläschchen des Wahnsinns", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fläschchens des Wahnsinns.\nFläschchen des Wahnsinns\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht 2 Stunden lang die Angriffskraft um 50. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nBenötigt Große ewige Essenz , Uralte Sandwurmgalle , Fläschchen mit chromatischem Widerstand , Kristallphiole"},
[234257] = {name = "[q2]Rezept: Elixier des Honigdachses", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\nBenötigtZirkel des Cenarius\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch die Herstellung eines Elixiers des Honigdachses.\nElixier des Honigdachses\nBenötigt Stufe 60\n[q2]Benutzen: Erhöht die Beweglichkeit um 30, die kritische Trefferchance um 2% und den Naturwiderstand um 15. Hält 1 Stunde lang an. (3 Sek. Abklingzeit)\nBenötigt Bergsilberweisling (2), Schwarmdistel (2), Qirajipirschergift , Kristallphiole"},
