[235133] = {name = "[q3]Formel: Buchband der Rechtschaffenheit", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Buchbands der Rechtschaffenheit.\n[q4]Buchband der Rechtschaffenheit\nWird beim Anlegen gebunden\n{Relikt} {Buchband}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Hammer der Rechtschaffenen' und 'Schild der Rechtschaffenheit' um 3%.\nBenötigt Nexuskristall (3), Qirajiseide (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (4)"},
[235134] = {name = "[q3]Formel: Buchband des Exorzisten", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Buchbands des Exorzisten.\n[q4]Buchband des Exorzisten\nWird beim Anlegen gebunden\n{Relikt} {Buchband}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Exorzismus' und 'Kreuzfahrerstoß' um 3%.\nBenötigt Nexuskristall (3), Qirajiseide (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (4)"},
[235135] = {name = "[q3]Formel: Buchband der Heiligkeit", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Buchbands der Heiligkeit.\n[q4]Buchband der Heiligkeit\nWird beim Anlegen gebunden\n{Relikt} {Buchband}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Heiliger Schock' um 3% und Eure Stärkung 'Schockierende Ehrfurcht' erhöht den Heiligschaden um zusätzlich 10%. (Dieser Effekt ist nicht mit 'Aura der Heiligkeit' stapelbar.)\nBenötigt Nexuskristall (3), Qirajiseide (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (4)"},
[235136] = {name = "[q3]Formel: Totem des pyroklastischen Donners", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Totems des pyroklastischen Donners.\n[q4]Totem des pyroklastischen Donners\nWird beim Anlegen gebunden\n{Relikt} {Totem}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Blitzschlag', 'Kettenblitzschlag' und 'Lavaeruption' um 3%.\nBenötigt Nexuskristall (3), Schwarmdistel (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (3)"},
[235137] = {name = "[q3]Formel: Totem der donnernden Schläge", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Totems der donnernden Schläge.\n[q4]Totem der donnernden Schläge\nWird beim Anlegen gebunden\n{Relikt} {Totem}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Sturmschlag' und 'Waffe des Windzorns' um 3%.\nBenötigt Nexuskristall (3), Schwarmdistel (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (3)"},
[235138] = {name = "[q3]Formel: Totem des fließenden Magmas", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Totems des fließenden Magmas.\n[q4]Totem des fließenden Magmas\nWird beim Anlegen gebunden\n{Relikt} {Totem}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Flammenschock' und 'Schmelzschlag' um 3%.\nBenötigt Nexuskristall (3), Schwarmdistel (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (3)"},
[235139] = {name = "[q3]Formel: Götze des siderischen Zorns", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Götzen des siderischen Zorns.\n[q4]Götze des siderischen Zorns\nWird beim Anlegen gebunden\n{Relikt} {Götze}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Mondfeuer' und 'Zorn' um 3%.\nBenötigt Nexuskristall (2), Schwarmdistel (20), Verzaubertes Leder (3), Qirajipirschergift (4), Uralte Sandwurmgalle (4)"},
[235140] = {name = "[q3]Formel: Götze der Katzenwildheit", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Götzen der Katzenwildheit.\n[q4]Götze der Katzenwildheit\nWird beim Anlegen gebunden\n{Relikt} {Götze}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Wilder Biss' und 'Schreddern' um 3%.\nBenötigt Nexuskristall (2), Schwarmdistel (20), Verzaubertes Leder (3), Qirajipirschergift (4), Uralte Sandwurmgalle (4)"},
[235141] = {name = "[q3]Formel: Götze der Bärenwut", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Götzen der Bärenwut.\n[q4]Götze der Bärenwut\nWird beim Anlegen gebunden\n{Relikt} {Götze}\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht den Schaden von 'Prankenhieb' und 'Zerfleischen' um 3%.\nBenötigt Nexuskristall (2), Schwarmdistel (20), Verzaubertes Leder (3), Qirajipirschergift (4), Uralte Sandwurmgalle (4)"},
[235142] = {name = "[q3]Blutbedeckte Silbermünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Transmutiert 100 blutbedeckte Silbermünzen zu einer blutbedeckten Goldmünze.\n[q]\"Aus den Taschen Eurer Opfer geplündert und vom Blutloa gesegnet.\""},
[235143] = {name = "[q4]Blutbedeckte Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Aus den Taschen Eurer Opfer geplündert und vom Blutloa gesegnet.\""},
[235144] = {name = "Beutel mit blutbedeckten Kupfermünzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q]\"Enthält 100 blutbedeckte Kupfermünzen.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[235145] = {name = "Beutel mit blutbedeckten Silbermünzen", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält 100 blutbedeckte Silbermünzen.\"\n[q2]<Zum Öffnen rechtsklicken>"},
