[235276] = {name = "[q4]Elementarkartenset", additional_info = "Dieser Gegenstand startet eine Quest.\n[q]\"Eigentum des Dunkelmond-Jahrmarkts.\""},
[235277] = {name = "[q4]Kriegsfürstenkartenset", additional_info = "Dieser Gegenstand startet eine Quest.\n[q]\"Eigentum des Dunkelmond-Jahrmarkts.\""},
[235278] = {name = "[q4]Bestienkartenset", additional_info = "Dieser Gegenstand startet eine Quest.\n[q]\"Eigentum des Dunkelmond-Jahrmarkts.\""},
[235282] = {name = "[q4]Fühler der Kräftigung", additional_info = "Leerenberührt\nWird beim Aufheben gebunden\n{Distanz} {Zauberstab}\n{107 - 199 Naturschaden} {Tempo 1.60}\n(95.63 Schaden pro Sekunde)\n+4 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 31 und den verursachten Schaden um bis zu 11.\n[q2]Anlegen: Stellt alle 5 Sek. 2 Punkt(e) Mana wieder her."},
[235473] = {name = "[q4]Barrikade des Großmarschalls", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n3000 Rüstung\n56 Blocken\n+26 Ausdauer\n+10 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 44 Gesundheit und den verursachten Schaden um bis zu 24.\n[q2]Anlegen: Verringert den von Spielercharakteren und ihren Begleitern erlittenen Schaden um 5%. Dieser Effekt kann nicht aus mehreren Quellen kombiniert werden."},
[235474] = {name = "[q4]Barrikade des Obersten Kriegsfürsten", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n3000 Rüstung\n56 Blocken\n+26 Ausdauer\n+10 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 44 Gesundheit und den verursachten Schaden um bis zu 24.\n[q2]Anlegen: Verringert den von Spielercharakteren und ihren Begleitern erlittenen Schaden um 5%. Dieser Effekt kann nicht aus mehreren Quellen kombiniert werden."},
[235476] = {name = "[q4]Hackbeil des Obersten Kriegsfürsten", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Axt}\n{89 - 134 Schaden} {Tempo 1.80}\n(61.94 Schaden pro Sekunde)\n+13 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: +28 Angriffskraft.\n[q2]Anlegen: Verringert den von Spielercharakteren und ihren Begleitern erlittenen Schaden um 5%. Dieser Effekt kann nicht aus mehreren Quellen kombiniert werden."},
