[235497] = {name = "Trunk der Sande", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht Zielen in Silithus, Ahn'Qiraj, den Östlichen Pestländern und Naxxramas zugefügten Schaden um 3% und den kritischen Schaden gegen Ziele in diesen Gebieten um zusätzliche 3%. (3 Sek. Abklingzeit)"},
[235511] = {name = "[q4]Makelloser gelber Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[235512] = {name = "[q4]Makelloser grüner Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[235513] = {name = "[q4]Makelloser blauer Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[235514] = {name = "[q4]Makelloser roter Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[235517] = {name = "Fackel", additional_info = "Benötigt Stufe 60"},
[235526] = {name = "[q3]Formel: Armschiene - Zaubermacht", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Armschienen dauerhaft so verzaubern, dass sie den Schaden von Zaubern um bis zu 12 erhöhen.\n[q]\"Lehrt Euch, wie man Armschienen dauerhaft so verzaubert, dass sie den Schaden von Zaubern um bis zu 12 erhöhen.\""},
[235528] = {name = "[q3]Formel: Armschiene - Beweglichkeit", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\n[q2]Armschienen dauerhaft so verzaubern, dass sie die Beweglichkeit um 9 erhöhen.\n[q]\"Lehrt Euch, wie man Armschienen dauerhaft so verzaubert, dass die Beweglichkeit um 9 erhöht wird.\""},
[235529] = {name = "[q3]Obsidianzielfernrohr", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit verursachten Schaden um 10."},
[235530] = {name = "[q3]Bauplan: Obsidianzielfernrohr", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (300)\n[q]\"Lehrt Euch die Herstellung eines Obsidianzielfernrohrs.\""},
[235597] = {name = "[q2]Zaubernotizen: Tieffrieren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Euren Helm mit der Rune 'Tieffrieren':\n\n\nBetäubt das Ziel für 5 Sek.. Funktioniert nur bei eingefrorenen Zielen. Fügt Zielen, die dauerhaft gegen Betäubungseffekte immun sind, [462 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] bis [538 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] Schaden zu. Dieser Schaden profitiert von 'Vergletscherung', braucht aber keine Stapel davon auf.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235598] = {name = "[q2]Zaubernotizen: Eisige Adern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Prägt Eure Hosen mit der Rune 'Eisige Adern':\n\n\nBeschleunigt Euer Wirken von Zaubern, erhöht das Zaubertempo um 20% und verringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Wirken von Zaubern um 100%. Hält 20 Sek. lang an.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235599] = {name = "[q2]Zaubernotizen: Zeitanomalie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n{[q2]Prägt Euren Helm mit der Rune 'Zeitanomalie':\n\n\nSchleudert eine Kugel aus {Temporalenergie, die sich langsam vorwärts bewegt und allen nahen Gruppenmitgliedern jede 2 Sek. einen Schild gewährt, der 15 Sek. lang [100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100] Schaden} absorbiert. Dieser Schild häuft zusätzlichen Wert an, wenn Gruppenmitglieder in der Nähe der Kugel bleiben.}\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235600] = {name = "[q2]Rune des göttlichen Sturms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euer Brustteil mit der Rune 'Göttlicher Sturm':\n\n\nEin sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern 110% Waffenschaden zufügt. 'Göttlicher Sturm' heilt bis zu 3 Gruppen- oder Schlachtzugsmitglieder in Höhe von 25% des verursachten Schadens.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235601] = {name = "[q2]Rune des Fanatismus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Helm mit der Rune 'Fanatismus':\n\n\nErhöht Eure kritische Trefferchance mit Heiligzaubern um 18%. Zudem heilen Eure kritischen Heilzauber das Ziel im Verlauf von 12 Sek. für 60% der geheilten Menge.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235602] = {name = "[q2]Rune des Hammers der Rechtschaffenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Eure Armschienen mit der Rune 'Hammer der Rechtschaffenen':\n\n\nTrifft das aktuelle Ziel sowie bis zu 3 zusätzliche Ziele in der Nähe und verursacht pro Sekunde den 4-fachen Schaden Eurer Waffenhandwaffe als Heiligschaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235603] = {name = "[q2]Rune der rechtschaffenen Vergeltung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Umhang mit der Rune 'Rechtschaffene Vergeltung':\n\n\nWenn Eure Zauber 'Richturteil', 'Kreuzfahrerstoß' oder 'Göttlicher Sturm' einen kritischen Treffer erzielen, erleidet Euer Ziel im Verlauf von bis Abbruch 30% zusätzlichen Schaden.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235604] = {name = "[q2]Rune des Schilds der Rechtschaffenheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Umhang mit der Rune 'Schild der Rechtschaffenheit':\n\n\nVerpasst dem Ziel einen heftigen Schlag mit Eurem Schild, der Heiligschaden basierend auf Eurem Blockwert plus [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100] verursacht.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235605] = {name = "[q2]Rune der schockierenden Ehrfurcht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Prägt Euren Umhang mit der Rune 'Schockierende Ehrfurcht':\n\n\nWährend 'Zorn der Gerechtigkeit' nicht aktiv ist, erhaltet Ihr, wenn Ihr Schaden mit 'Heiliger Schock' verursacht, 1 Min. lang 200% Eurer Intelligenz als Zaubermacht. Zusätzlich verursacht Ihr 30% weniger Bedrohung.\n\n Ihr erhaltet zudem 10 Sek. lang 'Sonnenlicht', wenn Ihr die Rune 'Lichtinfusion' geprägt habt.\n\n\n 'Sonnenlicht' lässt Eure Fähigkeiten 'Göttlicher Sturm' und 'Kreuzfahrerstoß' sowie Eure Nahkampfangriffe zusätzlichen Heiligschaden in Höhe von 60% Eurer Heiligzaubermacht verursachen.\n[q]\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\""},
[235785] = {name = "\"Schlüssel\" für Totenwindkäfig", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Eure scharfsinnigen Observationsfähigkeiten stellen schnell fest, dass dieser \"Schlüssel\" lediglich ein Stein mit einer scharfen Kante ist. Ihr vermutet, dass es ausreichen sollte, ihn gegen das Schloss zu schlagen, um den Käfig zu öffnen.\""},
[235786] = {name = "[q2]Karazhankuriosität", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (99)"},
[235787] = {name = "Uralter Eisenholzzweig", additional_info = "Questgegenstand\nEinzigartig"},
[235788] = {name = "Enthusiastischer Irrwisch", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Das Teil will einfach nicht stillhalten...\""},
[235789] = {name = "Flamme des Lebens", additional_info = "Questgegenstand\nEinzigartig"},
[235790] = {name = "[q2]Verzauberter Feuerbrand", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Haltet die verzauberte Fackel hoch und versucht, die Dunkelheit in den Karazhangruften zu vertreiben. (15 Sek. Abklingzeit)"},
[235825] = {name = "Trunk der Sande", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Erhöht Zielen in Silithus, Ahn'Qiraj, den Östlichen Pestländern und Naxxramas zugefügten Schaden um 2% und den kritischen Schaden gegen Ziele in diesen Gebieten um zusätzliche 2%. (3 Sek. Abklingzeit)"},
[235852] = {name = "[q2]Violettes Säckchen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Dieses kleine Säckchen trägt das Zeichen der Kirin Tor von Dalaran. Es scheint einige kleine Gegenstände zu enthalten, doch seltsamerweise scheint es Euch nicht möglich, es aufzumachen, um zu sehen, was sich darin befindet.\""},
[235867] = {name = "Pergamentfetzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Der Pergamentfetzen scheint von einem größeren Poster oder Flugblatt abgerissen worden zu sein. Die einzigen Worte, die sich ausmachen lassen, scheinen ein Name zu sein... Erzmagier Tarsis Kir-Moldir\""},
[235868] = {name = "[q4]Bollwerk des Zorns", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n3177 Rüstung\n61 Blocken\n+14 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Fügt Nahkampfangreifern 100 Schattenschaden zu. Erzeugt das Doppelte des verursachten Schadens an Bedrohung.\n[q2]Anlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 3%.\n[q2]Anlegen: Verteidigung +10."},
[235869] = {name = "[q4]Gugel des Meisters", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Kopf} {Leder}\n198 Rüstung\n+10 Ausdauer\n+14 Intelligenz\n+10 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 59."},
