[235886] = {name = "[q4]Kaigys Klammer", additional_info = "Geweiht\nWird beim Aufheben gebunden\nHals\n+26 Beweglichkeit\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: +26 Angriffskraft.\n[q]\"Manche Flammen müssen nicht doppelt so hell leuchten, um nur halb so lange zu brennen.\""},
[235887] = {name = "[q4]Barians Halsband", additional_info = "Geweiht\nWird beim Aufheben gebunden\nHals\n+10 Intelligenz\n+8 Willenskraft\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 62 und den verursachten Schaden um bis zu 21.\n[q]\"Der Tod ist eine Gelegenheit, zu lernen, kein Verfehlen des eigenen Charakters.\""},
[235888] = {name = "[q4]Prügelstecken", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Streitkolben}\n{171 - 209 Schaden} {Tempo 2.80}\n(67.86 Schaden pro Sekunde)\n+10 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Streitkolben +3.\n[q2]Anlegen: Verteidigung +10.\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%."},
[235889] = {name = "[q4]Stecken des Bediensteten", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{166 - 228 Schaden} {Tempo 3.60}\n(54.72 Schaden pro Sekunde)\n+25 Beweglichkeit\n+40 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: +423 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Anlegen: Verteidigung +13."},
[235890] = {name = "[q4]Schattenwebernadel", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Dolch}\n{36 - 104 Schaden} {Tempo 1.70}\n(41.18 Schaden pro Sekunde)\n+11 Ausdauer\n+17 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 96."},
[235891] = {name = "[q4]Die gute Alte", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{290 - 355 Schaden} {Tempo 3.80}\n(84.87 Schaden pro Sekunde)\n+50 Stärke\n+12 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Benutzen: Zerschmettert die Leiche eines gefallenen Freundes oder Gegners und fügt Gegnern in der Nähe 588 Schaden zu. (2 Min Abklingzeit)\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q]\"Garantiert, das kein Grab zweimal gegraben werden muss.\""},
[235892] = {name = "[q4]Rückgrat des Dunkelreiters", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Bogen}\n{157 - 192 Schaden} {Tempo 3.30}\n(52.88 Schaden pro Sekunde)\n+5 Beweglichkeit\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Anlegen: +26 Angriffskraft.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%."},
[235893] = {name = "[q4]Schattengebundenes Grimoire", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+11 Intelligenz\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 43.\n\n[q]Kharons Erlass (0/2)\n[q0]Schattengebundenes Grimoire\nNiedergang des Verdammnisverkünders\n[q0](2) Set : Der verursachte Schaden von 'Schleichende Dunkelheit' wird um 100% erhöht."},
[235894] = {name = "[q0]Niedergang des Verdammnisverkünders", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Zauberstab}\n{153 - 188 Schattenschaden} {Tempo 1.50}\n(113.67 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Regelmäßige Schatteneffekte haben eine Chance, bis zu 5-mal 'Schleichende Dunkelheit' anzuwenden. Zauber, die direkten Schattenschaden verursachen, lassen diesen Effekt detonieren und verursachen 100 Schaden pro Stapel. (1.5s Abklingzeit)\n\n[q]Kharons Erlass (0/2)\n[q0]Schattengebundenes Grimoire\nNiedergang des Verdammnisverkünders\n[q0](2) Set : Der verursachte Schaden von 'Schleichende Dunkelheit' wird um 100% erhöht."},
[236002] = {name = "Komponentenliste", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Lesen rechtsklicken>"},
[236005] = {name = "[q4]Brustplatte des Schreckenspanzers", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Brust} {Platte}\n1027 Rüstung\n+21 Stärke\n+42 Ausdauer\nHaltbarkeit 165 / 165\nKlassen: Krieger\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 1%.\n[q2]Anlegen: Verteidigung +20.\n\n[q]Schlachtrüstung des Schreckenspanzers (0/9)\n[q0]Helm des Schreckenspanzers\nSchulterstücke des Schreckenspanzers\nBrustplatte des Schreckenspanzers\nTaillenschutz des Schreckenspanzers\nBeinplatten des Schreckenspanzers\nSabatons des Schreckenspanzers\nArmschienen des Schreckenspanzers\nStulpen des Schreckenspanzers\nRing des Schreckenspanzers\n[q0](2) Set : Eure Fähigkeit 'Spott' verfehlt nie ihr Ziel und die Chance, dass man Euren Angriffen ausweicht oder sie pariert werden, wird um 2% verringert.\n(4) Set : Verringert die Abklingzeit Eurer Fähigkeit 'Schildwall' um 3 Min. und verringert die Abklingzeit Eurer Fähigkeit 'Tollkühnheit' um 3 Min. 'Tollkühnheit' kann jetzt in jeder Haltung eingesetzt werden und erhöht nicht mehr den erlittenen Schaden.\n(6) Set : Wenn Ihr durch einen untoten Gegner Schaden erleidet, wird die verbleibende Dauer Eurer aktiven Fähigkeit 'Letztes Gefecht' auf 20 Sek. zurückgesetzt."},
