[236397] = {name = "[q4]Überreste der Tapferkeit", additional_info = "Accountgebunden"},
[236398] = {name = "[q5]Atiesh, Hohestab des Wächters", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{130 - 243 Schaden} {Tempo 2.90}\n(64.31 Schaden pro Sekunde)\n+20 Ausdauer\n+14 Intelligenz\n+30 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Hexenmeister\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 150.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung aller Gruppenmitglieder innerhalb von 30 Metern um bis zu 33. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\n[q2]Benutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)"},
[236399] = {name = "[q5]Atiesh, Hohestab des Wächters", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{130 - 243 Schaden} {Tempo 2.90}\n(64.31 Schaden pro Sekunde)\n+20 Ausdauer\n+22 Intelligenz\n+24 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Priester\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Erhöht für alle Gruppenmitglieder innerhalb von 30 Metern durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 62 Gesundheit und den verursachten Schaden um bis zu 19. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 300 Gesundheit und den verursachten Schaden um bis zu 150.\n[q2]Benutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)"},
[236400] = {name = "[q5]Atiesh, Hohestab des Wächters", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{129 - 242 Schaden} {Tempo 2.90}\n(63.97 Schaden pro Sekunde)\n+21 Ausdauer\n+24 Intelligenz\n+23 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Magier\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Euer Zaubertempo um 4%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 150.\n[q2]Anlegen: Erhöht das Zaubertempo aller Gruppenmitglieder innerhalb von 30 Metern um 2%. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\n[q2]Benutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)"},
[236401] = {name = "[q5]Atiesh, Hohestab des Wächters", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{129 - 242 Schaden} {Tempo 2.90}\n(63.97 Schaden pro Sekunde)\n+21 Ausdauer\n+25 Intelligenz\n+20 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Druide\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 3%.\n[q2]Anlegen: Erhöht die kritische Zaubertrefferchance aller Gruppenmitglieder innerhalb von 30 Metern um 2%. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 300 Gesundheit und den verursachten Schaden um bis zu 150.\n[q2]Anlegen: +592 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n[q2]Benutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)"},
[236414] = {name = "[q2]Beschädigte Vorratskiste aus Undermine", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q]\"Diese verbeulte und beschädigte Kiste sieht aus, als wäre sie buchstäblich von einem Zeppelin gefallen.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[236417] = {name = "[q3]Seele des Taktikers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Taktikers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNachdem Ihr die Haltung wechselt, sind die Wutkosten Eurer nächsten Offensivfähigkeit um 10 verringert."},
[236418] = {name = "[q3]Seele des Kriegsveteranen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Kriegsveteranen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNach Verlassen einer Haltung könnt Ihr 15 Sek. lang noch Fähigkeiten nutzen, die diese Haltung erfordern."},
[236419] = {name = "[q3]Seele des Kampfvoraussehers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Kampfvoraussehers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr eine Haltung einnehmt, erhaltet Ihr für 15 Sek. einen weiteren Vorteil:\n\n Kampfhaltung/Gladiatorhaltung: Verursachter Schaden um 5% erhöht.\n\n Berserkerhaltung: Kritische Trefferchance um 5% erhöht.\n\n Verteidigungshaltung: Erlittener körperlicher Schaden um 5% verringert."},
[236420] = {name = "[q3]Seele des Blutsuchers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Blutsuchers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer von 'Überwältigen' setzen die Dauer von 'Verwunden' auf Eurem Ziel auf die Höchstdauer zurück."},
[236421] = {name = "[q3]Seele des Titanischen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Titanischen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Heldenhafter Stoß', 'Zerschmettern' und 'Überwältigen' verursachen 10 + (5 * Combopunkte)% mehr Schaden."},
[236422] = {name = "[q3]Seele des Zerstörers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zerstörers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Treffer mit 'Zerschmettern' schließen die verbleibende Abklingzeit Eurer Fähigkeiten 'Tödlicher Stoß', 'Blutdurst' und 'Schildschlag' ab."},
[236423] = {name = "[q3]Seele des Todesgebundenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Todesgebundenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Todeswunsch' um 50%."},
[236424] = {name = "[q3]Seele des Bluters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Bluters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr verursacht 15% mehr Schaden, während ein Gegner in der Nähe mit Euren Effekten 'Verwunden' und 'Tiefe Wunden' gleichzeitig belegt ist."},
[236425] = {name = "[q3]Seele des makellosen Blockers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des makellosen Blockers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Blockwert Eures Schildes um 30."},
[236426] = {name = "[q3]Seele des Wilden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Wilden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr Schaden erleidet oder mit automatischen Angriffen Schaden verursacht, erzeugt Ihr zusätzlich 1 Wut."},
[236427] = {name = "[q3]Seele der Feindseligkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Feindseligkeit wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nErhöht Eure in der Verteidigungshaltung erzeugte Bedrohung um zusätzlich 10% und erhöht Euren in der Gladiatorhaltung verursachten Schaden um 4%."},
[236428] = {name = "[q3]Seele des Parierenden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Parierenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr erhaltet jedes Mal 10 Wut, wenn Ihr einen Angriff pariert oder einer Eurer Angriffe pariert wird."},
[236429] = {name = "[q3]Seele des Rächers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Rächers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Rache' gewährt Euch 'Schlaghagel' und erhöht Euer Angriffstempo für die nächsten 3 Hiebe um 30%."},
[236430] = {name = "[q3]Seele des Unermüdlichen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Unermüdlichen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Euer Ziel einen Angriff pariert, holt Ihr sofort zum 'Gegenschlag' aus und fügt ihm 200% Waffenschaden zu. 'Gegenschlag' kann nicht ausgewichen, geblockt oder pariert werden, kann aber pro Ziel nur alle 30 Sek. vorkommen."},
[236431] = {name = "[q3]Seele des Donnerbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Donnerbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Donnerknall' um 100%."},
[236432] = {name = "[q3]Seele der Schildwache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Schildwache wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Schildschlag' verursacht 100% mehr Bedrohung und seine Abklingzeit wird abgeschlossen, wenn er pariert oder geblockt wird oder ihm ausgewichen wird."},
[236433] = {name = "[q3]Seele des Rechtsauslegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Rechtsauslegers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Schildschlag' um 2 Sek."},
[236434] = {name = "[q3]Seele des Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Gladiators wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Blutrausch' um 30 Sek., während Ihr in Gladiatorhaltung seid."},
[236435] = {name = "[q3]Seele des Nachbebens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Nachbebens wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Schockwelle' um 25%."},
[236436] = {name = "[q3]Seele des Vermeidenden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Vermeidenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Finte' gewährt zusätzlich für 6 Sek. Vermeidung, was Euren durch Flächenangriffe von Gegnern außer Spielercharakteren erlittenen Schaden um 50% verringert."},
[236437] = {name = "[q3]Seele des Toxikologen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Toxikologen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den kritischen Schadensbonus Eurer Gifte um 100%."},
[236438] = {name = "[q3]Seele des Scharfrichters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Scharfrichters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Finishing-Moves haben eine Chance von 5% pro Combopunkt, die Energiekosten Eurer nächsten Fähigkeit aufzuheben."},
[236439] = {name = "[q3]Seele des Opportunisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Opportunisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Eröffnungsangriffe haben eine Chance von 100%, dass Eure nächste Fähigkeit keine Energie kostet."},
[236440] = {name = "[q3]Seele des Schlächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schlächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden, den Eure Waffenhandwaffe durch Fähigkeiten verursacht, die Combopunkte erzeugen, um 20%."},
[236441] = {name = "[q3]Seele des Phantoms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Phantoms wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Verschwinden' auf 1 Min. Kann nicht mit 'Flüchtigkeit' kombiniert werden."},
[236442] = {name = "[q3]Seele des Halunken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Halunken wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Verstümmeln' und 'Säbelschlitzer' um 20%."},
[236443] = {name = "[q3]Seele des Abenteuerlustigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Abenteuerlustigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Adrenalinrausch' um 4 Min."},
[236444] = {name = "[q3]Seele des Messerkenners", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Messerkenners wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure Chance, mit Dolchen einen kritischen Treffer zu erzielen, um 5%."},
[236445] = {name = "[q3]Seele des Pirschers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Pirschers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Chance auf einen kritischen Treffer Eurer Fähigkeit 'Hinterhalt' um 30%."},
[236446] = {name = "[q3]Seele des Effizienten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Effizienten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Finishing-Moves kosten 50% weniger Energie."},
[236447] = {name = "[q3]Seele des Messerjongleurs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Messerjongleurs wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn 'Nur eine Fleischwunde' und 'Klingentanz' aktiv sind, kosten 'Blutroter Sturm', 'Donnerbüchse' und 'Dolchfächer' 20 Energie weniger und erzeugen 100% mehr Bedrohung."},
[236448] = {name = "[q3]Seele des Schattenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schattenmeisters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Verschwinden' verringert während der Effektdauer sämtlichen erlittenen Magieschaden um 50%, lässt Euch dafür aber nicht mehr in die Verstohlenheit übergehen und hebt keine bewegungseinschränkenden Effekte auf."},
[236449] = {name = "[q3]Seele des Akrobaten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Akrobaten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Finishing-Moves haben eine Chance von 20% pro Combopunkt, Euch durch den nächsten eintreffenden Nahkampfangriff innerhalb von 10 Sek. 20% weniger körperlichen Schaden erleiden zu lassen."},
[236450] = {name = "[q3]Seele des protzigen Prüglers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des protzigen Prüglers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Effekt 'Schläge abschwächen' wird jetzt außerdem jedes Mal ausgelöst, wenn Ihr einen Combopunkt erhaltet."},
[236451] = {name = "[q3]Seele des schwarzen Gurts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des schwarzen Gurts wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Effekt 'Schläge abschwächen' gewährt Euch außerdem pro Stapel 20% mehr Rüstung von Gegenständen (bis zu einem Maximum von 100%)."},
[236452] = {name = "[q3]Seele des Fechters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Fechters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Abklingzeit für Euren 'Parierdolch' wird jedes Mal abgeschlossen, wenn Euer Ziel ausweicht oder pariert."},
[236453] = {name = "[q3]Seele des Säbelrasslers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Säbelrasslers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Parierdolch' trifft nun 1 zusätzliches Ziel in der Nähe und lässt 'Finsterer Stoß' 10 Sek. lang 1 zusätzliches Ziel in der Nähe treffen. Diese zusätzlichen Treffer werden nicht von 'Klingenwirbel' dupliziert."},
[236454] = {name = "[q3]Seele des Blutrünstigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schurke\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Blutrünstigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Parierdolch' aktiv ist, werdet Ihr zusätzlich um 15% des von 'Finsterer Stoß' verursachten Schadens geheilt. Überschüssige Heilung wird zu einer Blutbarriere, die Schaden in Höhe von bis zu 20% Eurer maximalen Gesundheit absorbiert."},
[236455] = {name = "[q3]Seele des Transfusionisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Transfusionisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Aderlass' erzeugt 50% mehr Mana und 100% weniger Bedrohung."},
[236456] = {name = "[q3]Seele des Verfeinerten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%."},
[236457] = {name = "[q3]Seele des Dezimierers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Dezimierers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Auslösechance Eures Talents 'Einbruch der Nacht' ist um 4% erhöht. 'Verbrennen' hat eine Chance von 4%, 'Dezimierung' unabhängig von der Gesundheit des Ziels auszulösen."},
[236458] = {name = "[q3]Seele des Fäulnisbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Fäulnisbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden Eurer regelmäßigen Zauber und Eurer Teufelswache um 10 + (5 * Combopunkte)%."},
[236459] = {name = "[q3]Seele des Böswilligen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Böswilligen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nRegelmäßiger Schaden Eurer Zauber 'Schattenflamme', 'Instabiles Gebrechen' und 'Fluch der Pein' sowie Schaden, den Eure Teufelswache verursacht, haben eine Chance von 4%, den Effekt 'Schattentrance' zu gewähren."},
[236460] = {name = "[q3]Seele des Schattenbeschwörers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schattenbeschwörers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nPro Effekt auf Eurem Ziel, der von Euch stammt, verursacht 'Schattenblitz' 10 + (5 * Combopunkte)% mehr Schaden, bis maximal 30 + (5 * Combopunkte)%."},
[236461] = {name = "[q3]Seele des Chaosherolds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Chaosherolds wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Chaosblitz' um 50% und erhöht den verursachten Schaden von 'Chaosblitz' und 'Schattenblitz' um 10%. Außerdem kann 'Chaosblitz' nun Euer Talent 'Verbesserter Schattenblitz' auslösen und dafür sorgen, dass es 26 zusätzliche Aufladungen hat (nicht mit zusätzlichen Aufladungen von 'Schattenflamme' stapelbar)."},
[236462] = {name = "[q3]Seele des Brandstifters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Brandstifters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr ein Ziel mit 'Feuersbrunst' trefft, wird Euer Feuerschaden für 20 Sek. um 5% erhöht. Bis zu 2-mal stapelbar."},
[236463] = {name = "[q3]Seele des infernalen Schäfers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des infernalen Schäfers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Angriffskraft und den Zauberschaden, den Euer Dämon durch Eure Attribute erlangt, um 20%."},
[236464] = {name = "[q3]Seele des Dämonenfürsten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Dämonenfürsten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Vorteile Eures Talents 'Meister der Dämonologie' um 50%."},
[236465] = {name = "[q3]Seele des dämonischen Exorzisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des dämonischen Exorzisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Verbannen' ist ein Spontanzauber und kann auf Euch selbst gewirkt werden, während Ihr ein Dämon seid. Ihr könnt 'Verbannen' nicht auf Euch selbst wirken, solange 'Vorahnung' auf Euch wirkt, und 'Verbannen' belegt Euch 1 Min. lang mit 'Vorahnung'."},
[236466] = {name = "[q3]Seelen des Leidenden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seelen des Leidenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr Schaden erleidet, erhaltet Ihr und Euer Diener Mana in Höhe des erlittenen Schadens, bis zu maximal 420 Mana pro Ereignis. Kann nur einmal alle paar Sekunden auftreten."},
[236467] = {name = "[q3]Seele des Flammengespensts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Flammengespensts wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Treffer mit 'Schattenspalten' haben eine Chance von 20%, Euch einen Seelensplitter zu gewähren, die Abklingzeit von 'Seelenfeuer' abzuschließen und Euren nächsten Einsatz von 'Seelenfeuer' innerhalb von 10 Sek. zu einem Spontanzauber zu machen."},
[236468] = {name = "[q3]Seele des Fleischverzehrers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Fleischverzehrers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend Ihr einen Gegner innerhalb von 30 Metern anvisiert, gewährt 'Aderlass' Euch Mana auf Kosten der Gesundheit Eures Ziels, fügt ihm jedoch 50 + (5 * Combopunkte)% weniger Schaden zu. Das erlangte Mana bleibt unverändert."},
[236469] = {name = "[q3]Seele des Abyssals", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Abyssals wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Metamorphose' aktiv ist, kosten Eure Angriffsfähigkeiten und Dämonenbeschwörungen keine Seelensplitter. Außerdem werden 15% Eurer maximalen Gesundheit geheilt, wenn Ihr einem Ziel mit 'Schattenbrand' Schaden zufügt."},
[236470] = {name = "[q3]Seele des Leerengeborenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Leerengeborenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nÜberschüssige Heilung, die Ihr auf Euch wirkt, wird in einen Schild umgewandelt, der Schaden absorbiert. Dieser Schild kann bis zu 30 + (5 * Combopunkte)% Eurer maximalen Gesundheit absorbieren und wird durch mehrere Heilungen gestapelt."},
[236471] = {name = "[q3]Seele der Umbralklinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Umbralklinge wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Schattenspalten' um 1.5 Sek."},
[236472] = {name = "[q3]Seele des Ritualisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Ritualisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Effekt von 'Dämonische Opferung' besteht nun fort, während Ihr einen aktiven Dämonenbegleiter habt, solange Ihr den geopferten Begleiter nicht erneut beschwört. Es kann immer nur ein Effekt von 'Dämonische Opferung' gleichzeitig aktiv sein."},
[236473] = {name = "[q3]Seele des Schmerzverbreiters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Hexenmeister\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schmerzverbreiters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNach dem Einsatz von 'Schattenspalten' trifft Euer 'Sengender Schmerz' 6 Sek. lang 1 zusätzliches Ziel in Nahkampfreichweite."},
[236474] = {name = "[q3]Seele des Irreführers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Irreführers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr erzeugt 8 Sek. lang 100% mehr Bedrohung, nachdem Ihr 'Ablenkender Schuss' verwendet habt."},
[236475] = {name = "[q3]Seele des Beutesuchers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Beutesuchers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr einen Kreaturentyp verfolgt, fügt Ihr diesem Kreaturentyp 3% mehr Schaden zu."},
[236476] = {name = "[q3]Seele des Scharfschützen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Scharfschützen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure nächste Schussfähigkeit 12 Sek. nach 'Gezielter Schuss' verursacht 20% mehr Schaden."},
[236477] = {name = "[q3]Seele des Gefahrenplünderers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Gefahrenplünderers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Gezielter Schuss' fügt Zielen, die von einem Eurer Falleneffekte betroffen sind, 20% mehr Schaden zu."},
[236478] = {name = "[q3]Seele des Wechslers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Wechslers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure schadensverursachenden Schussfähigkeiten verursachen 10% mehr Schaden, wenn der vorherige schadensverursachende Schuss ein anderer war als der aktuelle."},
[236479] = {name = "[q3]Seele des Toxinologen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Toxinologen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Schaden Eurer Fähigkeit 'Schlangenbiss' wird über ihre normale Dauer um 25% Eurer Angriffskraft erhöht."},
[236480] = {name = "[q3]Seele des Kopfgeldjägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Kopfgeldjägers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Tödlicher Schuss' gegen Ziele, die nicht von Spielercharakteren kontrolliert werden, um 10%."},
[236481] = {name = "[q3]Seele des Trickschützen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Trickschützen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Abklingzeit von 'Tödlicher Schuss' ist um 50% verringert. Wenn 'Schneller Tod' geprägt und 'Schnellfeuer' aktiv ist, hat 'Tödlicher Schuss' keine Abklingzeit und setzt gegen Ziele, die nicht von Spielercharakteren kontrolliert werden, 3-mal zusätzlich 'Tödlicher Schuss' mit Mindestreichweite und 30% Schaden ein."},
[236482] = {name = "[q3]Seele des Tierpflegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Tierpflegers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Angriffskraft, die Euer Wildtierbegleiter durch Eure Attribute erlangt, um 20%."},
[236483] = {name = "[q3]Seele des Hundemeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Hundemeisters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Fokusregeneration Eures Wildtierbegleiters um 20%."},
[236484] = {name = "[q3]Seele des Alphazähmers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Alphazähmers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Fokusregeneration Eurer Tiere um 100%."},
[236485] = {name = "[q3]Seele des Waidmanns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Waidmanns wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Mungobiss' verringert zudem die Ausweichchance seines Ziels um 1% und erhöht Eure Trefferchance 30 Sek. lang um 1%."},
[236487] = {name = "[q3]Seele des Vergelters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Vergelters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Mungobiss' wird zudem für 5 Sek. aktiviert, wenn Euer Ziel pariert oder blockt, oder wenn Euer Nahkampfangriff verfehlt."},
[236488] = {name = "[q3]Seele des Widerhalls", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Widerhalls wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\n'Raptorstoß' erhöht den Schaden Eurer nächsten anderen Nahkampffähigkeit (mit Ausnahme von 'Zurechtstutzen') innerhalb von 5 Sek. um 20%."},
[236489] = {name = "[q3]Seele des tödlichen Peitschers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des tödlichen Peitschers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden, den Eure Waffenhandwaffe durch 'Raptorstoß' und 'Flügeldrachenstoß' verursacht, um 20%."},
[236490] = {name = "[q3]Seele des Kinetikers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Kinetikers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer regelmäßiger Schaden hat eine Chance von 5%, die Abklingzeit einer Eurer Stoßfähigkeiten abzuschießen. Es wird stets der Stoß mit der längsten verbleibenden Abklingzeit gewählt."},
[236491] = {name = "[q3]Seele des Strategen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Strategen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den regelmäßigen Schaden von 'Flügeldrachenstoß' um 50% und den maximalen Fokus Eures Begleiters um 50."},
[236492] = {name = "[q3]Seele des Totschlägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Jäger\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Totschlägers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Aufprallschaden von 'Mungobiss' und allen Stoßfähigkeiten um 20%."},
[236493] = {name = "[q3]Seele des beschleunigten Heilers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des beschleunigten Heilers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Zauberzeit von 'Blitzheilung' um 0.1 Sek. und die Zauberzeit von 'Große Heilung' um 0.2 Sek."},
[236494] = {name = "[q3]Seele des Verfeinerten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%."},
[236495] = {name = "[q3]Seele der Zelebranten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zelebranten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure kritische Trefferchance mit 'Gebet der Heilung' und 'Kreis der Heilung' um 25%."},
[236496] = {name = "[q3]Seele des Treuen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Treuen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nLässt 15% Eurer Manaregeneration während des Zauberwirkens weiterlaufen."},
[236497] = {name = "[q3]Seele des Glücklichen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Glücklichen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure regelmäßige Heilung hat eine Chance von 2%, dass Euer nächster Zauber mit einer Zauberzeit von weniger als 10 Sek. zu einem Spontanzauber wird."},
[236498] = {name = "[q3]Seele des Resonanten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Resonanten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Zauber 'Kreis der Heilung' und 'Sühne' gewähren dem Ziel zusätzlich einen regelmäßigen Heilungseffekt, der im Verlauf von 15 Sek. 25% der normalen Menge heilt."},
[236499] = {name = "[q3]Seele des Verehrers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verehrers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Gebet der Besserung' erhält 2 zusätzliche Aufladungen."},
[236500] = {name = "[q3]Seele des Erzbischofs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Erzbischofs wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Kreis der Heilung' heilt nun das am schwersten verletzte Mitglied der Zielgruppe um 100% mehr Gesundheit."},
[236501] = {name = "[q3]Seele des Bußfertigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Bußfertigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eures Zaubers 'Sühne' um 6 Sek."},
[236502] = {name = "[q3]Seele des Seelenwächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Seelenwächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den von Eurem Zauber 'Machtwort: Schild' absorbierten Schaden um 10%."},
[236503] = {name = "[q3]Seele des Zwielichtwandlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zwielichtwandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr könnt 'Blitzheilung' in der Schattengestalt einsetzen."},
[236504] = {name = "[q3]Seele des Gedankenstörers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Gedankenstörers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer mit 'Gedankenschlag' verringern die Dauer Eures nächsten Einsatzes von 'Gedankenschinden' um 50% und erhöhen seinen Gesamtschaden um 25%."},
[236505] = {name = "[q3]Seele des Todesboten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Todesboten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eures Zaubers 'Schattenwort: Tod' um 6 Sek."},
[236506] = {name = "[q3]Seele des Willensquells", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Willensquells wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Schattenwort: Schmerz' hat pro Talentpunkt in 'Willensentzug' eine Chance von 2.0%, Euer Talent 'Willensentzug' auszulösen, wenn es Schaden verursacht, oder eine Chance von 20% pro Talentpunkt, wenn ein Ziel stirbt, während Euer 'Schattenwort: Schmerz' darauf aktiv ist. 'Innerer Fokus' hat außerdem eine Chance von 20% pro Talentpunkt, 'Willensentzug' auszulösen."},
[236507] = {name = "[q3]Seele des Zeloten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zeloten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Willensentzug' aktiv ist, verursacht Ihr 25% mehr Schattenschaden."},
[236508] = {name = "[q3]Seele des unnachgiebigen Schänders", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des unnachgiebigen Schänders wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Gedankenschinden' büßt keine Dauer mehr ein, wenn Ihr Schaden erleidet, und verschießt beim Einsatz einen kostenlosen 'Gedankenstachel' auf das Ziel."},
[236509] = {name = "[q3]Seele des Verächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Gedankenstachel' ist ein Spontanzauber, verursacht 10% mehr Schaden und kann während der Kanalisierung eines anderen Zaubers eingesetzt werden."},
[236510] = {name = "[q3]Seele des Seuchenbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Priester\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Seuchenbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Rune 'Schmerz und Leid' kann die Dauer von 'Verschlingende Seuche' erneuern."},
[236511] = {name = "[q3]Seele des Nachhallenden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Nachhallenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Zeitenleuchtfeuer währen 20% länger."},
[236512] = {name = "[q3]Seele des Chronoheilers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Chronoheilers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht alle chronomantische Heilung, die Ihr verursacht, um 10%."},
[236513] = {name = "[q3]Seele des Temporalverlangens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Temporalverlangens wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nJedes Mal, wenn Ihr ein Ziel mit Regeneration heilt, wird die verbleibende Abklingzeit von 'Zeit zurückdrehen' um 1 Sek. reduziert."},
[236514] = {name = "[q3]Seele des Präkognitiven", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Präkognitiven wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Zauber 'Arkane Geschosse' erstattet jedes Mal, wenn er Schaden verursacht, 10% seiner Grundmanakosten."},
[236515] = {name = "[q3]Seele des Arkanisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Arkanisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Arkanschlag' erhält eine zusätzliche Chance von 10%, 'Geschosssalve' auszulösen, die sich jetzt genauso auf 'Regeneration' auswirkt wie auf 'Arkane Geschosse'."},
[236516] = {name = "[q3]Seele des ewigen Hüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des ewigen Hüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure durch 'Massenregeneration' erzeugten Zeitenleuchtfeuer halten nun 21 Sek. lang an."},
[236517] = {name = "[q3]Seele des Zauberbinders", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zauberbinders wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Arkanschlag' erhöht Euren Schaden um zusätzlich 10% pro Stapel."},
[236518] = {name = "[q3]Seele des Schutzformers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schutzformers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Manaschild', 'Feuerzauberschutz' und 'Frostzauberschutz' absorbieren 50% mehr Schaden und gewähren dem Ziel für 30 Sek. 'Zeitenleuchtfeuer'."},
[236519] = {name = "[q3]Seele der Klauen des Winters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Klauen des Winters wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nErhöht die Chance, dass Eure Rune 'Eisige Finger' ausgelöst wird, um zusätzliche 15%."},
[236520] = {name = "[q3]Seele des Kryomanten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Kryomanten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den verursachten Schaden Eurer Zauber 'Frostblitz' und 'Zauberfrostblitz' um 75%."},
[236521] = {name = "[q3]Seele des Rufers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Rufers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr seid gegen jeglichen Schaden immun, während Ihr 'Hervorrufung' kanalisiert."},
[236522] = {name = "[q3]Seele des Elementaristen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Elementaristen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr einen Zauber einer anderen Magieart wirkt, erhaltet Ihr 15 Sek. lang 1% erhöhten Schaden."},
[236523] = {name = "[q3]Seele des magischen Rüstungsschmieds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des magischen Rüstungsschmieds wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Magische Rüstung' erhöht Eure Manaregeneration während des Zauberwirkens um zusätzliche 15%. 'Glühende Rüstung' erhöht Euren Zauberschaden und Heilung um 18. 'Eisrüstung' erhöht die Chance, 'Eisige Finger' auszulösen, um 20%."},
[236524] = {name = "[q3]Seele des Zündlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zündlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die von Euren Feuerzaubern verursachte Bedrohung um 20%."},
[236525] = {name = "[q3]Seele der feurigen Konvergenz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der feurigen Konvergenz wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nEuer 'Pyroschlag' fügt Zielen, die vom regelmäßigen Effekt Eures Zaubers 'Feuerball' betroffen sind, 20% mehr Schaden zu."},
[236526] = {name = "[q3]Seele der immerwährenden Flamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der immerwährenden Flamme wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer regelmäßige Effekt Eures Zaubers 'Feuerball' erhöht den von ihm verursachten Schaden im Verlauf der Effektdauer um 100% seines Aufprallschadens."},
[236527] = {name = "[q3]Seele des Pyromanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Pyromanen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Feuerschlag' gewährt zusätzlich Eurem nächsten Feuerzauber für 10 Sek. eine um 50% erhöhte kritische Trefferchance."},
[236528] = {name = "[q3]Seele des Entzünders", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Entzünders wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den von Eurem Talent 'Entzünden' verursachten Schaden um 10%."},
[236529] = {name = "[q3]Seele des Facklers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Magier\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Facklers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Schaden von 'Feuerball', 'Frostfeuerblitz' und 'Qualfeuerblitz' erhöht sich für jeden Eurer Feuereffekte auf dem Ziel um 4%, bis zu maximal 12%."},
[236530] = {name = "[q3]Seele des makellosen Blockers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des makellosen Blockers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Blockwert Eures Schildes um 30."},
[236531] = {name = "[q3]Seele des Lichthüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Lichthüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nHeilt Euch um 189 bis 211 Gesundheit, wenn Ihr blockt. Diese Heilung kann nur einmal alle paar Sekunden ausgelöst werden."},
[236532] = {name = "[q3]Seele des strahlenden Verteidigers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des strahlenden Verteidigers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Heiliger Schild' hat keine Aufladungen mehr und hält immer für die vollständige Effektdauer an. Zusätzlich wird der Schaden um 80% des Blockwerts Eures Schilds erhöht."},
[236533] = {name = "[q3]Seele des Schildträgers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schildträgers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die zusätzliche Blockchance von 'Heiliger Schild' um 10%."},
[236534] = {name = "[q3]Seele der Bastion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Bastion wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr erleidet 10% weniger Schaden, während 'Heiliger Schild' aktiv ist."},
[236535] = {name = "[q3]Seele des Abrechners", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Abrechners wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Talent 'Abrechnung' hat jetzt pro Talentpunkt eine Chance von 20%, ausgelöst zu werden, wenn Ihr blockt."},
[236536] = {name = "[q3]Seele des Gepanzerten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Gepanzerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Segen des Refugiums' erhöht beim Einsatz bei Euch selbst zusätzlich alle Werte um 10%."},
[236537] = {name = "[q3]Seele des Behüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Behüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Schild der Rechtschaffenen' macht Euren nächsten Einsatz von 'Heiliges Licht' zu einem Spontanzauber. Wenn er auf Euch selbst gewirkt wird, erstattet er 100% seiner Manakosten zurück und 'Vom Licht behütet' wirkt sich nicht darauf aus."},
[236538] = {name = "[q3]Seele des Friedensbewahrers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Friedensbewahrers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Chance für Verbündete, Euer 'Richturteil des Lichts' und 'Richturteil der Weisheit' auszulösen, auf 70%."},
[236539] = {name = "[q3]Seele des Verfeinerten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%."},
[236540] = {name = "[q3]Seele des Exemplars", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Exemplars wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Eure Fähigkeiten 'Lichtblitz', 'Heiliges Licht' oder 'Flamme des Glaubens' ein Ziel vollständig heilen, heilt Ihr zusätzlich auch alle seine Gruppenmitglieder um 189 bis 211 Gesundheit."},
[236541] = {name = "[q3]Seele des Inquisitors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Inquisitors wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance von 'Heiliger Schock' um 5%."},
[236542] = {name = "[q3]Seele des Überlegenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Überlegenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Euren durch 'Weihe' verursachten Schaden um 50%."},
[236543] = {name = "[q3]Seele des Dominus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Dominus wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDas Ziel Eurer 'Flamme des Glaubens' wird, wenn nicht Ihr selbst das seid, außerdem um 75% des Schadens geheilt, den Ihr mit 'Weihe', 'Exorzismus', 'Heiliger Schock', 'Heiliger Zorn' und 'Hammer des Zorns' verursacht."},
[236544] = {name = "[q3]Seele des Verteidigers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verteidigers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Göttliches Licht' um 25%."},
[236545] = {name = "[q3]Seele des Altruisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Altruisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Heilungen beim Ziel Eurer 'Flamme des Glaubens' heilen zusätzlich das nächste verletzte verbündete Ziel um 90% des geheilten Werts."},
[236546] = {name = "[q3]Seele des Richters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Richters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Richturteil des Lichts' und 'Richturteil der Weisheit' gewähren zusätzlich die Effekte von 'Richturteil des Kreuzfahrers'."},
[236547] = {name = "[q3]Seele des Siegelträgers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Siegelträgers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Siegel des Befehls', 'Siegel der Rechtschaffenheit', 'Siegel des Märtyrertums' und 'Sonnenlicht' verursachen 35% weniger Schaden, halten jetzt allerdings nach Einsatz eines weiteren Siegels noch 6 Sek. an, oder bis Ihr ein drittes Siegel einsetzt. 'Richturteil' kann mehrere Siegel auslösen, wenn sie aktiv sind."},
[236548] = {name = "[q3]Seele des Vollstreckers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Vollstreckers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den verursachten Schaden Eurer Zauber 'Richturteil' um 5%, und Eure Siegel auf dem Ziel werden nicht mehr verbraucht. 'Richturteil' kann nach Aktivierung mehrere Siegel auslösen."},
[236549] = {name = "[q3]Seele des Judikators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Judikators wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Richturteil' um 5 Sek., verringert jedoch den Schaden Eurer Einsätze von 'Richturteil' um 45%."},
[236550] = {name = "[q3]Seele des Aszendenten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Aszendenten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Richturteil' gewährt 8 Sek. lang 1% mehr Heiligschaden, bis zu 5-mal stapelbar."},
[236551] = {name = "[q3]Seele des Maßreglers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Maßreglers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Kreuzfahrerstoß' um 150%."},
[236552] = {name = "[q3]Seele des Exkommunikators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Exkommunikators wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure einfachen Angriffe mit zweihändigen Nahkampfwaffen erhöhen den Schaden Eures nächsten Einsatzes von 'Exorzismus' innerhalb von 20 Sek. um 35%. Bis zu 3-mal stapelbar."},
[236553] = {name = "[q3]Seele des Lichtbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Lichtbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den verursachten Schaden Eures Zaubers 'Heiliger Schock' um 50%."},
[236554] = {name = "[q3]Seele des Verbannten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verbannten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eures Zaubers 'Exorzismus' um 3 Sek. und erhöht dessen verursachten Schaden um 75%."},
[236555] = {name = "[q3]Seele des Templers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Paladin\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Templers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend Ihr eine Einhandwaffe ausgerüstet habt, entfesselt Euer 'Kreuzfahrerstoß' den Effekt von 'Richturteil' bei Euren Siegeln, ohne dabei das Siegel aufzubrauchen."},
[236556] = {name = "[q3]Seele des Windläufers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Windläufers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Euer Angriffstempo für 3 Angriffe nach dem Parieren, Ausweichen oder Blocken um 30%."},
[236557] = {name = "[q3]Seele des Schildmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schildmeisters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr pariert oder ausweicht, wird zusätzlich Eure Runenfähigkeit 'Schildmeisterschaft' aktiviert."},
[236558] = {name = "[q3]Seele des Totembeschützers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Totembeschützers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Totem der Steinhaut verringert zusätzlich den erlittenen körperlichen Schaden um 5% und Euer Totem der Windmauer verringert zusätzlich den erlittenen Magieschaden um 5%."},
[236559] = {name = "[q3]Seele des Schockabsorbers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Schockabsorbers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Flammenschock' gewährt auch eine 30% höhere Chance, zu blocken. Hält 5 Sek. lang an oder bis Ihr einen Angriff blockt."},
[236560] = {name = "[q3]Seele des spirituellen Bollwerks", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des spirituellen Bollwerks wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal wenn Ihr blockt, wird Euer Blockwert 6 Sek. lang um 10% Eures Zauberschadens erhöht. Bis zu 3-mal stapelbar."},
[236561] = {name = "[q3]Seele des Mahlstrombringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Mahlstrombringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr einen Angriff blockt, habt Ihr eine Chance von 50%, dass Eure Rune 'Waffe des Mahlstroms' ausgelöst wird."},
[236562] = {name = "[q3]Seele des Lavawandlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Lavawandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr einem Ziel mit 'Sturmschlag', 'Lavaeruption' oder 'Schmelzschlag' Schaden zufügt, verringert das zusätzlich Euren erlittenen Schaden für 10 Sek. um 10%."},
[236563] = {name = "[q3]Seele des wahren Alphas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des wahren Alphas wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr 'Geist des Alphas' auf Euch selbst wirkt, werden zusätzlich Eure Gesundheit um 5%, die von Euch erzeugte Bedrohung um 25% und sämtlicher von Euch verursachter Schaden um 5% erhöht."},
[236564] = {name = "[q3]Seele des Totemhüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Totemhüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Radius Eurer Totems, die auf verbündete Ziele wirken, ist auf 40 Meter erhöht."},
[236565] = {name = "[q3]Seele der Ahnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Ahnen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn die Zauber 'Welle der Heilung', 'Geringe Welle der Heilung' oder 'Springflut' gewirkt werden, besteht eine Chance von 25%, Mana zu gewinnen. Der Managewinn entspricht 35% der Grundkosten des Zaubers."},
[236566] = {name = "[q3]Seele des Geisterwebers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Geisterwebers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Zauber 'Welle der Heilung' springen auf bis zu zwei zusätzliche Ziele über. Bei jedem Sprung reduziert sich die Effektivität der Heilung um 60% und der Zauber springt auf bis zu 2 zusätzliche Ziele über."},
[236567] = {name = "[q3]Seele des Wasserwandlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Wasserwandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Schadens- und Heilungstreffer von nicht regelmäßigen Effekten haben jetzt eine Chance von 100%, Euren 'Wasserschild' auszulösen. Dafür verbrauchen sie weder eine Aufladung noch lösen sie die Abklingzeit aus."},
[236568] = {name = "[q3]Seele des Sturmpflegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Sturmpflegers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Kettenblitzschlag' heilt jetzt auch das Ziel Eures letzten Zaubers 'Erdschild' um 100% des verursachten Schadens."},
[236569] = {name = "[q3]Seele des Elementarsehers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Elementarsehers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Heilung von 'Kettenheilung' sowie den Schaden von 'Kettenblitzschlag' um 20%."},
[236570] = {name = "[q3]Seele des Vitalisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Vitalisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure 'Springflut' erhöht den von 'Kettenheilung' geheilten Wert um zusätzlich 25%."},
[236571] = {name = "[q3]Seele des Geisterheilers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Geisterheilers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Zauberzeit von 'Kettenheilung' um 0.5 Sek."},
[236572] = {name = "[q3]Seele des Verfeinerten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%."},
[236573] = {name = "[q3]Seele des Häuptlings", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Häuptlings wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Talent 'Schlaghagel' erhöht Euer Angriffstempo um zusätzliche 10%."},
[236574] = {name = "[q3]Seele des Zorngeladenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zorngeladenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Chance, 'Statischer Schock' auszulösen, ist um 12% erhöht (6% beim Führen von zwei Waffen)."},
[236575] = {name = "[q3]Seele des Sturmbrechers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Sturmbrechers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Waffenhandschaden von 'Sturmschlag' um 50%."},
[236576] = {name = "[q3]Seele des Orkans", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Orkans wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Statischer Schock' eingraviert ist, erhält Euer 'Blitzschlagschild' nun immer, wenn Ihr ein Ziel mit 'Blitzschlag' oder 'Kettenblitzschlag' trefft, eine Aufladung, bis zu einem Maximum von 9 Aufladungen. Zusätzlich kann Euer 'Blitzschlagschild' nun kritischen Schaden verursachen, wenn 'Statischer Schock' eingraviert ist."},
[236577] = {name = "[q3]Seele des seismischen Schmetterers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des seismischen Schmetterers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Sturmschlag' und 'Lavapeitsche' um 50%. Dieser Effekt wird bei Verwendung einer Zweihandwaffe auf 100% erhöht."},
[236578] = {name = "[q3]Seele des Flammenbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Flammenbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Treffer mit 'Sturmschlag', 'Lavapeitsche' und 'Lavaeruption' lassen Euer Ziel brennen, was ihm 30% des verursachten Schadens im Verlauf von 4 Sek. zufügt."},
[236579] = {name = "[q3]Seele des Vulkans", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Vulkans wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer mit 'Blitzschlag' haben eine Chance von 35%, die Abklingzeiten von 'Lavaeruption' und 'Kettenblitzschlag' abzuschließen und Euren nächsten Einsatz von 'Lavaeruption' oder 'Kettenblitzschlag' innerhalb von 10 Sek. zu einem Spontanzauber zu machen."},
[236580] = {name = "[q3]Seele der tobenden Flamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der tobenden Flamme wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Lavaeruption' setzt zusätzlich die Dauer Eures Effekts 'Flammenschock' auf dem Ziel wieder auf 12 Sek."},
[236581] = {name = "[q3]Seele des Elementarmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Elementarmeisters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Zaubertreffer haben jetzt eine Chance von 100%, Euer Talent 'Elementarfokus' auszulösen."},
[236582] = {name = "[q3]Seele des Stammesangehörigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Stammesangehörigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Effekt 'Treuer Beta' Eurer Fähigkeit 'Geist des Alphas' erhöht jetzt auch den Feuer-, Frost- und Naturschaden um 5 + (5 * Combopunkte)%."},
[236583] = {name = "[q3]Seele des Geisterführers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Geisterführers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Freizaubern' aktiv ist, verursacht Ihr 15 + (5 * Combopunkte)% mehr nichtkörperlichen Schaden."},
[236584] = {name = "[q3]Seele des Ältesten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Ältesten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr 'Blitzschlag', 'Kettenblitzschlag' oder 'Lavaeruption' wirkt, besteht eine Chance von 70%, Unterbrechungen durch Schaden zu vermeiden, und eine um 10% erhöhte Chance, Euer Talent 'Elementarfokus' auszulösen."},
[236585] = {name = "[q3]Seele der Elemente", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Elemente wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schadensbonus der kritischen Treffer Eurer Feuer-, Frost- und Naturzauber um 60%."},
[236586] = {name = "[q3]Seele des Lavaweisen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Lavaweisen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Schaden Eurer 'Lavaeruption' wird um einen Prozentsatz in Höhe Eurer kritischen Zaubertrefferchance erhöht."},
[236587] = {name = "[q3]Seele des Ahnenwächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Ahnenwächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 10%."},
[236588] = {name = "[q3]Seele des Verderbten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Schamane\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Verderbten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Chance, dass Eure Rune 'Kraftwoge' ausgelöst wird, um zusätzliche 5%."},
[236589] = {name = "[q3]Seele der sanften Pfote", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der sanften Pfote wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr könnt in 'Bärengestalt' oder 'Terrorbärengestalt' 'Wiedergeburt' und 'Anregen' wirken."},
[236590] = {name = "[q3]Seele des Wilden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Wilden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Wutanfall' um 30 Sek. und die Fähigkeit verringert nicht länger Eure Rüstung."},
