[236592] = {name = "[q3]Seele des Territorialen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Territorialen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Prankenhieb' (Bär) sorgt außerdem dafür, dass Euer 'Zermalmen' in den nächsten 6 Sek. 1 zusätzliches Ziel trifft."},
[236593] = {name = "[q3]Seele der Bestie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Bestie wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Zerfleischen' (Bär), 'Prankenhieb' (Bär), 'Zermalmen' und 'Aufschlitzen' haben eine um 5% erhöhte kritische Trefferchance bei Zielen, die von Eurem 'Aufschlitzen' betroffen sind."},
[236594] = {name = "[q3]Seele des Aufschlitzers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Aufschlitzers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Prankenhieb' weitet Euer 'Aufschlitzen' von Eurem Primärziel auf andere von ihm getroffene Ziele aus."},
[236595] = {name = "[q3]Seele des Rasenden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Rasenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr in Terrorbärengestalt ausweicht, erhöht sich der Schaden Eures nächsten Einsatzes von 'Zerfleischen' oder 'Prankenhieb' um 10%. Bis zu 5-mal stapelbar."},
[236596] = {name = "[q3]Seele des Zerfleischers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Zerfleischers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Zerfleischen' (Bär) um 1.5 Sek."},
[236597] = {name = "[q3]Seele des Anregers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Anregers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr 'Anregen' auf einen anderen Spielercharakter wirkt, ist auch Euer Charakter betroffen."},
[236598] = {name = "[q3]Seele des Nährers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Nährers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr Eure Zauber 'Heilende Berührung' oder 'Pflege' wirkt, erhaltet Ihr mit einer Chance von 25% Mana in Höhe von 35% der Grundkosten des Zaubers."},
[236599] = {name = "[q3]Seele des Gelassenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Gelassenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Gelassenheit' um 100% und erhöht ihre Heilung um 100%."},
[236600] = {name = "[q3]Seele des Traumwandlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Traumwandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer Eurer Heilzauber lösen den Effekt 'Traumzustand' aus und gewähren Euch 8 Sek. lang 50% Manaregeneration, während Ihr Zauber wirkt."},
[236601] = {name = "[q3]Seele des Hainhüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Hainhüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie kritischen Treffer Eurer nicht regelmäßigen Zauber verringern die Zauberzeit Eures nächsten Einsatzes von 'Heilende Berührung', 'Pflege' und 'Nachwachsen' um 0.5 Sek."},
[236602] = {name = "[q3]Seele des gefiederten Weisen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des gefiederten Weisen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Heilung durch 'Wildwuchs' um 10%. Darüber hinaus lässt sich 'Wildwuchs' nun in der Mondkingestalt einsetzen, und seine Heilung wird in dieser Gestalt zusätzlich um 50% erhöht."},
[236603] = {name = "[q3]Seele des gütigen Sehers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des gütigen Sehers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Wiedergeburt' und 'Anregen' um 65%."},
[236604] = {name = "[q3]Seele des Lebenswebers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Lebenswebers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Heilungen mit 'Heilende Berührung', 'Nachwachsen' und 'Pflege' heilen das Ziel sofort um weitere 50% der von ihnen hervorgerufenen Heilung."},
[236605] = {name = "[q3]Seele des Erleuchters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Erleuchters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Feenfeuer (Tiergestalt)' erhöht zudem die Chance für alle Angriffe, das Ziel zu treffen, 40 Sek. lang um 1%."},
