[236608] = {name = "[q3]Seele der Klaue", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Klaue wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Dauer von 'Krallenhieb' um 3 Sek. und den regelmäßigen Schaden um 10%."},
[236609] = {name = "[q3]Seele des Stolzes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Stolzes wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritische Trefferchance ist um 15% erhöht, während 'Tigerfuror' aktiv ist."},
[236610] = {name = "[q3]Seele des Barbarischen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Barbarischen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Schreddern', 'Wilder Biss' und 'Zermalmen' (Katze) verursachen 10% mehr Schaden pro Blutungseffekt auf dem Ziel, bis zu einer maximalen Steigerung von 20%."},
[236611] = {name = "[q3]Seele des Fieberhaften", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Fieberhaften wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Schreddern' hat keine Positionierungsvoraussetzung mehr, verursacht aber 5% mehr Schaden, wenn Ihr Euch hinter dem Ziel befindet."},
[236612] = {name = "[q3]Seele des Ausbluters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Ausbluters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Treffer mit 'Zerfleischen', 'Schreddern' und 'Wilder Biss' lassen Euer Ziel bluten und fügen ihm 30% des verursachten Schadens im Verlauf der nächsten 4 Sek. zu."},
[236613] = {name = "[q3]Seele des Dornenhüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Dornenhüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDurch 'Dornen' verursachter Schaden um 100% und Wirkungsdauer um 200% erhöht."},
[236614] = {name = "[q3]Seele des Irren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Irren wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure Chance auf Treffer mit Zaubern und Angriffen um 3%."},
