[236616] = {name = "[q3]Seele der Nacht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Nacht wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schadensradius und den verursachten Schaden der Sterne von 'Sternenregen' und 'Hurrikan' um 25%."},
[236617] = {name = "[q3]Seele der Bewahrer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der Bewahrer wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Einsätze von 'Zorn' haben eine Chance von 10%, ein Wäldchen aus 3 Treants zu beschwören, die Euer Ziel 15 Sek. lang angreifen."},
[236618] = {name = "[q3]Seele des Wutentbrannten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Wutentbrannten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer von 'Zorn' haben eine Chance von 50%, dass Euer nächstes 'Sternenfeuer' 10% mehr Schaden verursacht und sich bis zu 3-mal stapeln lässt."},
[236619] = {name = "[q3]Seele des Anmutigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Anmutigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Talent 'Anmut der Natur' erhält jedes Mal, wenn es ausgelöst wird, 1 zusätzliche Aufladung."},
[236620] = {name = "[q3]Seele des astralen Aszendenten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des astralen Aszendenten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schadensbonus für kritische Treffer Eurer Zauber 'Sternenfeuer', 'Sternensog' und 'Zorn' um 60%."},
[236621] = {name = "[q3]Seele des Kometenrufers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Kometenrufers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Zauberzeit und globale Abklingzeit von 'Sternenfeuer' um 0.5 Sek."},
[236622] = {name = "[q3]Seele des Waldes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele des Waldes wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance von 'Zorn' um 10%."},
[236623] = {name = "[q3]Seele der animalischen Expertise", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Druide\nBenötigt Stufe 55\n[q2]Benutzen: Die Seele der animalischen Expertise wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Chance, dass Eure Nahkampfangriffe pariert werden oder ihnen ausgewichen wird, ist um 5% verringert."},
[236642] = {name = "[q4]Heilerhandlappen", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Hände} {Stoff}\n81 Rüstung\n[q2]<Zufällige Verzauberung>\n+8 Ausdauer\n+17 Intelligenz\n+10 Willenskraft\nHaltbarkeit 35 / 35\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 70 und den verursachten Schaden um bis zu 24."},
[236643] = {name = "[q4]Handschuhe des Nachtwächters", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Hände} {Leder}\n155 Rüstung\n[q2]<Zufällige Verzauberung>\n+7 Intelligenz\nHaltbarkeit 40 / 40\nBenötigt Stufe 60\n[q2]Anlegen: Verbessert Eure Chance auf Treffer mit allen Zaubern und Angriffen um 2%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 37."},
[236644] = {name = "[q4]Handschützer des Trauernden", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Hände} {Kette}\n338 Rüstung\n[q2]<Zufällige Verzauberung>\n+7 Intelligenz\nHaltbarkeit 50 / 50\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht Euer Zaubertempo um 2%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 70 und den verursachten Schaden um bis zu 24."},
[236645] = {name = "[q4]Handschuhe des Lichtwirkers", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Hände} {Platte}\n602 Rüstung\n[q2]<Zufällige Verzauberung>\n+8 Ausdauer\n+17 Intelligenz\nHaltbarkeit 55 / 55\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht Euer Zaubertempo um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 70 und den verursachten Schaden um bis zu 24."},
[236656] = {name = "[q3]Gefrorene Rune", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Absorbiert 3500 bis 4500 Feuerschaden. Hält 1 Stunde lang an. (3 Min Abklingzeit)"},
[236657] = {name = "[q3]Blubbis modernder Ast", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verwandelt Euch 5 Min. lang in einen Ghul. (15 Min Abklingzeit)"},
[236658] = {name = "[q3]Blubbis Rückgrattrophäe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verwandelt Euch für 5 Min. in ein Skelett. (15 Min Abklingzeit)"},
