[238357] = {name = "[q4]Stab von Balzaphon", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{176 - 265 Schaden} {Tempo 3.90}\n(56.54 Schaden pro Sekunde)\n+8 Ausdauer\n+10 Intelligenz\n+7 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 55\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Frostzauber und Frosteffekte zugefügten Schaden um bis zu 47."},
[238358] = {name = "[q4]Schwarzstahls Oberschenkelknochen", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+12 Ausdauer\n+13 Willenskraft\nBenötigt Stufe 57\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 16."},
[238360] = {name = "[q4]Fürst Schwarzstahls Rundschild", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n2362 Rüstung\n42 Blocken\n+10 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 57\n[q2]Anlegen: Erhöht den Blockwert Eures Schilds um 32."},
[238361] = {name = "[q4]Fürst Schwarzstahls Klinge", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Schwert}\n{40 - 76 Schaden} {Tempo 1.30}\n(44.62 Schaden pro Sekunde)\n+10 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 57\n[q2]Anlegen: Verteidigung +9."},
[238362] = {name = "[q4]Armschienen der Heilung", additional_info = "Wird beim Aufheben gebunden\n{Handgelenke} {Stoff}\n42 Rüstung\n+5 Ausdauer\n+8 Intelligenz\n+13 Willenskraft\nHaltbarkeit 35 / 35\nBenötigt Stufe 57\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 33 und den verursachten Schaden um bis zu 11."},
[238363] = {name = "[q4]Griff des Schattens", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Stoff}\n60 Rüstung\n+14 Ausdauer\n+14 Intelligenz\nHaltbarkeit 35 / 35\nBenötigt Stufe 57\n[q2]Anlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 34."},
[238364] = {name = "[q4]Revanchions Umhang", additional_info = "Wird beim Aufheben gebunden\nRücken\n49 Rüstung\n+13 Stärke\n+13 Beweglichkeit\n+12 Ausdauer\nBenötigt Stufe 58"},
[238637] = {name = "Pirschersteak", additional_info = "Benötigt Stufe 55\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. 2550 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 25 Stärke und 10 Ausdauer."},
[238638] = {name = "Filet aus der Flanke", additional_info = "Benötigt Stufe 55\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. 2550 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 25 Beweglichkeit und 10 Ausdauer."},
[238639] = {name = "Morgengrauenomelett", additional_info = "Benötigt Stufe 55\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. 2550 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 29 Zauberschaden, 55 Heilkraft und 10 Ausdauer."},
[238641] = {name = "[q2]Fleckfinnenfestmahl", additional_info = "Benötigt Stufe 55\n[q2]Benutzen: Serviert ein vorzügliches Festmahl, das 3 Min. lang bestehen bleibt und bis zu 40 Spielercharaktere verköstigen kann.\n\n Essen\nStellt im Verlauf von 30 Sek. 2550 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 45 Min. lang 40 Angriffskraft, 23 Zauberschaden, 44 Heilkraft und 10 Ausdauer. (5 Min Abklingzeit)"},
[238642] = {name = "[q2]Großes Hummerbankett", additional_info = "Benötigt Stufe 55\n[q2]Benutzen: Serviert ein vorzügliches Festmahl, das 3 Min. lang bestehen bleibt und bis zu 40 Spielercharaktere verköstigen kann.\n\n Essen\nStellt im Verlauf von 30 Sek. 2550 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 45 Min. lang 40 Angriffskraft, 23 Zauberschaden, 44 Heilkraft und 10 Ausdauer. (5 Min Abklingzeit)"},
[238645] = {name = "Rezept: Pirschersteak", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (250)\n[q]\"Lehrt Euch, wie man ein Pirschersteak zubereitet.\""},
[238646] = {name = "Rezept: Filet aus der Flanke", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (250)\n[q]\"Lehrt Euch, wie man ein Filet aus der Flanke zubereitet.\""},
[238647] = {name = "Rezept: Morgengrauenomelett", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (250)\n[q]\"Lehrt Euch, wie man ein Morgengrauenomelett zubereitet.\""},
[238649] = {name = "Rezept: Fleckfinnenfestmahl", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\n[q]\"Lehrt Euch, wie man ein Fleckfinnenfestmahl zubereitet.\""},
[238650] = {name = "Rezept: Großes Hummerbankett", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\n[q]\"Lehrt Euch, wie man ein großes Hummerbankett zubereitet.\""},
