[238734] = {name = "[q2]Tüftelkiste: Teleportation", additional_info = "Benötigt Stufe 45\n[q2]Benutzen: Teleportiert Euch 20 Meter vorwärts."},
[238735] = {name = "[q2]Tüftelkiste: Nitrobooster", additional_info = "Benötigt Stufe 45\n[q2]Benutzen: Aktiviert eine Reihe von Strahlen, um Eure Bewegungsgeschwindigkeit für bis zu 8 Sek. um bis zu 160% zu erhöhen."},
[238736] = {name = "[q2]Tüftelkiste: Magnetversetzung", additional_info = "Benötigt Stufe 45\n[q2]Benutzen: Unterbricht ein Magnetfeld zwischen Euch und Eurem gegnerischen Ziel in der Nähe und schleudert Euch beide fort.\n\n Kann nur Ziele bis zu 2 Stufen über Euch betreffen. Einige Ziele können nicht versetzt werden. Ziele können nur einmal alle 2 Min. von diesem Effekt betroffen werden."},
[238737] = {name = "Tüftelkiste", additional_info = "Handwerksmaterial\n[q]\"Ein einfaches Kontrollmodul das von Ingenieuren beim Herstellen von Tüfteleien verwendet wird.\""},
[238781] = {name = "[q2]Halbwegs sicherer Transporter: Neu-Avalon", additional_info = "Wird bei Benutzung gebundenSchmuck\nBenötigt Stufe 60\nBenötigt Ingenieurskunst (290)\n[q2]Benutzen: Werft jede Vorsicht über Bord und probiert das Teleportationsgerät eines Goblins aus. Hoffentlich kommt Ihr in einem Stück in Neu-Avalon an. (4 Std. Abklingzeit)"},
[238782] = {name = "Bauplan: Tüftelkiste", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (250)\n[q]\"Lehrt Euch, wie man eine Tüftelkiste herstellt.\""},
[238783] = {name = "[q2]Bauplan: Tüftelkiste: Teleportation", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (260)\n[q]\"Lehrt Euch, wie man die Tüftelkiste: Teleportation herstellt.\""},
[238784] = {name = "[q2]Bauplan: Tüftelkiste: Nitrobooster", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (260)\n[q]\"Lehrt Euch, wie man die Tüftelkiste: Nitrobooster herstellt.\""},
[238785] = {name = "[q2]Bauplan: Tüftelkiste: Magnetversetzung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (260)\n[q]\"Lehrt Euch, wie man die Tüftelkiste: Magnetversetzung herstellt.\""},
[238786] = {name = "[q3]Bauplan: Tüftelei: Teleportation", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (280)\n[q2]Verbessert Euren Gürtel, damit er folgenden Effekt bietet:\n\nTeleportiert Euch 20 Meter vorwärts.\n[q]\"Lehrt Euch, wie man die Tüftelei: Teleportation herstellt.\""},
[238787] = {name = "[q3]Bauplan: Tüftelei: Nitrobooster", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (280)\n[q2]Verbessert Euren Gürtel, damit er folgenden Effekt bietet:\n\nAktiviert eine Reihe von Strahlen, um Eure Bewegungsgeschwindigkeit für bis zu 8 Sek. um bis zu 160% zu erhöhen.\n[q]\"Lehrt Euch, wie man die Tüftelei: Nitrobooster herstellt.\""},
[238788] = {name = "[q3]Bauplan: Tüftelei: Magnetversetzung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (280)\n[q2]Verbessert Euren Gürtel, damit er folgenden Effekt bietet:\n\nUnterbricht ein Magnetfeld zwischen Euch und Eurem gegnerischen Ziel in der Nähe und schleudert Euch beide fort.\n\n Kann nur Ziele bis zu 2 Stufen über Euch betreffen. Einige Ziele können nicht versetzt werden. Ziele können nur einmal alle 2 Min. von diesem Effekt betroffen werden.\n[q]\"Lehrt Euch, wie man die Tüftelei: Magnetversetzung herstellt.\""},
[238789] = {name = "[q3]Bauplan: Halbwegs sicherer Transporter: Neu-Avalon", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (300)\n[q]\"Lehrt Euch, wie man einen halbwegs sicheren Transporter: Neu-Avalon herstellt.\""},
[238794] = {name = "Widerwärtige Essensreste", additional_info = "Questgegenstand\n[q]\"Vielleicht ist der Hungertod doch eine Option.\""},
[238811] = {name = "Saftiger Apfel", additional_info = "Questgegenstand\n[q]\"Frisch vom Feld.\""},
[238830] = {name = "Apfelfernrohr", additional_info = "Questgegenstand\n[q2]Benutzen: Ermöglicht Euch, auf der Suche nach Äpfeln in weite Entfernungen zu sehen.\n[q]\"Wird von den faulsten Bauern dazu verwendet, aus dem Komfort der eigenen vier Wände die Ernte zu beaufsichtigen.\""},
[238831] = {name = "Apfelseil", additional_info = "Questgegenstand\n[q2]Benutzen: Stehlt einen Apfel aus sicherer Entfernung.\n[q]\"Ist nur ein einfaches Seil.\""},
[238899] = {name = "Erlesener Fisch", additional_info = "Questgegenstand\n[q]\"Eure Angelfertigkeiten sind nicht ausgeprägt genug, um einen Großteil dieser Fische zu identifizieren. Glücklicherweise ist das nicht Euer Problem.\""},
[238925] = {name = "[q4]Scharlachroter Köcher", additional_info = "Wird beim Anlegen gebunden\n30 Platz Köcher\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht das Distanzangriffstempo um 15%."},
[238926] = {name = "[q4]Scharlachroter Munitionsbeutel", additional_info = "Wird beim Anlegen gebunden\n30 Platz Munitionsbeutel\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht das Distanzangriffstempo um 15%."},
[238927] = {name = "[q2]Muster: Scharlachroter Köcher", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (275)\n[q]\"Lehrt Euch, wie man einen scharlachroten Köcher herstellt.\""},
[238928] = {name = "[q2]Muster: Scharlachroter Munitionsbeutel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (275)\n[q]\"Lehrt Euch, wie man einen scharlachroten Munitionsbeutel herstellt.\""},
[238935] = {name = "Sanft gequältes Fleisch", additional_info = "Questgegenstand\n[q]\"Wenn Ihr die grünen Stellen wegschneidet, wird schon keiner was bemerken.\""},
[238945] = {name = "[q4]Caladbrocken", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{334 - 501 Schaden} {Tempo 4.30}\n(97.09 Schaden pro Sekunde)\n+30 Stärke\n+10 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 300 / 300\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Trefferchance: Das Gewicht von Caladbrocken wirft 4 Sek. lang alle Gegnern in der Nähe zu Boden.\n[q2]Anlegen: Bewegungsgeschwindigkeit um 10% verringert.\n[q]\"Das Schwert und der Stein\""},
[238960] = {name = "Rüstmeisterkiste", additional_info = "Questgegenstand\n[q2]Benutzen: Legt ein Teil hergestellter Ausrüstung des Scharlachroten Kreuzzugs in die Kiste. Der Gegenstand wird dadurch dauerhaft vernichtet."},
[238961] = {name = "[q4]Caladschneide", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Schwert}\n{339 - 509 Schaden} {Tempo 3.90}\n(108.72 Schaden pro Sekunde)\n+50 Stärke\n+15 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 2%.\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Benutzen: Die Caladschneide wird 20 Sek. lang erneut von der Erde verschlungen, wodurch die Bewegungsgeschwindigkeit um 50% verringert wird. Wenn Ihr Euch bewegt, erhöht sich Eure Bewegungsgeschwindigkeit alle 2 Sekunden. Wenn Ihr in einen Gegner kracht, fügt Ihr diesem 300 bis 2700 Feuerschaden zu, wobei Ihr alle gegnerischen Spielercharaktere zurückstoßt und diesen Effekt beendet. (2 Min Abklingzeit)\n[q]\"Eine uralte Klinge, die vom Scharlachroten Kreuzzug geheim gehalten wird. Weist leichte Gebrauchsspuren auf.\""},
[238985] = {name = "Schwere Kiste", additional_info = "Questgegenstand\n[q]\"Bringt sie zum scharlachroten Rüstmeister, um Euren Wert zu beweisen.\""},
[239010] = {name = "[q4]Griff des Aschenbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n{99 - 162 Schaden} {Tempo 2.00}\n(65.25 Schaden pro Sekunde)\nHaltbarkeit 15 / 15\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Benutzen: Versucht, Kontakt zum Willen des Aschenbringers aufzunehmen. (4 Min Abklingzeit)"},
[239011] = {name = "[q5]Splitter kristallisierten Lichts", additional_info = "Wird beim Aufheben gebunden"},
[239012] = {name = "[q5]Span kristallisierten Lichts", additional_info = "Wird beim Aufheben gebunden"},
[239013] = {name = "[q5]Kristalline Axt", additional_info = "Wird beim Aufheben gebunden\n[q]\"Klingen des Lichts, wahrhaftig.\""},
[239016] = {name = "Weihsalz", additional_info = "Handwerksmaterial\n[q]\"Wird häufig von des Kreuzzüglern verwendet, um Unglück zu vertreiben. Lässt sich praktischerweise auch gut zum Kochen verwenden.\""},
[239017] = {name = "[q2]Erlesene Gewürze", additional_info = "Handwerksmaterial\n[q]\"Eine hochgradig regulierte Ware. Der direkte Kauf oder Verkauf wäre unklug. Wird von Köchen begehrt, die Festmahle zubereiten.\""},
[239021] = {name = "Carries Kochbuch", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\n[q2]Benutzen: Lehrt Euch, wie man die begehrtesten Festtagsrezepte von Carrie Herdfeuer kocht."},
[239060] = {name = "[q4]Wille des Berges", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Streitkolben}\n{169 - 316 Schaden} {Tempo 2.90}\n(83.62 Schaden pro Sekunde)\n+17 Stärke\n+5 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Trefferchance: Ruft den Willen des Berges an, wodurch der verursachte körperliche Schaden 15 Sek. lang um 5%, die Rüstung um 500 und die Größe um 20% erhöht werden.\n[q]\"Einst ein mächtiger Schmiedehammer, ist dieses wahrhaft erstaunliche Stück Handwerkskunst noch inspirierender, wenn man ihn in Händen hält.\""},
[239092] = {name = "Bescheuert beschrifteter Brief", additional_info = "Questgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest."},
[239097] = {name = "[q3]Schlüssel zur Kathedrale", additional_info = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig"},
[239117] = {name = "[q4]Kelch des des Kreuzzüglers", additional_info = "Wird beim Aufheben gebunden\n[q]\"Bringt ihn zusammen mit einem entsprechenden Gegenstand aus dem herstellbaren Set des scharlachroten des Kreuzzüglers zu Byron Steelblade in Neu-Avalon, um ihn gegen einen Klassensetgegenstand einzutauschen.\""},
[239119] = {name = "Heiliger Pfeil", additional_info = "Questgegenstand\n[q]\"Geheiligt sei der Pfeil, der unseren Feinden ihre Buße zukommen lässt.\""},
[239123] = {name = "[q0]Monster - BOW_1H_STANDARD_C_01 - Red", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Bogen}\n{1 - 2 Schaden} {Tempo 2.00}\n(0.75 Schaden pro Sekunde)\nHaltbarkeit 18 / 18"},
