[239149] = {name = "[q3]Muster: Kreuzzüglerknappsack", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (250)\n[q]\"Lehrt Euch, wie man einen Kreuzzüglerknappsack herstellt.\""},
[239150] = {name = "[q4]Muster: Blutrote Morgengespinsttasche", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (290)\n[q]\"Lehrt Euch, wie man eine blutrote Morgengespinsttasche herstellt.\""},
[239159] = {name = "[q2]S03 - Scharlachrote Enklave - Schild des Hauptmanns", additional_info = "Wird beim Anlegen gebunden\n{Schild}hand} {Schild}\n1861 Rüstung\n35 Blocken\n+3 Stärke\n+14 Ausdauer\nHaltbarkeit 85 / 85\nBenötigt Stufe 56"},
[239196] = {name = "[q5]Verdorbene lichtgeschmiedete Klinge", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nKlassen: Krieger , Paladin , Jäger"},
[239197] = {name = "[q4]Neugeschmiedete Klinge des Aschenbringers", additional_info = "Wird beim Aufheben gebunden"},
[239215] = {name = "[q4]Verkohltes Emblem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60"},
[239216] = {name = "[q5]Lichtgeschmiedetes Eisen", additional_info = "Wird beim Aufheben gebunden\nKlassen: Krieger , Paladin , Jäger"},
[239218] = {name = "[q5]Notizen der Steinformer", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Das Dokument ist in einer unsauberen Kurzschrift verfasst, doch was Ihr davon ausmachen könnt, legt nahe, dass diese Pläne und Projektnotizen das Produkt eines wahrhaft genialen Handwerkers sind.\""},
[239219] = {name = "[q4]Emblem des Aschenbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\n[q2]Benutzen: Kombiniert das Emblem des Aschenbringers, die neugeschmiedete Klinge des Aschenbringers und den Griff des Aschenbringers."},
[239221] = {name = "[q0]Monster - Sword1H, Basic", additional_info = "{Waffenhand} {Schwert}\n{1 - 2 Schaden} {Tempo 2.00}\n(0.75 Schaden pro Sekunde)\nHaltbarkeit 20 / 20"},
[239222] = {name = "[q3]Bauplan: Aufstellbäumchen", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (250)\n[q]\"Lehrt Euch, wie man ein Aufstellbäumchen herstellt.\""},
[239223] = {name = "Hausrequisite", additional_info = "Questgegenstand\n[q]\"Wirklich überzeugend, zumindest im Kontext einer Aufführung oder Oper.\""},
[239225] = {name = "Stilvoller Federkiel", additional_info = "Questgegenstand\n[q]\"Ihr könnt Euch kaum vorstellen, wie befriedigend es sein muss, die eigene Unterschrift damit zu setzen.\""},
[239246] = {name = "Zischluntes Einkaufsliste", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Eine Liste mit Gegenständen, die der Autor wie sie ihm in den Sinn kamen niedergeschrieben hat.\"\n[q2]<Zum Lesen rechtsklicken>"},
[239248] = {name = "[q4]Scharlachrote Plunderkiste", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält allerlei rumliegenden Plunder. Manchmal allerdings auch etwas Wertvolles von einem tollkühnen Abenteurer.\"\n[q2]<Zum Öffnen rechtsklicken>"},
[239292] = {name = "Forgewrights Notizen", additional_info = "Questgegenstand\nEinzigartig\n\"Enthält die gesammelten Gedanken und Werke von Franclorn Forgewright.\""},
[239301] = {name = "[q5]Verderbter Aschenbringer", additional_info = "Geweiht\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n{357 - 536 Schaden} {Tempo 3.80}\n(117.50 Schaden pro Sekunde)\n+53 Stärke\n-30 Ausdauer\nHaltbarkeit 145 / 145\nBenötigt Stufe 60\n[q2]Anlegen: Der Träger wird vom Willen des Aschenbringers erfüllt.\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\n[q2]Trefferchance: Stiehlt 475 bis 525 Gesundheit von bis zu 5 Gegnern und gewährt Euch pro betroffenem Gegner 30 Stärke oder Beweglichkeit. Bis zu 5-mal stapelbar.\n[q]\"Klinge des Scharlachroten Hochlords\""},
[239302] = {name = "Gürtel der scharlachroten Uniform", additional_info = "Questgegenstand\n[q]\"Ein dichter Lederriemen mit einer schweren Stahlschnalle. Ein wahrhaft meisterhafter Gürtel, der bereit dafür ist, durch skrupellose Tüfteleien verschandelt zu werden.\""},
[239316] = {name = "Triangulationssamophlang", additional_info = "Questgegenstand\nBenötigt Ingenieurskunst (1)\n[q2]Benutzen: Verwendet das Gerät an einem designierten Triangulationspunkt, um Zischlunte bei der Kalibrierung seines Teleporters zu helfen. (10 Sek. Abklingzeit)"},
[239512] = {name = "[q4]Handgelenke des Lichtbrechers", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Handgelenke} {Platte}\n477 Rüstung\n+29 Stärke\n+10 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 55 / 55\nKlassen: Krieger\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 1%.\n\n[q]Kriegsplatte des Lichtbrechers (0/8)\n[q0]Großhelm des Lichtbrechers\nSchultern des Lichtbrechers\nKürass des Lichtbrechers\nGürtel des Lichtbrechers\nTassetten des Lichtbrechers\nSchienbeinschützer des Lichtbrechers\nHandgelenke des Lichtbrechers\nHandschutz des Lichtbrechers\n[q0](2) Set : Der Schaden Eurer Fähigkeiten 'Heldenhafter Stoß', 'Spalten' und 'Rasanter Schlag' ist um 20% erhöht, während Ihr Euch in Kampfhaltung oder Berserkerhaltung befindet. Eure Fähigkeit 'Spalten' trifft 1 $|zusätzliches Ziel:zusätzliche Ziele; und kann 'Blutwoge' auslösen.\n(4) Set : Immer, wenn Ihr ein Ziel mit 'Wirbelwind' 'Heldenhafter Stoß', 'Rasanter Schlag' oder 'Spalten' trefft, wird der Schaden Eures nächsten Einsatzes von 'Zerschmettern' um 20% erhöht. Bis zu 5-mal stapelbar.\n(6) Set : Jedes Mal, wenn 'Tiefe Wunden' Schaden verursacht, wird die verbleibende Abklingzeit von 'Wirbelwind' um 3 Sek. verringert. 'Wirbelwind' fügt Zielen, die von Eurem Effekt 'Tiefe Wunden' betroffen sind, 100% mehr Schaden zu."},
