[239694] = {name = "[q4]Schwur des Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Beschwört Climgefahr, das Reittier der Hochkommandantin. Geschwindigkeit um 100% erhöht.\n[q]\"Lernt, wie Ihr Climgefahr, das Reittier des Hochgenerals, beschwört oder wieder freigebt. Dies ist ein sehr schnelles Reittier.\""},
[239695] = {name = "[q4]Scharlachrotes Ross", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\n[q2]Benutzen: Beschwört ein reitbares scharlachrotes Ross oder gibt es frei. Das ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)"},
[239696] = {name = "[q5]Griff des Aschenbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nHaltbarkeit 15 / 15\nBenötigt Stufe 60\n[q]\"Selbst in Stücke geschlagen scheint diese Klinge eine Aura düsteren Unheils zu verströmen.\""},
[239698] = {name = "Morgengespinststoff", additional_info = "Questgegenstand\n[q]\"Kleine Stofffetzen und Fäden, die auf geheimnisvolle Weise zum Webstuhl des Kreuzzüglers gezogen wurden. Werden scheinbar verwendet, um heilige Gewänder herzustellen.\""},
