[239764] = {name = "Purpurrotes Messerblatt", additional_info = "Questgegenstand\n[q]\"Ein leuchtend roter Farbstoff, der aus allem extrahiert wird, mit Ausnahme der frisch erblühten Blätter eines Messerblatts.\""},
[240018] = {name = "Zischluntes Tüftelhandbuch", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (250)\n[q2]Benutzen: Lehrt Euch, wie man Gürtel mit wiederverwendbaren Tüfteleien verbessert.\n[q]\"Eigentum von Zischlunte.\""},
[240020] = {name = "[q4]Beinschützer der Inquisition", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Beine} {Platte}\n954 Rüstung\n+17 Ausdauer\n+24 Intelligenz\nHaltbarkeit 120 / 120\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Erhöht Euer Zaubertempo um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 99 Gesundheit und den verursachten Schaden um bis zu 33.\n\n[q]Rüstung der Inquisition (0/8)\n[q0]Kopfstück der Inquisition\nSchiftung der Inquisition\nTunika der Inquisition\nGurt der Inquisition\nBeinschützer der Inquisition\nStiefel der Inquisition\nHandgelenksschutz der Inquisition\nHandschützer der Inquisition\n[q0](2) Set : 'Handauflegung' gewährt Euch 30 Sek. lang 20% Zaubertempo und verringert die globale Abklingzeit Eurer nächsten 5 Einsätze von 'Göttliches Licht', 'Heiliges Licht', 'Lichtblitz' und 'Heiliger Schock' um 0.5 Sek.\n(4) Set : Eure 'Flamme des Glaubens' wird jetzt auch ausgelöst, wenn Ihr das Ziel Eurer 'Flamme des Glaubens' heilt, allerdings mit 50% verringerter Effektivität.\n(6) Set : 25% Eurer verursachten Heilung werden zusätzlich auf das Ziel Eurer 'Flamme des Glaubens' übertragen."},
[240021] = {name = "[q4]Schiftung der Inquisition", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Schulter} {Platte}\n818 Rüstung\n+13 Ausdauer\n+14 Intelligenz\nHaltbarkeit 100 / 100\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Anlegen: Erhöht Euer Zaubertempo um 2%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 64 und den verursachten Schaden um bis zu 22.\n\n[q]Rüstung der Inquisition (0/8)\n[q0]Kopfstück der Inquisition\nSchiftung der Inquisition\nTunika der Inquisition\nGurt der Inquisition\nBeinschützer der Inquisition\nStiefel der Inquisition\nHandgelenksschutz der Inquisition\nHandschützer der Inquisition\n[q0](2) Set : 'Handauflegung' gewährt Euch 30 Sek. lang 20% Zaubertempo und verringert die globale Abklingzeit Eurer nächsten 5 Einsätze von 'Göttliches Licht', 'Heiliges Licht', 'Lichtblitz' und 'Heiliger Schock' um 0.5 Sek.\n(4) Set : Eure 'Flamme des Glaubens' wird jetzt auch ausgelöst, wenn Ihr das Ziel Eurer 'Flamme des Glaubens' heilt, allerdings mit 50% verringerter Effektivität.\n(6) Set : 25% Eurer verursachten Heilung werden zusätzlich auf das Ziel Eurer 'Flamme des Glaubens' übertragen."},
[240022] = {name = "[q4]Stiefel der Inquisition", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Füße} {Platte}\n749 Rüstung\n+13 Ausdauer\n+15 Intelligenz\nHaltbarkeit 75 / 75\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht Euer Zaubertempo um 2%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 68 und den verursachten Schaden um bis zu 23.\n\n[q]Rüstung der Inquisition (0/8)\n[q0]Kopfstück der Inquisition\nSchiftung der Inquisition\nTunika der Inquisition\nGurt der Inquisition\nBeinschützer der Inquisition\nStiefel der Inquisition\nHandgelenksschutz der Inquisition\nHandschützer der Inquisition\n[q0](2) Set : 'Handauflegung' gewährt Euch 30 Sek. lang 20% Zaubertempo und verringert die globale Abklingzeit Eurer nächsten 5 Einsätze von 'Göttliches Licht', 'Heiliges Licht', 'Lichtblitz' und 'Heiliger Schock' um 0.5 Sek.\n(4) Set : Eure 'Flamme des Glaubens' wird jetzt auch ausgelöst, wenn Ihr das Ziel Eurer 'Flamme des Glaubens' heilt, allerdings mit 50% verringerter Effektivität.\n(6) Set : 25% Eurer verursachten Heilung werden zusätzlich auf das Ziel Eurer 'Flamme des Glaubens' übertragen."},
[240023] = {name = "[q4]Unterarmschienen der Inquisition", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Handgelenke} {Platte}\n477 Rüstung\n+29 Stärke\n+10 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 55 / 55\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n\n[q]Kriegsplatte der Inquisition (0/8)\n[q0]Helm der Inquisition\nSchulterplatten der Inquisition\nBrustplatte der Inquisition\nGürtel der Inquisition\nGamaschen der Inquisition\nSchienbeinschützer der Inquisition\nUnterarmschienen der Inquisition\nHandschuhe der Inquisition\n[q0](2) Set : Während Ihr eine Zweihandwaffe ausgerüstet habt, gewähren Euch 'Kreuzfahrerstoß' und 'Exorzismus' Heilige Kraft und erhöhen den von Euch verursachten Heiligschaden um 10%. Bis zu 3-mal stapelbar. (100ms Abklingzeit)\n(4) Set : Euer 'Göttlicher Sturm', 'Heiliger Schock' und 'Heiliger Zorn' verbrauchen Eure gesamte Heilige Kraft und verursachen 100% mehr Schaden pro angesammelter Heiliger Kraft. Hat gegen Ziele, die von Spielercharakteren kontrolliert werden, eine Effektivität von 50%.\n(6) Set : Wenn Ihr Heilige Kraft verbraucht, wird Eure Angriffskraft 10 Sek. lang um 15% pro verbrauchter Heiliger Kraft erhöht."},
