[240837] = {name = "[q4]Schicksalsfäden", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Bogen}\n{177 - 330 Schaden} {Tempo 3.60}\n(70.42 Schaden pro Sekunde)\n+21 Beweglichkeit\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Chance von 10%, dass Distanzangriffe einen Schicksalsstrang erzeugen, sodass Ihr aus der Bewegung heraus einen Distanzangriff einsetzen könnt. Stränge können bis zu 5-mal gestapelt werden und halten 20 Sek. lang an.\n[q2]Benutzen: Erzeugt sofort 3 Schicksalsstränge. (1 Min, 20 Sek. Abklingzeit)"},
[240839] = {name = "[q4]Thal'kituun, der ungesehene Gast", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Dolch}\n{23 - 84 Schaden} {Tempo 1.30}\n(41.15 Schaden pro Sekunde)\n100 Rüstung\n+15 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 144.\n[q2]Anlegen: Verteidigung +7."},
[240841] = {name = "[q4]Wache der Hochkommandantin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\n{Waffenhand} {Schwert}\n{70 - 131 Schaden} {Tempo 1.20}\n(83.75 Schaden pro Sekunde)\n+14 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\n[q2]Anlegen: Verteidigung +12.\n[q2]Anlegen: Schwerter +3.\n[q2]Trefferchance: Erhöht 10 Sek. lang die Verteidigung um 20 und die Rüstung um 750."},
[240842] = {name = "[q4]Scharlachroter Seuchenbringer", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{157 - 236 Schaden} {Tempo 3.60}\n(54.58 Schaden pro Sekunde)\n150 Rüstung\n+24 Stärke\n+14 Beweglichkeit\n+48 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\n[q2]Anlegen: Verteidigung +7.\n[q2]Anlegen: Bei einem Nahkampfangriff besteht die Chance, Euren Gegner mit einer Seuche zu belegen, wodurch Gegner innerhalb von 8 Metern um den Zaubernden 12 Sek. lang alle 2 Sek. 100 Naturschaden erleiden. Das Angriffstempo dieser Ziele wird zudem um 15% verringert.\n[q2]Anlegen: +756 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
[240843] = {name = "[q4]Starterpistole", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Schusswaffe}\n{91 - 170 Schaden} {Tempo 2.00}\n(65.25 Schaden pro Sekunde)\n+11 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Anlegen: Verteidigung +7.\n[q2]Anlegen: Ein regulärer Distanzangriff auf ein Ziel bereitet Euch auf die Schlacht vor, wodurch 15 Sek. lang Eure Verteidigung um 20 und Euer Nahkampfangriffstempo um 10% erhöht wird."},
[240844] = {name = "[q4]Putress' Stecken", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Zauberstab}\n{159 - 296 Feuerschaden} {Tempo 1.50}\n(151.67 Schaden pro Sekunde)\n50 Rüstung\n+18 Ausdauer\nHaltbarkeit 75 / 75\nKlassen: Hexenmeister\nBenötigt Stufe 60\n[q2]Anlegen: Verteidigung +5.\n[q2]Benutzen: Verringert die Zauberzeit und die globale Abklingzeit von 'Sengender Schmerz' und 'Schattenspalten' 15 Sek. lang um 0.5 Sek. (2 Min Abklingzeit)"},
[240845] = {name = "Prototypmagnet", additional_info = "Questgegenstand\n[q2]Benutzen: Enthüllt Euren Prototypmagneten kurz und überlädt ihn, um zu versuchen, lose Metallobjekte zu erfassen. (8 Sek. Abklingzeit)"},
[240846] = {name = "Magnetischer Schrott", additional_info = "Questgegenstand\n[q]\"Des einen Müll ist des anderen Schatz, ob er will, oder nicht!\""},
