[240853] = {name = "[q0]Königinnensturz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\n{Einhändig} {Dolch}\n{123 - 229 Schaden} {Tempo 2.10}\n(83.81 Schaden pro Sekunde)\n+19 Beweglichkeit\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: [ S03 - Tuning and Overrides Passive - Krieger : Eure kritischen Treffer mit 'Blutdurst', Tödlicher Stoß', 'Heldenhafter Stoß' und 'Spalten' setzen die Dauer Eures Effekts 'Verwunden' auf dem Ziel auf 21 Sek ] [ Rogue Passive (DND) : Eure kritischen Treffer mit 'Meucheln', 'Verstümmeln' und 'Säbelschlitzer' setzen die Dauer Eurer 'Blutung' auf dem Ziel auf 16 Sek. und Eurer Fähigkeit 'Blutroter Sturm' auf dem Ziel auf 12 Sek ] [ S03 - Tuning and Overrides Passive - Jäger : Eure kritischen Treffer mit 'Raptorstoß' und 'Mungobiss' setzen die Dauer Eure Effekts 'Schlangenbiss' auf dem Ziel auf 15 Sek / Ihr werdet niemals würdig genug sein, um in den Nutzen dieser Klinge zu gelangen. ]\n\n[q]Gefallene Königswürde (0/2)\n[q0]Königsmörder\nKöniginnensturz\n[q0](2) Set : Die Klingen werden sich Euch nie unterwerfen."},
[240854] = {name = "[q4]Gnade", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Faustwaffe}\n{169 - 316 Schaden} {Tempo 2.90}\n(83.62 Schaden pro Sekunde)\n+16 Stärke\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen:\n\n[q]Hacken und Schmettern (0/2)\n[q0]Gnade\nPurpurrotes Spaltbeil\n[q0](2) Set : Der erhöhte Schaden von 'Gnade' und 'Purpurrotes Spaltbeil' ist 10% höher."},
[240919] = {name = "[q4]Wiederheerer", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Axt}\n{330 - 496 Schaden} {Tempo 3.80}\n(108.68 Schaden pro Sekunde)\n+44 Stärke\n+31 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Trefferchance: Ihr greift 9 Sek. lang alle Gegner in der Nähe an und verursacht Waffenschaden plus alle 1.5 Sek. zusätzlich 200 Schaden."},
[240920] = {name = "[q4]Leogan", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blazefury] (1)\n{Zweihändig} {Schwert}\n{148 - 222 Schaden} {Tempo 1.70}\n(108.82 Schaden pro Sekunde)\n+47 Stärke\n+24 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Fügt Euren Nahkampfangriffen 2 Heiligschaden hinzu.\n[q2]Anlegen: Verbessert Eure Trefferchance mit allen Heiligzaubern um 3%.\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 1%.\n[q2]Anlegen: Verringert die globale Abklingzeit Eurer Zauber 'Exorzismus' und 'Heiliger Zorn' um 0.5 Sek.\n[q2]Trefferchance: Erhöht die Stärke des Trägers 15 Sek. lang um 200."},
[240921] = {name = "[q4]Scharlachroter Schadensbringer", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{348 - 522 Schaden} {Tempo 4.00}\n(108.75 Schaden pro Sekunde)\n+47 Stärke\n+24 Ausdauer\n+15 Intelligenz\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Verringert die globale Abklingzeit Eurer Schock- und Blitzschlagzauber sowie Eures Zaubers 'Lavaeruption' um 0.5 Sek.\n[q2]Trefferchance: Erhöht die Stärke des Trägers 15 Sek. lang um 200."},
[240922] = {name = "[q4]Täuschung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\n{Einhändig} {Schwert}\n{146 - 272 Schaden} {Tempo 2.70}\n(77.41 Schaden pro Sekunde)\n+15 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Chance von 2%, bei einem Nahkampftreffer 1 Zusatzangriff zu erhalten. (Procchance: 2%, 100ms Abklingzeit)\n\n[q]Werkzeuge der Nathrezim (0/2)\n[q0]Täuschung\nDoppelzunge\n[q0](2) Set : Die Zusatzangriffe von 'Doppelzunge' und 'Täuschung' lösen jetzt 2 Zusatzangriffe aus."},
[240923] = {name = "[q0]Doppelzunge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\n{Einhändig} {Schwert}\n{164 - 305 Schaden} {Tempo 2.80}\n(83.75 Schaden pro Sekunde)\n+19 Stärke\n+8 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Chance von 2%, bei einem Nahkampftreffer 1 Zusatzangriff zu erhalten. (Procchance: 2%, 100ms Abklingzeit)\n\n[q]Werkzeuge der Nathrezim (0/2)\n[q0]Täuschung\nDoppelzunge\n[q0](2) Set : Die Zusatzangriffe von 'Doppelzunge' und 'Täuschung' lösen jetzt 2 Zusatzangriffe aus."},
[240924] = {name = "[q4]Stangenaxt der Bestie", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n{296 - 444 Schaden} {Tempo 3.40}\n(108.82 Schaden pro Sekunde)\n+40 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Der Effekt 'Feuer konzentrieren' gewährt Euch und Eurem Begleiter jetzt 20 Sek. lang um 4% erhöhten Schaden pro verbrauchtem Stapel.\n[q2]Anlegen: +756 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt."},
[240925] = {name = "[q4]Experiment 800M", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Schusswaffe}\n{159 - 297 Schaden} {Tempo 3.50}\n(65.14 Schaden pro Sekunde)\n+10 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\n[q2]Benutzen: Verwandelt Euch für 20 Sek. in eine scharlachrote Kanone, sodass Eure Distanzangriffe Explosionen hervorrufen und allen Gegnern innerhalb von 8 Metern um Eurer Ziel 386 bis 472 Feuerschaden zufügen. (2 Min Abklingzeit)"},
[240936] = {name = "[q4]Inaktiver Aschenbringer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n{155 - 233 Schaden} {Tempo 3.00}\n(64.67 Schaden pro Sekunde)\nBenötigt Stufe 60\n[q2]Benutzen: Versucht, Kontakt zum Willen des Aschenbringers aufzunehmen. (4 Min Abklingzeit)\n[q2]Anlegen: Der Träger wird vom Willen des Aschenbringers erfüllt.\n[q]\"In seiner aktuellen Form ist es nichts als eine Klinge...\""},
[240945] = {name = "Stück von Carries Apfelkuchen", additional_info = "[q2]Benutzen: Stellt im Verlauf von 18 Sek. 61.2 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Obwohl der Kuchen in drei gleich große Stücke geschnitten wurde, habt Ihr doch irgendwie das kleinste Stück bekommen.\""},
[240997] = {name = "[q4]Fratleys Sporn", additional_info = "Wird beim Aufheben gebunden\n{Wurfwaffe} {Wurfwaffe}\n{152 - 283 Schaden} {Tempo 3.00}\n(72.50 Schaden pro Sekunde)\n+6 Stärke\n+6 Beweglichkeit\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 1%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%."},
[240998] = {name = "[q4]Einschläfernde Klinge", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Dolch}\n{33 - 134 Schaden} {Tempo 2.00}\n(41.75 Schaden pro Sekunde)\n+11 Ausdauer\n+10 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\n[q2]Benutzen: Euer nächster regulärer Nahkampfangriff innerhalb von 20 Sek. verursacht Arkanschaden in Höhe des 2-Fachen Eurer Zaubermacht und lässt das Ziel 20 Sek. lang schlafen. (2 Min Abklingzeit)"},
[241001] = {name = "[q4]Tyrs Fall", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Streitkolben}\n{39 - 160 Schaden} {Tempo 2.40}\n(41.46 Schaden pro Sekunde)\n+9 Ausdauer\n+17 Intelligenz\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\n[q2]Anlegen: Wenn Ihr regelmäßigen Schaden verursacht, besteht eine Chance von 5%, dass Zauberschaden und Heilung 15 Sek. lang um 120 erhöht werden. (Procchance: 5%)"},
[241002] = {name = "[q4]Überreste der Roten", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Schwert}\n{39 - 160 Schaden} {Tempo 2.40}\n(41.46 Schaden pro Sekunde)\n+5 Ausdauer\n+10 Intelligenz\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht Euer Zaubertempo um 2%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\n[q2]Anlegen: Wenn Ihr nicht-regelmäßigem Feuerschaden verursacht, besteht eine Chance von 5%, dass sich Euer verursachter Feuerschaden 15 Sek. lang um 5% erhöht. (Procchance: 5%)"},
[241003] = {name = "[q4]Trugbild, Rute der Illusionen", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{200 - 279 Schaden} {Tempo 3.60}\n(66.53 Schaden pro Sekunde)\n+12 Ausdauer\n+28 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Euer Zaubertempo um 2%.\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\n[q2]Anlegen: Chance, mit einem Schadenszauber zu treffen, der auf Eurem Ziel ein Trugbild erzeugt, das Gegnern in der Nähe 30 Sek. lang Arkanschaden zufügt. (Procchance: 10%, 30s Abklingzeit)\n[q2]Benutzen: Tauscht Plätze mit Eurem Trugbild. (2 Min Abklingzeit)"},
[241004] = {name = "[q4]Verwirrung", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Zauberstab}\n{159 - 296 Heiligschaden} {Tempo 1.50}\n(151.67 Schaden pro Sekunde)\n-10 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 30.\n[q2]Anlegen: Die Reichweite Eurer Zauber 'Gedankenschinden', 'Feuerschlag' und 'Blutsauger' ist 10 Meter größer, aber 'Gedankenschinden' verlangsamt Gegner nicht mehr."},
[241006] = {name = "[q4]Spitze der Opferung", additional_info = "Wird beim Aufheben gebunden\n{Waffenhand} {Streitkolben}\n{39 - 160 Schaden} {Tempo 2.40}\n(41.46 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Euer Zaubertempo um 2%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 317 Gesundheit und den verursachten Schaden um bis zu 106.\n[q2]Benutzen: Während Ihr mehr als 30% Gesundheit habt, ist Eure Heilung um 200 erhöht, aber dafür opfert Ihr bei jeder Heilung 5% Eurer gesamten Gesundheit. Während dieser Effekt bei Euch aktiv ist, werdet Ihr nur durch direkte, nicht regelmäßige Heilzauber geheilt. (Umgeschalteter Effekt) (10 Sek. Abklingzeit)"},
[241008] = {name = "[q4]Geißelung", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{187 - 263 Schaden} {Tempo 3.60}\n(62.50 Schaden pro Sekunde)\n+20 Ausdauer\n+30 Intelligenz\n+21 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 317 Gesundheit und den verursachten Schaden um bis zu 106.\n[q2]Anlegen: Schadenszauber, die gegen Gegner eingesetzt werden, geißeln diese 20 Sek. lang. Wann immer sie Schaden verursachen, wird ihr Ziel um 3% seiner maximalen Gesundheit geheilt. Hält 20 Sek. lang oder für bis zu 10 Treffer an. (60 Sek. Abklingzeit) (1Min. Abklingzeit)"},
[241011] = {name = "[q4]Großstab der Treue", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n{200 - 279 Schaden} {Tempo 3.60}\n(66.53 Schaden pro Sekunde)\n+16 Ausdauer\n+20 Intelligenz\n+30 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Euer Zaubertempo um 4%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 317 Gesundheit und den verursachten Schaden um bis zu 106.\n[q2]Anlegen: Wenn sich keine Gegner innerhalb von 20 Metern um Euch herum befinden, werden alle Gruppenmitglieder innerhalb von 20 Metern alle 3 Sek. um 125 Gesundheit geteilt. Eine Gruppe kann immer nur einem Spielercharakter gleichzeitig die Treue schwören."},
[241012] = {name = "[q4]Zauberstab der Reanimation", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Zauberstab}\n{159 - 296 Heiligschaden} {Tempo 1.50}\n(151.67 Schaden pro Sekunde)\n+6 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 46 und den verursachten Schaden um bis zu 16."},
