[241034] = {name = "[q4]Lichtherz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+32 Ausdauer\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\n[q2]Anlegen: Verteidigung +16.\n[q2]Benutzen: Erhöht 20 Sek. lang die maximale Gesundheit um 2500. (2 Min Abklingzeit)"},
[241037] = {name = "[q4]Verworfenes Experiment", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure Bewegungsgeschwindigkeit um 4%.\n[q2]Benutzen: Nachdem Ihr das Experiment getrunken habt, erhöhen Nahkampf- oder Distanzangriffe Euer Angriffstempo 30 Sek. lang um 2%. Dieser Effekt ist bis zu 15-mal stapelbar. (2 Min Abklingzeit)"},
[241038] = {name = "[q4]Sir Dornels Didgeridoo", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\n[q2]Anlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\n[q2]Benutzen: Das Spielen des Didgeridoos beschwört ein zufälliges Wildtier an Eure Seite und erhöht 30 Sek. lang Eure körperlichen Fähigkeiten. Kann nur im Kampf verwendet werden. (2 Min Abklingzeit)"},
[241039] = {name = "[q4]Infusion der Seelen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Paladin , Priester , Schamane , Magier , Hexenmeister , Druide\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Euer Zaubertempo um 4%.\n[q2]Anlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 26.\n[q2]Anlegen: Die globale Abklingzeit Eurer nicht waffenbasierten Schadenszauber kann durch Zaubertempo um bis zu 0.5 Sek. verringert werden."},
[241068] = {name = "[q4]Stiltz' Standarte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+10 Intelligenz\n+10 Willenskraft\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 88 Gesundheit und den verursachten Schaden um bis zu 30.\n[q2]Benutzen: Stellt Stiltz' Standarte auf, die die maximale Gesundheit aller Verbündeten in der Nähe 20 Sek. lang um 1000 erhöht. (2 Min Abklingzeit)"},
