[241190] = {name = "[q2]Vogelpfeife", additional_info = "Wird bei Benutzung gebunden\n[q2]Benutzen: Beschwört Pepe, um Euch auf Euren Abenteuern zu begleiten!"},
[241191] = {name = "[q3]Formel: Waffe - Oberster Kreuzzügler", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (280)\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass sie oft bei Nahkampfangriffen 350 bis 450 Gesundheit heilt und die Stärke 20 Sek. lang um 120 erhöht.\n[q]\"Lehrt Euch, wie man eine Waffe dauerhaft so verzaubert, dass sie gelegentlich ihren Benutzer mit unfassbarer Stärke segnet.\""},
[241195] = {name = "[q3]Formel: Zweihandwaffe - Oberster Arkanist", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (280)\n[q2]Eine Zweihandnahkampfwaffe dauerhaft verzaubern, sodass bei einem Treffer mit einem Zauber häufig 350 bis 450 Mana wiederhergestellt und die Zaubermacht 20 Sek. lang um 140 erhöht wird.\n[q]\"Lehrt Euch, wie man eine zweihändige Nahkampfwaffe dauerhaft so verzaubert, dass sie gelegentlich ihren Benutzer mit erhöhter Zaubermacht segnet.\""},
[241201] = {name = "[q3]Formel: Waffe - Oberster Zauberer", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (280)\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass bei einem Treffer mit einem Zauber häufig 350 bis 450 Mana wiederhergestellt und die Zaubermacht 20 Sek. lang um 70 erhöht wird.\n[q]\"Lehrt Euch, wie man eine Nahkampfwaffe dauerhaft so verzaubert, dass sie gelegentlich ihren Benutzer mit erhöhter Zaubermacht segnet.\""},
[241212] = {name = "[q4]Kikerikanone", additional_info = "Wird beim Aufheben gebunden\n{Distanz} {Schusswaffe}\n{142 - 265 Schaden} {Tempo 3.50}\n(58.14 Schaden pro Sekunde)\n+10 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60"},
[241241] = {name = "[q4]Glücksdublone", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 2%.\n[q2]Benutzen: Wirft die Glücksdublone. Bei Kopf wird die Abklingzeit von 'Glücksdublone' abgeschlossen und Eure kritische Trefferchance mit allen Zaubern und Angriffen wird 15 Sek. lang um 5% erhöht. Bis zu 5-mal stapelbar. Bei Zahl werden alle Stapel von 'Glücksdublone' entfernt. (Ihr müsst Euch im Kampf befinden.) (30 Sek. Abklingzeit)\n[q]\"Doppelt oder nix.\""},
[241613] = {name = "[q3]Nicht mehr verwendet", additional_info = "Wird beim Aufheben gebunden"},
[241629] = {name = "[q4]Scharlachrote Kanonenkugel", additional_info = "Herbeigezauberter Gegenstand\nEinzigartig\nDauer: 10 min"},
[241649] = {name = "[q2]Stulpen der Hillsbradwache", additional_info = "Wird beim Anlegen gebunden\n{Hände} {Platte}\n345 Rüstung\n+15 Stärke\n+12 Ausdauer\nHaltbarkeit 40 / 40\nBenötigt Stufe 53"},
[241650] = {name = "Erheblicher verfärbter Heiltrank", additional_info = "Benötigt Stufe 60\n[q2]Benutzen: Stellt sofort 3750 bis 4250 Gesundheit wieder her, allerdings erleidet Ihr im Laufe der Zeit Schaden in Höhe von 75% des Werts.\n\n Die Symptome dieses Effekts können sich als Gift für 6 Sek. oder als Krankheit für 12 Sek. zeigen. (2 Min Abklingzeit)"},
[241651] = {name = "[q2]Rezept: Erheblicher verfärbter Heiltrank", additional_info = "Wird beim Aufheben gebunden\nBenötigt Alchimie (250)\n[q]\"Lehrt Euch, wie man einen erheblichen verfärbten Heiltrank herstellt.\""},
[241652] = {name = "Verfärbtes Tierherz", additional_info = nil},
[241653] = {name = "[q4]Erhitzte Klinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Schreckt die erhitzte Klinge im Wasser des Brunnens der Ewigkeit ab."},
[241654] = {name = "[q4]Inaktiver Aschenbringer", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Erhitzt die Klinge mithilfe der uralten Flammen aus den Zweigen von Nordrassil.\n[q]\"In seiner aktuellen Form ist es nichts als eine Klinge...\""},
[241655] = {name = "Beschädigter Heiltrank", additional_info = "Dieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n[q]\"Ein wahrhaft ekelhafter Trank.\""},
