[241657] = {name = "[q4]Gehärtete Klinge", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Versucht, Kontakt zum Willen des Aschenbringers aufzunehmen. (4 Min Abklingzeit)"},
[242018] = {name = "Blutendes Pestlandherz", additional_info = "Questgegenstand\n[q]\"Eine ungewöhnlich prächtige Blume, wenn man bedenkt, welcher Region sie entstammt. Sie ist trotz der Pest in der Lage, zu gedeihen.\""},
[242224] = {name = "Korb mit Herzen", additional_info = "Questgegenstand\n[q]\"Vermutlich nicht der beste Behälter, den man für diese Situation hätte auswählen können.\""},
[242256] = {name = "Säckchen mit Brandbomben", additional_info = "Questgegenstand\nEinzigartig\nBenötigt Stufe 60\n[q2]Benutzen: Werft die Brandbombe auf eine Balliste in der Nähe. (1 Min Abklingzeit)"},
[242257] = {name = "Geheimnisvolle alchemische Probe", additional_info = "Questgegenstand"},
[242258] = {name = "Forschungsnotizen", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Diese Notizen enthalten Experimente und Testdaten zu verschiedenen Seuchenvariationen, die aus Naxxramas stammen.\"\n[q2]<Zum Lesen rechtsklicken>"},
[242266] = {name = "[q2]Welt der Schutzkraft", additional_info = "Wird beim Aufheben gebunden\n[q]\"Von vorne bis hinten mit ausführlichen Aufzeichnungen zu allerlei magischen Schutzen gefüllt. Kurioserweise leuchtet das Buch schwach.\""},
[242267] = {name = "[q2]Vom Arkanist zum Erzmagier", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eine selbstbeweihräuchernde Autobiografie von einem Autor, der zu irrelevant ist, um genannt zu werden. Interessanterweise surrt das Buch aufgrund eines aufmerksamkeitssuchenden Zaubers.\""},
[242268] = {name = "[q2]Verzaubert einen Kreuzfahrer", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eine unterhaltsame Kurzgeschichte, die schnell dem Wahnsinn verfällt, bevor sie darin endet, dass der Antagonist alles bekommt, was er möchte. Witzigerweise strahlt das Buch vor Kraft.\""},
[242269] = {name = "[q3]Brillanz des Obersten Zauberers", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (280)\n[q2]Benutzen: Verbindet 15 Einheiten Illusionsstaub und 1 rechtschaffene Kugel an einem Partikel der Möglichkeiten, um eine neue Entdeckung zu machen."},
