[242465] = {name = "[q4]Fragment des angerempelten Kelchs", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Setzt 3 Bruchstücke zusammen, um den Kelch des Kreuzfahrers zu reparieren."},
[242793] = {name = "[q4]Tragbare Kanone", additional_info = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\n[q2]Anlegen: Verbessert Eure Chance auf Treffer mit allen Zaubern und Angriffen um 2%.\n[q2]Benutzen: Ladet Euch selbst in eine Kanone. Was soll schon schiefgehen? (1 Min, 30 Sek. Abklingzeit)"},
[243010] = {name = "[q4]Verderbter Aschenbringer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n{26 - 39 Schaden} {Tempo 3.60}\n(9.03 Schaden pro Sekunde)\n-25 Ausdauer\nHaltbarkeit 120 / 120\n[q]\"Klinge des Scharlachroten Hochlords\""},
