[243198] = {name = "[q4]Geflügelgenauigkeitszielfernrohr", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenötigt Stufe 60\n[q2]Benutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit verursachten Schaden um 10."},
[243229] = {name = "[q3]Ruhestein der Argentumdämmerung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Bringt Euch zurück zur Kapelle des hoffnungsvollen Lichts."},
