[243345] = {name = "Langstab", additional_info = "{Zweihändig} {Stab}\n{36 - 55 Schaden} {Tempo 3.00}\n(15.17 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 20"},
[244353] = {name = "[q4]Geflügelgenauigkeitszielfernrohr", additional_info = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenötigt Stufe 60\n[q2]Benutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht dadurch die Trefferchance um 3%."},
[244460] = {name = "[q4]Caladschneide", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Streitkolben}\n{339 - 509 Schaden} {Tempo 3.90}\n(108.72 Schaden pro Sekunde)\n+50 Stärke\n+15 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 2%.\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Benutzen: Die Caladschneide wird 20 Sek. lang erneut von der Erde verschlungen, wodurch die Bewegungsgeschwindigkeit um 50% verringert wird. Wenn Ihr Euch bewegt, erhöht sich Eure Bewegungsgeschwindigkeit alle 2 Sekunden. Wenn Ihr in einen Gegner kracht, fügt Ihr diesem 300 bis 2700 Feuerschaden zu, wobei Ihr alle gegnerischen Spielercharaktere zurückstoßt und diesen Effekt beendet. (2 Min Abklingzeit)\n[q]\"Eine uralte Klinge, die vom Scharlachroten Kreuzzug geheim gehalten wird. Weist leichte Gebrauchsspuren auf.\""},
[245675] = {name = "Schlüssel für die Gordokinnentür", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"},
[246055] = {name = "[q0]Handschutz der Inquisition", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Hände} {Platte}\n681 Rüstung\n+13 Ausdauer\n+38 Intelligenz\nHaltbarkeit 55 / 55\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Erhöht Eurer Angriffstempo um 2%.\n\n[q]Schockplatte der Inquisition (0/8)\n[q0]Gesichtsschutz der Inquisition\nSchulterklappen der Inquisition\nKürass der Inquisition\nKordel der Inquisition\nPlattenbeinschützer der Inquisition\nStampfer der Inquisition\nArmschienen der Inquisition\nHandschutz der Inquisition\n[q0](2) Set : Während 'Verunsicherungstaktik' aktiv ist, gewähren Euer 'Kreuzfahrerstoß' und 'Exorzismus' Euch Heilige Kraft und erhöhen den von Euch verursachten Heiligschaden um 10%. Bis zu 3-mal stapelbar. (100ms Abklingzeit)\n(4) Set : Euer 'Göttlicher Sturm', 'Heiliger Schock' und 'Heiliger Zorn' verbrauchen Eure gesamte Heilige Kraft und verursachen 100% mehr Schaden pro angesammelter Heiliger Kraft. Hat gegen Ziele, die von Spielercharakteren kontrolliert werden, eine Effektivität von 50%.\n(6) Set : Wenn Ihr Heilige Kraft verbraucht, wird Eure Zaubermacht 10 Sek. lang um 8 bis 18% pro verbrauchter Heiliger Kraft erhöht."},
[246056] = {name = "[q4]Armschienen der Inquisition", additional_info = "Geweiht\nWird beim Aufheben gebunden\n{Handgelenke} {Platte}\n477 Rüstung\n+13 Ausdauer\n+29 Intelligenz\nHaltbarkeit 55 / 55\nKlassen: Paladin\nBenötigt Stufe 60\n[q2]Anlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\n[q2]Anlegen: Verbessert Eure Trefferchance mit allen Heiligzaubern um 3%.\n\n[q]Schockplatte der Inquisition (0/8)\n[q0]Gesichtsschutz der Inquisition\nSchulterklappen der Inquisition\nKürass der Inquisition\nKordel der Inquisition\nPlattenbeinschützer der Inquisition\nStampfer der Inquisition\nArmschienen der Inquisition\nHandschutz der Inquisition\n[q0](2) Set : Während 'Verunsicherungstaktik' aktiv ist, gewähren Euer 'Kreuzfahrerstoß' und 'Exorzismus' Euch Heilige Kraft und erhöhen den von Euch verursachten Heiligschaden um 10%. Bis zu 3-mal stapelbar. (100ms Abklingzeit)\n(4) Set : Euer 'Göttlicher Sturm', 'Heiliger Schock' und 'Heiliger Zorn' verbrauchen Eure gesamte Heilige Kraft und verursachen 100% mehr Schaden pro angesammelter Heiliger Kraft. Hat gegen Ziele, die von Spielercharakteren kontrolliert werden, eine Effektivität von 50%.\n(6) Set : Wenn Ihr Heilige Kraft verbraucht, wird Eure Zaubermacht 10 Sek. lang um 8 bis 18% pro verbrauchter Heiliger Kraft erhöht."},
